#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Flask 3 – Copier tous les fichiers .mp4 d'un répertoire source vers
une clé USB montée en /media/usb.

Fonctionnalités :
- Page d’accueil Bootstrap 5 avec un bouton « Lancer la copie »
- Barre de progression dynamique (100 % une fois terminée)
- Copie exécutée dans un thread en arrière‑plan
- Mise à jour de la barre via polling AJAX (GET /progress)
"""

from flask import Flask, render_template_string, request, jsonify, redirect, url_for
import os
import shutil
import threading
import time

app = Flask(__name__)
app.config['SECRET_KEY'] = 'dev'          # à modifier en production

# --------------------------------------------------------------------------- #
# Configuration
# --------------------------------------------------------------------------- #
SOURCE_DIR = "/chemin/vers/repertoire/source"   # <-- à adapter
USB_MOUNT_POINT = "/media/usb"                   # <-- à adapter
DEST_DIR = os.path.join(USB_MOUNT_POINT, "copie_mp4")
# --------------------------------------------------------------------------- #

# --------------------------------------------------------------------------- #
# Variables partagées (thread‑safe)
# --------------------------------------------------------------------------- #
progress_lock = threading.Lock()
copy_progress = {
    'total_files': 0,
    'files_copied': 0,
    'status': 'idle',   # idle / running / finished / error
    'error_msg': '',
}

def copier_fichiers():
    """
    Fonction exécutée dans un thread. Elle copie tous les fichiers .mp4
    de SOURCE_DIR vers DEST_DIR, en mettant à jour copy_progress.
    """
    try:
        # Pré‑validation
        if not os.path.isdir(SOURCE_DIR):
            raise FileNotFoundError(f"Répertoire source introuvable : {SOURCE_DIR}")

        if not os.path.isdir(USB_MOUNT_POINT):
            raise FileNotFoundError(f"Clé USB non montée : {USB_MOUNT_POINT}")

        # Création du dossier de destination s'il n'existe pas
        os.makedirs(DEST_DIR, exist_ok=True)

        # Liste des fichiers .mp4
        mp4_files = [
            f for f in os.listdir(SOURCE_DIR)
            if os.path.isfile(os.path.join(SOURCE_DIR, f)) and f.lower().endswith('.mp4')
        ]

        total = len(mp4_files)
        with progress_lock:
            copy_progress.update({
                'total_files': total,
                'files_copied': 0,
                'status': 'running',
                'error_msg': '',
            })

        if total == 0:
            # Pas de fichier à copier
            with progress_lock:
                copy_progress['status'] = 'finished'
            return

        for idx, filename in enumerate(mp4_files, start=1):
            src = os.path.join(SOURCE_DIR, filename)
            dst = os.path.join(DEST_DIR, filename)

            # On copie en conservant les métadonnées
            shutil.copy2(src, dst)

            # Simuler un délai de copie pour voir la progression
            # (à enlever en production)
            time.sleep(0.2)

            # Mise à jour de la progression
            with progress_lock:
                copy_progress['files_copied'] = idx

        # Fin
        with progress_lock:
            copy_progress['status'] = 'finished'

    except Exception as exc:          # pragma: no cover
        # En cas d’erreur on stocke le message
        with progress_lock:
            copy_progress['status'] = 'error'
            copy_progress['error_msg'] = str(exc)


@app.route("/", methods=["GET"])
def index():
    """
    Page principale : bouton + barre de progression.
    Le template est intégré dans le code pour éviter un fichier .html séparé.
    """
    html_template = """
    <!doctype html>
    <html lang="fr">
      <head>
        <meta charset="utf-8">
        <title>Copie MP4 vers USB</title>
        <meta name="viewport" content="width=device-width, initial-scale=1">

        <!-- Bootstrap 5 (CDN) -->
        <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">
        <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>

        <style>
          body { padding-top: 4rem; }
        </style>
      </head>

      <body>
        <div class="container">

          <h1 class="mb-4">Copie de fichiers MP4 vers USB</h1>

          <!-- Bouton -->
          <button id="startBtn" class="btn btn-primary mb-3">
            <i class="bi bi-arrow-right-circle"></i> Lancer la copie
          </button>

          <!-- Barre de progression -->
          <div class="progress mb-3" style="height: 25px; display:none;" id="progressContainer">
            <div class="progress-bar" role="progressbar" style="width: 0%" aria-valuenow="0" aria-valuemin="0" aria-valuemax="100"></div>
          </div>

          <!-- Messages -->
          <div id="statusMsg" class="alert" role="alert" style="display:none;"></div>
        </div>

        <!-- JavaScript -->
        <script>
          const startBtn = document.getElementById('startBtn');
          const progressBar = document.querySelector('.progress-bar');
          const progressContainer = document.getElementById('progressContainer');
          const statusMsg = document.getElementById('statusMsg');

          let pollInterval = null;

          startBtn.addEventListener('click', () => {
            // Désactiver le bouton pour éviter les clics multiples
            startBtn.disabled = true;
            statusMsg.style.display = 'none';
            progressContainer.style.display = 'block';
            progressBar.style.width = '0%';
            progressBar.setAttribute('aria-valuenow', '0');

            // Envoi de la requête POST /start
            fetch('/start', { method: 'POST' })
              .then(resp => {
                if (!resp.ok) throw new Error('Erreur serveur');
                return resp.json();
              })
              .then(data => {
                console.log('Démarrage', data);
                // Démarrer le polling
                if (!pollInterval) {
                  pollInterval = setInterval(checkProgress, 500);
                }
              })
              .catch(err => {
                console.error(err);
                statusMsg.className = 'alert alert-danger';
                statusMsg.innerText = 'Impossible de démarrer la copie';
                statusMsg.style.display = 'block';
                startBtn.disabled = false;
              });
          });

          function checkProgress() {
            fetch('/progress')
              .then(resp => resp.json())
              .then(data => {
                const pct = data.percentage;
                progressBar.style.width = pct + '%';
                progressBar.setAttribute('aria-valuenow', pct);
                progressBar.innerText = pct + '%';

                if (data.status === 'finished') {
                  clearInterval(pollInterval);
                  pollInterval = null;
                  statusMsg.className = 'alert alert-success';
                  statusMsg.innerText = 'Copie terminée !';
                  statusMsg.style.display = 'block';
                  startBtn.disabled = false;
                } else if (data.status === 'error') {
                  clearInterval(pollInterval);
                  pollInterval = null;
                  statusMsg.className = 'alert alert-danger';
                  statusMsg.innerText = 'Erreur : ' + data.error_msg;
                  statusMsg.style.display = 'block';
                  startBtn.disabled = false;
                }
              })
              .catch(err => {
                console.error(err);
              });
          }
        </script>
      </body>
    </html>
    """
    return render_template_string(html_template)


@app.route("/start", methods=["POST"])
def start_copy():
    """
    Point de terminaison appelé par le bouton.
    Si une copie est déjà en cours, on refuse de lancer une autre.
    Sinon, on démarre un thread dédié.
    """
    with progress_lock:
        if copy_progress['status'] == 'running':
            return jsonify({"error": "Une copie est déjà en cours."}), 409

        # Réinitialiser les variables
        copy_progress.update({
            'total_files': 0,
            'files_copied': 0,
            'status': 'idle',
            'error_msg': '',
        })

    thread = threading.Thread(target=copier_fichiers, daemon=True)
    thread.start()

    return jsonify({"message": "Copie démarrée."}), 200


@app.route("/progress", methods=["GET"])
def get_progress():
    """
    Retourne la progression actuelle en JSON.
    Exemple : { "percentage": 45, "status": "running" }
    """
    with progress_lock:
        total = copy_progress['total_files']
        copied = copy_progress['files_copied']
        status = copy_progress['status']
        error_msg = copy_progress['error_msg']

    percentage = 0
    if total > 0:
        percentage = int(copied * 100 / total)

    return jsonify({
        "percentage": percentage,
        "status": status,
        "error_msg": error_msg,
    })


# --------------------------------------------------------------------------- #
# Lancer l’application
# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    # Assurez‑vous que la clé USB est montée
    if not os.path.isdir(USB_MOUNT_POINT):
        print(f"[Erreur] Le point de montage {USB_MOUNT_POINT} n'existe pas.")
        exit(1)

    # Démarrage de Flask
    app.run(host="0.0.0.0", port=5000, debug=True)
```

