import os
import uuid
from flask import (
    Flask, render_template, request, session, redirect,
    url_for, send_file, jsonify, make_response
)
import openai
from io import BytesIO

app = Flask(__name__)
app.secret_key = os.urandom(24)  # 用于 session，加密
openai.api_key = os.getenv("OPENAI_API_KEY")  # 记得先在 env 里填好

# ---------- 工具函数 ----------
def call_chatgpt(messages, temperature=0.7, max_tokens=1500):
    """
    调用 ChatGPT（GPT-4）完成对话，返回 assistant 的内容。
    """
    response = openai.ChatCompletion.create(
        model="gpt-4",
        messages=messages,
        temperature=temperature,
        max_tokens=max_tokens,
        top_p=1,
        frequency_penalty=0,
        presence_penalty=0,
    )
    return response.choices[0].message.content.strip()

def init_session():
    """
    初始化 session 存储结构
    """
    session.setdefault("outline", "")
    session.setdefault("character", "")
    session.setdefault("plot", "")
    session.setdefault("style", "现代")
    session.setdefault("chapters", [])      # 列表，存每一章的文本
    session.setdefault("draft", "")        # 当前生成的章节草稿

# ---------- 路由 ----------
@app.route("/", methods=["GET"])
def index():
    init_session()
    return render_template(
        "index.html",
        outline=session["outline"],
        character=session["character"],
        plot=session["plot"],
        style=session["style"],
        chapters=session["chapters"],
        draft=session["draft"],
    )

# ---- 1. 自动扩写大纲、人设、情节 ----
@app.route("/expand", methods=["POST"])
def expand():
    init_session()
    # 读取用户的关键词，可能是任何文字
    user_input = request.form.get("keywords", "").strip()
    if not user_input:
        return jsonify({"error": "请输入关键词"}), 400

    # 先把关键词作为起始提示
    prompt = (
        f"你是一位小说创作助手。请根据以下关键词，完整、富有创意地分别给出：\n"
        f"1. 小说大纲（约200字）\n"
        f"2. 主角人设（约200字）\n"
        f"3. 情节（约200字）\n"
        f"关键词：{user_input}\n\n"
        f"输出格式：\n"
        f"Outline: ...\n"
        f"Character: ...\n"
        f"Plot: ..."
    )
    messages = [{"role": "user", "content": prompt}]
    response = call_chatgpt(messages, temperature=0.8, max_tokens=1200)

    # 简单解析（依据你给的固定格式）
    parts = response.split("\n")
    new_outline = new_character = new_plot = ""
    for part in parts:
        if part.startswith("Outline:"):
            new_outline = part[len("Outline:"):].strip()
        elif part.startswith("Character:"):
            new_character = part[len("Character:"):].strip()
        elif part.startswith("Plot:"):
            new_plot = part[len("Plot:"):].strip()

    # 更新 session
    session["outline"] = new_outline
    session["character"] = new_character
    session["plot"] = new_plot

    return jsonify({
        "outline": new_outline,
        "character": new_character,
        "plot": new_plot,
    })

# ---- 2. 生成章节（用户选择语言风格后） ----
@app.route("/generate", methods=["POST"])
def generate():
    init_session()
    style = request.form.get("style", "现代").strip()
    session["style"] = style

    # 构造 prompt
    prompt = (
        f"请根据以下信息，用{style}的语言写一章网络小说（约1500词）\n"
        f"Outline: {session['outline']}\n"
        f"Character: {session['character']}\n"
        f"Plot: {session['plot']}\n\n"
        f"注意：章节应自然过渡，不要重复之前的内容，保持连贯性。"
    )
    messages = [{"role": "user", "content": prompt}]
    chapter_text = call_chatgpt(messages, temperature=0.85, max_tokens=2000)

    # 保存到 draft（用户可再修改）
    session["draft"] = chapter_text
    return jsonify({"draft": chapter_text})

# ---- 3. 重新生成（用户给意见后） ----
@app.route("/revise", methods=["POST"])
def revise():
    """
    接收用户对 draft 的意见，重新生成章节。
    """
    init_session()
    feedback = request.form.get("feedback", "").strip()
    if not feedback:
        return jsonify({"error": "请填写修改意见"}), 400

    # 把之前的 draft 加入提示，让模型根据反馈重新生成
    prompt = (
        f"你是一位小说创作助手。根据以下用户反馈，改写上一章节的内容，使其更好，保持同样的风格（{session['style']}）：\n"
        f"原章节：\n{session['draft']}\n\n"
        f"用户反馈：\n{feedback}\n\n"
        f"请直接给出改写后的章节。"
    )
    messages = [{"role": "user", "content": prompt}]
    revised_text = call_chatgpt(messages, temperature=0.75, max_tokens=2000)

    session["draft"] = revised_text
    return jsonify({"draft": revised_text})

# ---- 4. 记录章节（确认后保存） ----
@app.route("/confirm", methods=["POST"])
def confirm():
    """
    把当前 draft 追加到 chapters 列表，并清空 draft。
    """
    init_session()
    if not session.get("draft"):
        return jsonify({"error": "没有草稿可以确认"}), 400
    session["chapters"].append(session["draft"])
    session["draft"] = ""  # 清空草稿
    return jsonify({"chapters": session["chapters"]})

# ---- 5. 下载完整小说（txt） ----
@app.route("/download", methods=["GET"])
def download():
    init_session()
    if not session["chapters"]:
        return "没有任何章节可以下载", 400
    content = ""
    for idx, ch in enumerate(session["chapters"], 1):
        content += f"第{idx}章\n{'='*30}\n{ch}\n\n"

    # 把内容写进 BytesIO，返回下载
    buffer = BytesIO()
    buffer.write(content.encode("utf-8"))
    buffer.seek(0)
    filename = f"novel_{uuid.uuid4().hex[:8]}.txt"
    return send_file(
        buffer,
        as_attachment=True,
        download_name=filename,
        mimetype="text/plain; charset=utf-8"
    )

# ---- 6. 继续下一章节（只需要新的情节） ----
@app.route("/continue", methods=["POST"])
def continue_chapter():
    """
    让用户提交新的情节，直接生成下一章。
    """
    init_session()
    new_plot = request.form.get("new_plot", "").strip()
    if not new_plot:
        return jsonify({"error": "请输入新情节"}), 400
    # 更新 session plot
    session["plot"] = new_plot

    # 调用 generate 逻辑
    return generate()

# ---------- 运行 ----------
if __name__ == "__main__":
    app.run(debug=True)
```

**说明**：

* `call_chatgpt` 封装了 ChatGPT 的调用，默认温度 0.7~0.85。  
* 所有核心状态（outline/character/plot/chapters/草稿）存储在 `session` 中，便于在页面间保持。  
* `continue` 路由仅更新 `plot`，后续调用 `generate`，从而避免重新输入大纲/人设。  
* 下载端点直接把所有章节拼接成一段文本，方便用户下载。

