        document.getElementById('character').textContent = data.character || '(无)';
        document.getElementById('plot').textContent = data.plot || '(无)';
    } else {
        alert(data.error || '扩写失败');
    }
    setLoading(btn, false);
});

// 2. 生成章节
document.getElementById('btn-generate').addEventListener('click', async () => {
    const btn = document.getElementById('btn-generate');
    setLoading(btn, true);
    const form = new FormData();
    form.append('style', document.getElementById('style-select').value);
    const res = await fetch('/generate', {
        method: 'POST',
        body: form
    });
    const data = await res.json();
    if (res.ok) {
        document.getElementById('draft-content').textContent = data.draft || '(无)';
    } else {
        alert(data.error || '生成失败');
    }
    setLoading(btn, false);
});

// 3. 重新生成
document.getElementById('btn-revise').addEventListener('click', async () => {
    const btn = document.getElementById('btn-revise');
    setLoading(btn, true);
    const res = await fetch('/revise', {
        method: 'POST',
        headers: {'Content-Type': 'application/x-www-form-urlencoded'},
        body: 'feedback=' + encodeURIComponent(document.getElementById('feedback').value)
    });
    const data = await res.json();
    if (res.ok) {
        document.getElementById('draft-content').textContent = data.draft || '(无)';
    } else {
        alert(data.error || '重新生成失败');
    }
    setLoading(btn, false);
});

// 4. 确认章节
document.getElementById('btn-confirm').addEventListener('click', async () => {
    const btn = document.getElementById('btn-confirm');
    setLoading(btn, true);
    const res = await fetch('/confirm', { method: 'POST' });
    const data = await res.json();
    if (res.ok) {
        // 简单更新已确认章节列表
        const chaptersBox = document.getElementById('chapters-box');
        chaptersBox.innerHTML = '<h3>已确认章节</h3>';
        data.chapters.forEach((ch, idx) => {
            chaptersBox.innerHTML += `<h4>第${idx+1}章</h4><pre>${ch}</pre>`;
        });
        document.getElementById('draft-content').textContent = '';
    } else {
        alert(data.error || '确认失败');
    }
    setLoading(btn, false);
});

// 6. 继续下一章节
document.getElementById('btn-continue').addEventListener('click', async () => {
    const btn = document.getElementById('btn-continue');
    setLoading(btn, true);
    const res = await fetch('/continue', {
        method: 'POST',
        headers: {'Content-Type': 'application/x-www-form-urlencoded'},
        body: 'new_plot=' + encodeURIComponent(document.getElementById('new-plot').value)
    });
    const data = await res.json();
    if (res.ok) {
        document.getElementById('draft-content').textContent = data.draft || '(无)';
        document.getElementById('new-plot').value = '';
    } else {
        alert(data.error || '继续生成失败');
    }
    setLoading(btn, false);
});
</script>

</body>
</html>
```

> **核心点**  
> * **AJAX**（`fetch`）实现无刷新交互。  
> * `setLoading()` 让按钮在请求期间变成“请稍候”，避免多次点击。  
> * `draft` 是“草稿”阶段，用户可先修改后再确认。  
> * `chapters` 以列表方式保存在 session，前端循环渲染。  

