│
└─ db.sqlite3         # SQLite database (auto‑created on start)
```

> **Tip** – If you’re deploying to a service like Railway, Render, or Fly.io, set the `PORT` env var automatically.  
> For a local dev run, `node server.js` will listen on `http://localhost:3000`.

---

## 2. Code

### 2.1 `package.json`

```json
{
  "name": "image-short-url",
  "version": "1.0.0",
  "description": "Upload images and get short URLs",
  "main": "server.js",
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "author": "Your Name",
  "license": "MIT",
  "dependencies": {
    "better-sqlite3": "^7.6.0",
    "ejs": "^3.1.9",
    "express": "^4.18.2",
    "mime-types": "^2.1.35",
    "morgan": "^1.10.0",
    "multer": "^1.4.5-lts.1",
    "nanoid": "^4.0.2"
  },
  "devDependencies": {
    "nodemon": "^3.0.1"
  }
}
```

> `type: "module"` lets us use ES‑module syntax (`import … from …`) which keeps the code concise.

---

### 2.2 `server.js`

```js
// server.js
import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import multer from 'multer';
import morgan from 'morgan';
import { nanoid } from 'nanoid';
import mime from 'mime-types';
import Database from 'better-sqlite3';
import fs from 'fs';

// --- Basic helpers --------------------------------------
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const UPLOAD_DIR = path.join(__dirname, 'uploads');
if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR);

// SQLite (single file DB)
const db = new Database(path.join(__dirname, 'db.sqlite3'));
db.pragma('journal_mode = WAL');

// Create table if not exists
db.exec(`
  CREATE TABLE IF NOT EXISTS images (
    id      TEXT PRIMARY KEY,      -- short id
    filename TEXT NOT NULL,        -- original filename
    mimetype TEXT NOT NULL,        -- MIME type
    upload_ts INTEGER NOT NULL    -- epoch ms
  )
`);

// prepared statements
const insertStmt = db.prepare(`INSERT INTO images(id, filename, mimetype, upload_ts)
                               VALUES(@id, @filename, @mimetype, @upload_ts)`);
const selectStmt = db.prepare(`SELECT * FROM images WHERE id = ?`);
const cleanupStmt = db.prepare(`DELETE FROM images WHERE id = ?`);

// --- Multer config --------------------------------------
const storage = multer.diskStorage({
  destination: UPLOAD_DIR,
  filename: (req, file, cb) => {
    // keep original filename safe
    const safe = file.originalname.replace(/[^a-zA-Z0-9.\-_]/g, '_');
    cb(null, `${nanoid(12)}_${safe}`);
  }
});

const upload = multer({
  storage,
  limits: { fileSize: 10 * 1024 * 1024 }, // 10 MB limit
  fileFilter: (req, file, cb) => {
    const allowed = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
    if (allowed.includes(file.mimetype)) cb(null, true);
    else cb(new Error('Only images are allowed'));
  }
});

// --- Express app ---------------------------------------
const app = express();
const PORT = process.env.PORT ?? 3000;

// Static assets
app.use('/static', express.static(path.join(__dirname, 'public')));
app.use('/uploads', express.static(UPLOAD_DIR));

// Logging
app.use(morgan('tiny'));

// Body parser for URL‑encoded forms (not needed for file uploads)
app.use(express.urlencoded({ extended: true }));

// Home page – simple upload form
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

// Handle file upload
app.post('/upload', upload.single('image'), (req, res) => {
  if (!req.file) return res.status(400).send('No file uploaded.');

  const id = nanoid(6); // 6‑char short id, change if you want longer
  const { filename, mimetype } = req.file;

  try {
    insertStmt.run({
      id,
      filename,
      mimetype,
      upload_ts: Date.now()
    });

    const shortUrl = `${req.protocol}://${req.get('host')}/${id}`;
    res.send(`
      <p>✅ Image uploaded!</p>
      <p>Short URL: <a href="${shortUrl}">${shortUrl}</a></p>
      <p><a href="/">Upload another</a></p>
    `);
  } catch (e) {
    console.error(e);
    res.status(500).send('Server error. Please try again.');
  }
});

// Serve an image by its short id
app.get('/:id', (req, res) => {
  const { id } = req.params;
  const row = selectStmt.get(id);
  if (!row) return res.status(404).send('Image not found.');

  const filePath = path.join(UPLOAD_DIR, row.filename);
  if (!fs.existsSync(filePath))
    return res.status(404).send('File missing on disk.');

  res.set('Content-Type', row.mimetype);
  res.sendFile(filePath);
});

// Optional: Delete image after some time or via admin route
// (Just an example; not exposed publicly)
// app.post('/delete/:id', (req, res) => { ... })

// Start server
app.listen(PORT, () => {
  console.log(`🚀 Image‑Short URL app listening on http://localhost:${PORT}`);
});
```

