## Arduino Pro Mini – “датчик‑передатчик”

Ниже – полный, полностью прокомментированный скетч.  
Он использует:

| Что | Как подключено | Что делает |
|-----|----------------|------------|
| **HC‑12** | `RX = D10`, `TX = D11` (через `SoftwareSerial`) | Передаёт/принимает данные по радиоканалу |
| **DS18B20** | `DQ = D2` (One‑Wire bus) | Читает температуру |
| **Цифровой вход** | `D3` | Считывает 0/1, которое также отправляется |

> **Важно** – перед загрузкой скетча убедитесь, что HC‑12 подключён к **D10/D11**, а не к **D0/D1** (пины 0/1 используются для загрузки и будут конфликтовать при работе).

---

```cpp
/* ------------------------------------------------------------------
   Arduino Pro Mini – датчик температуры + цифровой вход
   ---------------------------------------------------------
   Подключение:
     HC‑12  ->  D10 (RX)  D11 (TX)   (SoftwareSerial)
     DS18B20->  D2          (OneWire)
     Цифровой вход -> D3

   Протокол передачи:
     <ID>:<TEMP_C>:<DIGITAL>\n
   Пример:   01:22.3:1\n
   ------------------------------------------------------------------ */

#include <OneWire.h>           // Библиотека OneWire
#include <DallasTemperature.h>// Библиотека драйвера DS18B20
#include <SoftwareSerial.h>   // Работа с дополнительным UART

/* ---------- Константы ------------------------------------------------- */
const uint8_t PIN_DS18B20  = 2;   // Пин DS18B20 (One‑Wire)
const uint8_t PIN_DIGITAL  = 3;   // Пин цифрового входа
const uint8_t PIN_RX_HC12  = 10;  // Пин RX HC‑12 (принимает от модуля)
const uint8_t PIN_TX_HC12  = 11;  // Пин TX HC‑12 (отправляет в модуль)

const unsigned long SEND_INTERVAL = 2000; // Период отправки данных (мс)
const char      DEVICE_ID[] = "01";       // Идентификатор устройства
/* --------------------------------------------------------------------- */

// Объекты
OneWire oneWire(PIN_DS18B20);
DallasTemperature sensors(&oneWire);
SoftwareSerial hc12(PIN_RX_HC12, PIN_TX_HC12);  // (RX, TX)

// Переменные
unsigned long lastSend = 0;
float currentTemp = 0.0;
int digitalState = 0;

/* ------------------------------------------------------------------
   Инициализация: 1) HC‑12, 2) DS18B20, 3) цифровой вход
   ------------------------------------------------------------------ */
void setup() {
  pinMode(PIN_DIGITAL, INPUT_PULLUP); // Для однопроводного датчика без резистора
  // 1. Запускаем HC‑12
  hc12.begin(9600); // Стандартный бадрейт HC‑12
  hc12.setTimeout(500); // Таймаут для чтения (не обязательный)

  // 2. Запускаем датчик температуры
  sensors.begin();

  // 3. Для отладки: вывод в Serial (если нужен монитор)
  Serial.begin(115200);
  Serial.println(F("Система готова"));
}

/* ------------------------------------------------------------------
   Основной цикл: считываем, формируем пакет и отправляем
   ------------------------------------------------------------------ */
void loop() {
  unsigned long now = millis();

  // Если пришло время отправить данные
  if (now - lastSend >= SEND_INTERVAL) {
    lastSend = now;

    // ----- Считываем температуру -----
    sensors.requestTemperatures();           // Запрашиваем все датчики
    currentTemp = sensors.getTempCByIndex(0); // Берём первый датчик

    // ----- Считываем цифровой вход -----
    // Если датчик подключён к земле, используйте INPUT_PULLUP
    digitalState = digitalRead(PIN_DIGITAL);

    // ----- Формируем строку пакета -----
    // Пример: 01:22.3:1\n
    //   ID   : 2‑значный номер
    //   TEMP : число с одной дробной точкой
    //   STATE: 0 или 1
