## 2️⃣ Node.js 服务端 `server.js`

```js
/**
 * server.js
 * ----------------------------------
 * 1. 监听 3000 端口
 * 2. /run-kdj 端点：调用 stockkdj.py 并返回 stdout 内容
 */

const express = require('express');
const { execFile } = require('child_process');
const path = require('path');

const app = express();
const PORT = 3000;

// 路由：/run-kdj
app.get('/run-kdj', (req, res) => {
  // 指定 Python 可执行文件和脚本路径
  const python = process.platform === 'win32' ? 'python' : 'python3';
  const scriptPath = path.join(__dirname, 'stockkdj.py');

  execFile(python, [scriptPath], { cwd: __dirname }, (error, stdout, stderr) => {
    if (error) {
      console.error('Python script error:', error);
      res.status(500).json({ error: '执行 Python 脚本失败', details: stderr });
      return;
    }

    // 去掉尾部的换行符
    const result = stdout.trim();
    res.json({ result });
  });
});

// 首页：返回简单的 HTML 页面
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'index.html'));
});

app.listen(PORT, () => {
  console.log(`🚀 Server is running at http://localhost:${PORT}`);
});
```

