require('dotenv').config();
const express = require('express');
const cors = require('cors');
const multer = require('multer');
const { OpenAI } = require('openai');
const path = require('path');
const fs = require('fs');

// ---------- CONFIG ----------
const PORT = process.env.PORT || 5000;
const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

// ---------- EXPRESS SETUP ----------
const app = express();
app.use(cors());
app.use(express.json());
app.use(express.static(path.join(__dirname, '..', 'frontend'))); // Serve static files

// ---------- AUDIO UPLOAD ----------
const upload = multer({ dest: 'uploads/' });

app.post('/api/translate', upload.single('audio'), async (req, res) => {
  try {
    const file = req.file;
    if (!file) {
      // If no file, fall back to text input
      const barkText = req.body.barkText || '';
      return translateText(barkText, res);
    }

    // We would normally transcribe the audio first (e.g., Whisper).
    // For demo purposes, we pretend the user typed the bark text.
    // In a real implementation, you would send the audio to Whisper or use
    // the new OpenAI Audio API to get a transcription.
    const barkText = req.body.barkText || 'Bark bark'; // placeholder

    // Delete uploaded file after use
    fs.unlinkSync(file.path);

    return translateText(barkText, res);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ---------- TEXT TRANSLATION ----------
async function translateText(barkText, res) {
  if (!barkText.trim()) {
    return res.status(400).json({ error: 'No bark input provided' });
  }

  const prompt = `
You are BotDoggy, an AI that translates a dog's vocalization into clear, human‑readable text.
The input is a series of sounds the dog made.  
Translate the meaning in simple English, and if possible, give a brief explanation of the dog's emotional state.

Input:
${barkText}

Output:
  `;

  try {
    const completion = await openai.chat.completions.create({
      model: 'gpt-4o-mini', // or 'gpt-3.5-turbo'
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.2,
      max_tokens: 200,
    });

    const translation = completion.choices[0].message.content.trim();
    res.json({ translation });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: 'Error while translating' });
  }
}

// ---------- START ----------
app.listen(PORT, () => {
  console.log(`BotDoggy backend listening on port ${PORT}`);
});
```

> **Tip**: For real audio translation, replace the placeholder logic with a call to the OpenAI *Audio* API (Whisper) or another speech‑to‑text model.

