const translateBtn = document.getElementById('translateBtn');
const barkTextInput = document.getElementById('barkText');
const audioFileInput = document.getElementById('audioFile');
const outputEl = document.getElementById('output');
const loadingEl = document.getElementById('loading');

translateBtn.addEventListener('click', async () => {
  const barkText = barkTextInput.value.trim();
  const audioFile = audioFileInput.files[0];

  if (!barkText && !audioFile) {
    alert('Please type some bark or upload an audio file.');
    return;
  }

  loadingEl.classList.remove('hidden');
  outputEl.textContent = '';

  try {
    const formData = new FormData();
    if (audioFile) formData.append('audio', audioFile);
    if (barkText) formData.append('barkText', barkText);

    const res = await fetch('/api/translate', {
      method: 'POST',
      body: formData
    });

    if (!res.ok) throw new Error('Translation failed');

    const data = await res.json();
    outputEl.textContent = data.translation;
  } catch (err) {
    console.error(err);
    outputEl.textContent = '❌ Something went wrong. Please try again.';
  } finally {
    loadingEl.classList.add('hidden');
  }
});
```

