const cloud = require('wx-server-sdk')
cloud.init()

exports.main = async (event, context) => {
  const wxContext = cloud.getWXContext()
  const db = cloud.database()
  const { amount } = event

  // 防止负数
  if (amount <= 0) throw new Error('积分需为正数')

  await db.collection('users')
    .where({ _openid: wxContext.OPENID })
    .update({
      data: {
        score: db.command.inc(amount)
      }
    })

  // 记录日志
  await db.collection('transactions').add({
    from: wxContext.OPENID,
    to: wxContext.OPENID,
    amount,
    type: 'add',
    time: new Date().toISOString()
  })

  return {}
}
```

### 3.4 `transfer`

```js
const cloud = require('wx-server-sdk')
cloud.init()

exports.main = async (event, context) => {
  const wxContext = cloud.getWXContext()
  const db = cloud.database()
  const { to, amount } = event

  if (!to) throw new Error('目标 openid 不能为空')
  if (amount <= 0) throw new Error('转账金额需为正数')
  if (to === wxContext.OPENID) throw new Error('不能转账给自己')

  // 事务处理
  const wxTx = db.command
  return db.runTransaction(async tx => {
    // 读取发起人余额
    const fromDoc = await tx.collection('users')
      .doc(wxContext.OPENID)
      .get()
    const fromScore = fromDoc.data.score

    if (fromScore < amount) throw new Error('积分不足')

    // 读取目标余额
    const toDoc = await tx.collection('users')
      .doc(to)
      .get()

    if (!toDoc.data) throw new Error('目标用户不存在')

    // 更新双方积分
    await tx.collection('users')
      .doc(wxContext.OPENID)
      .update({ score: wxTx.inc(-amount) })

    await tx.collection('users')
      .doc(to)
      .update({ score: wxTx.inc(amount) })

    // 记录交易
    await tx.collection('transactions').add({
      from: wxContext.OPENID,
      to,
      amount,
      type: 'transfer',
      time: new Date().toISOString()
    })
  })
}
```

> **注意**：云函数默认使用 `cloud.database().runTransaction`（云数据库事务）来保证并发安全。

### 3.5 `getRecords`

```js
const cloud = require('wx-server-sdk')
cloud.init()

exports.main = async (event, context) => {
  const wxContext = cloud.getWXContext()
  const db = cloud.database()

  const records = await db.collection('transactions')
    .where({
      $or: [
        { from: wxContext.OPENID },
        { to: wxContext.OPENID }
      ]
    })
    .orderBy('time', 'desc')
    .get()

  // 处理显示信息
  const out = records.data.map(r => ({
    id: r._id,
    type: r.type,
    amount: r.amount,
    time: r.time,
    otherUser: r.type === 'transfer'
      ? (r.from === wxContext.OPENID ? r.to : r.from)
      : 'self'
  }))

  return { records: out }
}
```

