Ниже пример простого консольного приложения на **C++**, которое позволяет вручную ввести ориентированный граф (не взвешенный).  
Граф хранится в виде списка смежности (`std::vector<std::vector<int>>`).  
После ввода можно вывести список смежности, чтобы убедиться, что ввод прошёл корректно.

```cpp
// directed_graph_input.cpp
// C++17, компиляция: g++ -std=c++17 directed_graph_input.cpp -o directed_graph_input

#include <iostream>
#include <vector>
#include <iomanip>

int main()
{
    using namespace std;

    int n, m;                      // n – число вершин, m – число ребер
    cout << "Введите число вершин (n): ";
    while(!(cin >> n) || n <= 0) { // простая проверка входных данных
        cout << "Ошибка. Введите положительное целое число: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    cout << "Введите число ребер (m): ";
    while(!(cin >> m) || m < 0) {
        cout << "Ошибка. Введите неотрицательное целое число: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    // Список смежности: для каждой вершины хранится вектор смежных вершин
    vector<vector<int>> adj(n);

    cout << "Вводите пары (a b) для ребра a->b (индексируем с 0, т.е. вершины от 0 до "
         << n-1 << "):\n";

    for(int i = 0; i < m; ++i) {
        int from, to;
        cout << "Ребро #" << i+1 << ": ";
        while(!(cin >> from >> to) ||
              from < 0 || from >= n ||
              to < 0 || to >= n)
        {
            cout << "Неверный ввод. Введите два числа от 0 до " << n-1
                 << " (от vertex -> to vertex): ";
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
        }
        adj[from].push_back(to);
    }

    // Вывод списка смежности
    cout << "\nСписок смежности (ориентированный граф):\n";
    for(int v = 0; v < n; ++v) {
        cout << "Вершина " << v << ": ";
        for(size_t j = 0; j < adj[v].size(); ++j) {
            cout << adj[v][j];
            if (j + 1 < adj[v].size()) cout << ", ";
        }
        cout << '\n';
    }

    // Если нужно, можно вывести матрицу смежности
    cout << "\nМатрица смежности:\n";
    cout << setw(5) << "";
    for(int j = 0; j < n; ++j) cout << setw(3) << j;
    cout << '\n';
    for(int i = 0; i < n; ++i) {
        cout << setw(5) << i;
        for(int j = 0; j < n; ++j) {
            // ищем, есть ли ребро i->j
            bool edge = false;
            for(int x : adj[i]) if(x == j) { edge = true; break; }
            cout << setw(3) << (edge ? 1 : 0);
        }
        cout << '\n';
    }

    return 0;
}
```

### Как пользоваться

1. Компилируйте программу:
   ```
   g++ -std=c++17 directed_graph_input.cpp -o directed_graph_input
   ```
2. Запустите программу:
   ```
   ./directed_graph_input
   ```
3. Введите количество вершин `n` и количество ребер `m`.  
4. По очереди вводите пары `(a b)` – это ребро из вершины `a` в вершину `b`.  
   Вершины индексируются с нуля, поэтому допустимые значения: `0 … n‑1`.  
5. После ввода вы увидите список смежности и матрицу смежности, чтобы убедиться, что граф записан правильно.

### Что дальше?

- Если нужно хранить веса ребер, замените тип `int` в списке смежности на `std::pair<int, int>` (где второй элемент – вес).  
- Для больших графов удобно хранить вектор векторов `vector<vector<int>>` (как выше) или использовать `unordered_map`.  
- Вы можете расширить программу, реализовав поиск в глубину/ширину, топологическую сортировку, поиск циклов и т.д.  

Пример выше – это минимальный «шаблон», который можно развивать под свои задачи.

