下面给出一个完整、可直接编译运行的 **C 代码**，实现把 **两个升序链表** 合并为一个新的升序链表。  
合并过程中并不再为新链表申请新节点，而是直接把原链表中的节点按顺序拼接起来，保持原来的节点结构，符合「拼接给定的两个链表的所有节点组成」的要求。

```c
/*********************************************************************
 *  题目：将两个升序链表合并为一个升序链表
 *  说明：
 *      1. 输入两个升序链表的头指针 l1、l2
 *      2. 返回一个新的升序链表头指针
 *      3. 合并过程中仅调整指针，不为新链表创建新的节点
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>

/* 链表节点结构体 */
struct ListNode {
    int val;
    struct ListNode *next;
};

/* 通过链表尾部插入新节点（用于构造测试链表） */
void appendNode(struct ListNode **head, int val)
{
    struct ListNode *node = (struct ListNode*)malloc(sizeof(struct ListNode));
    node->val = val;
    node->next = NULL;

    if (*head == NULL) {
        *head = node;
    } else {
        struct ListNode *p = *head;
        while (p->next) p = p->next;
        p->next = node;
    }
}

/* 释放整个链表内存 */
void freeList(struct ListNode *head)
{
    while (head) {
        struct ListNode *tmp = head;
        head = head->next;
        free(tmp);
    }
}

/* 打印链表（调试用） */
void printList(struct ListNode *head)
{
    while (head) {
        printf("%d", head->val);
        if (head->next) printf(" -> ");
        head = head->next;
    }
    printf("\n");
}

/* 合并两个升序链表（返回合并后的链表头） */
struct ListNode* mergeTwoLists(struct ListNode* l1, struct ListNode* l2)
{
    /* 虚拟头结点，简化边界处理 */
    struct ListNode dummy;
    dummy.next = NULL;
    struct ListNode *tail = &dummy;

    /* 当两个链表都还有节点时，逐个比较并把较小的节点接到 tail 后面 */
    while (l1 && l2) {
        if (l1->val <= l2->val) {
            tail->next = l1;   /* 取 l1 的节点 */
            l1 = l1->next;
        } else {
            tail->next = l2;   /* 取 l2 的节点 */
            l2 = l2->next;
        }
        tail = tail->next;      /* 让 tail 移动到新加入的节点 */
    }

    /* 其中一个链表已空，直接把另一个链表接到 tail 后面 */
    if (l1) tail->next = l1;
    if (l2) tail->next = l2;

    return dummy.next;  /* 返回合并后的链表头 */
}

/* 主函数：演示如何使用 mergeTwoLists */
int main()
{
    /* 构造第一个升序链表 1->3->5 */
    struct ListNode *list1 = NULL;
    appendNode(&list1, 1);
    appendNode(&list1, 3);
    appendNode(&list1, 5);

    /* 构造第二个升序链表 2->4->6->8 */
    struct ListNode *list2 = NULL;
