#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "mjson.h"

#define MAX_INPUT  6          // кнопок
#define MAX_OUTPUT 6          // реле
#define MAX_MAP    12         // допустимое число записей в карте
#define MAX_CHAIN  6          // максимальная длина цепочки

/* --------- Данные, которые пользователь передаёт ---------- */

const char *json_map =
    "[ {\"input\":1, \"chain\":[2] },"
      "{\"input\":1, \"chain\":[3,4]},"
      "{\"input\":2, \"chain\":[5]} ]";

/* --------- Внутренние структуры ---------- */

typedef struct {
    int  input;          // номер кнопки (1‑6)
    int  chain_len;      // сколько реле в цепочке
    int  chain[MAX_CHAIN]; // номера реле (1‑6)
