/* --------- Парсер JSON (mjson) ---------- */

static int parse_map(const char *json, MapEntry *entries, int *cnt)
{
    struct json_object *obj = json_tokener_parse(json);
    if (!obj || json_object_get_type(obj) != json_type_array) {
        fprintf(stderr, "Ошибка парсинга JSON.\n");
        return -1;
    }

    *cnt = json_object_array_length(obj);
    if (*cnt > MAX_MAP) {
        fprintf(stderr, "Слишком много записей в карте.\n");
        json_object_put(obj);
        return -1;
    }

    for (int i = 0; i < *cnt; ++i) {
        struct json_object *elem = json_object_array_get_idx(obj, i);
        if (json_object_get_type(elem) != json_type_object) {
            fprintf(stderr, "Неверный элемент карты.\n");
            json_object_put(obj);
            return -1;
        }

        /* input */
        struct json_object *o_input = json_object_object_get(elem, "input");
        if (!o_input || json_object_get_type(o_input) != json_type_int) {
            fprintf(stderr, "Проверьте поле input.\n");
            json_object_put(obj);
            return -1;
        }
        entries[i].input = json_object_get_int(o_input);

        /* chain */
        struct json_object *o_chain = json_object_object_get(elem, "chain");
        if (!o_chain || json_object_get_type(o_chain) != json_type_array) {
            fprintf(stderr, "Проверьте поле chain.\n");
            json_object_put(obj);
            return -1;
        }
        int len = json_object_array_length(o_chain);
        if (len > MAX_CHAIN) {
            fprintf(stderr, "Слишком длинная цепочка.\n");
            json_object_put(obj);
            return -1;
        }
        entries[i].chain_len = len;
        for (int j = 0; j < len; ++j) {
            struct json_object *o_val = json_object_array_get_idx(o_chain, j);
            entries[i].chain[j] = json_object_get_int(o_val);
        }
    }

