    /* 1. Найти кнопки, у которых произошел подъем */
    int rise_mask = 0;                  // битовая маска 0‑5
    for (int i = 0; i < MAX_INPUT; ++i) {
        if (btn[i] && !prev_btn[i])         // 0 → 1
            rise_mask |= (1 << i);
    }

    /* 2. Для каждой такой кнопки выполнить обход цепочек */
    for (int i = 0; i < MAX_INPUT; ++i) {
        if (!(rise_mask & (1 << i)))
            continue;   // эта кнопка не сработала

        /* Найти все записи, где input == i+1 */
        for (int m = 0; m < map_cnt; ++m) {
            if (map[m].input != i + 1)
                continue;

            /* Проходим по цепочке */
            int visited[MAX_OUTPUT] = {0};
            for (int k = 0; k < map[m].chain_len; ++k) {
                int r = map[m].chain[k] - 1;   // 0‑based
                if (r < 0 || r >= MAX_OUTPUT) {
                    fprintf(stderr, "Неверный номер реле %d.\n",
                            map[m].chain[k]);
                    continue;
                }
                /* Включаем реле и помечаем как «заполнено» */
                relay[r] = 1;
                visited[r] = 1;

                /* Если цепочка длиннее 1 – продолжаем к следующему реле */
                /* Здесь просто включаем все реле подряд, так как
                   в примере цепочки «передают» сигнал дальше. */
                /* Если нужно более сложное поведение (например,
                   только одно реле в цепочке включается), это надо
                   изменить. */
            }
        }
    }

    /* 3. Сохраняем текущее состояние кнопок для следующего цикла */
    memcpy(prev_btn, btn, sizeof(int)*MAX_INPUT);
}

/* --------- Пример "синтеза" --------- */

int main(void)
{
    /* 1. Парсим карту */
    MapEntry map[MAX_MAP];
    int map_cnt = 0;
    if (parse_map(json_map, map, &map_cnt) != 0) {
        return EXIT_FAILURE;
    }

    /* 2. Симуляция: массивы состояний */
    int btn[MAX_INPUT]  = {0};
    int relay[MAX_OUTPUT] = {0};
    int prev_btn[MAX_INPUT] = {0};

    /* 3. Демонстрационный цикл (10 итераций) */
    for (int t = 0; t < 10; ++t) {
        /* Считаем «кнопки» (для демонстрации меняем их вручную) */
        /* Например, в 2‑й итерации нажимаем кнопку 1, в 5‑й – кнопку 2 */
        if (t == 2) btn[0] = 1;   // кнопка 1
        if (t == 5) btn[1] = 1;   // кнопка 2

        /* Обрабатываем */
        process_cycle(btn, relay, map, map_cnt, prev_btn);

        /* Выводим состояние реле */
        printf("t=%d  relay: ", t);
        for (int i = 0; i < MAX_OUTPUT; ++i)
            printf("%d ", relay[i]);
        printf("\n");

        /* Сброс кнопок (чтобы не «постоянно» держать 1) */
        for (int i = 0; i < MAX_INPUT; ++i) btn[i] = 0;
    }

    return EXIT_SUCCESS;
}
