```c
/*********************************************************************
 *  简单的银行家算法 + 时间片轮转调度（C语言实现）
 *  资源类型：A(10), B(15), C(8)
 *  进程数量：最多5个
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/*---------------------------------------------------------------*/
/* 1. 资源与进程相关定义                                    */
/*---------------------------------------------------------------*/
#define RES_TYPE 3          /* 资源种类：A,B,C */
#define MAX_PROC 5          /* 最多同时存在的进程数 */
#define MAX_NAME_LEN 8

/* 资源总量 */
int total[RES_TYPE] = {10, 15, 8};   /* A,B,C */

/* 进程状态 */
typedef enum {RUN, READY, BLOCK, FINISH} ProcState;

/* 进程控制块 (PCB) */
typedef struct {
    char  name[MAX_NAME_LEN];   /* 名字，如 P1, P2 … */
    int   max[RES_TYPE];        /* 最大需求 */
    int   alloc[RES_TYPE];      /* 已分配 */
    int   need[RES_TYPE];       /* 剩余需求 = max - alloc */
    int   pending[RES_TYPE];    /* 阻塞时的请求（待处理） */
    ProcState state;            /* 当前状态 */
} PCB;

/* 进程池（数组） */
PCB  procPool[MAX_PROC];
int  procCnt = 0;                /* 当前存活进程数 */

/* 可用资源 */
int  avail[RES_TYPE];

/* 队列（简单数组实现） */
typedef struct {
    int  idx[MAX_PROC];
    int  front, rear, size;
} Queue;

void q_init(Queue *q) { q->front = q->rear = q->size = 0; }
int  q_empty(Queue *q) { return q->size == 0; }
int  q_full (Queue *q) { return q->size == MAX_PROC; }
int  q_push (Queue *q, int val) {
    if (q_full(q)) return -1;
    q->rear = (q->rear + 1) % MAX_PROC;
    q->idx[q->rear] = val;
    q->size++;
    return 0;
}
int  q_pop  (Queue *q, int *val) {
    if (q_empty(q)) return -1;
    *val = q->idx[q->front];
    q->front = (q->front + 1) % MAX_PROC;
    q->size--;
    return 0;
}
int  q_peek (Queue *q, int *val) {
    if (q_empty(q)) return -1;
    *val = q->idx[q->front];
    return 0;
}

/*---------------------------------------------------------------*/
/* 2. 工具函数：随机数、打印等                          */
/*---------------------------------------------------------------*/
int rand_range(int n) { return rand() % n; }  /* 0 .. n-1 */

/* 生成随机资源需求（不超过 max） */
void rand_request(int *req, const int *need) {
    for (int i = 0; i < RES_TYPE; ++i)
        req[i] = rand_range(need[i] + 1);  /* 0 ~ need[i] */
}

/* 计算 need = max - alloc */
void calc_need(PCB *p) {
    for (int i = 0; i < RES_TYPE; ++i)
        p->need[i] = p->max[i] - p->alloc[i];
}

/* 生成一个随机进程 */
int new_process(const char *name, int max_need[RES_TYPE]) {
    if (procCnt >= MAX_PROC) return -1;
    PCB *p = &procPool[procCnt];
    snprintf(p->name, MAX_NAME_LEN, "%s", name);
    for (int i = 0; i < RES_TYPE; ++i) {
        int maxVal = max_need[i];
        p->max[i] = rand_range(maxVal + 1);      /* 0 .. maxVal */
        p->alloc[i] = 0;
    }
    calc_need(p);
    p->state = READY;
    p->pending[0] = p->pending[1] = p->pending[2] = 0;
    procCnt++;
    return procCnt-1;
}

/*---------------------------------------------------------------*/
/* 3. 银行家算法相关                                       */
/*---------------------------------------------------------------*/
int safe_solve(void) {
    int work[RES_TYPE];
    int finish[MAX_PROC];
    for (int i = 0; i < RES_TYPE; ++i) work[i] = avail[i];
    for (int i = 0; i < procCnt; ++i) finish[i] = 0;

    int progress;
    do {
        progress = 0;
        for (int i = 0; i < procCnt; ++i) {
            if (finish[i] || procPool[i].state == FINISH) continue;
            int ok = 1;
            for (int j = 0; j < RES_TYPE; ++j) {
                if (procPool[i].need[j] > work[j]) { ok = 0; break; }
            }
            if (ok) {
                /* 通过这个进程后释放资源 */
                for (int j = 0; j < RES_TYPE; ++j) work[j] += procPool[i].alloc[j];
                finish[i] = 1;
                progress = 1;
            }
        }
    } while (progress);

    for (int i = 0; i < procCnt; ++i)
        if (!finish[i] && procPool[i].state != FINISH) return 0;  /* not safe */

    return 1;  /* safe */
}

/* 尝试为进程 p 申请资源 req */
int request_resources(int pid, int req[RES_TYPE]) {
    /* 1. 检查是否超出需求 */
    for (int i = 0; i < RES_TYPE; ++i)
        if (req[i] > procPool[pid].need[i]) return -1;  /* 违规请求 */

    /* 2. 先预留资源，检查是否安全 */
    for (int i = 0; i < RES_TYPE; ++i) avail[i] -= req[i];
    for (int i = 0; i < RES_TYPE; ++i) procPool[pid].alloc[i] += req[i];
    calc_need(&procPool[pid]);

    if (!safe_solve()) {
        /* 不是安全的，回滚并阻塞 */
        for (int i = 0; i < RES_TYPE; ++i) avail[i] += req[i];
        for (int i = 0; i < RES_TYPE; ++i) procPool[pid].alloc[i] -= req[i];
        calc_need(&procPool[pid]);

        /* 记录待处理请求 */
        memcpy(procPool[pid].pending, req, sizeof(req));
        procPool[pid].state = BLOCK;
        return 0;  /* blocked */
    }
    /* 安全，继续执行 */
    return 1;  /* granted */
}

/* 释放进程的所有资源 */
void release_resources(int pid) {
    for (int i = 0; i < RES_TYPE; ++i) avail[i] += procPool[pid].alloc[i];
    for (int i = 0; i < RES_TYPE; ++i) procPool[pid].alloc[i] = 0;
    calc_need(&procPool[pid]);
}

/* 尝试把阻塞进程重新调度到就绪队列 */
void wake_up_blocked(Queue *ready) {
    for (int i = 0; i < procCnt; ++i) {
        if (procPool[i].state != BLOCK) continue;
        if (request_resources(i, procPool[i].pending) == 1) {
            procPool[i].state = READY;
            q_push(ready, i);
        }
    }
}

/*---------------------------------------------------------------*/
/* 4. 调度核心（时间片轮转）                               */
/*---------------------------------------------------------------*/
void scheduler(Queue *ready, Queue *finished) {
    int idx;
    if (q_pop(ready, &idx) != 0) return;  /* 无可调度进程 */

    PCB *p = &procPool[idx];
    p->state = RUN;

    /* 1. 随机请求资源 */
    int req[RES_TYPE];
    rand_request(req, p->need);

    /* 2. 申请资源 */
    int ret = request_resources(idx, req);
    if (ret == 0) {
        /* blocked */
        q_push(finished, -1);   /* nothing, keep finished queue unchanged */
        return;
    }

    /* 3. 检查是否完成 */
    int finished_flag = 1;
    for (int i = 0; i < RES_TYPE; ++i)
        if (p->need[i] > 0) finished_flag = 0;
    if (finished_flag) {
        p->state = FINISH;
        release_resources(idx);
        q_push(finished, idx);

        /* 尝试唤醒阻塞进程 */
        wake_up_blocked(ready);

        /* 随机创建新进程（最多 MAX_PROC） */
        if (procCnt < MAX_PROC) {
            char name[8];
            snprintf(name, sizeof(name), "P%d", rand_range(100)+1);
            int max_need[RES_TYPE];
            for (int j = 0; j < RES_TYPE; ++j)
                max_need[j] = total[j];   /* 允许最大需求等于总资源 */
            int nid = new_process(name, max_need);
            if (nid >= 0) q_push(ready, nid);
        }
        return;
    }

    /* 4. 还没完成，回到就绪队列 */
    p->state = READY;
    q_push(ready, idx);
}

/*---------------------------------------------------------------*/
/* 5. 打印状态                                               */
/*---------------------------------------------------------------*/
void print_state(Queue *ready, Queue *blocked, Queue *finished) {
    printf("\n===== 当前调度状态 =====\n");

    /* 当前运行的进程（在调度函数里已切回到 READY） */
    printf("Ready Queue: ");
    for (int i = 0; i < ready->size; ++i) {
        int pid = ready->idx[(ready->front + i) % MAX_PROC];
        printf("%s ", procPool[pid].name);
    }
    printf("\n");

    printf("Blocked Queue: ");
    for (int i = 0; i < blocked->size; ++i) {
        int pid = blocked->idx[(blocked->front + i) % MAX_PROC];
        printf("%s ", procPool[pid].name);
    }
    printf("\n");

    printf("Finished Queue: ");
    for (int i = 0; i < finished->size; ++i) {
        int pid = finished->idx[(finished->front + i) % MAX_PROC];
        if (pid >= 0)
            printf("%s ", procPool[pid].name);
    }
    printf("\n");

    printf("\nAvailable Resources: A=%d B=%d C=%d\n",
           avail[0], avail[1], avail[2]);

    printf("\n--- PCB 列表 ---\n");
    for (int i = 0; i < procCnt; ++i) {
        PCB *p = &procPool[i];
        const char *state_str = (p->state==RUN?"RUN":
                                 p->state==READY?"READY":
                                 p->state==BLOCK?"BLOCK":"FINISH");
        printf("%s: max=[%d %d %d]  alloc=[%d %d %d]  need=[%d %d %d]  state=%s\n",
               p->name,
               p->max[0], p->max[1], p->max[2],
               p->alloc[0], p->alloc[1], p->alloc[2],
               p->need[0], p->need[1], p->need[2],
               state_str);
    }
    printf("===============================\n");
}

/*---------------------------------------------------------------*/
/* 6. 主函数                                                 */
/*---------------------------------------------------------------*/
int main(void) {
    srand((unsigned)time(NULL));

    /* 初始化可用资源 */
    for (int i = 0; i < RES_TYPE; ++i) avail[i] = total[i];

    /* 创建初始进程（最多5个） */
    for (int i = 0; i < MAX_PROC; ++i) {
        char name[8];
        snprintf(name, sizeof(name), "P%d", i+1);
        int max_need[RES_TYPE];
        for (int j = 0; j < RES_TYPE; ++j)
            max_need[j] = total[j];
        new_process(name, max_need);
    }

    /* 队列 */
    Queue ready, blocked, finished;
    q_init(&ready); q_init(&blocked); q_init(&finished);

    /* 把所有进程放到就绪队列 */
    for (int i = 0; i < procCnt; ++i)
        q_push(&ready, i);

    /* 主调度循环（演示 50 个时间片） */
    for (int cycle = 0; cycle < 50; ++cycle) {
        scheduler(&ready, &finished);
        print_state(&ready, &blocked, &finished);
    }

    return 0;
}
```

