/*
 *  Circle Intersection Counter
 *
 *  This program reads the coordinates of the centres of two circles and
 *  their radii, then prints how many intersection points the circles
 *  have (0, 1, 2 or infinite – when the circles coincide).
 *
 *  Author:   OpenAI ChatGPT
 *  Date:     2026‑01‑31
 */

#include <stdio.h>
#include <math.h>

#define EPS 1e-9   /* tolerance for floating‑point comparisons */

int main(void)
{
    double x1, y1, r1;
    double x2, y2, r2;
    double dx, dy, d, sum, diff;

    printf("Circle 1:   Enter centre coordinates (x y) and radius r1:\n");
    if (scanf("%lf %lf %lf", &x1, &y1, &r1) != 3) {
        fprintf(stderr, "Invalid input for circle 1.\n");
        return 1;
    }

    printf("Circle 2:   Enter centre coordinates (x y) and radius r2:\n");
    if (scanf("%lf %lf %lf", &x2, &y2, &r2) != 3) {
        fprintf(stderr, "Invalid input for circle 2.\n");
        return 1;
    }

    /* Calculate distance between centres */
    dx = x2 - x1;
    dy = y2 - y1;
    d  = sqrt(dx * dx + dy * dy);

    sum = r1 + r2;
    diff = fabs(r1 - r2);

    printf("\nNumber of intersection points: ");

    /* Special case: coincident centres */
    if (fabs(d) < EPS) {
        if (fabs(r1 - r2) < EPS) {
            printf("Infinite (the circles coincide)\n");
        } else {
            printf("0 (concentric circles with different radii)\n");
        }
    } else {
        if (d > sum + EPS) {
            printf("0 (circles are separate)\n");
        } else if (d < diff - EPS) {
            printf("0 (one circle lies entirely inside the other)\n");
        } else if (fabs(d - sum) < EPS || fabs(d - diff) < EPS) {
            printf("1 (tangent circles)\n");
        } else {
            printf("2 (the circles intersect at two points)\n");
        }
    }

    return 0;
}
```

**How it works**

1. The program reads the centre coordinates `(x1, y1)` and radius `r1` for the first circle, and the same for the second circle.
2. It computes the Euclidean distance `d` between the two centres.
3. Using `d`, `r1`, and `r2`, it applies the standard geometric rules:
   * `d == 0` and `r1 == r2` → infinite intersections (coincident circles).
   * `d == 0` and `r1 != r2` → no intersection (concentric circles).
   * `d > r1 + r2` → circles are separate → 0 points.
   * `d < |r1 - r2|` → one circle lies completely inside the other → 0 points.
   * `d == r1 + r2` or `d == |r1 - r2|` → tangent → 1 point.
   * otherwise → circles intersect at two points.
4. The result is printed to the console.

