/* todo.c
 * Simple console Todo app (C11)
 *
 * Compile:   gcc -std=c11 -Wall -Wextra -o todo todo.c
 * Run:       ./todo
 *
 * Data file: todos.txt  (in the same directory)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ---------- Constants ---------- */
#define INITIAL_CAPACITY 10
#define MAX_LINE_LEN 256
#define DATA_FILE "todos.txt"

/* ---------- Data Structures ---------- */
typedef struct {
    char **items;   // Array of dynamically allocated strings
    size_t count;   // Number of items currently stored
    size_t capacity;/* Allocated size of items[] */
} TodoList;

/* ---------- Function Prototypes ---------- */
void initList(TodoList *list);
void freeList(TodoList *list);
void loadListFromFile(TodoList *list, const char *filename);
void saveListToFile(const TodoList *list, const char *filename);
void addTodo(TodoList *list, const char *description);
void listTodos(const TodoList *list);
void deleteTodo(TodoList *list, size_t index);
void showMenu(void);
int readLine(char *buffer, size_t size);
void clearStdin(void);

/* ---------- Main ---------- */
int main(void) {
    TodoList todo;
    initList(&todo);

    loadListFromFile(&todo, DATA_FILE);

    int choice;
    while (1) {
        showMenu();
        printf("Choose an option: ");
        if (scanf("%d", &choice) != 1) {
            printf("Invalid input. Try again.\n");
            clearStdin();
            continue;
        }
        clearStdin();  // Remove the trailing newline

        switch (choice) {
            case 1: { /* Add */
                char line[MAX_LINE_LEN];
                printf("Enter task description (max %zu chars): ", MAX_LINE_LEN-1);
                if (readLine(line, sizeof line)) {
                    addTodo(&todo, line);
                } else {
                    printf("Failed to read line.\n");
                }
                break;
            }
            case 2: /* List */
                listTodos(&todo);
                break;
            case 3: { /* Delete */
                if (todo.count == 0) {
                    printf("No tasks to delete.\n");
                    break;
                }
                size_t idx;
                printf("Enter the index of the task to delete: ");
                if (scanf("%zu", &idx) != 1) {
                    printf("Invalid input.\n");
                    clearStdin();
                    break;
                }
                clearStdin();
                if (idx < 1 || idx > todo.count) {
                    printf("Index out of range.\n");
                } else {
                    deleteTodo(&todo, idx - 1);
                }
                break;
            }
            case 4: /* Quit */
                saveListToFile(&todo, DATA_FILE);
                freeList(&todo);
                printf("Goodbye!\n");
                return 0;
            default:
                printf("Unknown option. Please choose 1‑4.\n");
        }
    }
}

/* ---------- Function Implementations ---------- */

/* Initialise an empty list */
void initList(TodoList *list) {
    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    list->items = calloc(list->capacity, sizeof(char *));
    if (!list->items) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

/* Release all allocated memory */
void freeList(TodoList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->items[i]);
    }
    free(list->items);
}

/* Load all lines from file into the list */
void loadListFromFile(TodoList *list, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        /* No file – start with empty list */
        return;
    }

    char line[MAX_LINE_LEN];
    while (fgets(line, sizeof(line), fp)) {
        /* Remove trailing newline */
        line[strcspn(line, "\r\n")] = '\0';
        addTodo(list, line);
    }
    fclose(fp);
}

/* Write the list back to disk */
void saveListToFile(const TodoList *list, const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s for writing.\n", filename);
        return;
    }
    for (size_t i = 0; i < list->count; ++i) {
        fprintf(fp, "%s\n", list->items[i]);
    }
    fclose(fp);
}

/* Append a new description to the list */
void addTodo(TodoList *list, const char *description) {
    /* Expand array if needed */
    if (list->count == list->capacity) {
        size_t newCap = list->capacity * 2;
        char **newItems = realloc(list->items, newCap * sizeof(char *));
        if (!newItems) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }
        list->items = newItems;
        list->capacity = newCap;
    }

    /* Store a copy of the string */
    list->items[list->count] = strdup(description);
    if (!list->items[list->count]) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }
    ++list->count;
    printf("Task added.\n");
}

/* Print all tasks */
void listTodos(const TodoList *list) {
    if (list->count == 0) {
        printf("No tasks.\n");
        return;
    }
    printf("\n--- Todo List ---\n");
    for (size_t i = 0; i < list->count; ++i) {
        printf("%zu: %s\n", i + 1, list->items[i]);
    }
    printf("-----------------\n");
}

/* Remove an item by its zero‑based index */
void deleteTodo(TodoList *list, size_t index) {
    free(list->items[index]);
    for (size_t i = index; i + 1 < list->count; ++i) {
        list->items[i] = list->items[i + 1];
    }
    --list->count;
    printf("Task deleted.\n");
}

/* Simple menu display */
void showMenu(void) {
    printf("\n=== Todo App ===\n");
    printf("1. Add a task\n");
    printf("2. List tasks\n");
    printf("3. Delete a task\n");
    printf("4. Quit\n");
}

/* Read a line of input safely */
int readLine(char *buffer, size_t size) {
    if (fgets(buffer, (int)size, stdin) == NULL) {
        return 0;
    }
    /* Trim newline */
    buffer[strcspn(buffer, "\r\n")] = '\0';
    return 1;
}

/* Clear the rest of the line if user typed too many chars */
void clearStdin(void) {
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF);
}
```

