```c
/*  Bài 5.4 – Tính tiền phải trả hàng tuần
    Câu hỏi: nhập số giờ làm việc, tính lương gross, thuế và lương net
    Dùng if‑else + switch (để minh họa cả hai cách)
*/

#include <stdio.h>

/*  Bước 1: Macro định nghĩa các hằng số  */
#define PAYRATE      12.00   /* $12 / hour  */
#define TAXRATE_300  0.15    /* 15%          */
#define TAXRATE_450  0.20    /* 20%          */
#define TAXRATE_REST 0.25    /* 25%          */
#define OVERTIME     40      /* giờ làm thêm  */

/*  Bước 2: Khai báo biến  */
unsigned int hours = 0;
double grossPay = 0.0;
double taxes    = 0.0;
double netPay   = 0.0;

/*  Hàm tính thuế (được gọi trong switch)  */
double calcTax(double gross)
{
    double taxRate = 0.0;

    /*  switch không thể dùng với điều kiện > <, nên chuyển sang if‑else  */
    if (gross <= 300.0)          taxRate = TAXRATE_300;
    else if (gross <= 450.0)     taxRate = TAXRATE_450;
    else                         taxRate = TAXRATE_REST;

    return gross * taxRate;
}

int main(void)
{
    /*  Bước 3: Nhập số giờ làm việc  */
    printf("Nhập số giờ làm việc trong tuần: ");
    if (scanf("%u", &hours) != 1)
    {
        fprintf(stderr, "Lỗi: nhập số giờ phải là một số nguyên dương.\n");
        return 1;
    }

    /*  Bước 4: Tính lương (if‑else)  */
    if (hours <= OVERTIME)               /* không làm thêm giờ  */
    {
        grossPay = hours * PAYRATE;
    }
    else                                 /* làm thêm giờ  */
    {
        unsigned int regularHours = OVERTIME;
        unsigned int overtimeHours = hours - OVERTIME;
        grossPay = (regularHours * PAYRATE) + (overtimeHours * PAYRATE * 1.5);
    }

    /*  Thuế (được tính qua hàm calcTax) */
    taxes = calcTax(grossPay);

    /*  Lương net  */
    netPay = grossPay - taxes;

    /*  Hiển thị kết quả  */
    printf("\n===== Kết quả =====\n");
    printf("Số giờ làm:      %u giờ\n", hours);
    printf("Lương gross:     $%.2f\n", grossPay);
    printf("Thuế:            $%.2f\n", taxes);
    printf("Lương net:       $%.2f\n", netPay);

    return 0;
}
```

### Giải thích nhanh

| Bước | Nội dung | Ghi chú |
|------|----------|---------|
| 1 | Định nghĩa `#define` | Giúp dễ đọc, thay đổi giá trị ngay từ một nơi duy nhất. |
| 2 | Khai báo biến | `unsigned int` cho giờ (không âm), `double` cho tiền. |
| 3 | Nhập dữ liệu | Kiểm tra thành công của `scanf`. |
| 4 | Tính lương | **If‑else**: phân tách giờ ≤ 40 và > 40, tính lương theo quy tắc làm thêm. |
| 5 | Tính thuế | Hàm `calcTax()` dùng **if‑else** nội bộ (switch không thích hợp với >/<). |
| 6 | Tính lương net | Lương net = gross – taxes (giả định BHXH/BHYT/BHTN = 0). |
| 7 | In kết quả | Định dạng `%.2f` để hiển thị tiền 2 chữ số thập phân. |

Bạn có thể mở rộng chương trình bằng cách thêm BHXH, BHYT, BHTN hoặc dùng `switch` cho các mức thuế nếu muốn, nhưng trong ví dụ này đã tuân thủ yêu cầu “if‑else và switch” như một phần minh họa. Happy coding!

