    for (int i = 0; i < n; ++i) {
        printf("Process %d burst time: ", i + 1);
        if (scanf("%d", &p[i].bursttime) != 1 || p[i].bursttime < 0) {
            fprintf(stderr, "Invalid burst time.\n");
            free(p);
            return 1;
        }
    }

    /* Compute waiting times and turnaround times */
    int totalWaiting = 0;      /* sum of all waiting times */
    p[0].waitingtime = 0;
    p[0].turnaround  = p[0].bursttime;

    for (int i = 1; i < n; ++i) {
        p[i].waitingtime = p[i-1].waitingtime + p[i-1].bursttime;
        p[i].turnaround  = p[i].waitingtime + p[i].bursttime;
    }

