```c
/*
 *  repeat_count.c
 *
 *  Count repeated numbers in a list entered by the user.
 *  The program works for any integer value (positive, negative or zero).
 *
 *  Compile with:   gcc -std=c11 -Wall -Wextra -o repeat_count repeat_count.c
 *  Run:            ./repeat_count
 *
 *  Author:   ChatGPT (2026‑01‑31)
 */

#include <stdio.h>
#include <stdlib.h>

/* Comparator for qsort (int values). */
static int cmp_int(const void *a, const void *b)
{
    int ai = *(const int *)a;
    int bi = *(const int *)b;
    return (ai > bi) - (ai < bi);          /* return 1, 0, or -1 */
}

int main(void)
{
    int n;

    printf("How many numbers will you enter? ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        fprintf(stderr, "Invalid input.\n");
        return EXIT_FAILURE;
    }

    /* Allocate array for the numbers. */
    int *arr = malloc((size_t)n * sizeof(int));
    if (!arr) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    printf("Enter %d integer(s) (separated by whitespace or newline):\n", n);
    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Failed to read number %d.\n", i + 1);
            free(arr);
            return EXIT_FAILURE;
        }
    }

    /* Sort the array so that duplicates become adjacent. */
    qsort(arr, (size_t)n, sizeof(int), cmp_int);

    /* Scan the sorted array and count duplicates. */
    int current = arr[0];
    int count   = 1;

    printf("\nRepeated numbers and their counts:\n");
    int found_repeat = 0;

    for (int i = 1; i < n; ++i) {
        if (arr[i] == current) {
            count++;
        } else {
            if (count > 1) {
                printf("  %d occurs %d times\n", current, count);
                found_repeat = 1;
            }
            current = arr[i];
            count   = 1;
        }
    }

    /* Handle the last run */
    if (count > 1) {
        printf("  %d occurs %d times\n", current, count);
        found_repeat = 1;
    }

    if (!found_repeat) {
        printf("  No repeated numbers found.\n");
    }

    free(arr);
    return EXIT_SUCCESS;
}
```

### How it works

| Step | Explanation |
|------|-------------|
| **Input** | Reads the number of integers (`n`) and then `n` integers from the user. |
| **Sort** | `qsort()` arranges the numbers in ascending order. This makes duplicates consecutive. |
| **Count** | One linear pass (`O(n)`) over the sorted array keeps track of how many times the current value has appeared. |
| **Output** | Whenever a value’s run ends, the program checks if its count is > 1 and prints it. |

