        fprintf(stderr, "Both arguments must be positive integers.\n");
        return EXIT_FAILURE;
    }

    size_t n_ops    = (size_t)n_ops_l;
    size_t n_entries = (size_t)n_entries_l;

    /* Allocate space for the vectors */
    int *vector1 = malloc(n_entries * sizeof *vector1);
    int *vector2 = malloc(n_entries * sizeof *vector2);
    int *sum     = malloc(n_entries * sizeof *sum);

    if (!vector1 || !vector2 || !sum) {
        fprintf(stderr, "Memory allocation failed.\n");
        /* Free anything that succeeded before exiting */
        free(vector1); free(vector2); free(sum);
        return EXIT_FAILURE;
    }

    /* Main loop: read, add, output */
    for (size_t i = 0; i < n_ops; ++i) {
