 *  Naciśnij Ctrl‑D (Unix) / Ctrl‑Z + Enter (Windows) aby zakończyć wprowadzanie.
 */

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    int znak;                      /* używamy int, bo getchar() zwraca EOF */

    /* Odczytujemy znaki jeden po drugim, aż napotkamy EOF */
    while ((znak = getchar()) != EOF) {
        /* Jeśli jest mała litera, zamieniamy ją na wielką */
        if (islower(znak)) {
            putchar(toupper(znak));
        } else {
            /* Inne znaki pozostawiamy bez zmian */
            putchar(znak);
        }
    }

    return 0;
}
