    out[len] = '\0';
    return out;
}

/* Найти базу по имени (basename) */
static Base *find_base(Base *bases, int count, const char *name) {
    for (int i = 0; i < count; ++i)
        if (strcmp(bases[i].basename, name) == 0)
            return &bases[i];
    return NULL;
}

/* Считывает слова из файла‑базы. Возвращает 0 при успехе, иначе -1 */
static int load_base_words(Base *b) {
    FILE *fp = fopen(b->pathtobase, "r");
    if (!fp) return -1;

    char line[LINE_MAX];
    int cap = 10;
    b->words = malloc(cap * sizeof(char *));
    if (!b->words) {
        fclose(fp);
        return -1;
    }
    b->word_count = 0;

    while (fgets(line, sizeof(line), fp)) {
        char *word = trim_quotes(line);
        if (!word) continue;          // пустая строка
        if (b->word_count >= cap) {   // расширяем массив
            cap *= 2;
            char **tmp = realloc(b->words, cap * sizeof(char *));
            if (!tmp) {
                free(word);
                fclose(fp);
                return -1;
            }
            b->words = tmp;
        }
        b->words[b->word_count++] = word;
    }
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Основные функции                                                */
/* ------------------------------------------------------------------ */

/* Чтение исходного файла, поиск файлов "text" и "data" */
static int parse_source_file(const char *src, char **text_file, char **data_file) {
    FILE *fp = fopen(src, "r");
    if (!fp) {
        fprintf(stderr, "Не удалось открыть файл '%s'\n", src);
        return -1;
    }

    char line[LINE_MAX];
    int found_text = 0, found_data = 0;

    while (fgets(line, sizeof(line), fp)) {
        /* Ищем строку вида "text":"file1.txt" */
        char tmp[LINE_MAX];
        if (sscanf(line, "\"text\":\"%[^\"]\"", tmp) == 1) {
            *text_file = strdup(tmp);
            found_text = 1;
        }
        /* Ищем строку вида "data":"file2.txt" */
        if (sscanf(line, "\"data\":\"%[^\"]\"", tmp) == 1) {
            *data_file = strdup(tmp);
            found_data = 1;
        }
        if (found_text && found_data)
            break;
    }
    fclose(fp);
    if (!found_text || !found_data) {
        fprintf(stderr, "В исходном файле не найдены обязательные строки \"text\" и/или \"data\"\n");
        return -1;
    }
    return 0;
}

/* Чтение data‑файла, создание массива структур Base */
static int parse_data_file(const char *data, Base **bases, int *count) {
    FILE *fp = fopen(data, "r");
    if (!fp) {
        fprintf(stderr, "Не удалось открыть data‑файл '%s'\n", data);
        return -1;
    }

    char line[LINE_MAX];
    int cap = 10;
    *bases = malloc(cap * sizeof(Base));
    if (!*bases) {
        fclose(fp);
        return -1;
    }
    *count = 0;

    while (fgets(line, sizeof(line), fp)) {
        char base_name[LINE_MAX], path_name[LINE_MAX];
        /* Ожидаем формат: "base-a":"./a.db" */
        if (sscanf(line, "\"%[^\"]\":\"%[^\"]\"", base_name, path_name) != 2)
            continue;   // пропускаем непонятные строки

        /* Создаём новый элемент */
        if (*count >= cap) {
            cap *= 2;
            Base *tmp = realloc(*bases, cap * sizeof(Base));
            if (!tmp) {
                fclose(fp);
                return -1;
            }
            *bases = tmp;
        }

        (*bases)[*count].basename = strdup(base_name);
        (*bases)[*count].pathtobase = strdup(path_name);
        (*bases)[*count].words = NULL;
        (*bases)[*count].word_count = 0;

        (*count)++;
    }
    fclose(fp);
    return 0;
}

/* Замена токенов %base-name% в строке шаблона */
static int replace_placeholders(const char *template, Base *bases, int base_count, char **out) {
    size_t len = strlen(template);
    /* Оценка максимальной длины результата: можно увеличить на 2 раза */
    size_t out_cap = len * 2 + 1;
    char *res = malloc(out_cap);
    if (!res) return -1;
    size_t pos = 0;          // позиция в исходной строке
    size_t out_pos = 0;      // позиция в результирующей строке

    srand((unsigned)time(NULL));   // инициализация генератора случайных чисел

    while (pos < len) {
        if (template[pos] == '%' && pos + 1 < len && template[pos+1] != '%') {
            /* нашли начало токена */
            size_t start = pos + 1;
            size_t end = start;
            while (end < len && template[end] != '%')
                end++;
            if (end < len) {
                /* получили токен без % */
                size_t token_len = end - start;
                char *token = malloc(token_len + 1);
                if (!token) {
                    free(res);
                    return -1;
                }
                strncpy(token, template + start, token_len);
                token[token_len] = '\0';

                Base *b = find_base(bases, base_count, token);
                if (b && b->word_count > 0) {
                    /* случайный выбор слова */
                    int idx = rand() % b->word_count;
                    const char *word = b->words[idx];
                    size_t word_len = strlen(word);
                    if (out_pos + word_len + 1 > out_cap) {
                        out_cap = (out_cap + word_len + 1) * 2;
                        char *tmp = realloc(res, out_cap);
                        if (!tmp) {
                            free(token);
                            free(res);
                            return -1;
                        }
                        res = tmp;
                    }
                    memcpy(res + out_pos, word, word_len);
                    out_pos += word_len;
                } else {
                    /* База не найдена – оставляем токен как есть */
                    if (out_pos + token_len + 2 > out_cap) {
                        out_cap = (out_cap + token_len + 2) * 2;
                        char *tmp = realloc(res, out_cap);
                        if (!tmp) {
                            free(token);
                            free(res);
                            return -1;
                        }
                        res = tmp;
                    }
                    res[out_pos++] = '%';
                    memcpy(res + out_pos, token, token_len);
                    out_pos += token_len;
                    res[out_pos++] = '%';
                }
                free(token);
                pos = end + 1;   /* дальше после закрывающего % */
                continue;
            }
        }
        /* обычный символ */
        if (out_pos + 2 > out_cap) {
            out_cap = (out_cap + 2) * 2;
            char *tmp = realloc(res, out_cap);
            if (!tmp) {
                free(res);
                return -1;
            }
            res = tmp;
        }
        res[out_pos++] = template[pos++];
    }
    res[out_pos] = '\0';
    *out = res;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Главная функция                                                  */
/* ------------------------------------------------------------------ */

int main(void) {
    char *source_file = NULL;
    char *output_file = NULL;

    /* 1) Спрашиваем имена файлов */
    printf("Введите имя исходного файла (source): ");
    if (!fgets(source_file = malloc(LINE_MAX), LINE_MAX, stdin)) {
        fprintf(stderr, "Ошибка ввода.\n");
        return EXIT_FAILURE;
    }
    source_file[strcspn(source_file, "\r\n")] = '\0';   // убираем LF/CR

    printf("Введите имя выходного файла: ");
    if (!fgets(output_file = malloc(LINE_MAX), LINE_MAX, stdin)) {
        fprintf(stderr, "Ошибка ввода.\n");
        free(source_file);
        return EXIT_FAILURE;
    }
    output_file[strcspn(output_file, "\r\n")] = '\0';

    /* 2) Получаем имена text‑ и data‑файлов */
    char *text_file = NULL;
    char *data_file = NULL;
    if (parse_source_file(source_file, &text_file, &data_file) != 0) {
        free(source_file); free(output_file);
        return EXIT_FAILURE;
    }

    /* 3) Читаем data‑файл, создаём массив Base */
    Base *bases = NULL;
    int base_count = 0;
    if (parse_data_file(data_file, &bases, &base_count) != 0) {
        free(source_file); free(output_file); free(text_file); free(data_file);
        return EXIT_FAILURE;
    }

    /* 4) Загрузим слова из файлов‑баз */
    for (int i = 0; i < base_count; ++i) {
        if (load_base_words(&bases[i]) != 0) {
            fprintf(stderr, "Ошибка чтения базы '%s'\n", bases[i].pathtobase);
            /* продолжаем – можно обработать ошибку иначе */
        }
    }

    /* 5) Читаем text‑файл (считаем, что он содержит ровно одну строку) */
    FILE *fp = fopen(text_file, "r");
    if (!fp) {
        fprintf(stderr, "Не удалось открыть text‑файл '%s'\n", text_file);
        /* Освобождаем ресурсы */
        goto cleanup;
    }
    char template[LINE_MAX];
    if (!fgets(template, sizeof(template), fp)) {
        fprintf(stderr, "Не удалось прочитать строку из '%s'\n", text_file);
        fclose(fp);
        goto cleanup;
    }
    fclose(fp);
    template[strcspn(template, "\r\n")] = '\0';

    /* 6) Заменяем токены */
    char *final_str = NULL;
    if (replace_placeholders(template, bases, base_count, &final_str) != 0) {
        fprintf(stderr, "Ошибка при заменах.\n");
        goto cleanup;
    }

    /* 7) Записываем результат */
    FILE *out_fp = fopen(output_file, "w");
    if (!out_fp) {
        fprintf(stderr, "Не удалось открыть файл для записи '%s'\n", output_file);
        free(final_str);
        goto cleanup;
    }
    fprintf(out_fp, "%s\n", final_str);
    fclose(out_fp);

    printf("Готово. Результат записан в '%s'\n", output_file);

    /* Освобождаем память */
    free(final_str);

cleanup:
    free(source_file); free(output_file); free(text_file); free(data_file);
    for (int i = 0; i < base_count; ++i) {
        free(bases[i].basename); free(bases[i].pathtobase);
        for (int j = 0; j < bases[i].word_count; ++j)
            free(bases[i].words[j]);
        free(bases[i].words);
    }
    free(bases);

    return EXIT_SUCCESS;
}
