```c
/*  Kruskal 算法（邻接矩阵输入）  */

#include <stdio.h>
#include <stdlib.h>

/* ---------- 结构体定义 ---------- */
typedef struct {
    int n;          /* 顶点数 */
    int **edges;    /* 邻接矩阵 */
} MGraph;

/* 边的信息 */
typedef struct {
    int u, v, w;    /* u–v 的边，权值 w */
} Edge;

/* ---------- 辅助函数 ---------- */

/* qsort 的比较函数（按权值升序） */
int cmpEdge(const void *a, const void *b)
{
    const Edge *e1 = (const Edge *)a;
    const Edge *e2 = (const Edge *)b;
    return e1->w - e2->w;
}

/* 并查集 – find（带路径压缩） */
int find(int x, int *parent)
{
    if (parent[x] != x)
        parent[x] = find(parent[x], parent);
    return parent[x];
}

/* 并查集 – union（按秩合并） */
void unite(int x, int y, int *parent, int *rank)
{
    int fx = find(x, parent);
    int fy = find(y, parent);
    if (fx == fy) return;

    if (rank[fx] < rank[fy])
        parent[fx] = fy;
    else if (rank[fx] > rank[fy])
        parent[fy] = fx;
    else {
        parent[fy] = fx;
        rank[fx]++;
    }
}

/* ---------- Kruskal 主程序 ---------- */
void Kruskal(MGraph g)
{
    /* 1. 把邻接矩阵里的边收集起来（只考虑 i<j，防止重复） */
    int maxEdges = g.n * (g.n - 1) / 2;
    Edge *edges = (Edge *)malloc(maxEdges * sizeof(Edge));
    int cnt = 0;

    for (int i = 0; i < g.n; ++i) {
        for (int j = i + 1; j < g.n; ++j) {
            int w = g.edges[i][j];
            if (w < 32767) {          /* 32767 表示无边 */
                edges[cnt].u = i;
                edges[cnt].v = j;
                edges[cnt].w = w;
                ++cnt;
            }
        }
    }

    /* 2. 按权值升序排序 */
    qsort(edges, cnt, sizeof(Edge), cmpEdge);

    /* 3. 并查集初始化 */
    int *parent = (int *)malloc(g.n * sizeof(int));
    int *rank   = (int *)malloc(g.n * sizeof(int));
    for (int i = 0; i < g.n; ++i) {
        parent[i] = i;
        rank[i]   = 0;
    }

    /* 4. 逐条选边，形成最小生成树 */
    int used = 0;
    for (int i = 0; i < cnt && used < g.n - 1; ++i) {
        Edge e = edges[i];
        if (find(e.u, parent) != find(e.v, parent)) {
            unite(e.u, e.v, parent, rank);
            printf("(%d,%d):%d\n", e.u, e.v, e.w);
            ++used;
        }
    }

    /* 5. 释放内存 */
    free(edges);
    free(parent);
    free(rank);
}

/* ---------- 主函数 ---------- */
int main(void)
{
    int n, e;
    if (scanf("%d%d", &n, &e) != 2) return 0;   /* 读取顶点数和边数（边数在后面不使用） */

    /* 读邻接矩阵 */
    MGraph g;
    g.n = n;
    g.edges = (int **)malloc(n * sizeof(int *));
    for (int i = 0; i < n; ++i)
        g.edges[i] = (int *)malloc(n * sizeof(int));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int val;
            scanf("%d", &val);
            g.edges[i][j] = val;
        }
    }

    /* 输出结果 */
    printf("Krusal:\n");
    Kruskal(g);

    /* 释放邻接矩阵 */
    for (int i = 0; i < n; ++i) free(g.edges[i]);
    free(g.edges);

    return 0;
}
```

### 说明

1. **并查集**  
   - 用 `find` 与 `unite` 实现 Kruskal 的“是否会形成环”判断。  
   - `rank` 用来保持树的高度，进一步提升效率。

2. **边的收集**  
   - 只考虑 `i < j` 的边，避免把同一条边收集两遍。  
   - 权值为 `32767` 的记为“无边”，直接忽略。

3. **排序**  
   - 使用 `qsort` 对边按权值升序排序，随后按顺序检查并加入 MST。

4. **输出格式**  
   - 首先打印 `Krusal:`，随后每行按 `(i,j):w` 的格式输出已选边。  
   - 与样例完全一致（只要输入与样例相同，输出就会相同）。

5. **内存管理**  
   - 所有动态分配的内存均在使用完毕后释放，避免内存泄漏。  

这样即可得到符合题目要求的 Kruskal 最小生成树输出。

