    if (!fSortie) {
        perror("Erreur ouverture fichier de sortie");
        return EXIT_FAILURE;
    }

    fprintf(fSortie, "Vote invalide : %d\n\n", votesInvalides);
    fprintf(fSortie, "Nombre d'electeurs : %d\n", totalVotes);
    fprintf(fSortie, "Nombre de votes valides : %d\n", totalVotes - votesInvalides);
    fprintf(fSortie, "Nombre de votes annules : %d\n\n", votesInvalides);
    fprintf(fSortie, "Candidat%*sScore\n", largeurNomMax, "");
