 *  Run:          ./calc
 */

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <math.h>

int main(void)
{
    double a, b, result;
    char op, choice;

    printf("Простой калькулятор\n");
    printf("Доступные операции: +  -  *  /\n");

    do {
        printf("\nВведите первое число: ");
        if (scanf("%lf", &a) != 1) {
            printf("Ошибка ввода!\n");
            return 1;
        }

        printf("Введите операцию (+, -, *, /): ");
        /* Считываем символ, пропуская пробелы и перевод строки */
        while ((op = getchar()) == ' ' || op == '\n');

        if (op == '/' && (scanf("%lf", &b) == 1) && b == 0.0) {
            printf("Деление на ноль невозможно!\n");
            /* сброс оставшегося ввода */
            int c;
            while ((c = getchar()) != '\n' && c != EOF);
            continue;
        }

        printf("Введите второе число: ");
        if (scanf("%lf", &b) != 1) {
            printf("Ошибка ввода!\n");
            return 1;
        }

        /* Выполняем расчёт */
        switch (op) {
            case '+':
                result = a + b;
                break;
            case '-':
                result = a - b;
                break;
            case '*':
                result = a * b;
                break;
            case '/':
                /* Деление уже проверено выше */
                result = a / b;
                break;
            default:
                printf("Неизвестная операция: %c\n", op);
                continue;
        }

        printf("Результат: %.10g\n", result);

        /* Спросим, делать ещё */
        printf("\nНовая операция? (y – продолжить, q – выйти): ");
        while ((choice = getchar()) == ' ' || choice == '\n');
    } while (choice != 'q' && choice != 'Q');

    printf("До свидания!\n");
    return 0;
}
