```c
#include <stdio.h>

/* Tính giai thừa n! bằng vòng lặp for
   (đối với n <= 20, kết quả vừa trong unsigned long long) */
int main(void)
{
    unsigned long long n, fact = 1ULL;

    printf("Nhập số n (n >= 0): ");
    if (scanf("%llu", &n) != 1)
    {
        printf("Lỗi nhập dữ liệu.\n");
        return 1;
    }

    if (n == 0 || n == 1)
    {
        fact = 1ULL;
    }
    else
    {
        for (unsigned long long i = 2; i <= n; ++i)
        {
            fact *= i;
        }
    }

    printf("%llu! = %llu\n", n, fact);
    return 0;
}
