#define MAX_TB      10
#define BUF_SIZE    512
#define BROADCAST_IP "255.255.255.255"

/* Structure d’une entrée de tb */
struct tb_entry {
    char ip[INET_ADDRSTRLEN];   /* chaîne d’adresse IP */
    uint16_t port;              /* port de l’émetteur */
};

/* Tableau partagé */
struct tb_shared {
    int  count;                     /* nombre d’entrées actuelles */
    struct tb_entry entries[MAX_TB];
};

/* Variables globales pour le nettoyage */
int shm_id = -1;
void *shm_addr = NULL;

/* Gestionnaire de signal SIGINT (Ctrl‑C) */
void cleanup(int sig) {
    if (shm_id != -1) {
        shmctl(shm_id, IPC_RMID, NULL);
    }
    exit(0);
}

/* Fonction d’impression du tableau tb */
void print_tb(struct tb_shared *tb) {
    printf("\n=== Tableau tb (télémetteurs) ===\n");
    if (tb->count == 0) {
        printf("Aucun télémetteur détecté.\n");
    } else {
        for (int i = 0; i < tb->count; ++i) {
            printf("%d : %s:%u\n", i + 1, tb->entries[i].ip,
                   ntohs(tb->entries[i].port));
        }
    }
    printf("===================================\n");
}

/* Fonction d’initialisation de la socket en mode broadcast */
int init_broadcast_socket(void) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* Autorise l’envoi sur une adresse de broadcast */
    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_BROADCAST,
                   &opt, sizeof(opt)) < 0) {
        perror("setsockopt SO_BROADCAST");
        close(sock);
        exit(EXIT_FAILURE);
    }

    return sock;
}

/* Fonction d’initialisation de la socket d’écoute */
int init_listener_socket(void) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port        = htons(PORT);

    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(sock);
        exit(EXIT_FAILURE);
    }

    return sock;
}

/* Fonction exécutée par le processus fils (écouteur) */
void receiver_process(const char *msg, struct tb_shared *tb) {
    int sock = init_listener_socket();

    char buffer[BUF_SIZE];
    struct sockaddr_in src_addr;
    socklen_t addr_len = sizeof(src_addr);

    while (1) {
        ssize_t n = recvfrom(sock, buffer, BUF_SIZE - 1, 0,
                             (struct sockaddr *)&src_addr, &addr_len);
        if (n < 0) {
            perror("recvfrom");
            continue;
        }

        buffer[n] = '\0';      /* garantir null‑termination */

        /* Vérifie si la chaîne reçue est identique à l’argument */
        if (strcmp(buffer, msg) == 0) {
            /* Ajoute l’adresse source dans tb (si il reste de la place) */
            if (tb->count < MAX_TB) {
                struct tb_entry *e = &tb->entries[tb->count++];
                inet_ntop(AF_INET, &src_addr.sin_addr,
                          e->ip, INET_ADDRSTRLEN);
                e->port = src_addr.sin_port;
                printf("-> Reçu de %s:%u, ajouté à tb\n",
                       e->ip, ntohs(src_addr.sin_port));
            } else {
                printf("-> tb plein, message ignoré\n");
            }
        }
    }
    close(sock);
}

/* Fonction exécutée par le processus père (émetteur) */
void sender_process(const char *msg, struct tb_shared *tb) {
    int sock = init_broadcast_socket();

    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family      = AF_INET;
    dest_addr.sin_port        = htons(PORT);
    if (inet_aton(BROADCAST_IP, &dest_addr.sin_addr) == 0) {
        fprintf(stderr, "inet_aton: adresse de broadcast invalide\n");
        close(sock);
        exit(EXIT_FAILURE);
    }

    time_t last_print = time(NULL);

    while (1) {
        /* Envoi du message */
        if (sendto(sock, msg, strlen(msg), 0,
                   (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
            perror("sendto");
        } else {
            printf("[Père] Envoyé: \"%s\"\n", msg);
        }

        /* Toutes les 30 s, affichage du tableau tb */
        time_t now = time(NULL);
        if (difftime(now, last_print) >= 30.0) {
            print_tb(tb);
            last_print = now;
        }

        sleep(1);
    }
    close(sock);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage : %s \"chaîne à diffuser\"\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    const char *message = argv[1];

    /* Création de la mémoire partagée */
    shm_id = shmget(IPC_PRIVATE, sizeof(struct tb_shared),
                    IPC_CREAT | 0666);
    if (shm_id < 0) {
        perror("shmget");
        exit(EXIT_FAILURE);
    }

    shm_addr = shmat(shm_id, NULL, 0);
    if (shm_addr == (void *)-1) {
        perror("shmat");
        shmctl(shm_id, IPC_RMID, NULL);
        exit(EXIT_FAILURE);
    }

    struct tb_shared *tb = (struct tb_shared *)shm_addr;
    memset(tb, 0, sizeof(struct tb_shared));   /* initialisation */

    /* Gestion du signal SIGINT pour nettoyer */
    signal(SIGINT, cleanup);

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        cleanup(0);
    } else if (pid == 0) {
        /* Processus fils : écouteur */
        receiver_process(message, tb);
        shmdt(shm_addr);
    } else {
        /* Processus père : émetteur */
        sender_process(message, tb);
        shmdt(shm_addr);
    }

    /* Le programme ne devrait jamais atteindre ce point */
    return 0;
}
```

### Explications rapides
| Élément | Rôle |
|---------|------|
| **`struct tb_shared`** | Tableau partagé (max 10 entrées) contenant IP et port. |
| **`shmget` / `shmat`** | Allocation et attachement de la mémoire partagée. |
| **`fork()`** | Création du père (émetteur) et de l’enfant (écouteur). |
| **Socket de broadcast** | `setsockopt(SO_BROADCAST)` permet d’envoyer à `255.255.255.255`. |
| **Socket d’écoute** | `bind` à `INADDR_ANY` sur le port 2346. |
| **`recvfrom`** | Récupère l’adresse source via `src_addr`. |
| **Gestion du tableau** | Le père n’imprime le tableau que toutes les 30 s. |
| **Signal `SIGINT`** | Nettoyage de la mémoire partagée lors de `Ctrl‑C`. |

Ce programme est autonome et illustre l’usage de UDP broadcast, de fork et de mémoire partagée en C.

