Below is a **very small, self‑contained example** that shows how a *client* can talk to a *server* that acts as an HTTP CONNECT proxy but every payload is wrapped in **Base64**.  
The example is intentionally minimal so you can copy‑paste the two programs into separate files, build and run them on a Linux/Unix box (or any system that has the OpenSSL development headers).

> **Why Base64?**  
> The server will accept a normal HTTP CONNECT request, reply with `200 Connection Established`, and then enter a raw‑data mode.  
> The client will encode every byte that it sends to the server in Base64, the server will decode it, forward it to the destination host, read the destination’s reply, Base64‑encode that reply and stream it back to the client.  
> The result is a **simple “HTTP tunnel over Base64”** that you can test with any HTTP client (e.g. `curl`) or a custom program.

--------------------------------------------------------------------
### 1. Common helpers – Base64 encode / decode

Both programs use the same tiny helper that lives in `b64.c` / `b64.h`.  
It’s built on top of OpenSSL’s EVP interface so you need `-lssl -lcrypto` on the link line.

**b64.h**
```c
#ifndef B64_H
#define B64_H

/* Encode plain data into Base64.
 * Returned buffer must be freed by the caller. */
char *b64_encode(const unsigned char *in, size_t inlen, size_t *outlen);

/* Decode Base64 data.
 * Returned buffer must be freed by the caller. */
unsigned char *b64_decode(const char *in, size_t inlen, size_t *outlen);

#endif /* B64_H */
```

**b64.c**
```c
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include "b64.h"

static const char *base64_table =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    "abcdefghijklmnopqrstuvwxyz"
    "0123456789+/";

char *b64_encode(const unsigned char *in, size_t inlen, size_t *outlen)
{
    /* 4/3 overhead + 1 for NUL */
    size_t enc_len = 4 * ((inlen + 2) / 3) + 1;
    char *enc = malloc(enc_len);
    if (!enc) return NULL;

    EVP_ENCODE_CTX *ctx = EVP_ENCODE_CTX_new();
    int outl = 0;
    EVP_EncodeInit(ctx);
    EVP_EncodeUpdate(ctx, (unsigned char *)enc, &outl, in, inlen);
    int finl = 0;
    EVP_EncodeFinal(ctx, (unsigned char *)enc + outl, &finl);
    EVP_ENCODE_CTX_free(ctx);
    *outlen = outl + finl;
    enc[*outlen] = '\0';
    return enc;
}

unsigned char *b64_decode(const char *in, size_t inlen, size_t *outlen)
{
    /* Worst case: same size as input */
    size_t dec_len = inlen;
    unsigned char *dec = malloc(dec_len);
    if (!dec) return NULL;

    EVP_ENCODE_CTX *ctx = EVP_ENCODE_CTX_new();
    int outl = 0;
    EVP_DecodeInit(ctx);
    EVP_DecodeUpdate(ctx, dec, &outl, (const unsigned char *)in, inlen);
    int finl = 0;
    EVP_DecodeFinal(ctx, dec + outl, &finl);
    EVP_ENCODE_CTX_free(ctx);
    *outlen = outl + finl;
    return dec;
}
```

Compile the helper once:
```bash
gcc -c b64.c
```

--------------------------------------------------------------------
### 2. The Server – “b64‑proxy”

**b64_proxy.c**
```c
/*
 * A minimal HTTP CONNECT proxy that forwards data in Base64.
 * Usage: ./b64_proxy <listen_port>
 *
 * The server will accept a CONNECT request, reply with
 * "200 Connection Established", then read Base64 data from
 * the client, decode it, forward it to the requested host,
 * read the reply, encode it and stream it back to the client.
 *
 * Compile:
 *   gcc -o b64_proxy b64_proxy.c b64.o -lssl -lcrypto -pthread
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/select.h>
#include <signal.h>

#include "b64.h"

#define BUF_SIZE 4096
#define MAX_HEADER_SIZE 8192
#define MAX_HOST_LEN 256

/* Helper: read until double CRLF or buffer full */
static ssize_t read_header(int fd, char *buf, size_t max)
{
    size_t tot = 0;
    while (tot < max) {
        ssize_t n = recv(fd, buf + tot, 1, 0);
        if (n <= 0) return n;      // error or closed
        tot += n;
        if (tot >= 4 && strstr(buf, "\r\n\r\n") != NULL)
            return tot;
    }
    return -1;   // header too big
}

/* Parse CONNECT line: "CONNECT host:port HTTP/1.1" */
static int parse_connect(const char *hdr, char *host, int *port)
{
    const char *p = strstr(hdr, "CONNECT ");
    if (!p) return -1;
    p += 8; // skip CONNECT
    const char *end = strstr(p, " HTTP");
    if (!end) return -1;
    char tmp[512];
    if (end - p >= sizeof(tmp)) return -1;
    memcpy(tmp, p, end - p);
    tmp[end - p] = '\0';

    char *colon = strchr(tmp, ':');
    if (!colon) return -1;
    *colon = '\0';
    strncpy(host, tmp, MAX_HOST_LEN-1);
    host[MAX_HOST_LEN-1] = '\0';
    *port = atoi(colon + 1);
    return 0;
}

/* Connect to destination host:port */
static int connect_to(const char *host, int port)
{
    struct addrinfo hints, *res, *rp;
    int sfd = -1;
    char portstr[6];
    snprintf(portstr, sizeof(portstr), "%d", port);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family   = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(host, portstr, &hints, &res) != 0) {
        perror("getaddrinfo");
        return -1;
    }

    for (rp = res; rp; rp = rp->ai_next) {
        sfd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (sfd == -1) continue;
        if (connect(sfd, rp->ai_addr, rp->ai_addrlen) != -1) break;
        close(sfd); sfd = -1;
    }
    freeaddrinfo(res);
    return sfd;
}

/* Forward data between two sockets with Base64 on the client side. */
static void forward_loop(int client_fd, int dst_fd)
{
    char buf[BUF_SIZE];
    ssize_t n;

    /* Set both sockets to non‑blocking to avoid deadlocks */
    fcntl(client_fd, F_SETFL, O_NONBLOCK);
    fcntl(dst_fd,    F_SETFL, O_NONBLOCK);

    fd_set rfds;
    int maxfd = client_fd > dst_fd ? client_fd : dst_fd;
    maxfd++;

    while (1) {
        FD_ZERO(&rfds);
        FD_SET(client_fd, &rfds);
        FD_SET(dst_fd,    &rfds);

        int ready = select(maxfd, &rfds, NULL, NULL, NULL);
        if (ready < 0) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        }

        /* From client → dst */
        if (FD_ISSET(client_fd, &rfds)) {
            n = recv(client_fd, buf, sizeof(buf), 0);
            if (n <= 0) break;
            size_t dec_len;
            unsigned char *dec = b64_decode(buf, n, &dec_len);
            if (!dec) { fprintf(stderr, "b64 decode error\n"); break; }
            if (send(dst_fd, dec, dec_len, 0) != (ssize_t)dec_len) {
                free(dec); break;
            }
            free(dec);
        }

        /* From dst → client */
        if (FD_ISSET(dst_fd, &rfds)) {
            n = recv(dst_fd, buf, sizeof(buf), 0);
            if (n <= 0) break;
            size_t enc_len;
            char *enc = b64_encode((unsigned char *)buf, n, &enc_len);
            if (!enc) { fprintf(stderr, "b64 encode error\n"); break; }
            if (send(client_fd, enc, enc_len, 0) != (ssize_t)enc_len) {
                free(enc); break;
            }
            free(enc);
        }
    }
}

static void handle_connection(int conn_fd)
{
    char header[MAX_HEADER_SIZE];
    ssize_t hlen = read_header(conn_fd, header, sizeof(header));
    if (hlen <= 0) {
        close(conn_fd);
        return;
    }

    char host[MAX_HOST_LEN];
    int port = 0;
    if (parse_connect(header, host, &port) != 0) {
        const char *bad = "HTTP/1.1 400 Bad Request\r\n\r\n";
        send(conn_fd, bad, strlen(bad), 0);
        close(conn_fd);
        return;
    }

    /* Connect to destination */
    int dst_fd = connect_to(host, port);
    if (dst_fd < 0) {
        const char *fail = "HTTP/1.1 502 Bad Gateway\r\n\r\n";
        send(conn_fd, fail, strlen(fail), 0);
        close(conn_fd);
        return;
    }

    /* Tell the client we’re ready */
    const char *ok = "HTTP/1.1 200 Connection Established\r\n\r\n";
    send(conn_fd, ok, strlen(ok), 0);

    /* Enter raw data loop */
    forward_loop(conn_fd, dst_fd);

    close(dst_fd);
    close(conn_fd);
}

static void sigchld_handler(int sig)
{
    (void)sig;
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <listen_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int port = atoi(argv[1]);

    /* Ignore SIGPIPE to keep send() from dying */
    signal(SIGPIPE, SIG_IGN);
    /* Reap zombies */
    signal(SIGCHLD, sigchld_handler);

    /* Socket setup */
    int listen_fd;
    struct sockaddr_in srv_addr;
    listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    memset(&srv_addr, 0, sizeof(srv_addr));
    srv_addr.sin_family      = AF_INET;
    srv_addr.sin_addr.s_addr = INADDR_ANY;
    srv_addr.sin_port        = htons(port);

    bind(listen_fd, (struct sockaddr *)&srv_addr, sizeof(srv_addr));
    listen(listen_fd, SOMAXCONN);

    printf("b64_proxy listening on port %d\n", port);

    while (1) {
        struct sockaddr_in cli_addr;
        socklen_t cli_len = sizeof(cli_addr);
        int conn_fd = accept(listen_fd, (struct sockaddr *)&cli_addr, &cli_len);
        if (conn_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }

        /* Fork a child to handle the connection */
        pid_t pid = fork();
        if (pid < 0) {
            perror("fork");
            close(conn_fd);
            continue;
        }
        if (pid == 0) {     /* child */
            close(listen_fd);
            handle_connection(conn_fd);
            exit(EXIT_SUCCESS);
        }
        /* parent */
        close(conn_fd);
    }

    close(listen_fd);
    return 0;
}
```

--------------------------------------------------------------------
### 3. The Client – “b64_client”

**b64_client.c**
```c
/*
 * A tiny client that connects to the b64_proxy and sends a simple HTTP GET
 * request encoded in Base64. It reads the Base64 reply, decodes it
 * and prints it to stdout.
 *
 * Usage:
 *   ./b64_client <proxy_host> <proxy_port> <target_host> <target_port> <path>
 *
 * Compile:
 *   gcc -o b64_client b64_client.c b64.o -lssl -lcrypto
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#include "b64.h"

#define BUF_SIZE 4096

static int connect_to(const char *host, int port)
{
    struct addrinfo hints, *res, *rp;
    int sfd = -1;
    char portstr[6];
    snprintf(portstr, sizeof(portstr), "%d", port);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family   = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(host, portstr, &hints, &res) != 0) {
        perror("getaddrinfo");
        return -1;
    }

    for (rp = res; rp; rp = rp->ai_next) {
        sfd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (sfd == -1) continue;
        if (connect(sfd, rp->ai_addr, rp->ai_addrlen) != -1) break;
        close(sfd); sfd = -1;
    }
    freeaddrinfo(res);
    return sfd;
}

/* Send a CONNECT request to the proxy */
static int do_connect(int sock, const char *dest_host, int dest_port)
{
    char req[512];
    snprintf(req, sizeof(req),
             "CONNECT %s:%d HTTP/1.1\r\nHost: %s:%d\r\n\r\n",
             dest_host, dest_port, dest_host, dest_port);
    if (send(sock, req, strlen(req), 0) != (ssize_t)strlen(req))
        return -1;

    /* Read until blank line */
    char resp[2048];
    ssize_t n = recv(sock, resp, sizeof(resp)-1, 0);
    if (n <= 0) return -1;
    resp[n] = '\0';

    /* Very naive status‑code check */
    if (strncmp(resp, "HTTP/1.1 200", 12) != 0)
        return -1;
    return 0;
}

/* Send a Base64‑encoded payload */
static int send_b64(int sock, const unsigned char *data, size_t len)
{
    size_t enc_len;
    char *enc = b64_encode(data, len, &enc_len);
    if (!enc) return -1;
    int res = send(sock, enc, enc_len, 0) == (ssize_t)enc_len ? 0 : -1;
    free(enc);
    return res;
}

/* Receive a Base64‑encoded response and write the decoded bytes to stdout */
static int recv_and_print(int sock)
{
    char buf[BUF_SIZE];
    ssize_t n;
    while ((n = recv(sock, buf, sizeof(buf), 0)) > 0) {
        size_t dec_len;
        unsigned char *dec = b64_decode(buf, n, &dec_len);
        if (!dec) {
            fprintf(stderr, "b64 decode failed\n");
            return -1;
        }
        fwrite(dec, 1, dec_len, stdout);
        free(dec);
    }
    return 0;
}

int main(int argc, char *argv[])
{
