    f->visited = 1;
    for (CallNode *c = f->calls; c; c = c->next) {
        Function *next = find_function(c->name);
        if (!next) continue;          /* вызов функции, которую не нашли в таблице */
        if (next->visited) continue;  /* избежать бесконечных циклов */
