        // создания окна/SwapChain из RenderTargetView и т.п.
        ID3D11Device* pDevice = nullptr;
        ID3D11DeviceContext* pContext = nullptr;
        D3D_FEATURE_LEVEL fl = D3D_FEATURE_LEVEL_11_0;
        HRESULT hr = D3D11CreateDevice(nullptr, D3D_DRIVER_TYPE_HARDWARE,
                                        nullptr, 0, &fl, 1,
                                        D3D11_SDK_VERSION,
                                        &pDevice, nullptr, &pContext);
        if (SUCCEEDED(hr))
        {
            DXGI_SWAP_CHAIN_DESC desc = {};
            desc.BufferDesc.Width = 1;
            desc.BufferDesc.Height = 1;
            desc.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
            desc.BufferDesc.RefreshRate.Numerator = 60;
            desc.BufferDesc.RefreshRate.Denominator = 1;
            desc.SampleDesc.Count = 1;
            desc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
            desc.OutputWindow = GetDesktopWindow();
            desc.Windowed = TRUE;
            desc.SwapEffect = DXGI_SWAP_EFFECT_DISCARD;
            desc.Flags = 0;

            IDXGISwapChain* pTmp = nullptr;
            if (SUCCEEDED(pDevice->GetAdapter()->GetParent(
                                __uuidof(IDXGIFactory2), reinterpret_cast<void**>(&pTmp))))
            {
                IDXGIFactory2* pFactory = reinterpret_cast<IDXGIFactory2*>(pTmp);
                hr = pFactory->CreateSwapChain(pDevice, &desc, &pSwapChain);
                pFactory->Release();
            }
            pContext->Release();
            pDevice->Release();

            if (FAILED(hr))
                pSwapChain = nullptr;
        }
        if (!pSwapChain) Sleep(50);
    }

    // Получаем vtable и ставим хук
    if (pSwapChain)
    {
        // Инициализируем MinHook
        if (MH_Initialize() != MH_OK)
        {
            MessageBoxA(NULL, "MH_Initialize() failed", "Error", MB_ICONERROR);
            return 0;
        }

        DWORD_PTR* vTable = *(DWORD_PTR**)pSwapChain;
        // Present – индекс 8
        if (MH_CreateHook(reinterpret_cast<void*>(vTable[8]),
                          &hkPresent,
                          reinterpret_cast<void**>(&oPresent)) == MH_OK)
        {
            MH_EnableHook(reinterpret_cast<void*>(vTable[8]));
        }
    }

    return 0;
}

// ---------------------------------------------------------------------
// 6. DLL Entry Point
BOOL APIENTRY DllMain(HMODULE hModule,
                      DWORD   ul_reason_for_call,
                      LPVOID  lpReserved)
{
    switch (ul_reason_for_call)
    {
    case DLL_PROCESS_ATTACH:
        DisableThreadLibraryCalls(hModule);
        CreateThread(nullptr, 0, HookThread, nullptr, 0, nullptr);
        break;
    case DLL_PROCESS_DETACH:
        // Очищаем ImGui
        if (g_Initialized)
        {
            ImGui_ImplDX11_Shutdown();
            ImGui_ImplWin32_Shutdown();
            ImGui::DestroyContext();
        }

        // Удаляем хук и завершаем MinHook
        if (oPresent)
        {
            MH_DisableHook(MH_ALL_HOOKS);
            MH_Uninitialize();
        }
        break;
    }
    return TRUE;
}
```

### Что делает код

1. **HookThread** создаёт временный `IDXGISwapChain` (чтобы получить адрес `Present`) и ждёт, пока в игре реально не будет создан swap‑chain.  
2. На найденной точке (`vTable[8]`) ставится MinHook, перенаправляя вызовы в `hkPresent`.  
3. **`hkPresent`**:  
   * При первом вызове инициализирует ImGui (получает `ID3D11Device`, `ID3D11DeviceContext`, `HWND`).  
   * Обрабатывает клавишу **Insert** – открывает/закрывает меню.  
   * Отрисовывает простое меню (показывает FPS, счетчик, кнопку, demo‑окно).  
   * Вызывает оригинальный `Present`.  

---

## 3. Как собрать

1. **Скачайте MinHook** – https://github.com/TsudaKageyu/minhook (или включите заголовки и `minhook.lib` в проект).  
2. **Скачайте ImGui** – https://github.com/ocornut/imgui. Скопируйте исходники в папку `imgui/`.  
3. Создайте новый **Win32 DLL** проект в Visual Studio.  
4. Добавьте в проект все файлы выше, включите пути к `include/` и `src/`.  
5. В `Project Properties` → `Linker` → `Input` добавьте `minhook.lib` и `dxgi.lib`, `d3d11.lib`.  
6. Скомпилируйте. Получится `YourDll.dll`.

---

## 4. Инъекция в игру

Существует много готовых инструментов (rcedit, Extreme Injector, EasyHook, etc.).  
Самый простой способ:

```bat
@echo off
start "" "C:\Windows\System32\regsvr32.exe" /s /n %1
```

или с помощью `WinRAR` → `Вставка` → `DLL`.  
Просто запустите ваш injector, укажите путь к DLL и к исполняемому файлу игры.

---

## 5. Что можно улучшить / изменить

| Возможность | Как сделать |
|-------------|------------|
| Меню в стиле `ImGui::Begin("MyMenu")` | Добавьте `ImGui::GetIO().MouseDrawCursor = true;` и обработайте мышь через `ImGui_ImplWin32_WndProcHandler`. |
| Показать/скрыть меню с `VK_F1` | Поменяйте `VK_INSERT` на `VK_F1` в `ToggleMenu`. |
| Установить свой стиль | `ImGui::StyleColorsClassic()` / `ImGui::StyleColorsDark()` / `ImGui::StyleColorsLight()` + свои цветовые палитры. |
| Удерживание клавиши (чтобы не срабатывать несколько раз) | Используйте переменную `bool prevKey = false;` и сравнивайте `GetAsyncKeyState`. |
| Удалить зависимость от `DXGI_SWAP_CHAIN_DESC` | Можно получить `HWND` из `GetActiveWindow()` или через `GetForegroundWindow()`. |

---

## 6. Советы по отладке

| Ситуация | Что проверить |
|----------|---------------|
| DLL не «переходит» в `DLL_PROCESS_ATTACH` | Проверьте, что injector действительно загружает DLL. |
| Хук не работает | Убедитесь, что vTable[8] действительно `Present`. Для некоторых игр (DXGI 1.3+) индекс может отличаться. |
| ImGui не отображается | Убедитесь, что `g_pd3dDevice` и `g_pd3dDeviceContext` корректны; проверьте, что `ImGui_ImplDX11_Init` возвращает `TRUE`. |
| Вылетает при первом вызове | Попробуйте добавить `__try / __except` вокруг вызова `oPresent`. |

---

## 7. Заключение

Ниже представлен минимальный, но полностью работоспособный пример хука `Present` для DirectX 11 и меню ImGui.  
С его помощью можно быстро добавить UI к любой игре, которая использует DX11.  
Надеюсь, этот материал будет полезен при создании ваших модов, инструментов отладки или учебных проектов!

