/* Kiểm tra xem một số nguyên dương có phải số đối xứng không */
int is_palindrome(int n)
{
    if (n < 0)           /* số âm không được xem là đối xứng */
        return 0;

    int original = n, rev = 0;
    while (n > 0) {
        rev = rev * 10 + n % 10;
        n /= 10;
    }
    return rev == original;
}

