## 1.  Kod źródłowy

```c
/*  sem_demo.c  –  kontrola dwóch jednosegmentowych semaforów
 *
 *  Kompilacja:
 *      gcc -pthread -o sem_demo sem_demo.c
 *
 *  Użycie:
 *      # blokowanie
 *          ./sem_demo
 *
 *          (klawisze)
 *              1   –  zarezerwuj semafor 1
 *              q   –  zwolnij semafor 1
 *              2   –  zarezerwuj semafor 2
 *              w   –  zwolnij semafor 2
 *
 *          Uruchom dwie instancje. Jedna może „zajmować” semafor, a druga
 *          będzie w trybie oczekiwania (blokada). Gdy pierwsza zwolni,
 *          druga odblokuje się.
 *
 *      # zakleszczenie
 *          ./sem_demo -d
 *
 *          Po uruchomieniu program poprosi o wybór kolejności:
 *              1 – sem1 → sem2
 *              2 – sem2 → sem1
 *
 *          Uruchom dwie instancje z różnymi wyborami – nastąpi deadlock.
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <semaphore.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <errno.h>

#define SEM1_NAME "/sem_demo_sem1"
#define SEM2_NAME "/sem_demo_sem2"

static sem_t *sem1 = NULL;
static sem_t *sem2 = NULL;
static int  is_deadlock_mode = 0;

/* ------------------------------------------------------------------ */
/*  Obsługa sygnału SIGINT – czyść i zamknij semafory                */
/* ------------------------------------------------------------------ */
static void cleanup(int signo)
{
    (void)signo;               /* nie używamy */
    if (sem1) sem_close(sem1);
    if (sem2) sem_close(sem2);
    /* Nie usuwamy semaforów w trybie normalnym – pozwalamy innym procesom na dalsze użycie. */
    printf("\n[%d] Zakończono program.\n", getpid());
    exit(EXIT_SUCCESS);
}

/* ------------------------------------------------------------------ */
static void open_semaphores(void)
{
    sem1 = sem_open(SEM1_NAME, O_CREAT, 0644, 1);
    if (sem1 == SEM_FAILED) {
        perror("sem_open SEM1");
        exit(EXIT_FAILURE);
    }

    sem2 = sem_open(SEM2_NAME, O_CREAT, 0644, 1);
    if (sem2 == SEM_FAILED) {
        perror("sem_open SEM2");
        exit(EXIT_FAILURE);
    }
}

/* ------------------------------------------------------------------ */
static void close_semaphores(void)
{
    if (sem1) sem_close(sem1);
    if (sem2) sem_close(sem2);
}

/* ------------------------------------------------------------------ */
/*  Tryb normalny – ręczne sterowanie z klawiatury                    */
/* ------------------------------------------------------------------ */
static void run_normal_mode(void)
{
    printf("\n[%d] Tryb normalny (blokowanie).\n", getpid());
    printf("Klawisze:\n  1 – zarezerwuj sem1\n  q – zwolnij sem1\n  2 – zarezerwuj sem2\n  w – zwolnij sem2\n  x – zakończ\n\n");

    int c;
    while ((c = getchar()) != EOF) {
        if (c == '\n' || c == '\r')
            continue;   /* ignoruj enter */

        switch (c) {
        case '1':
            printf("[%d] Próba zarezerwowania sem1… ", getpid());
            fflush(stdout);
            if (sem_wait(sem1) == 0)
                printf("zarezerwowano!\n");
            else
                perror("sem_wait sem1");
            break;
        case 'q':
            if (sem_post(sem1) == 0)
                printf("[%d] Zwolniono sem1.\n", getpid());
            else
                perror("sem_post sem1");
            break;
        case '2':
            printf("[%d] Próba zarezerwowania sem2… ", getpid());
            fflush(stdout);
            if (sem_wait(sem2) == 0)
                printf("zarezerwowano!\n");
            else
                perror("sem_wait sem2");
            break;
        case 'w':
            if (sem_post(sem2) == 0)
                printf("[%d] Zwolniono sem2.\n", getpid());
            else
                perror("sem_post sem2");
            break;
        case 'x':
            printf("[%d] Wyjście.\n", getpid());
            return;
        default:
            printf("Nieznany klawisz: %c\n", c);
        }
    }
}

/* ------------------------------------------------------------------ */
/*  Tryb deadlock – automatyczne wchodzenie w zakleszczenie           */
/* ------------------------------------------------------------------ */
static void run_deadlock_mode(void)
{
    printf("\n[%d] Tryb deadlock. Wybierz kolejność:\n  1 – sem1 → sem2\n  2 – sem2 → sem1\n", getpid());

    int order = 0;
    while (order != 1 && order != 2) {
        int c = getchar();
        if (c == '1' || c == '2') {
            order = c - '0';
        } else if (c == '\n' || c == '\r') {
            continue;
        } else {
            printf("Wybierz 1 lub 2: ");
        }
    }

    printf("[%d] Wybrano kolejność %s.\n",
           getpid(),
           order == 1 ? "sem1 → sem2" : "sem2 → sem1");

    /* W pierwszym procesie: sem1 → sem2, w drugim: sem2 → sem1. */
    if (order == 1) {
        printf("[%d] Próba zarezerwowania sem1… ", getpid());
        fflush(stdout);
        sem_wait(sem1);
        printf("zarezerwowano!\n");

        printf("[%d] Próba zarezerwowania sem2… ", getpid());
        fflush(stdout);
        sem_wait(sem2);
        printf("zarezerwowano!\n");

        /* Po sukcesie zwalniamy */
        sem_post(sem2);
        sem_post(sem1);
    } else {
        printf("[%d] Próba zarezerwowania sem2… ", getpid());
        fflush(stdout);
        sem_wait(sem2);
        printf("zarezerwowano!\n");

        printf("[%d] Próba zarezerwowania sem1… ", getpid());
        fflush(stdout);
        sem_wait(sem1);
        printf("zarezerwowano!\n");

        /* Po sukcesie zwalniamy */
        sem_post(sem1);
        sem_post(sem2);
    }

    printf("[%d] Operacje zakończone (lub program zablokowany).\n", getpid());
    /* Program nie kończy się, jeśli doszło do deadlocku – użytkownik musi przerwać. */
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    /* Rejestracja obsługi SIGINT (Ctrl+C) */
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* Czytanie flag */
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-d") == 0)
            is_deadlock_mode = 1;
    }

    /* Otwieramy semafory */
    open_semaphores();

    /* Uruchamiamy odpowiedni tryb */
    if (is_deadlock_mode)
        run_deadlock_mode();
    else
        run_normal_mode();

    /* Sprzątamy */
    close_semaphores();
    return 0;
}
```

