### 2.  `magazzino.c`

```c
/*  magazzino.c  -----------------------------------------------------------
 *  Implementation of the functions declared in magazzino.h
 *  ----------------------------------------------------------------------- */

#include "magazzino.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>

/* --------------------------------------------------------------------- */
/* Helper: Compute total value of a product (in centesimi)               */
/* --------------------------------------------------------------------- */
static inline int valore_totale(const Prodotto *p) {
    return p->costo_centesimi * p->quantità;
}

/* --------------------------------------------------------------------- */
/* 1) Lettura del file --------------------------------------------------- */
int leggi_magazzino(FILE *fp, Prodotto prod[], int *n_prodotti) {
    char line[256];
    int  cnt = 0;

    if (!fp || !prod || !n_prodotti) return 1;

    while (fgets(line, sizeof(line), fp)) {
        if (cnt >= MAX_PRODOTTI) {
            fprintf(stderr, "Errore: superato il numero massimo di prodotti (%d)\n",
                    MAX_PRODOTTI);
            return 1;
        }

        /* Skip empty lines */
        char *p = line;
        while (isspace((unsigned char)*p)) ++p;
        if (*p == '\0' || *p == '#') continue;

        Prodotto tmp;
        /* read: codice cost quantita */
        int fields = sscanf(line, "%31s %lf %d",
                            tmp.codice,
                            &(double){0},
                            &tmp.quantità);
        if (fields != 3) {
            fprintf(stderr, "Formato non valido: %s", line);
            continue; /* skip this line */
        }

        /* cost read as double, convert to cents (round to nearest int) */
        double cost;
        sscanf(line, "%31s %lf %d", tmp.codice, &cost, &tmp.quantità);
        tmp.costo_centesimi = (int)llround(cost * 100.0);

        prod[cnt++] = tmp;
    }

    *n_prodotti = cnt;
    return 0;
}

/* --------------------------------------------------------------------- */
/* 2) Controllo aggiornamento ------------------------------------------- */
int check_aggiornamento(Prodotto prod[], int n_prodotti,
                        const char *codice, int variazione) {
    int i;

    if (!prod || !codice) return -1;

    for (i = 0; i < n_prodotti; ++i) {
        if (strcmp(prod[i].codice, codice) == 0) {
            /* product found */
            int nuova_qty = prod[i].quantità + variazione;

            /* rule checks */
            if (nuova_qty < 0) return -2;           /* decrement too large */
            if (nuova_qty > 10000) return -2;        /* too many units */
            /* All good */
            return 1;
        }
    }
    return -1; /* not found */
}

/* --------------------------------------------------------------------- */
/* 3) Aggiornamento e stampa --------------------------------------------- */
void aggiorna_e_stampa(Prodotto prod[], int n_prodotti,
                       const char *codice, int variazione) {
    int i, trovato = -1;
    for (i = 0; i < n_prodotti; ++i) {
        if (strcmp(prod[i].codice, codice) == 0) {
            trovato = i;
            break;
        }
    }
    if (trovato < 0) {
        /* should never happen because we called check_aggiornamento before */
        return;
    }

    /* valore prima */
    int totale_prec = valore_totale(&prod[trovato]);

    /* update */
    prod[trovato].quantità += variazione;

    /* valore dopo */
    int totale_dopo = valore_totale(&prod[trovato]);

    /* print */
    printf("Prodotto %s: valore prima = %.2f €, dopo = %.2f €\n",
           prod[trovato].codice,
           totale_prec / 100.0,
           totale_dopo / 100.0);
}

/* --------------------------------------------------------------------- */
/* 4) Ordinamento e stampa su file -------------------------------------- */
static int cmp_valore_desc(const void *a, const void *b) {
    const Prodotto *pa = (const Prodotto *)a;
    const Prodotto *pb = (const Prodotto *)b;
    int va = valore_totale(pa);
    int vb = valore_totale(pb);
    return (vb - va);   /* descending */
}

int ordina_e_stampa_file(FILE *out, Prodotto prod[], int n_prodotti) {
    if (!out || !prod) return 1;

    /* sort */
    qsort(prod, n_prodotti, sizeof(Prodotto), cmp_valore_desc);

    /* write */
    fprintf(out, "Magazzino ordinato per valore (costo * quantità) decrescente\n");
    fprintf(out, "%-31s %10s %10s %15s\n", "CODICE", "COSTO", "QUANT", "VALORE");
    fprintf(out, "----------------------------------------------------------------\n");

    for (int i = 0; i < n_prodotti; ++i) {
        fprintf(out,
                "%-31s %10.2f %10d %15.2f\n",
                prod[i].codice,
                prod[i].costo_centesimi / 100.0,
                prod[i].quantità,
                valore_totale(&prod[i]) / 100.0);
    }

    return 0;
}
```

--------------------------------------------------------------------

### 3.  `main.c`

```c
/*  main.c  ---------------------------------------------------------------
 *  Program that reads the warehouse file, allows interactive updates,
 *  and writes the final sorted list to an output file.
 *  ----------------------------------------------------------------------- */

#include "magazzino.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINEA 128

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr,
                "Uso: %s file_entrata file_uscita\n"
                "  file_entrata : file con la descrizione iniziale dei prodotti\n"
                "  file_uscita  : file su cui scrivere l'ordine finale\n",
                argv[0]);
        return EXIT_FAILURE;
    }

    /* ----------------------------------------------------------------- */
    /* 1) Apertura file di ingresso e lettura                         */
    /* ----------------------------------------------------------------- */
    FILE *fin = fopen(argv[1], "r");
    if (!fin) {
        perror("Errore apertura file di input");
        return EXIT_FAILURE;
    }

    Prodotto prodotti[MAX_PRODOTTI];
    int n_prodotti = 0;

    if (leggi_magazzino(fin, prodotti, &n_prodotti)) {
        fprintf(stderr, "Errore nella lettura del file di magazzino.\n");
        fclose(fin);
        return EXIT_FAILURE;
    }
    fclose(fin);

    printf("Letti %d prodotti.\n", n_prodotti);

    /* ----------------------------------------------------------------- */
    /* 2) Ciclo interattivo di aggiornamento                             */
    /* ----------------------------------------------------------------- */
    char cod[MAX_CODE_LEN];
    int  var;
    while (1) {
        printf("\nInserisci <codice> <variazione> (es. P001 10 oppure P002 -5): ");
        if (scanf("%31s %d", cod, &var) != 2) {
            fprintf(stderr, "Input non valido.\n");
            /* consume rest of line */
            int ch;
            while ((ch = getchar()) != '\n' && ch != EOF);
            continue;
        }

        if (strcmp(cod, SENTINEL_CODE) == 0) {
            printf("Terminazione richiesta.\n");
            break;
        }

        int rc = check_aggiornamento(prodotti, n_prodotti, cod, var);
        if (rc == -1) {
            printf("Errore: prodotto \"%s\" non trovato.\n", cod);
            continue;
        } else if (rc == -2) {
            printf("Errore: variazione non realizzabile per \"%s\".\n", cod);
            continue;
        }

        /* valid update */
        aggiorna_e_stampa(prodotti, n_prodotti, cod, var);
    }

    /* ----------------------------------------------------------------- */
    /* 3) Output finale su file                                           */
    /* ----------------------------------------------------------------- */
    FILE *fout = fopen(argv[2], "w");
    if (!fout) {
        perror("Errore apertura file di output");
        return EXIT_FAILURE;
    }

    if (ordina_e_stampa_file(fout, prodotti, n_prodotti)) {
        fprintf(stderr, "Errore durante l'ordinamento/scrittura.\n");
        fclose(fout);
        return EXIT_FAILURE;
    }

    fclose(fout);
    printf("\nStampa finalizzata su \"%s\".\n", argv[2]);

    return EXIT_SUCCESS;
}
```

--------------------------------------------------------------------

### 4.  Come compilare

```bash
gcc -Wall -Wextra -O2 -std=c11 -o magazzino main.c magazzino.c
```

--------------------------------------------------------------------

### 5.  Esempio di file di ingresso (`magazzino.txt`)

```
P001  12.50   100
P002  7.30    500
P003  3.15    2000
# commenti possono essere ignorati
```

