#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>

/* --------------------------------------------------------------------- */
/* Helper to print a buffer in hex */
static void hexdump(const char *label, const unsigned char *buf, size_t len)
{
    printf("%s (%zu bytes):\n", label, len);
    for (size_t i = 0; i < len; i++) {
        printf("%02x", buf[i]);
        if ((i + 1) % 16 == 0)
            printf("\n");
        else
            printf(" ");
    }
    if (len % 16 != 0)
        printf("\n");
}

/* --------------------------------------------------------------------- */
/* Main demo routine */
int main(void)
{
    int ret = 1;          /* Assume failure */
    EVP_KDF_CTX *kdf_ctx = NULL;
    unsigned char *shared_secret = NULL;
    size_t ss_len = 0;

    /* ---------------------------------------------------------------- */
    /* 1. Create a dummy shared secret (64 bytes) – replace with real ECDH result */
    ss_len = 64;
    shared_secret = OPENSSL_malloc(ss_len);
    if (!shared_secret) {
        fprintf(stderr, "Memory allocation failed\n");
        goto cleanup;
    }

    /* For demo purposes, just fill with deterministic data */
    for (size_t i = 0; i < ss_len; i++)
        shared_secret[i] = (unsigned char)i;

    /* ---------------------------------------------------------------- */
    /* 2. Set up X9.63 KDF context */
    kdf_ctx = EVP_KDF_CTX_new_id(EVP_KDF_X9_63);
    if (!kdf_ctx) {
        fprintf(stderr, "EVP_KDF_CTX_new_id failed\n");
        goto cleanup;
    }

    /* 3. Build the parameter list for the KDF */
    /*    Parameters are stored in a BIGNUM for the counter, a string for shared‑info,
     *    and a string for the digest algorithm. */
    OSSL_PARAM params[5];
    params[0] = OSSL_PARAM_construct_uint64("counter", 0);    /* start at 0 */
    params[1] = OSSL_PARAM_construct_octet_string("sharedinfo",
                                                  NULL, 0);          /* optional */
    params[2] = OSSL_PARAM_construct_utf8_string("digest", "SHA512", 0);
    params[3] = OSSL_PARAM_construct_end();

    /* 4. Perform the derivation – we want 16 + 64 = 80 bytes of key material */
    unsigned char out[80];   /* 80 bytes = 640 bits */
    size_t outlen = sizeof(out);

    if (EVP_KDF_derive(kdf_ctx, out, outlen,
                       OSSL_PARAM_construct_octet_string("in", shared_secret, ss_len),
                       OSSL_PARAM_construct_octet_string("salt", NULL, 0),   /* none */
                       OSSL_PARAM_construct_octet_string("label", NULL, 0),   /* none */
                       params) != 1) {
        fprintf(stderr, "EVP_KDF_derive failed\n");
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    /* ---------------------------------------------------------------- */
    /* 5. Split the output into AES‑128 key and HMAC‑SHA512 key */
    unsigned char aes_key[16];
    unsigned char hmac_key[64];

