/* ------------------------------------------------------------
 *  最長嚴格遞增子序列 (Longest Increasing Subsequence)
 *  程式作者：ChatGPT
 *  語言：C (C99 以上)
 * ------------------------------------------------------------ */
#include <stdio.h>
#include <stdlib.h>

/* 取得最大值的簡易函式 */
static inline int max(int a, int b) { return (a > b) ? a : b; }

int main(void) {
    int n;
    /* 讀入序列長度，如果輸入結束或格式錯誤就直接退出 */
    if (scanf("%d", &n) != 1 || n <= 0) {
        fprintf(stderr, "請輸入有效的序列長度 n (n > 0)。\n");
        return EXIT_FAILURE;
    }

    /* 動態分配儲存原始資料 */
    int *a = malloc(n * sizeof(int));
    if (!a) { perror("malloc"); return EXIT_FAILURE; }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            fprintf(stderr, "輸入錯誤，請確保輸入 %d 個整數。\n", n);
            free(a);
            return EXIT_FAILURE;
        }
    }

    /* dp[i] : 以 a[i] 為結尾的 LIS 長度
     * prev[i] : 以 a[i] 為結尾的 LIS 上一個位置，-1 表示起點 */
    int *dp   = malloc(n * sizeof(int));
    int *prev = malloc(n * sizeof(int));
    if (!dp || !prev) { perror("malloc"); free(a); return EXIT_FAILURE; }

    int best_len = 1;          /* 最長長度 */
    int best_pos = 0;          /* 最長 LIS 的結尾位置 */

    for (int i = 0; i < n; ++i) {
        dp[i]   = 1;          /* 至少自己一個 */
        prev[i] = -1;         /* 起點 */

        for (int j = 0; j < i; ++j) {
            if (a[j] < a[i] && dp[j] + 1 > dp[i]) {
                dp[i]   = dp[j] + 1;
                prev[i] = j;
            }
        }

        if (dp[i] > best_len) {
            best_len = dp[i];
            best_pos = i;
        }
    }

    /* 逆向回溯得到 LIS（存於 tmp 中） */
    int *tmp = malloc(best_len * sizeof(int));
    if (!tmp) { perror("malloc"); free(a); free(dp); free(prev); return EXIT_FAILURE; }

    int idx = best_pos;
    for (int i = best_len - 1; i >= 0; --i) {
        tmp[i] = a[idx];
        idx = prev[idx];
    }

    /* 輸出結果 */
    printf("LIS 長度: %d\n", best_len);
    printf("LIS 元素: ");
    for (int i = 0; i < best_len; ++i) {
        printf("%d", tmp[i]);
        if (i + 1 < best_len) putchar(' ');
    }
    putchar('\n');

    /* 釋放記憶體 */
    free(a);
    free(dp);
    free(prev);
    free(tmp);
    return EXIT_SUCCESS;
}
```

