Below is a **complete, self‑contained C program** that

1. Generates an array of `n` random integers (0–99).  
2. Sorts that array with the classic **Quick Sort** algorithm.  
3. Prints the array before and after sorting so you can see the change.

```c
/*********************************************************************
 * quicksort.c
 *
 *   Generates a random array of integers and sorts it with Quick‑Sort.
 *
 *   Compile with:
 *     gcc -Wall -Wextra -O2 quicksort.c -o quicksort
 *
 *   Run with:
 *     ./quicksort          (prompts for the array size)
 *     ./quicksort <n>      (uses <n> as the array size)
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/* ------------------------------------------------------------- */
/* Utility functions                                               */
/* ------------------------------------------------------------- */

/* Swap two integers in place */
static inline void swap(int *a, int *b)
{
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

/* Print an integer array of length n */
static void print_array(const int *arr, size_t n)
{
    for (size_t i = 0; i < n; ++i) {
        printf("%5d", arr[i]);
        if ((i + 1) % 10 == 0) putchar('\n');   /* wrap after 10 numbers */
    }
    if (n % 10 != 0) putchar('\n');
}

/* ------------------------------------------------------------- */
/* Quick‑Sort implementation                                      */
/* ------------------------------------------------------------- */

/* Lomuto partition scheme */
static int partition(int *arr, int low, int high)
{
    int pivot = arr[high];          /* choose the rightmost element as pivot */
    int i = low - 1;

    for (int j = low; j < high; ++j) {
        if (arr[j] <= pivot) {
            ++i;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);   /* place pivot in its correct position */
    return i + 1;
}

/* Quick‑Sort (recursive) */
void quicksort(int *arr, int low, int high)
{
    if (low < high) {
        int pi = partition(arr, low, high);

        quicksort(arr, low, pi - 1);  /* sort left part */
        quicksort(arr, pi + 1, high); /* sort right part */
    }
}

/* ------------------------------------------------------------- */
/* Random array generation                                         */
/* ------------------------------------------------------------- */

/* Allocate and fill an array of n random integers [0, 99] */
int *generate_random_array(size_t n)
{
    if (n == 0) return NULL;        /* nothing to allocate */

    int *arr = malloc(n * sizeof(int));
    if (!arr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; ++i) {
        arr[i] = rand() % 100;      /* random numbers 0‑99 */
    }

    return arr;
}

/* ------------------------------------------------------------- */
/* Main program                                                   */
/* ------------------------------------------------------------- */

int main(int argc, char *argv[])
{
    size_t n = 0;       /* number of elements */

    /* --------- parse command line or ask the user ---------- */
    if (argc == 2) {
        /* use the first argument as the size */
        n = (size_t)strtoul(argv[1], NULL, 10);
    } else if (argc == 1) {
        /* prompt the user */
        printf("Enter the number of elements to sort: ");
        if (scanf("%zu", &n) != 1 || n == 0) {
            fprintf(stderr, "Invalid input.\n");
            return EXIT_FAILURE;
        }
    } else {
        fprintf(stderr, "Usage: %s [size]\n", argv[0]);
        return EXIT_FAILURE;
    }

    /* --------- initialise random number generator  ---------- */
    srand((unsigned)time(NULL));

    /* --------- generate the random array ------------------- */
    int *arr = generate_random_array(n);
    if (!arr) {
        fprintf(stderr, "Failed to allocate array.\n");
        return EXIT_FAILURE;
    }

    printf("\nUnsorted array (%zu elements):\n", n);
    print_array(arr, n);

    /* --------- sort with Quick‑Sort ------------------------ */
    quicksort(arr, 0, (int)n - 1);

    printf("\nSorted array:\n");
    print_array(arr, n);

    free(arr);
    return EXIT_SUCCESS;
}
```

### How it works

| Step | Code |
|------|------|
| **Generate** | `generate_random_array()` allocates memory and fills it with random numbers in the range 0–99. |
| **Sort** | `quicksort()` implements the classic recursive Quick‑Sort using the Lomuto partition scheme. |
| **Print** | `print_array()` prints the array, wrapping every 10 numbers for readability. |
| **Main** | Reads the desired array size (either from the command line or the user), seeds the RNG with the current time, creates the array, sorts it, and displays the result. |

### Compile & Run

```bash
