```c
#include <stdio.h>
#include <stdlib.h>

/* ---------- 结构体 ---------- */
typedef struct BstNode {
    int data;
    struct BstNode *lchild, *rchild;
} BstNode;

typedef struct QNode {
    BstNode *data;
    struct QNode *next;
} QNode;

typedef struct {
    QNode *front, *rear;
} BiTQueue;

/* ---------- 树操作 ---------- */
BstNode* GetNewNode(int data) {
    BstNode* p = (BstNode*)malloc(sizeof(BstNode));
    p->data = data;
    p->lchild = p->rchild = NULL;
    return p;
}

BstNode* Insert(BstNode* root, int data) {
    if (!root) return GetNewNode(data);
    if (data < root->data) root->lchild = Insert(root->lchild, data);
    else if (data > root->data) root->rchild = Insert(root->rchild, data);
    return root;
}

/* ---------- 队列 ---------- */
BiTQueue* InitQueue(void) {
    BiTQueue* Q = (BiTQueue*)malloc(sizeof(BiTQueue));
    QNode* dummy = (QNode*)malloc(sizeof(QNode));
    dummy->next = NULL;
    Q->front = Q->rear = dummy;   /* 用哨兵节点简化 push/pop */
    return Q;
}

void Push(BiTQueue* Q, BstNode* T) {
    QNode* node = (QNode*)malloc(sizeof(QNode));
    node->data = T;
    node->next = NULL;
    Q->rear->next = node;
    Q->rear = node;
}

BstNode* Pop(BiTQueue* Q) {
    if (Q->front == Q->rear) return NULL;   /* 为空 */
    QNode* temp = Q->front->next;
    BstNode* ret = temp->data;
    Q->front->next = temp->next;
    if (Q->rear == temp) Q->rear = Q->front;  /* 只剩一个 */
    free(temp);
    return ret;
}

int IsEmpty(BiTQueue* Q) {
    return Q->front == Q->rear;
}

/* ---------- BFS 打印指定层 ---------- */
void LeveOrderTraverse(BstNode* root, int level) {
    if (!root) return;
    BiTQueue* Q = InitQueue();
    Push(Q, root);
    int currentLevel = 0;
    while (!IsEmpty(Q)) {
        int sz = 0;  /* 当前层剩余节点数 */
        for (QNode* p = Q->front->next; p != NULL; p = p->next) sz++;
        for (int i = 0; i < sz; ++i) {
            BstNode* p = Pop(Q);
            if (currentLevel == level) printf("%d ", p->data);
            if (p->lchild) Push(Q, p->lchild);
            if (p->rchild) Push(Q, p->rchild);
        }
        if (currentLevel == level) break;   /* 已打印完该层，可提前退出 */
        currentLevel++;
    }
    free(Q->front);   /* 释放哨兵 */
    free(Q);
}

/* ---------- 主函数 ---------- */
int main(void) {
    int cnt, level, val;
    if (scanf("%d", &cnt) != 1) return 1;
    BstNode *root = NULL;
    for (int i = 0; i < cnt; ++i) {
        if (scanf("%d", &val) != 1) return 1;
        root = Insert(root, val);
    }
    if (scanf("%d", &level) != 1) return 1;
    LeveOrderTraverse(root, level);
    return 0;
}
```

