/*********************************************************************
 *  Большие целые (до 30‑31 десятичных разрядов)
 *  - хранение: массив char, порядок цифр обратный (младший разряд в 0‑м индексе)
 *  - операции: + – -, * – /
 *  - никаких контейнеров кроме массивов
 *  - система счисления: десятичная
 *********************************************************************/

#include <bits/stdc++.h>
using namespace std;

/* --------------------------------------------------------------- */
struct BigInt
{
    static const int MAXD = 35;          // 35 > 31 (10^30 + 1)
    int  sign;                          //  1  – положительно
                                         // -1  – отрицательно
                                         //  0  – ноль
    char d[MAXD];                       // цифры, d[0] – младший разряд
    int  len;                           // количество цифр (длина)

    BigInt() { clear(); }

    /* очистить (получить 0) */
    void clear()
    {
        sign = 0;
        len  = 0;
    }

    /* нормализовать: убрать ведущие нули, задать sign */
    void normalize()
    {
        while (len > 0 && d[len-1] == 0) len--;
        if (len == 0) sign = 0;
        if (sign == 0) len = 0;
    }

    /* ввод из строки */
    static BigInt fromString(const string &s)
    {
        BigInt x;
        int i = 0, n = (int)s.size();
        while (i < n && isspace(s[i])) i++;

        /* знак */
        if (i < n && (s[i] == '+' || s[i] == '-'))
            x.sign = (s[i] == '-') ? -1 : 1, ++i;
        else
            x.sign = 1;

        /* цифры (можно в любой длины, но не более MAXD) */
        vector<char> tmp;
        while (i < n && isdigit(s[i]))
            tmp.push_back(s[i++]);

        /* убрать возможные ведущие нули в вводе */
        int pos = 0;
        while (pos+1 < (int)tmp.size() && tmp[pos] == '0') ++pos;

        x.len = (int)tmp.size() - pos;
        if (x.len == 0) { x.sign = 0; return x; }

        /* копируем в обратном порядке */
        for (int k = 0; k < x.len; ++k)
            x.d[k] = tmp[(int)tmp.size()-1 - k] - '0';

        x.normalize();
        return x;
    }

    /* печать в строку (с поддержкой знака) */
    string toString() const
    {
        if (sign == 0) return "0";
        string s;
        if (sign < 0) s.push_back('-');
        for (int i = len-1; i >= 0; --i)
            s.push_back(char('0' + d[i]));
        return s;
    }

    /* сравнение абсолютных значений (без знака) */
    static int cmpAbs(const BigInt &a, const BigInt &b)
    {
        if (a.len != b.len) return (a.len > b.len) ? 1 : -1;
        for (int i = a.len-1; i >= 0; --i)
            if (a.d[i] != b.d[i]) return (a.d[i] > b.d[i]) ? 1 : -1;
        return 0;
    }

    /* addAbs(a,b) – сложить абсолютные значения a и b, знак 1 */
    static BigInt addAbs(const BigInt &a, const BigInt &b)
    {
        BigInt r;
        r.sign = 1;
        r.len = max(a.len, b.len);
        int carry = 0;
        for (int i = 0; i < r.len; ++i) {
            int sum = carry;
            if (i < a.len) sum += a.d[i];
            if (i < b.len) sum += b.d[i];
            r.d[i] = sum % 10;
            carry   = sum / 10;
        }
        if (carry) r.d[r.len++] = carry;
        r.normalize();
        return r;
    }

    /* subAbs(a,b) – a - b, предполагается a.abs >= b.abs */
    static BigInt subAbs(const BigInt &a, const BigInt &b)
    {
        BigInt r;
        r.sign = 1;
        r.len  = a.len;
        int borrow = 0;
        for (int i = 0; i < r.len; ++i) {
            int diff = a.d[i] - borrow - (i < b.len ? b.d[i] : 0);
            if (diff < 0) { diff += 10; borrow = 1; }
            else          borrow = 0;
            r.d[i] = diff;
        }
        r.normalize();
        return r;
    }

    /* операция + */
    static BigInt add(const BigInt &a, const BigInt &b)
    {
        if (a.sign == 0) return b;
        if (b.sign == 0) return a;
        if (a.sign == b.sign) {
            BigInt r = addAbs(a,b);
            r.sign = a.sign;
            return r;
        }
        /* разный знак */
        int cmp = cmpAbs(a,b);
        if (cmp == 0) return BigInt();          // 0
        if (cmp > 0) {                          // |a| > |b|
            BigInt r = subAbs(a,b);
            r.sign = a.sign;
            return r;
        } else {                                // |b| > |a|
            BigInt r = subAbs(b,a);
            r.sign = b.sign;
            return r;
        }
    }

    /* операция - (a - b) */
    static BigInt sub(const BigInt &a, const BigInt &b)
    {
        BigInt nb = b;
        if (nb.sign != 0) nb.sign = -nb.sign;
        return add(a, nb);
    }

    /* умножение на маленькое число (0 <= m <= 9) */
    static BigInt mulSmall(const BigInt &a, int m)
    {
        if (m == 0 || a.sign == 0) return BigInt();
        BigInt r;
        r.sign = a.sign;
        int carry = 0;
        for (int i = 0; i < a.len; ++i) {
            int prod = a.d[i] * m + carry;
            r.d[i] = prod % 10;
            carry  = prod / 10;
        }
        while (carry) {
            r.d[r.len++] = carry % 10;
            carry /= 10;
        }
        r.len = a.len;
        if (carry) {
            r.d[r.len++] = carry;
        }
        r.normalize();
        return r;
    }

    /* добавить маленькое число (0..9) к абсолютному значению */
    static BigInt addSmall(const BigInt &a, int add)
    {
        BigInt r = a;
        if (r.sign == 0) {
            if (add == 0) return r;
            r.sign = 1;
            r.len  = 0;
        }
        int carry = add;
        for (int i = 0; i < r.len && carry; ++i) {
            int sum = r.d[i] + carry;
            r.d[i]  = sum % 10;
            carry   = sum / 10;
        }
        while (carry) {
            r.d[r.len++] = carry % 10;
            carry /= 10;
        }
        r.normalize();
        return r;
    }

    /* умножение (полностью) */
    static BigInt mul(const BigInt &a, const BigInt &b)
    {
        if (a.sign == 0 || b.sign == 0) return BigInt();
        BigInt r;
        r.sign = a.sign * b.sign;
        r.len  = a.len + b.len;
        for (int i = 0; i < a.len; ++i) {
            int carry = 0;
            for (int j = 0; j < b.len || carry; ++j) {
                int cur = r.d[i+j] + a.d[i] * (j < b.len ? b.d[j] : 0) + carry;
                r.d[i+j] = cur % 10;
                carry    = cur / 10;
            }
        }
        r.normalize();
        return r;
    }

    /* деление (целое) + остаток, возвращает пару {q, r} */
    static pair<BigInt,BigInt> divmod(const BigInt &a, const BigInt &b)
    {
        if (b.sign == 0) throw runtime_error("Division by zero");
        BigInt dividend = a; dividend.sign = 1;
        BigInt divisor  = b; divisor.sign  = 1;

        BigInt q; q.sign = 0; q.len = 0;
        BigInt r; r.sign = 0; r.len = 0;

        if (cmpAbs(dividend, divisor) < 0) {   // |a| < |b|
            r = dividend; r.sign = a.sign;
            return {q, r};
        }

        /* массив для хранения цифр частного от старшего к младшему */
        char qdigits[MAXD];
        int qlen = 0;

        /* остаток пока что 0 */
        for (int i = dividend.len-1; i >= 0; --i) {
            /* r = r * 10 + dividend.d[i] */
            r = mulSmall(r, 10);
            r = addSmall(r, dividend.d[i]);

            /* найти d : divisor*d <= r < divisor*(d+1) , 0 <= d <= 9 */
            int d = 0;
            BigInt prod;
            for (d = 9; d >= 0; --d) {
                prod = mulSmall(divisor, d);
                if (cmpAbs(r, prod) >= 0) break;
            }
            qdigits[qlen++] = char('0' + d);
            /* r = r - divisor*d */
            if (d > 0) r = subAbs(r, prod);
        }

        /* сформировать результат q (обратный порядок) */
        q.sign = (a.sign == b.sign) ? 1 : -1;
        for (int i = 0; i < qlen; ++i) {
            q.d[i] = qdigits[qlen-1-i] - '0';
        }
        q.len = qlen;
        q.normalize();

        r.sign = a.sign;          // по стандарту остаток имеет знак делимого
        r.normalize();

        return {q, r};
    }
};

/* --------------------------------------------------------------- */
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    /* Пример: вводятся два числа и операция (+, -, *, /) */
    cout << "Введите два целых числа (по модулю <= 10^30) и операцию (+,-,*,/):\n";
    string s1, s2, op;
    if (!(cin >> s1 >> s2 >> op)) return 0;

    BigInt a = BigInt::fromString(s1);
    BigInt b = BigInt::fromString(s2);
    BigInt res;
    BigInt rem;

    if (op == "+") res = BigInt::add(a,b);
    else if (op == "-") res = BigInt::sub(a,b);
    else if (op == "*") res = BigInt::mul(a,b);
    else if (op == "/") {
        auto qr = BigInt::divmod(a,b);
        res = qr.first;
        rem = qr.second;
    } else {
        cerr << "Неверная операция\n";
        return 1;
    }

    if (op == "/")
        cout << "Quotient: " << res.toString() << "\n"
             << "Remainder: " << rem.toString() << "\n";
    else
        cout << "Result: " << res.toString() << "\n";

    return 0;
}
```

**Краткое пояснение**

* `BigInt` хранит число в виде массива `d[]`, где `d[0]` – младший разряд, `len` – количество разрядов, `sign` – знак.
* Все операции реализованы без использования динамических контейнеров (`vector`, `string` и т.п.) – только массивы фиксированной длины.
