**Код на C (решение системы двух линейных уравнений)**  

```c
#include <stdio.h>
#include <stdbool.h>

/* Структура‑результат: 
   - ok  – true, если решение найдено однозначно;
   - x,y – найденные значения переменных.           */
typedef struct {
    bool ok;
    double x;
    double y;
} Result;

/* Функция‑решатель:
   a*x + b*y = c
   x  - y   = d
   Принимает целые параметры и возвращает Result. */
Result solve(int a, int b, int c, int d)
{
    Result r = {false, 0.0, 0.0};

    /* Определитель матрицы [[a,b],[1,-1]] = -a - b   */
    int det = -a - b;

    if (det == 0) {          /* Система не имеет единственного решения */
        /* Можно дополнительно проверить, есть ли бесконечно много решений */
        int left1 = a * d + b * d;   /* a*d + b*d = (a+b)*d  */
        int left2 = c;               /* правая часть первого уравнения */
        if (left1 == left2) {
            /* Бесконечно много решений – например, x = t, y = t - d  */
            /* В данной задаче будем считать, что «решения нет» */
            r.ok = false;
        } else {
            /* Нет решений */
            r.ok = false;
        }
        return r;
    }

    /* a + b != 0  – можно вычислять */
    double denom = (double)(a + b);
    r.y = (double)(c - a * d) / denom;
    r.x = r.y + d;
    r.ok = true;
    return r;
}

int main(void)
{
    int a, b, c, d;
    printf("Введите a, b, c, d (через пробел): ");
    if (scanf("%d %d %d %d", &a, &b, &c, &d) != 4) {
        printf("Ошибка ввода!\n");
        return 1;
    }

    Result res = solve(a, b, c, d);

    if (res.ok) {
        printf("Решение: x = %.6f, y = %.6f\n", res.x, res.y);
    } else {
        printf("Система не имеет единственного решения.\n");
    }

    return 0;
}
```

### Как работает программа
1. **Чтение входных данных.**  
   Пользователь вводит четыре целых числа `a`, `b`, `c`, `d`.

2. **Решатель `solve`.**  
   - Вычисляется определитель `det = -a - b`.  
   - Если `det == 0`, система линейно зависима: либо нет решений, либо бесконечно много. В обоих случаях функция возвращает `ok = false`.  
   - Если `det != 0`, решение существует и уникально. Сначала вычисляем `y = (c - a*d)/(a+b)`, потом `x = y + d`.

3. **Вывод результата.**  
   Если решение найдено (`ok == true`), выводятся значения `x` и `y` с точностью до 6 знаков после запятой.  
   Иначе выводится сообщение о том, что решение единственного нет.

### Что ещё можно улучшить
- Вывести дополнительную информацию о бесконечно множестве решений, если `a + b == 0` и `c == (a+b)*d`.  
- Сделать ввод более гибким (проверка диапазона, обработка ошибок).  

Но для задачи «решить систему из двух уравнений» данный код полностью удовлетворяет требованиям.

