    cin.tie(nullptr);

    while (true) {
        cout << "Please enter size of board as a power of 2 (0 to quit): ";
        int size;
        if (!(cin >> size)) return 0;
        if (size == 0) break;

        // validate that size is a power of 2
        if ((size & (size - 1)) != 0) {
            cout << "The board size should be a power of 2\n";
            continue;
        }

        cout << "Please enter coordinates of missing square (separate by a space): ";
        int mx, my;
        cin >> mx >> my;
        if (mx < 0 || mx >= size || my < 0 || my >= size) {
            cout << "Missing square coordinates are out of bounds\n";
            continue;
        }

        board.assign(size, vector<string>(size, ""));   // create empty board

        tromino(0, 0, mx, my, size);   // start the recursive tiling

        // ---------- print the board ----------
        for (int y = size - 1; y >= 0; --y) {
            for (int x = 0; x < size; ++x) {
                cout << board[y][x];
                if (x != size - 1) cout << '\t';
            }
            cout << '\n';
        }
        cout << '\n';
    }
    return 0;
}
