#include <stdio.h>
#include <ctype.h>
#include <string.h>

int main(void)
{
    /* A buffer that can hold any reasonably short line of input.
       100 bytes is plenty for this purpose. */
    char buffer[100];

    /* Prompt the user. */
    printf("Please enter a single letter: ");
    fflush(stdout);                /* make sure the prompt is printed */

    /* Read a line from stdin.  fgets() stores the newline if there is room. */
    if (fgets(buffer, sizeof buffer, stdin) == NULL) {
        /* End‑of‑file or read error. */
        fprintf(stderr, "Error reading input.\n");
        return 1;
    }

    /* Find the first newline or the terminating NUL.  Everything
       before that is the user's actual input. */
    size_t len = strcspn(buffer, "\n");

    /* Check that exactly one character was entered and that it
       is an alphabetic letter. */
    if (len == 1 && isalpha((unsigned char)buffer[0])) {
        printf("You entered the letter: '%c'\n", buffer[0]);
    } else {
