static int cmp_pos_min_req(const void *a, const void *b)
{
    const Station *sa = (const Station *)a;
    const Station *sb = (const Station *)b;

    /* Safe subtraction: use long long or compare directly */
    if (sa->min_req < sb->min_req) return -1;
