static int cmp_neg_min_req(const void *a, const void *b)
{
    const Station *sa = (const Station *)a;
    const Station *sb = (const Station *)b;

    /* reversed sign for descending */
    if (sa->min_req > sb->min_req) return -1;
    if (sa->min_req < sb->min_req) return  1;
