/* 计算最大值 */
int max_value(int *pa, int *pb)
{
    return (*pa > *pb) ? *pa : *pb;
}

/* 计算最小值 */
int min_value(int *pa, int *pb)
{
    return (*pa < *pb) ? *pa : *pb;
}

/* 计算和 */
int sum_value(int *pa, int *pb)
{
    return *pa + *pb;
}

