    for (int i = 1; i < n; ++i)
        readRow(a[i], m);

    /* ---- process columns and output result array ---- */
    int *tempRow = (int *)malloc(n * sizeof(int));
    if (!tempRow) {
        perror("malloc");
        for (int i = 0; i < n; ++i) free(a[i]);
        free(a);
        return 1;
    }

    for (int col = 0; col < m; ++col) {
        if (isNonDecreasing(a, n, col)) {
            copyColumn(a, n, col, tempRow);
            /* print the new row */
            for (int i = 0; i < n; ++i) {
                if (i) putchar(' ');
                printf("%d", tempRow[i]);
            }
            putchar('\n');
        }
    }

    /* ---- free memory ---- */
    free(tempRow);
    for (int i = 0; i < n; ++i) free(a[i]);
    free(a);

    return 0;
}

/* -----------  Function definitions  ----------- */

/* Reads one row of length colCount into the supplied buffer */
void readRow(int *row, int colCount)
{
    for (int j = 0; j < colCount; ++j) {
        if (scanf("%d", &row[j]) != 1) {
            fprintf(stderr, "Error reading element.\n");
            exit(1);
        }
    }
}

/* Returns 1 iff column colIndex of array a (with rowCount rows) is
   non‑decreasing. */
int isNonDecreasing(int **a, int rowCount, int colIndex)
{
    for (int i = 1; i < rowCount; ++i) {
        if (a[i][colIndex] < a[i-1][colIndex])
            return 0;
    }
    return 1;
}

/* Copies column colIndex into destRow (length rowCount). */
void copyColumn(int **a, int rowCount, int colIndex, int *destRow)
{
    for (int i = 0; i < rowCount; ++i)
        destRow[i] = a[i][colIndex];
}
```

