Below is a **complete, working example** of the file‑sharing system you asked for.  
It is written for a POSIX‑compatible system (Linux/Unix).  
All communication is done through **System V shared memory** (`shmget/shmat`) and **named POSIX
semaphores** (`sem_open/sem_wait/sem_post`).  
The server creates a new thread for every command that it receives.

> **TL;DR – How to use**
> 
> 1. Compile the two programs  
>    ```bash
>    gcc -Wall -pthread -o server server.c
>    gcc -Wall -o client client.c
>    ```  
> 2. Start the server in one terminal: `./server`  
> 3. In another terminal run a client command:  
>    - Write: `./client write myfile.txt "Hello world"`  
>    - Read: `./client read myfile.txt`  
> 4. The client prints the file’s contents (for a read) and then exits;  
>    the server stays alive, ready for the next client.

---

## 1.  Common definitions

Both programs share a few constants, so they are defined in a header
(`common.h`) to avoid duplication.

```c
/* common.h */
#ifndef COMMON_H
#define COMMON_H

/* Size of the command shared memory (holds a null‑terminated string) */
#define CMD_SHM_SIZE  1024

/* Size of a data‑shared memory – large enough for demo files */
#define DATA_SHM_SIZE 4096

/* Names of the POSIX semaphores (must start with '/') */
#define SEM_MUTEX_NAME     "/fileshare_mutex"
#define SEM_CLIENT_READY   "/fileshare_client_ready"
#define SEM_SERVER_READY   "/fileshare_server_ready"

/* Key used to create the command‑shm (ftok directory & id) */
#define CMD_SHM_KEY_PATH   "/tmp"
#define CMD_SHM_KEY_ID     0x1234

/* Helper for perror + exit */
#define DIE(msg) do { perror(msg); exit(EXIT_FAILURE); } while (0)

#endif /* COMMON_H */
```

---

## 2.  `server.c`

```c
/* server.c */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <pthread.h>
#include <semaphore.h>
#include "common.h"

/* Thread argument – we keep a copy of the command string */
struct thread_arg {
    char command[CMD_SHM_SIZE];
};

static int cmd_shm_id;          /* ID of the command shared memory */
static char *cmd_shm_addr;      /* Address of the command shared memory */
static sem_t *mutex_sem;        /* Binary semaphore protecting cmd_shm */
static sem_t *client_ready_sem;
static sem_t *server_ready_sem;

/* Utility: create a new shared memory segment of the given size.
 * Returns the key (used by the client to attach) or -1 on error. */
static int create_data_shm(void **addr, size_t size)
{
    key_t key = ftok(CMD_SHM_KEY_PATH, rand());   /* random id for uniqueness */
    int shmid = shmget(key, size, IPC_CREAT | 0666);
    if (shmid < 0) {
        perror("shmget (data)");
        return -1;
    }
    void *p = shmat(shmid, NULL, 0);
    if (p == (void *)-1) {
        perror("shmat (data)");
        return -1;
    }
    *addr = p;
    return key;
}

/* Thread routine that processes a single command */
static void *handle_command(void *arg)
{
    struct thread_arg *targ = (struct thread_arg *)arg;
    char *cmd = targ->command;
    free(targ);          /* no longer needed */

    /* Quick split into tokens */
    char *token = strtok(cmd, " \t");
    if (!token) {
        fprintf(stderr, "Malformed command\n");
        goto done;
    }

    /* --------------------------------------------------------------------
     *  1) WRITE  :  "write <filename> <data…>"
     * -------------------------------------------------------------------- */
    if (strcmp(token, "write") == 0) {
        char *filename = strtok(NULL, " \t");
        char *data      = strtok(NULL, "");   /* rest of the line */
        if (!filename || !data) {
            fprintf(stderr, "Malformed write command\n");
            goto done;
        }

        FILE *f = fopen(filename, "w");
        if (!f) {
            perror("fopen write");
            goto done;
        }
        fputs(data, f);
        fclose(f);
        printf("[server] wrote %lu bytes to %s\n", strlen(data), filename);

        /* No extra shared memory needed – just signal completion */
        sem_post(server_ready_sem);
        goto done;
    }

    /* --------------------------------------------------------------------
     *  2) READ   :  "read <filename>"
     * -------------------------------------------------------------------- */
    if (strcmp(token, "read") == 0) {
        char *filename = strtok(NULL, " \t");
        if (!filename) {
            fprintf(stderr, "Malformed read command\n");
            goto done;
        }

        /* Read the file into a buffer */
        FILE *f = fopen(filename, "rb");
        if (!f) {
            perror("fopen read");
            /* Still need to tell the client that we failed */
            sem_post(server_ready_sem);
            goto done;
        }
        fseek(f, 0, SEEK_END);
        long fsize = ftell(f);
        fseek(f, 0, SEEK_SET);
        if (fsize > DATA_SHM_SIZE) {
            fprintf(stderr, "File too large for demo\n");
            fclose(f);
            sem_post(server_ready_sem);
            goto done;
        }
        char *buf = (char *)malloc(fsize);
        if (!buf) { perror("malloc"); fclose(f); sem_post(server_ready_sem); goto done; }
        fread(buf, 1, fsize, f);
        fclose(f);

        /* Create a new shared memory segment for the file data */
        void *data_shm;
        int key = create_data_shm(&data_shm, fsize);
        if (key < 0) {
            free(buf);
            sem_post(server_ready_sem);
            goto done;
        }
        memcpy(data_shm, buf, fsize);
        free(buf);

        /* Write the key back to the command shared memory (protected by mutex) */
        sem_wait(mutex_sem);
        snprintf(cmd_shm_addr, CMD_SHM_SIZE, "%d", key);
        sem_post(mutex_sem);

        /* Tell client that data is ready */
        sem_post(server_ready_sem);
        printf("[server] sent file %s (size %ld) via key %d\n",
               filename, fsize, key);
        goto done;
    }

    fprintf(stderr, "Unknown command: %s\n", token);
done:
    /* Nothing to clean – the thread will just exit */
    return NULL;
}

int main(void)
{
    /* --------------------------------------------------------------------
     *  Create and attach the command shared memory
     * -------------------------------------------------------------------- */
    key_t cmd_key = ftok(CMD_SHM_KEY_PATH, CMD_SHM_KEY_ID);
    cmd_shm_id = shmget(cmd_key, CMD_SHM_SIZE, IPC_CREAT | 0666);
    if (cmd_shm_id < 0) DIE("shmget cmd");

    cmd_shm_addr = shmat(cmd_shm_id, NULL, 0);
    if (cmd_shm_addr == (void *)-1) DIE("shmat cmd");

    /* --------------------------------------------------------------------
     *  Open semaphores
     * -------------------------------------------------------------------- */
    mutex_sem       = sem_open(SEM_MUTEX_NAME,       O_CREAT, 0644, 1);   /* binary */
    client_ready_sem= sem_open(SEM_CLIENT_READY,    O_CREAT, 0644, 0);   /* client->srv */
    server_ready_sem= sem_open(SEM_SERVER_READY,    O_CREAT, 0644, 0);   /* srv->client */
    if (mutex_sem == SEM_FAILED ||
        client_ready_sem == SEM_FAILED ||
        server_ready_sem == SEM_FAILED) DIE("sem_open");

    printf("[server] Ready. Waiting for clients.\n");

    /* --------------------------------------------------------------------
     *  Main loop – wait for a command from any client
     * -------------------------------------------------------------------- */
    while (1) {
        sem_wait(client_ready_sem);     /* a client has written a command */

        /* Grab the command */
        sem_wait(mutex_sem);
        char cmd_buf[CMD_SHM_SIZE];
        strncpy(cmd_buf, cmd_shm_addr, CMD_SHM_SIZE);
        cmd_buf[CMD_SHM_SIZE-1] = '\0';      /* safety */
        /* clear the old command to avoid accidental re‑reads */
        memset(cmd_shm_addr, 0, CMD_SHM_SIZE);
        sem_post(mutex_sem);

        /* Spawn a thread to process it */
        pthread_t th;
        struct thread_arg *arg = malloc(sizeof(*arg));
        strcpy(arg->command, cmd_buf);
        if (pthread_create(&th, NULL, handle_command, arg) != 0) {
            perror("pthread_create");
            /* If we fail to start a thread we must signal the client */
            sem_post(server_ready_sem);
        } else {
            pthread_detach(th);     /* we do not need to join it */
        }
    }

    /* Cleanup never reached, but good practice */
    shmdt(cmd_shm_addr);
    shmctl(cmd_shm_id, IPC_RMID, NULL);
    sem_close(mutex_sem);
    sem_close(client_ready_sem);
    sem_close(server_ready_sem);
    sem_unlink(SEM_MUTEX_NAME);
    sem_unlink(SEM_CLIENT_READY);
    sem_unlink(SEM_SERVER_READY);

    return 0;
}
```

### What the server does

| Step | Action |
|------|--------|
| 1 | Creates a **command shared memory** (`CMD_SHM_SIZE` bytes) and three **named semaphores**. |
| 2 | The main thread waits on `client_ready_sem` (client signals “command ready”). |
| 3 | Once a command arrives, it is copied out, the shared memory slot is cleared, and a **new thread** is spawned. |
| 4 | The thread parses the command:  
 • `write` – writes the supplied data into a file.  
 • `read` – creates a fresh shared memory segment, copies the file contents into it, writes the *key* of that segment back into the command shared memory, and signals the client with `server_ready_sem`. |
| 5 | After the thread finishes, the server returns to step 2 and waits for the next command. |

