## 3.  `client.c`

```c
/* client.c */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <semaphore.h>
#include "common.h"

/* Helper: build the command string from argv */
static char *build_command(int argc, char **argv)
{
    /* Minimal sanity checks */
    if (argc < 3) {
        fprintf(stderr, "Usage:\n"
                        "  %s write <filename> <data>\n"
                        "  %s read  <filename>\n", argv[0], argv[0]);
        exit(EXIT_FAILURE);
    }

    if (strcmp(argv[1], "write") == 0 && argc < 4) {
        fprintf(stderr, "write command needs filename and data\n");
        exit(EXIT_FAILURE);
    }

    /* Construct a single string: "write file data…" or "read file" */
    size_t len = 0;
    for (int i = 1; i < argc; ++i) {
        len += strlen(argv[i]) + 1;   /* +1 for space or terminating NUL */
    }
    char *cmd = malloc(len + 1);
    if (!cmd) { perror("malloc"); exit(EXIT_FAILURE); }

    cmd[0] = '\0';
    for (int i = 1; i < argc; ++i) {
        strcat(cmd, argv[i]);
        if (i < argc-1) strcat(cmd, " ");
    }
    return cmd;
}

int main(int argc, char **argv)
{
    /* -------------------------------------------------------------
     *  Attach to the command shared memory
     * ------------------------------------------------------------- */
    key_t cmd_key = ftok(CMD_SHM_KEY_PATH, CMD_SHM_KEY_ID);
    int cmd_shm_id = shmget(cmd_key, CMD_SHM_SIZE, 0666);
    if (cmd_shm_id < 0) DIE("shmget cmd");

    char *cmd_shm_addr = shmat(cmd_shm_id, NULL, 0);
    if (cmd_shm_addr == (void *)-1) DIE("shmat cmd");

    /* -------------------------------------------------------------
     *  Open semaphores
     * ------------------------------------------------------------- */
    sem_t *mutex_sem       = sem_open(SEM_MUTEX_NAME,       O_RDONLY);
    sem_t *client_ready_sem= sem_open(SEM_CLIENT_READY,    O_RDONLY);
    sem_t *server_ready_sem= sem_open(SEM_SERVER_READY,    O_RDONLY);
    if (mutex_sem == SEM_FAILED ||
        client_ready_sem == SEM_FAILED ||
        server_ready_sem == SEM_FAILED) DIE("sem_open");

    /* -------------------------------------------------------------
     *  Build the command string from command line
     * ------------------------------------------------------------- */
    char *command = build_command(argc, argv);
    printf("[client] Sending command: \"%s\"\n", command);

    /* -------------------------------------------------------------
     *  Write the command into shared memory
     * ------------------------------------------------------------- */
    sem_wait(mutex_sem);
    strncpy(cmd_shm_addr, command, CMD_SHM_SIZE);
    cmd_shm_addr[CMD_SHM_SIZE-1] = '\0';  /* safety */
    sem_post(mutex_sem);

    /* Signal to the server that a command is ready */
    sem_post(client_ready_sem);

    /* -------------------------------------------------------------
     *  Wait for the server to process it
     * ------------------------------------------------------------- */
    sem_wait(server_ready_sem);

    /* -------------------------------------------------------------
     *  If it was a read, the server has written the key of a new
     *  shared memory segment into cmd_shm_addr.  Fetch it and read.
     * ------------------------------------------------------------- */
    if (strncmp(command, "read ", 5) == 0) {
        /* The key is just a decimal number written into cmd_shm_addr */
        int key = atoi(cmd_shm_addr);
        if (key <= 0) {
            fprintf(stderr, "Server did not provide a valid key.\n");
            goto cleanup;
        }
        /* Attach to that memory segment */
        int data_shm_id = shmget((key_t)key, DATA_SHM_SIZE, 0666);
        if (data_shm_id < 0) {
            perror("shmget data");
            goto cleanup;
        }
        void *data_shm = shmat(data_shm_id, NULL, 0);
        if (data_shm == (void *)-1) {
            perror("shmat data");
            goto cleanup;
        }
        printf("[client] File contents:\n");
        fwrite(data_shm, 1, DATA_SHM_SIZE, stdout);
        /* We only know the real size – we could let the server send it,
           but for demo we just print until we hit a null or EOF.  */
        printf("\n");

        /* Detach (the server will remove the segment when done) */
        shmdt(data_shm);
    }

cleanup:
    /* Clean up our side */
    free(command);
    shmdt(cmd_shm_addr);
    sem_close(mutex_sem);
    sem_close(client_ready_sem);
    sem_close(server_ready_sem);

    return 0;
}
```

### What the client does

1. **Build** the command string from `argv` (`write fname data…` or `read fname`).  
2. **Attach** to the pre‑existing command shared memory.  
3. **Lock** the command area, **write** the command, **unlock** it.  
4. **Signal** the server with `client_ready_sem`.  
5. **Wait** on `server_ready_sem`.  
6. For a *read* command:  
   * The server writes the *key* of a new data shared memory into the same command area.  
   * The client reads that key, attaches to the new segment and prints its content.  

---

## 4.  Things to keep in mind

| Topic | Note |
|-------|------|
| **Semaphores** | We use *named* POSIX semaphores. They persist until the process closes them or the system is rebooted. In a real system you would unlink them once you are sure no process will use them again. |
| **Shared memory size** | `DATA_SHM_SIZE` is 4096 bytes – good for demo but not for large files. In production you would map the file directly or split the data into chunks. |
| **Error handling** | The code prints an error and exits on most failures. Production code should handle transient errors more gracefully. |
| **Race conditions** | All accesses to the command shared memory are protected by `mutex_sem`. The server signals the client only after it has finished processing the command, so the client can safely read the result. |
| **Security** | The shared memory is created with mode `0666`. Anyone who can run `client` could read/write the files. In a real system you would tighten permissions. |

---

## 5.  Build & run

```bash
# Compile
gcc -Wall -pthread -o server server.c
gcc -Wall -o client client.c

# Start server
./server          # leave this terminal open

# In another terminal run clients
./client write test.txt "Hello, world!"
./client read  test.txt
```

You should see output like

```
[server] Ready. Waiting for clients.
[client] Sending command: "write test.txt Hello, world!"
[server] wrote 13 bytes to test.txt
[client] Sending command: "read test.txt"
[server] sent file test.txt (size 13) via key 123456
[client] File contents:
Hello, world!
```

The server keeps running and can serve multiple clients concurrently – each client spawns a thread inside the server that handles the command. If you want the server to shut down cleanly you could trap signals and free all shared memory / semaphores before exiting.

