下面给出一份 **完整可编译** 的示例程序（基于你原先的框架）。  
核心思路：

1. **矩阵键盘** 只负责返回按下的字符。  
2. 把每个键映射到一个频率（`freq[]` 中的值）。  
3. 当处于 **录音** 状态时，按键既会立即发声又会把频率写入缓冲区。  
4. 通过 **K1‑K4**（你原来的 `key_scan` 函数）来控制录音/播放/暂停/停止。  
5. 播放时遍历缓冲区，按顺序播放所有音符。  
6. 通过 `song_playing` 标志在定时器 ISR 中产生方波；每个音符播放完后把该标志置为 0。

> **说明**  
> * 为简化实现，所有音符的持续时间均设为 200 ms（可自行修改）。  
> * `music_buffer` 只保存频率索引（0~12），最大长度 32。  
> * 当缓冲区满时会自动忽略后续按键。  
> * 你可以自行把 `key_scan(0)` 改为 `matrix_keypad_scan()`，或把矩阵键盘与 K1–K4 合并使用。

```c
/*  ======================  基础文件  ======================  */
#include "public.h"
#include "key.h"
#include "beep.h"
#include "songdata.h"

/*  ======================  时钟与计时器  ======================  */
#define Clk      0x070000          // 16‑MHz 时钟下的计数基准
unsigned char data val_H;          // 计数器高字节
unsigned char data val_L;          // 计数器低字节

/*  ======================  矩阵键盘  ======================  */
#define ROWS 4
#define COLS 4
sbit row1 = P1^7; sbit row2 = P1^6; sbit row3 = P1^5; sbit row4 = P1^4;
sbit col1 = P1^3; sbit col2 = P1^2; sbit col3 = P1^1; sbit col4 = P1^0;

const unsigned char keymap[ROWS][COLS] = {
    {'1','2','3','A'},
    {'4','5','6','B'},
    {'7','8','9','C'},
    {'*','0','#','D'}
};

/*  ======================  音符频率  ======================  */
const unsigned int freq[] = {
    262, 294, 330, 349, 392, 440, 494, 523, 0, 587, 659, 698, 784
};

/*  ======================  音乐缓冲区  ======================  */
#define MAX_BUFFER 32
unsigned char music_buffer[MAX_BUFFER];   // 只存频率索引
unsigned char music_len = 0;              // 已录音符数量

/*  ======================  状态枚举  ======================  */
typedef enum { IDLE, RECORDING, PLAYING, PAUSED } play_state_t;
play_state_t state = IDLE;

/*  ======================  全局标志  ======================  */
sbit P00 = P2^5;          // 扬声器控制引脚
bit song_playing = 0;     // 当为 1 时，定时器产生方波

/*  ======================  定时器中断  ======================  */
void t0_isr(void) interrupt 1
{
    if (song_playing)  /* 产生方波 */
        P00 = ~P00;
    else
        P00 = 1;       /* 关蜂鸣器 */

    TH0 = val_H;      /* 重新装载计数值 */
    TL0 = val_L;
}

/*  ======================  延时  ======================  */
void Delay(unsigned char cnt)          // 单位：约 1 ms (根据时钟可自行校准)
{
    unsigned int i;
    while (cnt--)
        for (i = 0; i < 0x3600; ++i);   // 约 1 ms
}

/*  ======================  矩阵键盘扫描  ======================  */
char matrix_keypad_scan(void)
{
    char key = 0;
    int i, j;
    /* 1. 行全高，列全低 */
    row1 = row2 = row3 = row4 = 1;
    col1 = col2 = col3 = col4 = 0;

    for (i = 0; i < ROWS; ++i)
    {
        /* 拉低当前行 */
        switch (i)
        {
        case 0: row1 = 0; break;
        case 1: row2 = 0; break;
        case 2: row3 = 0; break;
        case 3: row4 = 0; break;
        }
        /* 小延时让线路稳定 */
        Delay(1);

        /* 逐列检测 */
        for (j = 0; j < COLS; ++j)
        {
            if (col1 == 0) { key = keymap[i][j];   break; }
            if (col2 == 0) { key = keymap[i][j+1]; break; }
            if (col3 == 0) { key = keymap[i][j+2]; break; }
            if (col4 == 0) { key = keymap[i][j+3]; break; }
        }
        if (key) break;          /* 已找到按键 */
    }
    /* 等待按键释放 */
    while (col1==0 || col2==0 || col3==0 || col4==0);
    return key;
}

/*  ======================  按键 → 频率索引  ======================  */
int key_to_freq_index(char k)
{
    int i;
    for (i = 0; i < 13; ++i)
    {
        if (freq[i] == 0) continue;            // 0 为占位
        if (k == (char)('1' + i)) return i;    // '1'~'9'
        if (k == '0' && i == 10) return 10;    // 10 对应 '0'
        if (k == '*' && i == 11) return 11;    // 11 对应 '*'
        if (k == '#' && i == 12) return 12;    // 12 对应 '#'
    }
    /* 对 'A','B','C','D' 也做映射，可自行扩展 */
    return -1;  // 无效
}

/*  ======================  单音播放  ======================  */
void play_note(unsigned int frequency)
{
    unsigned int val = Clk / frequency;
    val = 0xFFFF - val;
    val_H = (val >> 8) & 0xFF;
    val_L = val & 0xFF;
    TH0 = val_H; TL0 = val_L;
    song_playing = 1;
    Delay(20);                // 约 200 ms（可根据需要改动）
    song_playing = 0;
}

/*  ======================  缓冲区播放  ======================  */
void playback(void)
{
    unsigned char idx = 0;
    while (state == PLAYING && idx < music_len)
    {
        play_note(freq[music_buffer[idx]]);
        idx++;
        /* 暂停检测（按下任何键即可暂停） */
        if (key_scan(0) != KEY_UNPRESS) { state = PAUSED; break; }
    }
    if (idx >= music_len) state = IDLE;   // 播放完毕
}

/*  ======================  主程序  ======================  */
void main(void)
{
    unsigned char k;
    TMOD = 0x01;          // 定时器 0 作为 16 位计数器
    IE   = 0x82;          // 允许中断
    TR0  = 1;             // 启动定时器

    while (1)
    {
        /* --------------------- 读取按键 --------------------- */
        /* 先检查 K1–K4（按键扫描函数） */
        k = key_scan(0);
        if (k == KEY1_PRESS)   /* 开始 / 结束录音 */
        {
            if (state == RECORDING) state = IDLE;    // 停止录音
            else {
                state = RECORDING;
                music_len = 0;                        // 清空缓冲区
            }
            continue;
        }
        else if (k == KEY2_PRESS) /* 开始 / 暂停 播放 */
        {
            if (state == PLAYING) state = PAUSED;
            else if (state == PAUSED) state = PLAYING;
            else if (state == IDLE && music_len > 0) state = PLAYING;
            continue;
        }
        else if (k == KEY3_PRESS) /* 停止播放并清空缓冲区 */
        {
            state = IDLE;
            music_len = 0;
            continue;
        }
        /* --------------------- 读取矩阵键盘 --------------------- */
        k = matrix_keypad_scan();
        if (k == 0) continue;          // 没有按键
        int idx = key_to_freq_index(k);
        if (idx < 0) continue;         // 不是音符键

        /* ① 立即播放对应音符 */
        play_note(freq[idx]);

        /* ② 录音状态下，保存频率索引 */
        if (state == RECORDING && music_len < MAX_BUFFER)
            music_buffer[music_len++] = idx;
    }
}
```

### 如何使用

| 按键 | 功能 |
|------|------|
| **K1** | 开始 / 结束录音（录音时按键会立即发声并保存到缓冲区） |
| **K2** | 开始 / 暂停 播放（若已录音可循环播放；暂停后再次按 K2 继续） |
| **K3** | 停止播放并清空缓冲区（即回到录音前的状态） |
| **K4** |（可自行扩展，例如退出程序或返回主菜单） |
| **矩阵键盘** | 任何音符键（1~9、0、\*、# 等）均会发出对应频率的音，并在录音时被记录 |

> **小结**  
> * 通过把 `song_playing` 交给定时器 ISR 控制，只要 `song_playing` 为 1，P00 就会在 ISR 内产生方波，音频输出保持稳定。  
> * 所有音符的频率都写在 `freq[]` 中，按键与频率的映射在 `key_to_freq_index()` 里完成。  
> * 播放过程是一个阻塞循环，若想让系统在播放时还能做其他事情，只需把 `playback()` 放进独立任务或改成非阻塞式即可。  

这样即可实现 **矩阵键盘演奏、录音、自动播放/暂停/退出** 的完整功能。

