/*  Shortest Job First (SJF) – non‑preemptive
    C11 – GCC 9+ (works with any modern C compiler)
*/

#include <stdio.h>
#include <stdlib.h>

struct sjfs {
    int bursttime;     /* time required on the CPU          */
    int waitingtime;   /* time process waits in ready queue */
    int totaltime;     /* turnaround time = burst + wait    */
};

int main(void)
{
    int n;

    printf("Enter the number of processes: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        fprintf(stderr, "Invalid number of processes.\n");
        return EXIT_FAILURE;
    }

    /* limit to 10 for simplicity – adjust if you need more */
    if (n > 10) {
        fprintf(stderr, "Maximum 10 processes allowed.\n");
        return EXIT_FAILURE;
    }

    struct sjfs p[10];

    printf("Enter the burst times of the %d processes:\n", n);
    for (int i = 0; i < n; ++i) {
        printf("  Burst time of process %d: ", i + 1);
        if (scanf("%d", &p[i].bursttime) != 1 || p[i].bursttime < 0) {
            fprintf(stderr, "Invalid burst time.\n");
            return EXIT_FAILURE;
        }
    }

    /* ------------------------------------------------------------------ */
    /* 1. Sort processes by burst time (Shortest Job First)                */
    /* ------------------------------------------------------------------ */
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (p[j].bursttime > p[j + 1].bursttime) {
                struct sjfs tmp = p[j];
                p[j]     = p[j + 1];
                p[j + 1] = tmp;
            }
        }
    }

    /* ------------------------------------------------------------------ */
    /* 2. Compute waiting time and turnaround time                         */
    /* ------------------------------------------------------------------ */
    int cumulativeBurst = 0;     /* running sum of burst times   */
    int totalWaiting    = 0;     /* sum of all waiting times     */

    printf("\nSJF schedule results:\n");
    for (int i = 0; i < n; ++i) {
        p[i].waitingtime = cumulativeBurst;
        p[i].totaltime   = p[i].bursttime + p[i].waitingtime;

        cumulativeBurst += p[i].bursttime;
        totalWaiting    += p[i].waitingtime;

        printf("Process %2d:  burst = %3d,  waiting = %3d,  turnaround = %3d\n",
               i + 1, p[i].bursttime, p[i].waitingtime, p[i].totaltime);
    }

    /* ------------------------------------------------------------------ */
    /* 3. Average waiting time                                            */
    /* ------------------------------------------------------------------ */
    double avgWaiting = (double)totalWaiting / n;
    printf("\nAverage waiting time = %.2f\n", avgWaiting);

    return EXIT_SUCCESS;
}
```

---

### How it works

1. **Input** – the program reads up to 10 burst times.  
2. **Sorting** – a classic bubble sort (you can replace it with `qsort` if you like) reorders the array of structures by `bursttime`.  
3. **Timing** – a single scan calculates waiting time (`cumulativeBurst`) and turnaround time (`burst + waiting`).  
4. **Output** – prints the per‑process data and the average waiting time.

