            p += 1;
            return M_E;
        }
        /* Функция */
        return parse_function();
    }

    /* Число */
    double val;
    if (isdigit((unsigned char)*p) || *p == '.') {
        val = parse_number();
    } else if (*p == '(') {
        /* Скобки */
        p++;                  /* '(' */
        val = parse_expression();
        skip_spaces();
        if (*p != ')') {
            fprintf(stderr, "Ошибка: не найдена закрывающая скобка.\n");
