/* * и / */
static double parse_term(void)
{
    double val = parse_factor();
    for (;;) {
        skip_spaces();
        if (*p == '*') {
            p++;
            val *= parse_factor();
        } else if (*p == '/') {
            p++;
            double denom = parse_factor();
            if (denom == 0) {
                fprintf(stderr, "Ошибка: деление на ноль.\n");
                exit(EXIT_FAILURE);
            }
            val /= denom;
        } else break;
    }
    return val;
}

/* + и - */
static double parse_expression(void)
{
    double val = parse_term();
    for (;;) {
        skip_spaces();
        if (*p == '+') {
            p++;
            val += parse_term();
        } else if (*p == '-') {
            p++;
            val -= parse_term();
        } else break;
    }
    return val;
}

