## 2. 代码实现（C 语言）  

```c
/*********************************************************************
 *  磁盘调度算法演示：FCFS、SSTF、SCAN
 *  1. 从键盘读取请求序列
 *  2. 输入磁头初始位置、移动方向、磁盘最大磁道号
 *  3. 输出各算法的调度次序及平均寻道长度
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

/* ---------- 结构体 ---------- */
typedef struct {
    int *req;          // 请求序列
    int n;             // 请求数
    int head;          // 当前磁头位置
    int direction;     // 初始方向：1 (向上) 或 -1 (向下)
    int maxTrack;      // 磁盘最大磁道号
} DiskScheduling;

/* ---------- 工具函数 ---------- */

/* 计算平均寻道长度 */
double avgSeekLength(const int *order, int n, int start)
{
    int sum = 0;
    int cur = start;
    for (int i = 0; i < n; ++i) {
        sum += abs(order[i] - cur);
        cur = order[i];
    }
    return (double)sum / n;
}

/* 打印调度顺序 */
void printOrder(const int *order, int n, const char *algName)
{
    printf("\n--- %s 调度顺序 ---\n", algName);
    for (int i = 0; i < n; ++i) {
        printf("%4d", order[i]);
    }
    printf("\n");
}

/* ---------- 调度算法 ---------- */

/* 1) FCFS */
void fcfs(const int *req, int n, int start, int *orderOut)
{
    memcpy(orderOut, req, n * sizeof(int));
}

/* 2) SSTF */
void sstf(const int *req, int n, int start, int *orderOut)
{
    int *visited = (int*)calloc(n, sizeof(int));
    int cur = start;

    for (int i = 0; i < n; ++i) {
        int bestIdx = -1;
        int bestDist = INT_MAX;
        for (int j = 0; j < n; ++j) {
            if (visited[j]) continue;
            int dist = abs(req[j] - cur);
            if (dist < bestDist) {
                bestDist = dist;
                bestIdx = j;
            }
        }
        visited[bestIdx] = 1;
        orderOut[i] = req[bestIdx];
        cur = req[bestIdx];
    }
    free(visited);
}

/* 3) SCAN (Elevator) */
void scan(const int *req, int n, int start, int direction, int maxTrack, int *orderOut)
{
    /* 先把请求分成两组：大于等于起点和小于起点 */
    int *above = (int*)malloc(n * sizeof(int));
    int *below = (int*)malloc(n * sizeof(int));
    int upCnt = 0, lowCnt = 0;

    for (int i = 0; i < n; ++i) {
        if (req[i] >= start) {
            above[upCnt++] = req[i];
        } else {
            below[lowCnt++] = req[i];
        }
    }

    /* 排序：大于起点的升序，小于起点的降序 */
    qsort(above, upCnt, sizeof(int), (__compar_fn_t)memcmp);
    qsort(below, lowCnt, sizeof(int), (__compar_fn_t)memcmp);
    /* 由于 qsort 无法直接实现降序，用逆序遍历即可 */

    int idx = 0;

    /* 根据初始方向决定先走哪一边 */
    if (direction == 1) {  /* 向上 */
        /* 先服务 above */
        for (int i = 0; i < upCnt; ++i)
            orderOut[idx++] = above[i];
        /* 到达磁盘最大端再反向 */
        if (upCnt < n) { /* 只有当还有请求时才需要反向 */
            for (int i = lowCnt - 1; i >= 0; --i)
                orderOut[idx++] = below[i];
        }
    } else {              /* 向下 */
        /* 先服务 below（降序） */
        for (int i = lowCnt - 1; i >= 0; --i)
            orderOut[idx++] = below[i];
        /* 到达磁盘最小端再反向 */
        if (lowCnt < n) {
            for (int i = 0; i < upCnt; ++i)
                orderOut[idx++] = above[i];
        }
    }

    free(above);
    free(below);
}

/* ---------- 主函数 ---------- */

int main(void)
{
    DiskScheduling ds;

    /* 1. 读取请求序列 */
    printf("请输入磁道请求序列（以空格或回车分隔，输入 -1 结束）：\n");
    int temp, count = 0;
    int reqArray[200];   /* 预留足够空间 */
    while (scanf("%d", &temp) == 1 && temp != -1) {
        reqArray[count++] = temp;
    }
    ds.n = count;
    ds.req = reqArray;

    if (ds.n == 0) {
        printf("没有有效请求，程序结束。\n");
        return 0;
    }

    /* 2. 输入磁头起始位置、方向、最大磁道号 */
    printf("请输入磁头起始位置（整数）: ");
    scanf("%d", &ds.head);

    printf("请输入磁头初始移动方向（1 表示向上，-1 表示向下）: ");
    scanf("%d", &ds.direction);
    if (ds.direction != 1 && ds.direction != -1) {
        printf("方向输入错误，程序结束。\n");
        return 1;
    }

    printf("请输入磁盘最大磁道号（整数）：");
    scanf("%d", &ds.maxTrack);

    /* 3. 为每个算法准备输出顺序数组 */
    int orderFCFS[ds.n], orderSSTF[ds.n], orderSCAN[ds.n];

    /* 4. 计算调度顺序 */
    fcfs(ds.req, ds.n, ds.head, orderFCFS);
    sstf(ds.req, ds.n, ds.head, orderSSTF);
    scan(ds.req, ds.n, ds.head, ds.direction, ds.maxTrack, orderSCAN);

    /* 5. 打印结果 */
    printOrder(orderFCFS, ds.n, "FCFS");
    double avgFCFS = avgSeekLength(orderFCFS, ds.n, ds.head);
    printf("FCFS 平均寻道长度: %.2f\n", avgFCFS);

    printOrder(orderSSTF, ds.n, "SSTF");
    double avgSSTF = avgSeekLength(orderSSTF, ds.n, ds.head);
    printf("SSTF 平均寻道长度: %.2f\n", avgSSTF);

    printOrder(orderSCAN, ds.n, "SCAN");
    double avgSCAN = avgSeekLength(orderSCAN, ds.n, ds.head);
    printf("SCAN 平均寻道长度: %.2f\n", avgSCAN);

    return 0;
}
