#include <linux/io.h>      // ioremap, readl, writel
#include <linux/dma-mapping.h> // 如果要做 DMA
#include <linux/slab.h>

#define PHYS_ADDR  0x000010UL          /* 物理起始地址 */
#define MEM_SIZE   (128UL * 1024 * 1024)/* 128 MB */

static void __iomem *mem_base = NULL;  /* 映射后的虚拟地址 */

/* 读取一个 32 位数据 */
static u32 read_reg(u32 offset)
{
    /* offset 以字节为单位 */
    return readl(mem_base + offset);
}

/* 写入一个 32 位数据 */
static void write_reg(u32 offset, u32 val)
{
    writel(val, mem_base + offset);
}

/* 驱动初始化 */
static int __init my_driver_init(void)
{
