    }
}

static int lexer_peek(Lexer *lx)
{
    lexer_skip_whitespace(lx);
    if (lx->pos >= lx->len) return -1;
    return lx->buf[lx->pos];
}

/* Читает идентификатор (или ключевое слово) */
static char *lexer_read_identifier(Lexer *lx)
{
    lexer_skip_whitespace(lx);
    size_t start = lx->pos;
    if (lx->pos < lx->len &&
        (isalpha((unsigned char)lx->buf[lx->pos]) || lx->buf[lx->pos] == '_')) {
        ++lx->pos;
        while (lx->pos < lx->len &&
               (isalnum((unsigned char)lx->buf[lx->pos]) ||
                lx->buf[lx->pos] == '_')) {
            ++lx->pos;
        }
        size_t len = lx->pos - start;
        char *s = malloc(len + 1);
        memcpy(s, lx->buf + start, len);
        s[len] = '\0';
        return s;
    }
    return NULL;
}

/* Читает один символ (пунктуацию) */
static char lexer_read_punct(Lexer *lx)
{
    lexer_skip_whitespace(lx);
    if (lx->pos >= lx->len) return '\0';
    return lx->buf[lx->pos++];
}

/* ------------------------------------------------------------------ */
/* 4. Основной алгоритм: ищем определения функций и вызовы            */
/* ------------------------------------------------------------------ */

/* Читаем тело функции до соответствующего '}' (с учётом вложенных {} ) */
static void parse_function_body(Lexer *lx, Function *current_func)
{
    int brace_depth = 0;
    while (lx->pos < lx->len) {
        lexer_skip_whitespace(lx);
        if (lx->pos >= lx->len) break;

        char c = lexer_peek(lx);
        /* Обработка скобок */
        if (c == '{') {
            ++brace_depth; ++lx->pos;
            continue;
        }
        if (c == '}') {
            if (brace_depth == 0) { ++lx->pos; break; } /* конец функции */
            --brace_depth; ++lx->pos;
            continue;
        }

        /* Проверяем возможный вызов функции: идентификатор '(' */
        if (isalpha((unsigned char)c) || c == '_') {
            char *ident = lexer_read_identifier(lx);
            if (!ident) continue;  /* safety */

            lexer_skip_whitespace(lx);
            c = lexer_peek(lx);
            if (c == '(') {          /* это потенциальный вызов */
                /* Скачиваем всё до соответствующей ')' – игнорируем аргументы */
                ++lx->pos;            /* '(' */
                int paren_depth = 1;
                while (lx->pos < lx->len && paren_depth > 0) {
                    char d = lx->buf[lx->pos++];
                    if (d == '(') ++paren_depth;
                    else if (d == ')') --paren_depth;
                    else if (d == '"' || d == '\'') { /* пропускаем литералы */
                        char quote = d;
                        while (lx->pos < lx->len) {
                            d = lx->buf[lx->pos++];
                            if (d == '\\') { lx->pos++; continue; }
                            if (d == quote) break;
                        }
                    }
                }
                /* Добавляем вызов */
                if (!is_keyword(ident)) {
                    Function *callee = find_or_create_func(ident);
                    add_call(current_func, callee);
                }
            } else {
                /* Это просто идентификатор (переменная, тип и т.д.) – ничего не делаем */
            }
            free(ident);
        } else {
            /* Обычный символ – пропускаем */
            ++lx->pos;
        }
    }
}

static void parse_file(const char *filename)
{
    /* Считываем файл полностью */
    FILE *f = fopen(filename, "rb");
    if (!f) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    fread(buf, 1, sz, f);
    fclose(f);
    buf[sz] = '\0';

    Lexer lx = { buf, (size_t)sz, 0 };

    /* Парсим весь файл */
    while (lx.pos < lx.len) {
        lexer_skip_whitespace(&lx);
        if (lx.pos >= lx.len) break;

        /* Смотрим, возможно ли начало объявления/определения функции */
        if (isalpha((unsigned char)lx.buf[lx.pos]) ||
            lx.buf[lx.pos] == '_' ) {
            /* Сохраняем текущую позицию, читаем идентификатор */
            size_t start_pos = lx.pos;
            char *ident = lexer_read_identifier(&lx);
            if (!ident) break;   /* safety */

            lexer_skip_whitespace(&lx);
            int next = lexer_peek(&lx);
            if (next == '(') {
                /* Читаем список параметров */
                int paren_depth = 0;
                while (lx.pos < lx.len) {
                    char d = lx.buf[lx.pos++];
                    if (d == '(') ++paren_depth;
                    else if (d == ')') {
                        --paren_depth;
                        if (paren_depth == 0) break;
                    }
                    else if (d == '"' || d == '\'') { /* пропускаем строки/символы */
                        char quote = d;
                        while (lx.pos < lx.len) {
                            d = lx.buf[lx.pos++];
                            if (d == '\\') { lx.pos++; continue; }
                            if (d == quote) break;
                        }
                    }
                }

                lexer_skip_whitespace(&lx);
                next = lexer_peek(&lx);
                if (next == '{') {
                    /* Это определение функции */
                    Function *func = find_or_create_func(ident);
                    ++lx.pos;            /* пропускаем '{' */
                    parse_function_body(&lx, func);
                }
            }
            free(ident);
        } else {
            /* просто пропускаем символ */
            ++lx.pos;
        }
    }

    free(buf);
}

/* ------------------------------------------------------------------ */
/* 5. Вывод результата                                               */
/* ------------------------------------------------------------------ */

static void print_call_graph(Function *f, int indent)
{
    for (int i = 0; i < indent; ++i) putchar(' ');
    printf("%s\n", f->name);
    for (CallNode *c = f->calls; c; c = c->next) {
        print_call_graph(c->callee, indent + 4);
    }
}

static int has_caller(Function *f)
{
    for (Function *g = func_head; g; g = g->next) {
        for (CallNode *c = g->calls; c; c = c->next)
            if (c->callee == f) return 1;
    }
    return 0;
}

int main(void)
{
    const char *infile = "test.txt";
    parse_file(infile);

    /* Выводим все «корни» дерева (функции, которые никто не вызывает) */
    printf("Call‑graph (roots shown):\n");
    for (Function *f = func_head; f; f = f->next) {
        if (!has_caller(f)) {
            print_call_graph(f, 0);
            putchar('\n');
        }
    }
    return 0;
}
```

### Как работает

1. **Чтение файла** – читается весь `test.txt` в строку.
2. **Лексический разбор** – пропускаются комментарии, строки и
   символьные литералы, чтобы не «обманываться» содержимым строк
   (например, `printf("foo(%s)", bar);`).
3. **Определения функций** – ищется шаблон  
   `… identifier ( … ) { … }`.  
   Когда такой блок найден, создаётся (или берётся уже существующий)
   объект `Function`, и его тело парсится для поиска вызовов.
4. **Вызовы** – внутри тела функции любой идентификатор, за которым
   сразу следует `(`, считается вызовом. Ключевые слова С игнорируются.
5. **Структура графа** – каждая функция хранит список вызовов
   (указателей на другие `Function`).  
   Для упрощения – линейный поиск вместо хэш‑таблицы.
6. **Вывод** – печатается дерево вызовов, начиная с функций‑корней
   (тех, которые никто не вызывает). Отступы показывают уровень
   вложенности.

### Ограничения

* Не обрабатываются макросы, `typedef`, функции, объявленные через
  указатели и т.п.
* Не учитывается условное компилирование (`#ifdef`).
* Для больших проектов требуется более надёжный парсер (например,
  Flex/Bison, Clang/LLVM).

Тем не менее, для простого анализа небольших файлов C
эта программа должна работать почти без ошибок.

