下面给出一份完整、可直接编译、可直接使用的 **C 代码示例**，演示如何把一段内存中的像素数据（这里假设是 24 bpp 的 RGB 颜色）写成一个标准的 **Windows BMP** 文件。  
代码同样可以轻松改造为 8 bpp、16 bpp、32 bpp 或灰度图的写出，只需要调整 `BITMAPINFOHEADER.biBitCount`、调配颜色表以及像素字节数即可。

---

## 1. BMP 文件结构回顾

| 结构 | 说明 | 大小（字节） | 备注 |
|------|------|--------------|------|
| `BITMAPFILEHEADER` | 文件头，前 14 字节 | 14 | 只用于文件系统，包含文件大小、偏移量等 |
| `BITMAPINFOHEADER` | DIB 头，Windows 官方版本 | 40 | 包含宽度、高度、位数、压缩方式等 |
| **可选**颜色表 | 仅在 1/4/8 bpp 时存在 |  |  |
| 像素数据 | 从右下角开始逆序存放 |  | 每行需填充至 4‑字节边界 |

> **行填充**：每行像素字节数必须是 4 的整数倍。若不足，则在行尾补 0。

---

## 2. 关键结构体

```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* BMP 文件头：14 字节 */
#pragma pack(push, 1)                /* 强制无填充 */
typedef struct {
    uint16_t bfType;      /* 0x4D42 = 'BM' */
    uint32_t bfSize;      /* 文件大小，单位字节 */
    uint16_t bfReserved1; /* 保留，必须为 0 */
    uint16_t bfReserved2; /* 保留，必须为 0 */
    uint32_t bfOffBits;   /* 像素数据起始偏移量 */
} BITMAPFILEHEADER;

/* BMP DIB 头（Windows BITMAPINFOHEADER）：40 字节 */
typedef struct {
    uint32_t biSize;          /* 本结构体大小，40 字节 */
    int32_t  biWidth;         /* 图像宽度（像素） */
    int32_t  biHeight;        /* 图像高度（像素），正值表示底部→顶部 */
    uint16_t biPlanes;        /* 颜色平面数，固定为 1 */
    uint16_t biBitCount;      /* 每像素位数（24、32…） */
    uint32_t biCompression;   /* 压缩方式（0 = BI_RGB） */
    uint32_t biSizeImage;     /* 图像数据大小（含行填充） */
    int32_t  biXPelsPerMeter; /* 水平分辨率（可填 0） */
    int32_t  biYPelsPerMeter; /* 垂直分辨率（可填 0） */
    uint32_t biClrUsed;       /* 实际使用的调色板条目数（0 = 自动） */
    uint32_t biClrImportant;  /* 重要色数（0 = 所有） */
} BITMAPINFOHEADER;
#pragma pack(pop)
```

> `#pragma pack(push, 1)`/`#pragma pack(pop)` 用来保证结构体按 **1 字节对齐**，与 BMP 文件规范严格一致。

---

## 3. 写 BMP 的核心函数

```c
/**
 * @brief 将内存中的 RGB24 图像写成 BMP 文件
 * @param filename     输出文件名
 * @param data         指向像素数据的指针，长度必须为 width * height * 3
 * @param width        图像宽度（像素）
 * @param height       图像高度（像素）
 * @return 0 成功，非0 失败
 */
int write_rgb24_to_bmp(const char *filename, const uint8_t *data,
                       int width, int height)
{
    if (!filename || !data || width <= 0 || height <= 0)
        return -1;

    /* 计算每行的字节数（按 4 字节对齐） */
    int rowBytes = (width * 3 + 3) & ~3;   /* 3*width 的下一个 4 的倍数 */
    uint32_t pixelDataSize = rowBytes * height;

    /* ① 组装文件头 */
    BITMAPFILEHEADER fileHeader;
    fileHeader.bfType      = 0x4D42;            /* 'BM' */
    fileHeader.bfOffBits   = sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER);
    fileHeader.bfReserved1 = 0;
    fileHeader.bfReserved2 = 0;
    fileHeader.bfSize      = fileHeader.bfOffBits + pixelDataSize;

    /* ② 组装 DIB 头 */
    BITMAPINFOHEADER infoHeader;
    memset(&infoHeader, 0, sizeof(infoHeader));
    infoHeader.biSize          = sizeof(BITMAPINFOHEADER);
    infoHeader.biWidth         = width;
    infoHeader.biHeight        = height;          /* 正值：底部→顶部 */
    infoHeader.biPlanes        = 1;
    infoHeader.biBitCount      = 24;
    infoHeader.biCompression   = 0;                 /* BI_RGB，未压缩 */
    infoHeader.biSizeImage     = pixelDataSize;
    infoHeader.biXPelsPerMeter = 0;
    infoHeader.biYPelsPerMeter = 0;
    infoHeader.biClrUsed       = 0;
    infoHeader.biClrImportant  = 0;

    /* ③ 打开文件 */
    FILE *fp = fopen(filename, "wb");
    if (!fp) return -1;

    /* ④ 写入头部 */
    if (fwrite(&fileHeader, 1, sizeof(fileHeader), fp) != sizeof(fileHeader) ||
        fwrite(&infoHeader, 1, sizeof(infoHeader), fp) != sizeof(infoHeader))
    {
        fclose(fp);
        return -1;
    }

    /* ⑤ 写像素数据（按 BMP 规则：行从底部往顶部、行对齐） */
    uint8_t *rowBuf = malloc(rowBytes);
    if (!rowBuf) {
        fclose(fp);
        return -1;
    }

    for (int y = height - 1; y >= 0; --y) {        /* 从底部行开始 */
        const uint8_t *srcRow = data + y * width * 3;
        memcpy(rowBuf, srcRow, width * 3);          /* 复制像素 */
        if (rowBytes > width * 3)
            memset(rowBuf + width * 3, 0, rowBytes - width * 3); /* 补齐 */
        if (fwrite(rowBuf, 1, rowBytes, fp) != rowBytes) {
            free(rowBuf);
            fclose(fp);
            return -1;
        }
    }

    free(rowBuf);
    fclose(fp);
    return 0;
}
```

### 代码要点

1. **像素顺序**  
   BMP 存储顺序为 **B、G、R**，而许多图像库（OpenCV、SDL 等）使用 **R、G、B**。如果你手头的数据是 RGB，只需要把 `srcRow` 的顺序改成 BGR，或者在写入前做一次 `swap`。上面示例假设数据已是 BGR 顺序，若不是请自行换位。

2. **行填充**  
   `rowBytes` 的计算保证每行字节数为 4 的整数倍。若 `width * 3` 已是 4 的倍数，填充字节为 0。

3. **负高度**  
   若想生成从 **顶部到底部** 的 BMP，只需把 `infoHeader.biHeight` 设为 `-height`。但大多数工具默认正高度，下面示例使用正高度（底部→顶部）。

---

## 4. 示例：生成 200 × 200 像素的彩色正弦波图

下面给出一个完整的 `main`，演示如何构造一幅图像并写入 BMP。

```c
int main(void)
{
    const int W = 200, H = 200;
    uint8_t *buf = malloc(W * H * 3);
    if (!buf) return 1;

    /* 生成简单的彩色梯度 + 正弦波 */
    for (int y = 0; y < H; ++y) {
        for (int x = 0; x < W; ++x) {
            /* 颜色梯度：R 随 X，G 随 Y，B 随正弦波 */
            uint8_t r = (uint8_t)(x * 255 / W);
            uint8_t g = (uint8_t)(y * 255 / H);
            uint8_t b = (uint8_t)(127 + 127 * sin(2.0 * M_PI * x / W));

            /* BMP 采用 BGR 顺序 */
            int idx = (y * W + x) * 3;
            buf[idx + 0] = b;
            buf[idx + 1] = g;
            buf[idx + 2] = r;
        }
    }

    if (write_rgb24_to_bmp("demo.bmp", buf, W, H) == 0)
        puts("BMP 写入成功: demo.bmp");
    else
        puts("BMP 写入失败");

    free(buf);
    return 0;
}
```

> 编译方式（gcc）  
> `gcc -o bmp_demo bmp_demo.c -lm`  
> （`-lm` 用于 `sin()`）

---

## 5. 进一步扩展

| 需求 | 代码改动 |
|------|----------|
| **8 bpp 灰度** | `biBitCount = 8`；需要在 `BITMAPINFOHEADER` 之后写 256 条调色板（每条 `0x00 0x00 0x00 0x00` + `i` + `i` + `i`）。像素数据仅 1 字节/像素，且行填充仍按 4 字节对齐。 |
| **32 bpp** | `biBitCount = 32`；像素为 `BGRA`，每像素 4 字节；行填充一般不需要（因为 4 字节对齐）。 |
| **压缩** | `biCompression = BI_RLE8` 或 `BI_RLE4`，需要实现对应的 RLE 编码。 |
| **大内存** | 采用分块写入：先写头部，然后每次读取/生成一行（或多行）写入文件，避免一次性占用太多内存。 |

---

## 6. 小结

- BMP 文件是最为简单的桌面图片格式之一，**不需要任何压缩**，因此实现起来非常直观。
- 只要掌握了 **文件头**、**DIB 头**、**颜色表（如果需要）** 以及 **像素行填充** 的规则，即可在 C 语言中完成任何位数的 BMP 写出。
- 上面给出的 `write_rgb24_to_bmp()` 函数已可直接使用，满足普通 24 bpp 彩色图的需求；如需其他位数，只需稍作修改即可。

