 *    gcc -std=c99 -Wall -Wextra -o calendar.exe calendar.c
 *
 *  说明：
 *    - 采用自定义 Date 结构体保存年月日
 *    - 通过简单的循环和边界检查实现加/减
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/* --------------------------- 数据结构 --------------------------- */
typedef struct {
    int year;   /* 年份，范围 1 ~ 9999 之内 */
    int month;  /* 月份 1 ~ 12 */
    int day;    /* 日期 1 ~ 31（根据月份和闰年决定） */
} Date;

/* --------------------------- 工具函数 --------------------------- */

/* 判断闰年 */
bool is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

/* 返回某年某月的天数 */
int days_in_month(int year, int month) {
    static const int days[12] = {31,28,31,30,31,30,31,31,30,31,30,31};
    if (month == 2 && is_leap_year(year))
        return 29;
    return days[month - 1];
}

/* 验证日期合法性（返回 true 说明合法） */
bool is_valid_date(const Date *d) {
    if (d->year < 1 || d->year > 9999) return false;
    if (d->month < 1 || d->month > 12) return false;
    int dim = days_in_month(d->year, d->month);
    if (d->day < 1 || d->day > dim) return false;
    return true;
}

/* 通过字符串输入读取日期（返回 true 表示成功） */
bool input_date(Date *d) {
    printf("请输入初始日期（格式: YYYY MM DD）：");
    if (scanf("%d %d %d", &d->year, &d->month, &d->day) != 3) {
        /* 清空输入缓冲区 */
        int c;
        while ((c = getchar()) != '\n' && c != EOF) {}
        return false;
    }
    if (!is_valid_date(d)) {
        printf("日期不合法，请重新输入！\n");
        return false;
    }
    return true;
}

/* 打印日期 */
void print_date(const Date *d) {
    printf("%04d-%02d-%02d\n", d->year, d->month, d->day);
}

/* --------------------------- 日期增/减 --------------------------- */

/* 通过调整 years, months, days（可以为负值）来改变日期 */
void adjust_date(Date *d, int years, int months, int days) {
    /* 先调整年份 */
    d->year += years;

    /* 再调整月份，处理跨年情况 */
    d->month += months;
    while (d->month > 12) {
        d->month -= 12;
        d->year += 1;
    }
    while (d->month < 1) {
        d->month += 12;
        d->year -= 1;
    }

    /* 确保年份仍在合法范围内 */
    if (d->year < 1) d->year = 1;
    if (d->year > 9999) d->year = 9999;

    /* 再调整天数，处理跨月/跨年 */
    d->day += days;
    while (d->day > days_in_month(d->year, d->month)) {
        d->day -= days_in_month(d->year, d->month);
        d->month += 1;
        if (d->month > 12) {
            d->month = 1;
            d->year += 1;
        }
    }
    while (d->day < 1) {
        d->month -= 1;
        if (d->month < 1) {
            d->month = 12;
            d->year -= 1;
        }
        d->day += days_in_month(d->year, d->month);
    }

    /* 最后再次校正天数（防止闰年/非闰年导致的 29/28 误差） */
    int dim = days_in_month(d->year, d->month);
    if (d->day > dim) d->day = dim;
}

/* 具体增/减功能的包装（更直观） */
void add_year(Date *d, int n)      { adjust_date(d, n, 0, 0); }
void sub_year(Date *d, int n)      { adjust_date(d, -n, 0, 0); }
void add_month(Date *d, int n)     { adjust_date(d, 0, n, 0); }
void sub_month(Date *d, int n)     { adjust_date(d, 0, -n, 0); }
void add_day(Date *d, int n)       { adjust_date(d, 0, 0, n); }
void sub_day(Date *d, int n)       { adjust_date(d, 0, 0, -n); }

/* --------------------------- 主程序 --------------------------- */
void show_menu() {
    printf("\n--- 万年历实验菜单 ---\n");
    printf("1  增加年份\n");
    printf("2  减少年份\n");
    printf("3  增加月份\n");
    printf("4  减少月份\n");
    printf("5  增加日期\n");
    printf("6  减少日期\n");
    printf("7  重置为初始时间\n");
    printf("0  退出程序\n");
    printf("请选择操作 (0-7)：");
}

int main(void) {
    Date init_date, cur_date;
    /* 输入初始日期，循环直到合法 */
    while (!input_date(&init_date)) {}

    cur_date = init_date;   /* 当前日期从初始值开始 */

    int choice;
    while (1) {
        printf("\n当前日期: ");
        print_date(&cur_date);

        show_menu();
        if (scanf("%d", &choice) != 1) {
            /* 输入错误，清空缓冲区 */
            int c;
            while ((c = getchar()) != '\n' && c != EOF) {}
            printf("输入无效，请重新输入！\n");
            continue;
        }

        switch (choice) {
            case 1: {
                int n;
                printf("请输入要增加的年份数：");
                if (scanf("%d", &n) == 1) add_year(&cur_date, n);
                else { /* 错误处理 */ }
                break;
            }
            case 2: {
                int n;
                printf("请输入要减少的年份数：");
                if (scanf("%d", &n) == 1) sub_year(&cur_date, n);
                break;
            }
            case 3: {
                int n;
                printf("请输入要增加的月份数：");
                if (scanf("%d", &n) == 1) add_month(&cur_date, n);
                break;
            }
            case 4: {
                int n;
                printf("请输入要减少的月份数：");
                if (scanf("%d", &n) == 1) sub_month(&cur_date, n);
                break;
            }
            case 5: {
                int n;
                printf("请输入要增加的日期数：");
                if (scanf("%d", &n) == 1) add_day(&cur_date, n);
                break;
            }
            case 6: {
                int n;
                printf("请输入要减少的日期数：");
                if (scanf("%d", &n) == 1) sub_day(&cur_date, n);
                break;
            }
            case 7:   /* 重置 */
                cur_date = init_date;
                printf("已重置到初始日期。\n");
                break;
            case 0:   /* 退出 */
                printf("退出程序。\n");
                return 0;
            default:
                printf("无效的选项，请重新选择。\n");
        }
    }
    return 0;
}
```

### 说明

1. **日期校验**  
