```c
#include <stdio.h>
#include <math.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;        // 读入样本数

    double data[100];                          // 存放读入的数据
    double sum = 0.0;

    for (int i = 0; i < n; ++i) {
        int x;
        scanf("%d", &x);
        data[i] = (double)x;
        sum += data[i];
    }

    double mean = sum / n;                     // 平均值

    double sumSqDiff = 0.0;                    // 离均差平方和
    for (int i = 0; i < n; ++i) {
        double diff = data[i] - mean;
        sumSqDiff += diff * diff;
    }

    double stddev;
    if (n <= 1)
        stddev = 0.0;                          // n==1 时标准差取 0
    else
        stddev = sqrt(sumSqDiff / (n - 1));    // 样本标准差

    printf("%.2f\n", mean);
    printf("%.2f\n", sumSqDiff);
    printf("%.2f\n", stddev);

    return 0;
}
