/*  Программа:  Количество точек пересечения двух окружностей
 *  Ввод:  x1 y1 r1  x2 y2 r2  – координаты центров и радиусы
 *  Вывод: 0 – пересечений нет
 *          1 – внешняя/внутренняя каска
 *          2 – две точки пересечения
 *         -1 – окружности совпадают (бесконечно много точек пересечения)
 *
 *  Используются только простые конструкции языка C, без функций (кроме main).
 */

#include <stdio.h>
#include <math.h>          /* для fabs и sqrt */

int main(void)
{
    double x1, y1, r1;     /* данные первой окружности   */
    double x2, y2, r2;     /* данные второй окружности  */
    double dx, dy;         /* разность координат         */
    double d2;             /* квадрат расстояния между центрами */
    double sumR, diffR;    /* суммы и разности радиусов */
    double sumR2, diffR2;  /* квадраты сумм и разностей */
    int result;            /* количество точек пересечения */

    /* ввод данных */
    printf("Введите x1 y1 r1: ");
    if (scanf("%lf %lf %lf", &x1, &y1, &r1) != 3) return 1;

    printf("Введите x2 y2 r2: ");
    if (scanf("%lf %lf %lf", &x2, &y2, &r2) != 3) return 1;

    /* вычисляем расстояние между центрами в квадрате */
    dx = x2 - x1;
    dy = y2 - y1;
    d2 = dx * dx + dy * dy;

    sumR = r1 + r2;
    diffR = fabs(r1 - r2);

    sumR2 = sumR * sumR;
    diffR2 = diffR * diffR;

    /* определяем число точек пересечения */
    if (fabs(d2 - sumR2) < 1e-9)          /* внешняя каска */
        result = 1;
    else if (fabs(d2 - diffR2) < 1e-9)     /* внутренняя каска */
        result = 1;
    else if (d2 > sumR2)                  /* центры «далее», чем сумма радиусов */
        result = 0;
    else if (d2 < diffR2)                 /* одна окружность полностью внутри другой */
        result = 0;
    else if (d2 == 0 && r1 == r2)         /* совпадают центры и радиусы */
        result = -1;                      /* бесконечно много точек */
    else                                   /* обычный случай – 2 точки пересечения */
        result = 2;

    /* вывод результата */
    if (result == -1)
        printf("Окружности совпадают – бесконечно много точек пересечения.\n");
    else
        printf("Количество точек пересечения: %d\n", result);

    return 0;
}
