#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

/* ---------- Hash table for int → int (key → value) ---------- */

#define HASH_TABLE_SIZE  (1 << 20)   /* 1,048,576 buckets – plenty for small data */

typedef struct Entry {
    int key;            /* the value stored in the array a[]  */
    int value;          /* 1‑based index of the last occurrence of key   */
    struct Entry *next; /* for separate chaining               */
} Entry;

static Entry *hash_table[HASH_TABLE_SIZE] = { NULL };

/* Simple integer hash function */
static inline unsigned int hash_int(int x)
{
    /* Knuth's multiplicative method */
    return (unsigned int)((x * 2654435761u) & (HASH_TABLE_SIZE - 1));
}

/* Insert or update a key → value mapping */
static void map_insert(int key, int value)
{
    unsigned int h = hash_int(key);
    Entry *e = hash_table[h];

    /* Update existing key if present */
    while (e) {
        if (e->key == key) {
            e->value = value;
            return;
        }
        e = e->next;
    }

    /* Otherwise allocate a new entry */
    e = (Entry *)malloc(sizeof(Entry));
    if (!e) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    e->key   = key;
    e->value = value;
    e->next  = hash_table[h];
    hash_table[h] = e;
}

/* Search for a key; returns -1 if not found */
static int map_find(int key)
{
    unsigned int h = hash_int(key);
    Entry *e = hash_table[h];
    while (e) {
        if (e->key == key) {
            return e->value;
        }
        e = e->next;
    }
    return -1; /* not found */
}

/* Clean up the hash table (free all allocated nodes) */
static void map_clear(void)
{
    for (unsigned int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Entry *e = hash_table[i];
        while (e) {
            Entry *next = e->next;
            free(e);
            e = next;
