    if (!dp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int maximum = 0;            /* at least one element can form a subsequence */
    for (int i = 0; i < n; ++i) {
        int prev_index = map_find(a[i] - 1); /* 1‑based index of a[i]–1 */
        if (prev_index != -1) {
            dp[i] = 1 + dp[prev_index - 1];   /* convert to 0‑based */
        } else {
            dp[i] = 1;
        }

        map_insert(a[i], i + 1);               /* store 1‑based index */
        if (dp[i] > maximum) {
            maximum = dp[i];
        }
    }

    free(dp);
    return maximum;
}

/* ---------- Main routine for demonstration ---------- */

