// ----------------- 解析相关 -----------------
static const char *s;     // 全局指针，指向输入字符串

// 跳过空格
static void skip_space(void) {
    while (isspace((unsigned char)*s)) s++;
}

// 返回当前字符，不移动指针
static char peek(void) {
    skip_space();
    return *s;
}

// 消费并返回当前字符
static char get(void) {
    skip_space();
    return *s++;
}

// 创建叶子节点（数字/变量等）
static Node* new_leaf(void) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->op = '\0';
    node->l = node->r = NULL;
    // 直接跳过数字/变量
    while (isalnum((unsigned char)*s)) s++;
    return node;
}

// 解析 Factor： '(' expr ')'  或  叶子
static Node* parseFactor(void);

// 解析 Term： factor { (*|/|%) factor }*
static Node* parseTerm(void) {
    Node *node = parseFactor();
    while (1) {
        char c = peek();
        if (c == '*' || c == '/' || c == '%') {
            get();                       // 消耗运算符
            Node *newnode = (Node*)malloc(sizeof(Node));
            newnode->op = c;
            newnode->l = node;
            newnode->r = parseFactor();
            node = newnode;
        } else break;
    }
    return node;
}

// 解析 Expr： term { (+|-) term }*
static Node* parseExpression(void) {
    Node *node = parseTerm();
    while (1) {
        char c = peek();
        if (c == '+' || c == '-') {
            get();                       // 消耗运算符
            Node *newnode = (Node*)malloc(sizeof(Node));
            newnode->op = c;
            newnode->l = node;
            newnode->r = parseTerm();
            node = newnode;
        } else break;
    }
    return node;
}

// 解析 Factor： '(' expr ')' | leaf
static Node* parseFactor(void) {
    char c = peek();
    if (c == '(') {
        get();                       // '('
        Node *node = parseExpression();
        if (*s != ')') {
            fprintf(stderr, "Error: missing ')'\n");
            exit(EXIT_FAILURE);
        }
        get();                       // ')'
        return node;
    } else {
        return new_leaf();
    }
}

// ----------------- 主程序 -----------------
