下面给出一份 **DWc SSI**（Synopsys 设计‑Ware Synchronous‑Serial‑Interface）在 **EEPROM 模式**下的示例代码。  
代码采用 C 语言（可直接嵌入到 MCU 的固件项目中），演示：

1.  SSI 复位、时钟、波特率等基本配置。  
2.  打开 **EEPROM 模式**（`SSI_CTRL_EEPROM_MODE`）。  
3.  读写 EEPROM 的函数（`SSI_EEPROM_Read`、`SSI_EEPROM_Write`）。  
4.  简易错误检查与状态查询。  

> ⚠️ 这份代码仅为演示模板，**寄存器地址、位字段** 需根据你使用的芯片手册自行替换。  
> 若你使用的是 Linux 内核的 `dwc_ssi` 驱动，思路类似，只需把上层调用改为 `ioremap`/`readl/writel` 即可。

---

## 1. 头文件与寄存器宏

```c
/*********************************************************************
 *  文件: dwc_ssi_eeprom.c
 *  描述: DWC SSI 驱动示例 – EEPROM 模式
 *********************************************************************/

#include <stdint.h>
#include <stdbool.h>

/* 你需要根据自己的硬件手册修改这些基地址和位字段 */
#define DWC_SSI_BASE          0x40000000UL          /* SSI 基址（示例） */

/* 寄存器偏移 */
#define SSI_CR0_OFFSET        0x00UL
#define SSI_CR1_OFFSET        0x04UL
#define SSI_DR_OFFSET         0x08UL
#define SSI_SR_OFFSET         0x0CUL
#define SSI_CPSR_OFFSET       0x10UL
#define SSI_IMR_OFFSET        0x14UL
#define SSI_ISR_OFFSET        0x18UL
#define SSI_TCR_OFFSET        0x1CUL
#define SSI_RCR_OFFSET        0x20UL
#define SSI_THR_OFFSET        0x24UL
#define SSI_RHR_OFFSET        0x28UL
#define SSI_SR2_OFFSET        0x2CUL
/* 以此类推，若硬件手册里有 EEPROM 模式专用寄存器，继续添加 */

/* 访问寄存器的宏（简化） */
#define REG32(addr)          (*(volatile uint32_t *)(addr))

/* 具体位字段（示例，需根据手册确认） */
#define SSI_CR1_SSE          (1U << 0)          /* SSI 使能 */
#define SSI_CR1_SSEEPROM_MODE (1U << 10)       /* EEPROM 模式开关（示例） */
#define SSI_SR_TIP           (1U << 0)          /* Transmit in Progress */
#define SSI_SR_RNE           (1U << 1)          /* Receive FIFO Not Empty */
#define SSI_SR_FEF           (1U << 4)          /* FIFO Error Flag */
```

> **提示**  
> - `SSI_CR1_SSEEPROM_MODE` 只是假设存在的位字段；实际芯片的 EEPROM 模式开启方式可能是 `SSI_CR0` 或者单独的控制寄存器。  
> - 需要先参考芯片手册确认寄存器布局与位定义。

---

## 2. SSI 基础初始化（开启 EEPROM 模式）

```c
/**
 * @brief  初始化 DWC SSI 为 EEPROM 模式
 *
 * @param  baud_rate: 目标波特率（如 100 kHz）
 * @return true 成功，false 失败（如时钟分频无法满足）
 */
bool SSI_Init_For_EEPROM(uint32_t baud_rate)
{
    volatile uint32_t *CR1   = (uint32_t *)(DWC_SSI_BASE + SSI_CR1_OFFSET);
    volatile uint32_t *CR0   = (uint32_t *)(DWC_SSI_BASE + SSI_CR0_OFFSET);
    volatile uint32_t *CPSR  = (uint32_t *)(DWC_SSI_BASE + SSI_CPSR_OFFSET);
    volatile uint32_t *IMR   = (uint32_t *)(DWC_SSI_BASE + SSI_IMR_OFFSET);

    /* 1. 先关闭 SSI */
    *CR1 &= ~SSI_CR1_SSE;

    /* 2. 计算并设置时钟分频（假设 SSI 时钟为系统时钟 / 2） */
    /* 这里使用简化公式：CPSR = SSI_CLOCK / (2 * baud_rate)  */
    /* 若不满足整数，需返回错误 */
    uint32_t system_clk = 48000000UL; /* 48MHz 系统时钟示例 */
    uint32_t cpsr_val   = system_clk / (2 * baud_rate);

    if (cpsr_val == 0 || cpsr_val > 0xFF) {
        return false;  /* 分频值非法 */
    }
    *CPSR = cpsr_val;

    /* 3. 配置 CR0（数据长度、时钟极性/相位等，视 EEPROM 需求而定） */
    /* 这里假设使用 8 位、CPOL=0、CPHA=0、MSB first */
    *CR0 = 0;
    *CR0 |= (7 << 0);          /* 8-bit data -> (data_len-1) = 7 */
    *CR0 |= (0 << 8);          /* CPOL = 0 */
    *CR0 |= (0 << 9);          /* CPHA = 0 */
    *CR0 |= (0 << 10);         /* MSB first (0) */

    /* 4. 启用 EEPROM 模式（假设位在 CR1） */
    *CR1 |= SSI_CR1_SSEEPROM_MODE;

    /* 5. 启用 SSI */
    *CR1 |= SSI_CR1_SSE;

    /* 6. 清除中断使能（根据需要可开启） */
    *IMR = 0;

    return true;
}
```

---

## 3. 低级读/写操作（FIFO 方式）

```c
/**
 * @brief  发送一个字节
 * @param  data: 要发送的字节
 */
static void SSI_Write_Byte(uint8_t data)
{
    volatile uint32_t *DR = (uint32_t *)(DWC_SSI_BASE + SSI_DR_OFFSET);
    /* 等待发送完成 */
    while (REG32(DWC_SSI_BASE + SSI_SR_OFFSET) & SSI_SR_TIP);
    *DR = data;
}

/**
 * @brief  读取一个字节
 * @return 接收到的字节
 */
static uint8_t SSI_Read_Byte(void)
{
    volatile uint32_t *DR = (uint32_t *)(DWC_SSI_BASE + SSI_DR_OFFSET);
    /* 等待接收完成 */
    while (!(REG32(DWC_SSI_BASE + SSI_SR_OFFSET) & SSI_SR_RNE));
    return (uint8_t)(*DR & 0xFF);
}
```

> **说明**  
> - 这里采用最简单的 FIFO/寄存器方式；实际硬件往往需要检查 FIFO 状态（`SSI_SR2`）或使用 DMA。  
> - 若 EEPROM 需要 **事务**（如页写/读取前的起始地址），请在 `SSI_EEPROM_Write/Read` 里插入对应协议。

---

## 4. EEPROM 读写接口（示例协议）

下面以常见 24C32/24C64 I²C‑EEPROM 的 SPI/SSI 兼容协议为例（真实协议请查手册）：

### 4.1 读取 EEPROM（随机读）

```c
/**
 * @brief  EEPROM 随机读取 1 字节
 * @param  addr: EEPROM 内部地址（0 ~ 0x7FFF）
 * @return 读取的数据
 */
uint8_t SSI_EEPROM_ReadByte(uint16_t addr)
{
    /* 发送读指令 0x03 + 地址高 8 位 + 地址低 8 位 */
    SSI_Write_Byte(0x03);               /* 读命令 */
    SSI_Write_Byte((uint8_t)(addr >> 8));/* 地址高 8 位 */
    SSI_Write_Byte((uint8_t)(addr & 0xFF));/* 地址低 8 位 */

    /* 发送 Dummy 时钟，让 EEPROM 回传数据 */
    return SSI_Read_Byte();             /* 读取返回的数据 */
}
```

### 4.2 写入 EEPROM（页写）

```c
/**
 * @brief  EEPROM 页写（一次写 ≤ 32 字节）
 * @param  addr: 写起始地址（0 ~ 0x7FFF）
 * @param  p_data: 指向待写数据的指针
 * @param  len: 数据长度（1 ~ 32）
 */
void SSI_EEPROM_WritePage(uint16_t addr, const uint8_t *p_data, uint8_t len)
{
    if (len == 0 || len > 32) return;  /* 页写长度检查 */

    SSI_Write_Byte(0x02);                 /* 写命令 */
    SSI_Write_Byte((uint8_t)(addr >> 8)); /* 地址高 8 位 */
    SSI_Write_Byte((uint8_t)(addr & 0xFF));/* 地址低 8 位 */

    /* 写入数据 */
    for (uint8_t i = 0; i < len; i++) {
        SSI_Write_Byte(p_data[i]);
    }

    /* 需要等待写周期完成（典型 5ms） */
    /* 这里使用延时函数或轮询 STATUS 位（若有） */
    /* 示例: delay_ms(5); */
}
```

### 4.3 读写封装函数

```c
/**
 * @brief  EEPROM 读写统一接口
 * @param  read: true 读取，false 写入
 * @param  addr: EEPROM 内部地址
 * @param  p_buf: 缓冲区（读时为输出，写时为输入）
 * @param  len: 读/写长度
 */
void SSI_EEPROM_ReadWrite(bool read, uint16_t addr, uint8_t *p_buf, uint8_t len)
{
    if (read) {
        for (uint8_t i = 0; i < len; i++) {
            p_buf[i] = SSI_EEPROM_ReadByte(addr + i);
        }
    } else {
        SSI_EEPROM_WritePage(addr, p_buf, len);
    }
}
```

---

## 5. 示例使用

```c
int main(void)
{
    /* 先初始化 SSI 为 EEPROM 模式（例如 100kHz） */
    if (!SSI_Init_For_EEPROM(100000)) {
        /* 初始化失败，处理错误 */
        while (1);
    }

    /* 写入 16 字节 */
    uint8_t wbuf[16] = {
        0xDE, 0xAD, 0xBE, 0xEF,
        0x01, 0x02, 0x03, 0x04,
        0x05, 0x06, 0x07, 0x08,
        0x09, 0x0A, 0x0B, 0x0C
    };
    SSI_EEPROM_ReadWrite(false, 0x0000, wbuf, 16);

    /* 读取 16 字节 */
    uint8_t rbuf[16] = {0};
    SSI_EEPROM_ReadWrite(true, 0x0000, rbuf, 16);

    /* 现在 rbuf 与 wbuf 应该相等 */
    while (1);
}
```

---

## 6. 注意事项

| # | 说明 |
|---|------|
| 1 | **时钟源**：SSI 的时钟频率决定能否满足 EEPROM 的要求。若时钟不可调，需考虑使用外部 PLL 或分频器。 |
| 2 | **EEPROM 协议**：不同 EEPROM（24C, 93C, AT24C 等）有不同的命令与页大小，请以手册为准。 |
| 3 | **错误检查**：实际项目中建议检查 `SSI_SR` 里 `FEF`、`BERR` 等位，必要时重试。 |
| 4 | **DMA**：如果需要大容量读写，可考虑用 SSI 的 DMA 通道。 |
| 5 | **中断**：示例中没有使用中断，若使用中断请在 ISR 中处理 `SSI_ISR` 与 `SSI_IMR`。 |

---

### 结语

以上代码是一个 **完整但简化的** 示例，展示了如何在 DWC SSI 里开启 EEPROM 模式并完成基本的读写。  
根据你具体的 MCU/SoC，可能需要：

- 调整寄存器基地址与偏移。  
- 更改时钟分频公式。  
- 对应 EEPROM 的命令序列（有的 EEPROM 需要先拉低 CS 线、发送 `WRITE_ENABLE` 等）。  
- 处理错误与超时。

