#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <ctype.h>
#ifdef _WIN32
    #include <windows.h>
#else
    #include <unistd.h>
    #include <sys/time.h>
#endif

/* --------------- 工具函数 ---------------- */

/* 判断闰年 */
int is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

/* 返回指定月份的天数 */
int days_in_month(int year, int month) {
    static const int days[12] = { 31,28,31,30,31,30,31,31,30,31,30,31 };
    if (month == 2 && is_leap_year(year)) return 29;
    return days[month - 1];
}

/* 让 tm 结构保持合法（处理溢出） */
void normalize_tm(struct tm *tm) {
    /* 年份：tm_year 是从 1900 开始的 */
    if (tm->tm_mon < 0) { tm->tm_year -= 1; tm->tm_mon += 12; }
    if (tm->tm_mon > 11) { tm->tm_year += 1; tm->tm_mon -= 12; }

    /* 日期 */
    int dim = days_in_month(tm->tm_year + 1900, tm->tm_mon + 1);
    if (tm->tm_mday < 1) {
        tm->tm_mon -= 1;
        if (tm->tm_mon < 0) { tm->tm_year -= 1; tm->tm_mon = 11; }
        tm->tm_mday = days_in_month(tm->tm_year + 1900, tm->tm_mon + 1);
    }
    while (tm->tm_mday > dim) {
        tm->tm_mday -= dim;
        tm->tm_mon += 1;
        if (tm->tm_mon > 11) { tm->tm_year += 1; tm->tm_mon = 0; }
        dim = days_in_month(tm->tm_year + 1900, tm->tm_mon + 1);
    }
}

/* 打印一行星期标题 */
void print_week_header() {
    puts("Sun Mon Tue Wed Thu Fri Sat");
}

/* 打印指定年月的日历 */
void print_month_calendar(int year, int month) {
    struct tm tm_start = {0};
    tm_start.tm_year = year - 1900;
    tm_start.tm_mon  = month - 1;
    tm_start.tm_mday = 1;
    mktime(&tm_start); /* 计算星期 */
    int first_weekday = tm_start.tm_wday; /* 0=Sunday ... 6=Saturday */

    printf("\n   %04d-%02d\n", year, month);
    print_week_header();

    int i;
    /* 前置空格 */
    for (i = 0; i < first_weekday; ++i) printf("    ");
    int dim = days_in_month(year, month);
    for (i = 1; i <= dim; ++i) {
        printf("%3d ", i);
        if ((first_weekday + i) % 7 == 0) printf("\n");
    }
    if ((first_weekday + dim) % 7 != 0) printf("\n");
}

/* 把 tm 写回系统时间 */
int set_system_time(const struct tm *tm) {
#ifdef _WIN32
    SYSTEMTIME st;
    st.wYear      = tm->tm_year + 1900;
    st.wMonth     = tm->tm_mon + 1;
    st.wDayOfWeek = tm->tm_wday;  /* 0=Sunday ... 6=Saturday */
    st.wDay       = tm->tm_mday;
    st.wHour      = tm->tm_hour;
    st.wMinute    = tm->tm_min;
    st.wSecond    = tm->tm_sec;
    st.wMilliseconds = 0;
    return SetSystemTime(&st);
#else
    struct timeval tv;
    struct timezone tz = {0,0};
    time_t epoch = mktime((struct tm *)tm); /* tm 必须是当地时区 */
    tv.tv_sec  = epoch;
    tv.tv_usec = 0;
    return settimeofday(&tv, &tz);
#endif
}

/* 读取一个整数（允许前后空格） */
int read_int() {
    char buf[32];
    if (!fgets(buf, sizeof buf, stdin)) return 0;
    return atoi(buf);
}

