## 2. 简单的内存池（Memory Pool）实现

内存池的核心是：先把一块大内存拆成若干块固定大小的 **块**（block），  
把空闲块连成链表，分配时只从链表头取，释放时再放回链表。  
优点：  
- **分配/释放 O(1)**，无需堆碎片；  
- **可预测**，适合实时系统；  
- **内存利用率高**。

```c
/* mem_pool.h */
#ifndef MEM_POOL_H
#define MEM_POOL_H

#include <stdint.h>
#include <stddef.h>

typedef struct MemPool {
    void    *pool_start;   /* 原始内存指针 */
    size_t   block_size;   /* 每个块的大小（含管理字段） */
    size_t   num_blocks;   /* 块的数量 */
    void    *free_list;    /* 空闲链表头指针 */
} MemPool;

/* 初始化内存池，返回 0 成功，非0 失败 */
int mem_pool_init(MemPool *mp, void *buffer, size_t buffer_size,
                  size_t block_size);

/* 从池里分配一块内存 */
void *mem_pool_alloc(MemPool *mp);

/* 归还一块内存 */
int mem_pool_free(MemPool *mp, void *ptr);

#endif /* MEM_POOL_H */
```

```c
/* mem_pool.c */
#include "mem_pool.h"

/* 这里的“块”内部只存下一块的指针，链表实现很简单 */
int mem_pool_init(MemPool *mp, void *buffer, size_t buffer_size,
                  size_t block_size)
{
    if (mp == NULL || buffer == NULL || block_size < sizeof(void *))
        return -1;

    mp->block_size = block_size;
    mp->num_blocks = buffer_size / block_size;
    if (mp->num_blocks == 0)
        return -1;

    mp->pool_start = buffer;
    mp->free_list = buffer;

    /* 链接空闲块 */
    uint8_t *p = (uint8_t *)buffer;
    for (size_t i = 0; i < mp->num_blocks - 1; ++i) {
        *(void **)p = p + block_size;    /* 指向下一块 */
        p += block_size;
    }
    *(void **)p = NULL;  /* 最后一块为空 */

    return 0;
}

void *mem_pool_alloc(MemPool *mp)
{
    if (mp->free_list == NULL)   /* 没空闲块 */
        return NULL;

    /* 取链表头 */
    void *block = mp->free_list;
    mp->free_list = *(void **)block;   /* 更新头指针 */
    return block;
}

int mem_pool_free(MemPool *mp, void *ptr)
{
    if (ptr == NULL)
        return -1;

    /* 放回链表头 */
    *(void **)ptr = mp->free_list;
    mp->free_list = ptr;
    return 0;
}
```

### 使用示例

```c
/* main.c */
#include <stdio.h>
#include "mem_pool.h"

#define POOL_SIZE   (1024 * 4)   /* 4KB */
#define BLOCK_SZ    (128)        /* 每块128B */

static uint8_t pool_buf[POOL_SIZE];

int main(void)
{
    MemPool mp;
    if (mem_pool_init(&mp, pool_buf, POOL_SIZE, BLOCK_SZ) != 0) {
        printf("pool init failed\n");
        return -1;
    }

    void *p1 = mem_pool_alloc(&mp);
    void *p2 = mem_pool_alloc(&mp);
    printf("alloc p1=%p p2=%p\n", p1, p2);

    mem_pool_free(&mp, p1);
    void *p3 = mem_pool_alloc(&mp);
    printf("alloc p3=%p (should equal p1)\n", p3);

    return 0;
}
