## 3. 简单的堆实现（Bmalloc / malloc）

如果系统需要支持 **可变大小** 的动态内存，可用一个极简的堆实现。  
下面的示例仅演示思想，实际嵌入式 RTOS（如 FreeRTOS、uC/OS‑III）会有更完整的实现。

```c
/* simple_heap.h */
#ifndef SIMPLE_HEAP_H
#define SIMPLE_HEAP_H

#include <stddef.h>

int heap_init(void *buffer, size_t buffer_size);
void *bmalloc(size_t size);
int  bfree(void *ptr);

#endif /* SIMPLE_HEAP_H */
```

```c
/* simple_heap.c */
#include "simple_heap.h"
#include <string.h>

#define ALIGN4(x)  (((x)+3)&~3)

typedef struct BlockHeader {
    size_t size;          /* 包括头部本身的大小，已对齐 */
    int    free;          /* 1: 空闲 0: 已分配 */
    struct BlockHeader *next;
} BlockHeader;

static void *heap_start = NULL;
static size_t heap_size  = 0;
static BlockHeader *free_list = NULL;

int heap_init(void *buffer, size_t buffer_size)
{
    if (buffer == NULL || buffer_size < sizeof(BlockHeader))
        return -1;

    heap_start = buffer;
    heap_size  = buffer_size;

    /* 只初始化一块空闲块 */
    BlockHeader *hdr = (BlockHeader *)buffer;
    hdr->size = buffer_size;
    hdr->free = 1;
    hdr->next = NULL;

    free_list = hdr;
    return 0;
}

static BlockHeader* find_free_block(size_t size)
{
    BlockHeader *prev = NULL, *cur = free_list;
    while (cur && !(cur->free && cur->size >= size)) {
        prev = cur;
        cur = cur->next;
    }
    return cur;
}

void *bmalloc(size_t size)
{
    if (size == 0)
        return NULL;

    size = ALIGN4(size);
    size_t total = size + sizeof(BlockHeader);

    BlockHeader *blk = find_free_block(total);
    if (!blk)
        return NULL; /* out of memory */

    /* 如果块足够大，可以拆分 */
    if (blk->size >= total + sizeof(BlockHeader) + 8) {
        BlockHeader *newblk = (BlockHeader *)
            ((uint8_t *)blk + total);
        newblk->size  = blk->size - total;
        newblk->free  = 1;
        newblk->next  = blk->next;

        blk->size = total;
        blk->next = newblk;
    }

    blk->free = 0;
    return (uint8_t *)blk + sizeof(BlockHeader);
}

int bfree(void *ptr)
{
    if (!ptr)
        return -1;

    BlockHeader *blk = (BlockHeader *)((uint8_t *)ptr - sizeof(BlockHeader));
    if (blk->free)
        return -1; /* double free */

    blk->free = 1;

    /* 合并相邻空闲块 */
    BlockHeader *cur = free_list;
    while (cur) {
        if (cur->next && cur->next->free &&
            (uint8_t *)cur + cur->size == (uint8_t *)cur->next) {
            cur->size += cur->next->size;
            cur->next = cur->next->next;
        } else {
            cur = cur->next;
        }
    }

    return 0;
}
```

