/* 假设页表占用一块连续内存（1 页） */
#define PT_BASE   ((PageTableEntry *)0x1000)
#define PT_NUM_ENTRIES 1024
#define PAGE_SHIFT 12
#define PAGE_SIZE  (1<<PAGE_SHIFT)

/* 简单的物理页帧分配器 */
static uint32_t next_free_frame = 1; /* 0保留为NULL页 */

static inline uint32_t alloc_frame(void)
{
