}

void init_page_table(void)
{
    for (int i = 0; i < PT_NUM_ENTRIES; ++i)
        PT_BASE[i].present = 0;
}

void map_page(uint32_t va, uint32_t pa, uint32_t flags)
{
    uint32_t idx = (va >> PAGE_SHIFT) & 0x3FF;
    PageTableEntry *pte = &PT_BASE[idx];
    pte->present = 1;
    pte->rw      = flags & 0x1;
    pte->user    = flags & 0x2;
    pte->frame   = pa >> PAGE_SHIFT;
}

void unmap_page(uint32_t va)
{
    uint32_t idx = (va >> PAGE_SHIFT) & 0x3FF;
    PT_BASE[idx].present = 0;
}

void enable_mmu(void)
{
