```c
/* udp_client.c
 * UDP client: sends a name (hard‑coded or from stdin),
 * receives uppercase reply and prints it.
 * Server IP and port are hard‑coded; change as needed.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define SERVER_IP   "192.168.1.10"   /* <-- Zmień na adres płytki */
#define SERVER_PORT 5000
#define BUF_SIZE    1024

int main(int argc, char *argv[]) {
    int sockfd;
    struct sockaddr_in servaddr;
    char sendbuf[BUF_SIZE];
    char recvbuf[BUF_SIZE];
    ssize_t n;
    socklen_t addrlen = sizeof(servaddr);

    /* 1. Create socket */
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* 2. Configure server address */
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family      = AF_INET;
    servaddr.sin_port        = htons(SERVER_PORT);
    if (inet_aton(SERVER_IP, &servaddr.sin_addr) == 0) {
        fprintf(stderr, "Niepoprawny adres IP serwera: %s\n", SERVER_IP);
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* 3. Tekst do wysłania – możesz wprowadzić ręcznie lub z argumentu */
    if (argc >= 2) {
        strncpy(sendbuf, argv[1], BUF_SIZE - 1);
        sendbuf[BUF_SIZE - 1] = '\0';
    } else {
        /* Domyślny tekst – imię i nazwisko */
        strncpy(sendbuf, "Jan Kowalski", BUF_SIZE - 1);
        sendbuf[BUF_SIZE - 1] = '\0';
    }

    printf("Wysyłam do %s:%d: \"%s\"\n",
           SERVER_IP, SERVER_PORT, sendbuf);

    /* 4. Wysyłanie */
    if (sendto(sockfd, sendbuf, strlen(sendbuf), 0,
               (struct sockaddr *)&servaddr, addrlen) < 0) {
        perror("sendto");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* 5. Odbiór odpowiedzi */
    n = recvfrom(sockfd, recvbuf, BUF_SIZE - 1, 0,
                 (struct sockaddr *)&servaddr, &addrlen);
    if (n < 0) {
        perror("recvfrom");
    } else {
        recvbuf[n] = '\0';
        printf("Otrzymano: \"%s\"\n", recvbuf);
    }

    close(sockfd);
    return 0;
}
```

### Kompilacja

