#include <iostream>
#include <vector>
using namespace std;

/* --------- Структура узла --------- */
struct Node {
    int key;            // значение узла
    Node* left;         // левый сын
    Node* right;        // правый сын

    Node(int k) : key(k), left(nullptr), right(nullptr) {}
};

/* --------- Готовая функция добавления узла --------- */
/*  Функция принимает ссылку на указатель «корня» и значение,
    которое нужно вставить. Внутри она создаёт новый узел и
    размещает его в правильном месте (пустое место в левом
    поддереве → вставка влево; иначе → вставка вправо). */
void AddNode(Node*& root, int val) {
    if (!root) {                    // если дерево пустое – создаём корень
        root = new Node(val);
        return;
    }

    Node* cur = root;
    while (true) {
        if (val < cur->key) {       // идём влево
            if (!cur->left) {
                cur->left = new Node(val);
                break;
            }
            cur = cur->left;
        } else {                    // идём вправо (равные значения считаем “правее”)
            if (!cur->right) {
                cur->right = new Node(val);
                break;
            }
            cur = cur->right;
        }
    }
}

/* --------- Функция заполнения дерева произвольным количеством элементов --------- */
/*  Вариант 1 – передаём в неё вектор/массив значений: */
void fullTree(Node*& root, const vector<int>& values) {
    for (int v : values) {
        AddNode(root, v);
    }
}

/*  Вариант 2 – интерактивное заполнение (на ввод пользователя) – можно использовать вместо
    предыдущего, если вы хотите «собрать» дерево из консоли. */
void fullTreeInteractive(Node*& root) {
    cout << "Введите числа (0 для завершения): ";
    int val;
    while (cin >> val && val != 0) {   // 0 — сигнал завершить ввод
        AddNode(root, val);
    }
}

/* --------- Для проверки – обход дерева (инфиксный) --------- */
void inorder(Node* node) {
    if (!node) return;
    inorder(node->left);
    cout << node->key << ' ';
    inorder(node->right);
}

/* --------- Демонстрация работы --------- */
int main() {
    Node* root = nullptr;            // сначала дерево пустое

    /* 1) Заполняем из вектора (пример) */
    vector<int> data{7, 3, 9, 1, 5, 8, 10};
    fullTree(root, data);

    cout << "Inorder (установленное дерево): ";
    inorder(root);
    cout << '\n';

    /* 2) Добавляем ещё элементы интерактивно */
    cout << "Теперь добавим ещё элементы через консоль: \n";
    fullTreeInteractive(root);

    cout << "Inorder после добавления: ";
    inorder(root);
    cout << '\n';

    /* Очистка памяти (необязательно, но хорошая практика) */
    // Можно написать рекурсивную функцию deleteTree()
    return 0;
}
```

### Как использовать

1. **`AddNode`** – готовая функция, которую вы уже имеете. Она добавляет один узел в дерево.  
2. **`fullTree(Node*& root, const vector<int>& values)`** – заполняет дерево из списка значений.  
