## 1.  Krótki opis

- **Gniazda domeny Unix** (ang. *Unix Domain Sockets*, `AF_UNIX`) pozwalają na komunikację
  pomiędzy procesami na tym samym hoście.
- Zamiast tworzyć gniazdo przy pomocy `socketpair()` (które automatycznie daje dwie strony),
  tworzymy je ręcznie przy pomocy `socket()`, `bind()`, `listen()`, `accept()`.
- Serwer:
  1. Tworzy gniazdo `AF_UNIX`, `SOCK_STREAM`.
  2. Binds do ścieżki `/tmp/uds_socket` (można zmienić).
  3. Otwiera kolejkę przychodzących połączeń (`listen`).
  4. Czeka na przychodzące połączenie (`accept`).
  5. Odczytuje tekst od klienta, konwertuje go na wielkie litery,
     odsyła z powrotem i zamyka połączenie.
  6. Po zakończeniu programu usuwa plik socketu (`unlink`).

- Klient:
  1. Tworzy gniazdo `AF_UNIX`, `SOCK_STREAM`.
  2. Łączy się z serwerem (`connect`).
  3. Wysyła wprowadzone dane (imię i nazwisko).
  4. Odczytuje odpowiedź (tekst w wielkich literach) i wypisuje.
  5. Zamyka połączenie.

Poniżej pełne, kompilowalne programy w C.

---

## 2.  Server (`uds_server.c`)

```c
/* uds_server.c
 * -------------
 *  Serwer komunikujący się przez gniazdo domeny Unix.
 *  Odbiera tekst, konwertuje do wielkich liter i zwraca klientowi.
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <ctype.h>
#include <string.h>
#include <errno.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <sys/stat.h>

#define SOCKET_PATH "/tmp/uds_socket"
#define BUF_SIZE 1024

/* Ustawienie wszystkich znaków na wielkie litery */
static void to_upper(char *buf, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        buf[i] = toupper((unsigned char)buf[i]);
}

int main(void)
{
    int server_fd, client_fd;
    struct sockaddr_un addr;
    char buf[BUF_SIZE];
    ssize_t n;

    /* 1. Utworzenie gniazda */
    server_fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* 2. Przygotowanie struktury adresu */
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    /* 3. Usunięcie ewentualnego starego pliku socketu */
    unlink(SOCKET_PATH);

    /* 4. Bindowanie */
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1) {
        perror("bind");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    /* 5. Otwarcie kolejki przychodzących połączeń */
    if (listen(server_fd, 5) == -1) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Serwer nasłuchuje na %s\n", SOCKET_PATH);

    /* 6. Akceptacja połączenia (blokuje, dopóki klient się nie połączy) */
    client_fd = accept(server_fd, NULL, NULL);
    if (client_fd == -1) {
        perror("accept");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Połączono z klientem.\n");

    /* 7. Odbiór danych */
    n = read(client_fd, buf, BUF_SIZE - 1);
    if (n == -1) {
        perror("read");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    buf[n] = '\0';                      /* null-terminate */
    printf("Odebrano: \"%s\"\n", buf);

    /* 8. Konwersja do wielkich liter */
    to_upper(buf, n);

    /* 9. Wysłanie odpowiedzi */
    if (write(client_fd, buf, n) != n) {
        perror("write");
    }

    /* 10. Zakończenie połączenia */
    close(client_fd);
    close(server_fd);
    unlink(SOCKET_PATH);  /* usuwamy plik socketu */

    printf("Serwer zakończył pracę.\n");
    return 0;
}
```

### Kompilacja

```bash
gcc -Wall -Wextra -o uds_server uds_server.c
```

---

## 3.  Client (`uds_client.c`)

```c
/* uds_client.c
 * -------------
 *  Klient łączący się z serwerem gniazda domeny Unix,
 *  wysyła tekst (imię i nazwisko), odbiera zwrotną odpowiedź.
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/un.h>

#define SOCKET_PATH "/tmp/uds_socket"
#define BUF_SIZE 1024

int main(void)
{
    int sock_fd;
    struct sockaddr_un addr;
    char buf[BUF_SIZE];
    ssize_t n;

    /* 1. Utworzenie gniazda */
    sock_fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (sock_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* 2. Przygotowanie struktury adresu */
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    /* 3. Połączenie z serwerem */
    if (connect(sock_fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1) {
        perror("connect");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    /* 4. Wczytanie danych od użytkownika */
    printf("Wprowadź imię i nazwisko: ");
    if (!fgets(buf, BUF_SIZE, stdin)) {
        fprintf(stderr, "Błąd odczytu.\n");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }
    size_t len = strlen(buf);
    if (buf[len - 1] == '\n')
        buf[--len] = '\0';  /* usunięcie znaku nowej linii */

    /* 5. Wysłanie danych */
    if (write(sock_fd, buf, len) != len) {
        perror("write");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    /* 6. Odbiór odpowiedzi */
    n = read(sock_fd, buf, BUF_SIZE - 1);
    if (n == -1) {
        perror("read");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }
    buf[n] = '\0';
    printf("Odpowiedź serwera: \"%s\"\n", buf);

    /* 7. Zakończenie połączenia */
    close(sock_fd);
    return 0;
}
```

### Kompilacja

