```c
/********************************************************************
 *  Diary Management System (C)
 *  Author : 2026
 ********************************************************************/
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* ---------- 预定义常量 ---------- */
#define MAX_DATE_LEN    11      // YYYY-MM-DD + '\0'
#define MAX_KEY_LEN     50
#define MAX_CONTENT_LEN 1024
#define MAX_LINE_LEN    2048
#define DIARY_FILE      "diary.txt"
#define DEFAULT_PASSWORD "admin"

/* ---------- 数据结构 ---------- */
typedef struct {
    char date[MAX_DATE_LEN];
    char keyword[MAX_KEY_LEN];
    char content[MAX_CONTENT_LEN];
} Entry;

/* ---------- 函数原型 ---------- */
int loadDiary(const char *filename, char *password,
              Entry **entries, size_t *count);
int saveDiary(const char *filename, const char *password,
              Entry *entries, size_t count);
int compareByDate(const void *a, const void *b);
void listEntries(Entry *entries, size_t count);
void addEntry(Entry **entries, size_t *count);
void editEntry(Entry *entries, size_t count);
void deleteEntry(Entry **entries, size_t *count);
void searchByKeyword(Entry *entries, size_t count);
void searchByDate(Entry *entries, size_t count);
int changePassword(const char *filename, const char *oldPwd);
void promptEnterKey(void);
void trimNewline(char *str);

/* ---------- 主程序 ---------- */
int main(void) {
    char password[64] = {0};
    Entry *entries = NULL;
    size_t count = 0;

    /* 1. 读取文件（若不存在则创建） */
    if (access(DIARY_FILE, F_OK) != 0) {
        /* 文件不存在，先写默认密码 */
        FILE *fp = fopen(DIARY_FILE, "w");
        if (!fp) { perror("fopen"); return EXIT_FAILURE; }
        fprintf(fp, "%s\n", DEFAULT_PASSWORD);
        fclose(fp);
    }

    if (loadDiary(DIARY_FILE, password, &entries, &count) != 0) {
        fprintf(stderr, "读取日记文件失败。\n");
        return EXIT_FAILURE;
    }

    /* 2. 进入密码验证循环 */
    for (int try = 0; try < 3; ++try) {
        char input[64];
        printf("请输入密码: ");
        if (!fgets(input, sizeof(input), stdin)) exit(EXIT_FAILURE);
        trimNewline(input);
        if (strcmp(input, password) == 0) {
            break;  // 正确密码
        } else if (try == 2) {
            printf("密码错误，程序退出。\n");
            free(entries);
            return EXIT_FAILURE;
        } else {
            printf("密码错误，请重试。\n");
        }
    }

    /* 3. 主菜单循环 */
    for (;;) {
        printf("\n=== Diary Menu ===\n");
        printf("1. 添加日记\n");
        printf("2. 修改日记\n");
        printf("3. 删除日记\n");
        printf("4. 浏览全部\n");
        printf("5. 按关键字搜索\n");
        printf("6. 按日期搜索\n");
        printf("7. 修改密码\n");
        printf("0. 退出\n");
        printf("请选择: ");

        int choice;
        if (scanf("%d", &choice) != 1) {
            while (getchar() != '\n'); // 清空错误输入
            continue;
        }
        while (getchar() != '\n'); // 清除换行符

        switch (choice) {
            case 1: addEntry(&entries, &count);   break;
            case 2: editEntry(entries, count);    break;
            case 3: deleteEntry(&entries, &count);break;
            case 4: listEntries(entries, count);  break;
            case 5: searchByKeyword(entries, count); break;
            case 6: searchByDate(entries, count);   break;
            case 7: changePassword(DIARY_FILE, password); break;
            case 0:
                if (saveDiary(DIARY_FILE, password, entries, count) != 0)
                    printf("保存失败！\n");
                free(entries);
                printf("再见！\n");
                return EXIT_SUCCESS;
            default:
                printf("无效选项，请重新选择。\n");
        }
    }
    return EXIT_SUCCESS;
}

/* ---------- 代码实现 ---------- */

/* 去掉字符串末尾的 '\n' 或 '\r\n' */
void trimNewline(char *str) {
    char *p = strchr(str, '\n');
    if (p) *p = '\0';
    p = strchr(str, '\r');
    if (p) *p = '\0';
}

/* 等待用户按回车 */
void promptEnterKey(void) {
    printf("\n(按回车继续...)");
    while (getchar() != '\n');
}

/* ---------- 加载日记 ---------- */
int loadDiary(const char *filename, char *password,
              Entry **entries, size_t *count) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return -1;

    /* 读取密码 */
    if (!fgets(password, 64, fp)) {
        fclose(fp);
        return -1;
    }
    trimNewline(password);

    /* 读取条目 */
    char line[MAX_LINE_LEN];
    size_t cap = 10, len = 0;
    *entries = malloc(cap * sizeof(Entry));
    if (!*entries) { fclose(fp); return -1; }

    while (fgets(line, sizeof(line), fp)) {
        trimNewline(line);
        if (strlen(line) == 0) continue; /* 跳过空行 */

        /* 解析 line: date|keyword|content */
        char *p1 = strchr(line, '|');
        if (!p1) continue;
        *p1 = '\0';
        char *date = line;

        char *p2 = strchr(p1 + 1, '|');
        if (!p2) continue;
        *p2 = '\0';
        char *keyword = p1 + 1;
        char *content = p2 + 1;

        if (len == cap) {
            cap *= 2;
            *entries = realloc(*entries, cap * sizeof(Entry));
            if (!*entries) { fclose(fp); return -1; }
        }
        strncpy((*entries)[len].date, date, MAX_DATE_LEN-1);
        (*entries)[len].date[MAX_DATE_LEN-1] = '\0';
        strncpy((*entries)[len].keyword, keyword, MAX_KEY_LEN-1);
        (*entries)[len].keyword[MAX_KEY_LEN-1] = '\0';
        strncpy((*entries)[len].content, content, MAX_CONTENT_LEN-1);
        (*entries)[len].content[MAX_CONTENT_LEN-1] = '\0';
        ++len;
    }
    fclose(fp);

    /* 按日期排序 */
    qsort(*entries, len, sizeof(Entry), compareByDate);
    *count = len;
    return 0;
}

/* ---------- 保存日记 ---------- */
int saveDiary(const char *filename, const char *password,
              Entry *entries, size_t count) {
    FILE *fp = fopen(filename, "w");
    if (!fp) return -1;

    /* 写密码 */
    fprintf(fp, "%s\n", password);

    /* 写条目 */
    for (size_t i = 0; i < count; ++i) {
        fprintf(fp, "%s|%s|%s\n",
                entries[i].date,
                entries[i].keyword,
                entries[i].content);
    }
    fclose(fp);
    return 0;
}

/* ---------- 日期比较（升序） ---------- */
int compareByDate(const void *a, const void *b) {
    const Entry *ea = (const Entry *)a;
    const Entry *eb = (const Entry *)b;
    return strcmp(ea->date, eb->date);
}

/* ---------- 浏览全部条目 ---------- */
void listEntries(Entry *entries, size_t count) {
    if (count == 0) { printf("没有日记条目。\n"); return; }
    for (size_t i = 0; i < count; ++i) {
        printf("\n[%zu] 日期: %s\n关键字: %s\n内容: %s\n",
               i + 1, entries[i].date, entries[i].keyword, entries[i].content);
    }
}

/* ---------- 添加条目 ---------- */
void addEntry(Entry **entries, size_t *count) {
    Entry new;
    printf("请输入日期 (YYYY-MM-DD): ");
    fgets(new.date, sizeof(new.date), stdin);
    trimNewline(new.date);

    printf("请输入关键字: ");
    fgets(new.keyword, sizeof(new.keyword), stdin);
    trimNewline(new.keyword);

    printf("请输入内容 (以回车结束，最多 %d 字):\n", MAX_CONTENT_LEN-1);
    fgets(new.content, sizeof(new.content), stdin);
    trimNewline(new.content);

    /* 动态扩容 */
    *entries = realloc(*entries, (*count + 1) * sizeof(Entry));
    (*entries)[*count] = new;
    ++(*count);

    /* 重新排序 */
    qsort(*entries, *count, sizeof(Entry), compareByDate);
    printf("日记已添加。\n");
}

/* ---------- 修改条目 ---------- */
void editEntry(Entry *entries, size_t count) {
    if (count == 0) { printf("没有可修改的条目。\n"); return; }
    listEntries(entries, count);
    printf("请输入要修改的条目编号: ");
    size_t idx;
    if (scanf("%zu", &idx) != 1 || idx < 1 || idx > count) {
        printf("编号无效。\n");
        while (getchar() != '\n'); /* 清理输入流 */
        return;
    }
    while (getchar() != '\n'); /* 清理换行 */

    Entry *e = &entries[idx - 1];

    printf("当前日期: %s\n", e->date);
    printf("新日期 (留空保持不变): ");
    char buf[MAX_DATE_LEN];
    fgets(buf, sizeof(buf), stdin);
    trimNewline(buf);
    if (strlen(buf)) strcpy(e->date, buf);

    printf("当前关键字: %s\n", e->keyword);
    printf("新关键字 (留空保持不变): ");
    fgets(buf, sizeof(buf), stdin);
    trimNewline(buf);
    if (strlen(buf)) strncpy(e->keyword, buf, MAX_KEY_LEN-1);

    printf("当前内容: %s\n", e->content);
    printf("新内容 (留空保持不变): ");
    fgets(buf, sizeof(buf), stdin);
    trimNewline(buf);
    if (strlen(buf)) strncpy(e->content, buf, MAX_CONTENT_LEN-1);

    /* 重新排序 */
    qsort(entries, count, sizeof(Entry), compareByDate);
    printf("日记已修改。\n");
}

/* ---------- 删除条目 ---------- */
void deleteEntry(Entry **entries, size_t *count) {
    if (*count == 0) { printf("没有可删除的条目。\n"); return; }
    listEntries(*entries, *count);
    printf("请输入要删除的条目编号: ");
    size_t idx;
    if (scanf("%zu", &idx) != 1 || idx < 1 || idx > *count) {
        printf("编号无效。\n");
        while (getchar() != '\n');
        return;
    }
    while (getchar() != '\n');

    /* 移除 */
    for (size_t i = idx; i < *count; ++i) {
        (*entries)[i - 1] = (*entries)[i];
    }
    --(*count);
    *entries = realloc(*entries, (*count + 1) * sizeof(Entry));
    printf("日记已删除。\n");
}

/* ---------- 按关键字搜索 ---------- */
void searchByKeyword(Entry *entries, size_t count) {
    char kw[MAX_KEY_LEN];
    printf("请输入关键字: ");
    fgets(kw, sizeof(kw), stdin);
    trimNewline(kw);
    int found = 0;
    for (size_t i = 0; i < count; ++i) {
        if (strstr(entries[i].keyword, kw)) {
            printf("\n[%zu] 日期: %s\n关键字: %s\n内容: %s\n",
                   i + 1, entries[i].date, entries[i].keyword, entries[i].content);
            found = 1;
        }
    }
    if (!found) printf("未找到匹配的条目。\n");
}

/* ---------- 按日期搜索 ---------- */
void searchByDate(Entry *entries, size_t count) {
    printf("输入查询日期 (YYYY-MM-DD) 或区间开始-结束 (YYYY-MM-DD-YYYY-MM-DD): ");
    char line[MAX_LINE_LEN];
    fgets(line, sizeof(line), stdin);
    trimNewline(line);

    /* 解析 */
    char *dash = strchr(line, '-');
    if (!dash) { /* 只给一个日期 */
        for (size_t i = 0; i < count; ++i) {
            if (strcmp(entries[i].date, line) == 0) {
                printf("\n[%zu] 日期: %s\n关键字: %s\n内容: %s\n",
                       i + 1, entries[i].date, entries[i].keyword, entries[i].content);
                return;
            }
        }
        printf("未找到匹配的条目。\n");
    } else {
        /* 区间查询 */
        char start[MAX_DATE_LEN], end[MAX_DATE_LEN];
        *dash = '\0';
        strcpy(start, line);
        strcpy(end, dash + 1);
        for (size_t i = 0; i < count; ++i) {
            if (strcmp(entries[i].date, start) >= 0 &&
                strcmp(entries[i].date, end) <= 0) {
                printf("\n[%zu] 日期: %s\n关键字: %s\n内容: %s\n",
                       i + 1, entries[i].date, entries[i].keyword, entries[i].content);
            }
        }
    }
}

/* ---------- 修改密码 ---------- */
int changePassword(const char *filename, const char *oldPwd) {
    printf("请输入旧密码: ");
    char old[64];
    fgets(old, sizeof(old), stdin);
    trimNewline(old);
    if (strcmp(old, oldPwd) != 0) {
        printf("旧密码错误。\n");
        return -1;
    }

    printf("请输入新密码: ");
    char newPwd[64];
    fgets(newPwd, sizeof(newPwd), stdin);
    trimNewline(newPwd);
    printf("请再次输入新密码: ");
    char newPwd2[64];
    fgets(newPwd2, sizeof(newPwd2), stdin);
    trimNewline(newPwd2);

    if (strcmp(newPwd, newPwd2) != 0) {
        printf("两次输入不一致。\n");
        return -1;
    }

    /* 仅更新文件的第一行 */
    FILE *fp = fopen(filename, "r+");
    if (!fp) { perror("fopen"); return -1; }
    /* 写入新密码 */
    fseek(fp, 0, SEEK_SET);
    fprintf(fp, "%s\n", newPwd);
    fclose(fp);

    printf("密码已修改。\n");
    return 0;
}
