```c
#include <stdio.h>
#include <stdlib.h>

/*
 * 约瑟夫环
 * 输入：两整数 n (人数) 与 m (每次移除的间隔)
 * 输出：最后剩下的人的 1‑基编号
 *
 * 时间复杂度：O(n)      —— 只需一次循环遍历 1…n
 * 空间复杂度：O(1)      —— 仅使用常数级别的临时变量
 */
int josephus(int n, int m) {
    int survivor = 0;          // f(1) = 0
    for (int i = 2; i <= n; ++i) {
        survivor = (survivor + m) % i;
    }
    return survivor + 1;       // 转换为 1‑基编号
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    if (n <= 0 || m <= 0) {
        fprintf(stderr, "n and m must be positive integers\n");
        return EXIT_FAILURE;
    }

    int last = josephus(n, m);
    printf("%d\n", last);
    return EXIT_SUCCESS;
}
```

