destinations = [
    ("192.168.1.10", 50001),
    ("192.168.1.11", 50001),
    ("192.168.1.12", 50001)
]

msg = b"Hello, device!"

# 等待 socket 可写
rlist, wlist, xlist = select.select([], [udp_sock], [], 1.0)
if udp_sock in wlist:
    for addr in destinations:
        udp_sock.sendto(msg, addr)
