bool isPrime(int n)
{
    if (n <= 1)            // 0, 1 and negative numbers are NOT prime
        return false;

    if (n <= 3)            // 2 and 3 are prime
        return true;

    if (n % 2 == 0 || n % 3 == 0)   // multiples of 2 or 3 are composite
        return false;

    /* Check divisibility only up to sqrt(n).
       We can skip even numbers by incrementing by 6
       (checking i and i+2).  This keeps the loop fast. */
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0)
            return false;
    }

    return true;   // no divisor found – n is prime
}

int main(void)
{
    int number;

    printf("Enter an integer: ");
    if (scanf("%d", &number) != 1) {
        fprintf(stderr, "Invalid input!\n");
        return 1;
    }

    if (isPrime(number))
        printf("%d is a prime number.\n", number);
    else
        printf("%d is NOT a prime number.\n", number);

    return 0;
}
