**在 Linux 设备驱动里，`id_table`（device ID table）通常是一个静态的 const 结构体数组，用来告诉子系统（USB、I2C、SPI、platform 等）哪些设备可以由该驱动匹配。**  
如果你想在运行时（即动态地）构造这个表并让驱动使用它，基本思路是：

1. **在驱动初始化时动态分配内存**  
   ```c
   /* 例如 USB 驱动 */
   static struct usb_driver my_usb_driver;
   static struct usb_device_id *my_id_table = NULL;
   ```
   ```c
   static int __init my_driver_init(void)
   {
       int i, nr_ids = get_runtime_num_ids();   /* 根据业务逻辑决定需要多少条记录 */
       /* 多加 1 以放置终止符 {} */
       my_id_table = kzalloc(sizeof(*my_id_table) * (nr_ids + 1), GFP_KERNEL);
       if (!my_id_table)
           return -ENOMEM;

       /* 填充 id_table */
       for (i = 0; i < nr_ids; i++) {
           /* 这里以 USB 为例，实际填充方式视子系统而定 */
           my_id_table[i].match_flags = USB_DEVICE_ID_MATCH_VENDOR |
                                        USB_DEVICE_ID_MATCH_PRODUCT;
           my_id_table[i].id.vendor = my_vendor_id[i];
           my_id_table[i].id.product = my_product_id[i];
       }
       /* 末尾自动由 kzalloc 初始化为 0，起到终止符作用 */

       /* 绑定表到驱动 */
       my_usb_driver.id_table = my_id_table;
       my_usb_driver.name     = "my_dyn_driver";
       /* 其它字段也要正常填写 */

       return usb_register_driver(&my_usb_driver, &my_drv_ops, THIS_MODULE);
   }
   ```

2. **驱动注销时释放表**  
   ```c
   static void __exit my_driver_exit(void)
   {
       usb_deregister_driver(&my_usb_driver);
       kfree(my_id_table);
   }
   ```

3. **注意事项**  

   - **表必须在注册前准备好**：`id_table` 的指针在调用 `register_*_driver()` 之前就要指向合法且不在栈上的内存。  
   - **表需要保持存在直到驱动卸载**：在驱动注销之前不能释放该内存，否则会导致子系统访问空指针。  
   - **终止符**：所有子系统（USB、I2C、SPI、platform 等）要求 `id_table` 以一个全 0 的记录结束。使用 `kzalloc` 自动完成这一点，或者手动写 `my_id_table[nr_ids] = {0}`。  
   - **`MODULE_DEVICE_TABLE` 宏不适用**：该宏是给编译时静态表使用，用来让 `modprobe` 能通过 `modinfo` 自动匹配驱动。动态生成的表无法被 `MODULE_DEVICE_TABLE` 处理，`modprobe` 无法基于此表加载驱动。若你需要让用户空间在设备出现时自动加载模块，必须使用静态表或在驱动内部自行完成匹配。  
   - **子系统 API**：不同子系统对 `id_table` 的结构体略有差异（USB 用 `struct usb_device_id`，I2C 用 `struct i2c_device_id`，SPI 用 `struct spi_device_id`，platform 用 `struct platform_device_id` 等）。填充时请按对应子系统的字段来做。  

4. **完整示例**（USB 驱动，动态构造 id_table）  

   ```c
   #include <linux/module.h>
   #include <linux/usb.h>

   static struct usb_driver dyn_usb_driver;
   static struct usb_device_id *dyn_id_table = NULL;

   static int dyn_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
   {
       pr_info("dyn_usb: device matched\n");
       return 0;
   }

   static void dyn_usb_disconnect(struct usb_interface *intf)
   {
       pr_info("dyn_usb: device disconnected\n");
   }

   static struct usb_driver_ops dyn_usb_ops = {
       .probe      = dyn_usb_probe,
       .disconnect = dyn_usb_disconnect,
   };

   static int __init dyn_usb_init(void)
   {
       int nr_ids = 2;   /* 假设我们想匹配两个设备 */
       dyn_id_table = kzalloc(sizeof(*dyn_id_table) * (nr_ids + 1), GFP_KERNEL);
       if (!dyn_id_table)
           return -ENOMEM;

       /* 设备 1 */
       dyn_id_table[0].match_flags = USB_DEVICE_ID_MATCH_VENDOR |
                                     USB_DEVICE_ID_MATCH_PRODUCT;
       dyn_id_table[0].id.vendor   = 0x1234;
       dyn_id_table[0].id.product  = 0x0001;

       /* 设备 2 */
       dyn_id_table[1].match_flags = USB_DEVICE_ID_MATCH_VENDOR |
                                     USB_DEVICE_ID_MATCH_PRODUCT;
       dyn_id_table[1].id.vendor   = 0x1234;
       dyn_id_table[1].id.product  = 0x0002;
       /* 末尾的 0 自动由 kzalloc 初始化 */

       dyn_usb_driver.name     = "dyn_usb";
       dyn_usb_driver.id_table = dyn_id_table;
       dyn_usb_driver.ops      = &dyn_usb_ops;

       return usb_register_driver(&dyn_usb_driver, THIS_MODULE);
   }

   static void __exit dyn_usb_exit(void)
   {
       usb_deregister_driver(&dyn_usb_driver);
       kfree(dyn_id_table);
   }

   module_init(dyn_usb_init);
   module_exit(dyn_usb_exit);
   MODULE_LICENSE("GPL");
   ```

**总结**：  
- 在驱动 **初始化** 之前用 `kzalloc/kalloc` 分配 `id_table`，并填充好需要匹配的设备 ID。  
- 把指针赋给驱动结构体的 `id_table` 字段，然后调用相应的 `*_register_driver()`。  
- 在驱动 **注销** 之前不要释放 `id_table`，注销后再 `kfree()`。  
- 由于 `MODULE_DEVICE_TABLE` 仅用于编译时静态表，动态表无法让 `modprobe` 自动加载。若需要自动加载，需要自行实现匹配逻辑或保持静态表。

