下面给出两段示例代码，分别说明：

1. **把整个 `.csv` 文件原始字节读进一个 `unsigned char *`（byte）数组**  
2. **按行读取 CSV，解析每个数值（假设是 0~255 的整数），并把它们存进 `unsigned char` 数组**  

两段代码都可以直接复制到 Visual Studio / GCC / clang 等环境中编译运行，演示了常用的文件 I/O 与字符串处理技巧。  

> **提示**  
> - 读取文件时一定要检查错误（`fopen`, `fread` 等）。  
> - 当你只关心数值内容时，推荐使用第二种方式；当你需要保持原始字节顺序（比如做 CRC 或传输）时，使用第一种方式。  

---

## 1. 读取整个 `.csv` 文件到 `byte`（`unsigned char`）数组

```c
/*********************************************************************
 *  读取整个 CSV 文件的字节流
 *  - 把文件读进一个 unsigned char * 数组
 *  - 适合做“二进制文件”读取，或者后期做 CRC / 加密等
 *********************************************************************/
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    const char *filepath = "data.csv";
    FILE *fp = fopen(filepath, "rb");            /* 二进制模式 */
    if (!fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    /* 取得文件大小 */
    if (fseek(fp, 0, SEEK_END) != 0) { /* seek 失败 */
        perror("fseek");
        fclose(fp);
        return EXIT_FAILURE;
    }
    long filesize = ftell(fp);          /* 文件长度（字节） */
    if (filesize < 0) {
        perror("ftell");
        fclose(fp);
        return EXIT_FAILURE;
    }
    rewind(fp);                          /* 回到文件头 */

    /* 分配缓冲区 */
    unsigned char *buf = malloc(filesize);
    if (!buf) {
        fprintf(stderr, "内存不足\n");
        fclose(fp);
        return EXIT_FAILURE;
    }

    /* 读取文件 */
    size_t nread = fread(buf, 1, (size_t)filesize, fp);
    if (nread != (size_t)filesize) {
        fprintf(stderr, "读取错误: 已读 %zu 字节，期望 %ld 字节\n",
                nread, filesize);
        free(buf);
        fclose(fp);
        return EXIT_FAILURE;
    }
    fclose(fp);

    /* 现在 buf[0..nread-1] 就是整个文件的字节内容 */
    /* 下面演示打印前 32 字节（十六进制） */
    printf("文件大小: %ld 字节\n", filesize);
    printf("前 32 字节（十六进制）: ");
    for (size_t i = 0; i < 32 && i < nread; ++i) {
        printf("%02X ", buf[i]);
    }
    printf("\n");

    /* 记得释放 */
    free(buf);
    return EXIT_SUCCESS;
}
```

> **解释**  
> - 用 `rb` 模式打开文件，防止 Windows 下的文本行结束符被自动转换。  
> - `fseek` + `ftell` 获取文件大小，然后 `rewind` 回文件头。  
> - `fread` 的第二个参数 1 表示读 1 字节，第三个参数是总字节数。  

---

## 2. 逐行读取 CSV 并把整数存进 `unsigned char` 数组

假设 CSV 文件内容如下：

```
12, 34, 56
78, 90, 123
255, 0, 1
```

我们把每个整数（0~255）存进一个 `unsigned char` 数组。

```c
/*********************************************************************
 *  按行读取 CSV，解析整数并存入 unsigned char 数组
 *  - 支持任意行数和列数
 *  - 每个值被强制转换为 unsigned char（0~255）
 *********************************************************************/
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

/* 预先分配一个缓冲区，用来保存整行字符串（假设行宽不超过 1024 字节） */
#define MAX_LINE_LEN 1024

/* 简单的动态数组，用来存放解析出的字节 */
typedef struct {
    unsigned char *data;
    size_t size;      /* 已使用字节数 */
    size_t capacity;  /* 已分配字节数 */
} ByteArray;

static void ba_init(ByteArray *ba)
{
    ba->capacity = 1024;          /* 初始容量 */
    ba->size     = 0;
    ba->data     = malloc(ba->capacity);
}

static void ba_append(ByteArray *ba, unsigned char v)
{
    if (ba->size >= ba->capacity) {          /* 容量不足，扩容 */
        size_t newcap = ba->capacity * 2;
        unsigned char *tmp = realloc(ba->data, newcap);
        if (!tmp) {
            fprintf(stderr, "内存分配失败\n");
            free(ba->data);
            exit(EXIT_FAILURE);
        }
        ba->data = tmp;
        ba->capacity = newcap;
    }
    ba->data[ba->size++] = v;
}

static void ba_free(ByteArray *ba)
{
    free(ba->data);
    ba->data = NULL;
    ba->size = 0;
    ba->capacity = 0;
}

int main(void)
{
    const char *filepath = "data.csv";
    FILE *fp = fopen(filepath, "r");   /* 只读文本模式 */
    if (!fp) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    ByteArray ba;
    ba_init(&ba);

    char line[MAX_LINE_LEN];
    while (fgets(line, sizeof(line), fp)) {
        /* 删除行尾换行符 */
        line[strcspn(line, "\r\n")] = '\0';

        /* 逐个 token（逗号分隔） */
        char *tok = strtok(line, ",");
        while (tok) {
            /* 去掉前后空格 */
            while (*tok == ' ' || *tok == '\t') ++tok;
            char *end = tok;
            while (*end && (*end != ' ' && *end != '\t')) ++end;
            *end = '\0';

            /* 转换为 long，检查范围 0~255 */
            errno = 0;
            long val = strtol(tok, NULL, 10);
            if (errno != 0 || val < 0 || val > 255) {
                fprintf(stderr, "非法数值 '%s'\n", tok);
                ba_free(&ba);
                fclose(fp);
                return EXIT_FAILURE;
            }

            ba_append(&ba, (unsigned char)val);

            tok = strtok(NULL, ",");
        }
    }
    fclose(fp);

    /* 现在 ba.data[0..ba.size-1] 就是所有整数的字节表示 */
    printf("读取到 %zu 个字节。\n", ba.size);
    printf("前 20 字节（十六进制）: ");
    for (size_t i = 0; i < ba.size && i < 20; ++i) {
        printf("%02X ", ba.data[i]);
    }
    printf("\n");

    ba_free(&ba);
    return EXIT_SUCCESS;
}
```

### 代码要点

| 步骤 | 说明 |
|------|------|
| `fgets` | 逐行读取。`MAX_LINE_LEN` 必须足够大，防止行过长导致截断。 |
| `strtok` | 以 `,` 为分隔符把一行拆分成 token。 |
| `strtol` | 把 token 转为 `long`，再判断是否在 0~255 范围。 |
| `ByteArray` | 典型的可动态扩展数组，实现 `append`、`init`、`free`。 |
| `*end = '\0'` | 手动截断 token，避免 `strtok` 对后续 token 产生干扰。 |

> **如果 CSV 的数值超出了 `unsigned char` 的范围**（例如 0~65535），请把 `ByteArray` 换成 `unsigned short` 或 `int` 等类型，并相应修改 `ba_append` 的参数类型。

