/*********************************************************************
 *  Đề bài:  Cho số nguyên dương n (1 ≤ n ≤ 10⁷).  Liệt kê tất cả
 *  các số nguyên tố ≤ n trên một dòng, cách nhau bởi dấu cách.
 *
 *  Thuật toán: Sieve of Eratosthenes (đảo ngược) – O(n log log n)
 *  Độ phức tạp bộ nhớ: O(n) (có thể giảm bằng bitset nếu n lớn hơn)
 *
 *  Ghi chú: Nếu n <= 1, không có số nguyên tố.
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main(void) {
    unsigned int n;
    if (scanf("%u", &n) != 1) return 1;   /* Đọc n */

    if (n < 2) {                          /* Không có số nguyên tố */
        return 0;
    }

    /* Đặt mảng bool: 1 → số nguyên tố, 0 → không phải */
    /* Dùng calloc để tự động khởi tạo toàn bộ thành 0 */
    char *isPrime = calloc(n + 1, sizeof(char));
    if (!isPrime) return 1;               /* Kiểm tra lỗi cấp phát */

    /* Tất cả số >= 2 đều ban đầu là có thể là nguyên tố */
    for (unsigned int i = 2; i <= n; ++i) isPrime[i] = 1;

    unsigned int limit = (unsigned int) sqrt((double)n);

    for (unsigned int p = 2; p <= limit; ++p) {
        if (!isPrime[p]) continue;        /* Nếu p không nguyên tố thì bỏ qua */

        /* Bỏ đi tất cả các bội của p */
        for (unsigned int multiple = p * p; multiple <= n; multiple += p) {
            isPrime[multiple] = 0;
        }
    }

    /* In ra các số nguyên tố */
    int first = 1;  /* Đánh dấu số đầu tiên để không xuống dòng đầu dòng */
    for (unsigned int i = 2; i <= n; ++i) {
        if (isPrime[i]) {
            if (!first) putchar(' ');
            printf("%u", i);
            first = 0;
        }
    }
    putchar('\n');

    free(isPrime);
    return 0;
}
