#include <stdio.h>
#include <string.h>

#define MAX_HASH 1000001

/* Hash table: maps a number → its **first** occurrence index. */
static int hashtable[MAX_HASH];

/* ----------------------------------------------------------------- */
/* Helpers for the hash table                                         */
/* ----------------------------------------------------------------- */
static void clearHashtable(void) {
    /* -1 means “not seen yet”. */
    memset(hashtable, 0xFF, sizeof hashtable);
}

static int getHash(int number) {
    if (number >= 0 && number < MAX_HASH) {
        return hashtable[number];
    }
    return -1;           /* out of bounds → not present */
}

static void setHashIfUnset(int number, int index) {
    if (number >= 0 && number < MAX_HASH && hashtable[number] == -1) {
        hashtable[number] = index;   /* store only the first index */
    }
}

/* ----------------------------------------------------------------- */
/* Main routine: find and print one longest consecutive subsequence  */
/* ----------------------------------------------------------------- */
static void findLongestConsecutiveSequence(const int *book, int n) {
    clearHashtable();

    /* Pass 1 – populate the hash table with the first index of each value */
    for (int i = 0; i < n; ++i) {
        setHashIfUnset(book[i], i);
    }

    /* Pass 2 – look for the longest streak */
    int longestStreak = 0;
    int startNumber  = -1;      /* value that starts the longest streak */

    for (int i = 0; i < n; ++i) {
        int num = book[i];

        /* Only consider numbers that could be the start of a sequence */
        if (getHash(num - 1) == -1) {
            int curLen = 1;
            while (getHash(num + curLen) != -1) {
                ++curLen;
            }

            if (curLen > longestStreak) {   /* strictly longer? */
                longestStreak = curLen;
                startNumber   = num;
            }
        }
    }

    /* ----------------------------------------------------------------- */
    /* Print the result (exactly one subsequence)                         */
    /* ----------------------------------------------------------------- */
    printf("%d\n", longestStreak);
    for (int i = 0; i < longestStreak; ++i) {
        /* We print the index of the number that starts the streak + i. */
        printf("%d ", getHash(startNumber + i));
    }
    printf("\n");
}

/* --------------------------------------------------------------------- */
/* Main – just reads input, calls the routine, and exits                  */
/* --------------------------------------------------------------------- */
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int *book = malloc(sizeof(int) * n);
    if (!book) return 0;

    for (int i = 0; i < n; ++i) {
        scanf("%d", &book[i]);
    }

    findLongestConsecutiveSequence(book, n);

    free(book);
    return 0;
}
```

### Why this guarantees *exactly one* longest subsequence

1. **First‑in‑hash**: By storing only the first occurrence of each number, we avoid “skipping” earlier indices that belong to a longer, legitimate sequence.
2. **Strict comparison**: `curLen > longestStreak` ensures that only *strictly* longer streaks replace the current best.  Equal‑length streaks are ignored, so the earliest one found is kept.
3. **Single print block**: After the search, the code prints the indices for one streak only – the one stored in `startNumber` and `longestStreak`.

