    // ----------- 1. Ввод данных и создание файла --------------------
    std::string fileName;
    std::cout << "Enter name of binary file: ";
    std::getline(std::cin, fileName);

    int n;
    std::cout << "Enter number of employees: ";
    std::cin >> n;
    std::cin.ignore();   // отбросить перевод строки

    std::vector<Employee> employees(n);
    std::unordered_map<int, size_t> idx;   // ID → индекс

    for (int i = 0; i < n; ++i)
    {
        std::cout << "Employee #" << i + 1 << ":\n";
        std::cout << "  ID: ";
        std::cin >> employees[i].num;
        std::cin.ignore();
        std::cout << "  Name (max 9 chars): ";
        std::string tmp; std::getline(std::cin, tmp);
        strncpy(employees[i].name, tmp.c_str(), sizeof(employees[i].name));
        employees[i].name[sizeof(employees[i].name)-1] = '\0';
        std::cout << "  Hours: ";
        std::cin >> employees[i].hours;
        std::cin.ignore();
        idx[employees[i].num] = i;
    }

    WriteEmployees(fileName, employees);
    std::cout << "\nInitial file:\n";
    PrintEmployees(employees);

    // ----------- 2. Создаём именованный канал -------------------------
    HANDLE hPipe = CreateNamedPipe(
        PIPE_NAME,
        PIPE_ACCESS_DUPLEX,
        PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
        1,          // одновременное подключение только одного клиента
        65536, 65536,
        0, nullptr);

    if (hPipe == INVALID_HANDLE_VALUE)
    {
        std::cerr << "CreateNamedPipe failed: " << GetLastError() << '\n';
        return 1;
    }

    // ----------- 3. Запускаем клиент -------------------------
    STARTUPINFO si = {0};
    si.cb = sizeof(si);
    PROCESS_INFORMATION pi = {0};

    // Клиент принимает имя канала в командной строке
    std::wstring cmdLine = L"\"Client.exe\" \"";
    cmdLine += PIPE_NAME;
    cmdLine += L"\"";

    if (!CreateProcess(nullptr, const_cast<LPWSTR>(cmdLine.c_str()),
                       nullptr, nullptr, FALSE, 0, nullptr, nullptr,
                       &si, &pi))
    {
        std::cerr << "CreateProcess failed: " << GetLastError() << '\n';
        CloseHandle(hPipe);
        return 1;
    }

    // ----------- 4. Ожидание подключения клиента --------------------
    std::cout << "Waiting for client to connect...\n";
    if (!ConnectNamedPipe(hPipe, nullptr))
    {
        std::cerr << "ConnectNamedPipe failed: " << GetLastError() << '\n';
        CloseHandle(hPipe);
        return 1;
    }
    std::cout << "Client connected.\n";

    // Структура блокировок для каждой записи
    std::vector<RecordLock> locks(n);

    // ----------- 5. Обслуживаем запросы ------------------------------
    const size_t BUF_SIZE = 512;
    char buffer[BUF_SIZE];
    DWORD bytesRead;

    bool serverRunning = true;

    while (serverRunning)
    {
        bool success = ReadFile(hPipe, buffer, BUF_SIZE, &bytesRead, nullptr);
        if (!success || bytesRead == 0)
        {
            std::cerr << "ReadFile from client failed: " << GetLastError() << '\n';
            break;
        }

        std::string msg(buffer, bytesRead);
        std::istringstream iss(msg);
        std::string cmd;
        iss >> cmd;

        if (cmd == "READ")
        {
            int id; iss >> id;
            auto it = idx.find(id);
            if (it == idx.end())
            {
                std::string err = "ERROR: No employee with ID " + std::to_string(id) + "\n";
                WriteFile(hPipe, err.c_str(), (DWORD)err.size(), &bytesRead, nullptr);
                continue;
            }

            size_t i = it->second;
            auto &rl = locks[i];

            // Блокируем (shared) – ждем пока запись не будет свободна для чтения
            bool gotLock = false;
            while (!gotLock)
            {
                std::unique_lock lock(rl.mutex);
                if (!rl.write)
                {
                    ++rl.readCount;
                    gotLock = true;
                }
            }

            // Отправляем запись
            std::ostringstream oss;
            oss << "OK\n" << employees[i].num << '\n'
                << employees[i].name << '\n'
                << employees[i].hours << '\n';
            std::string out = oss.str();
            WriteFile(hPipe, out.c_str(), (DWORD)out.size(), &bytesRead, nullptr);
        }
        else if (cmd == "WRITE")
        {
            int id; iss >> id;
            auto it = idx.find(id);
            if (it == idx.end())
            {
                std::string err = "ERROR: No employee with ID " + std::to_string(id) + "\n";
                WriteFile(hPipe, err.c_str(), (DWORD)err.size(), &bytesRead, nullptr);
                continue;
            }

            size_t i = it->second;
            auto &rl = locks[i];

            // Ждем эксклюзивного доступа
            bool gotLock = false;
            while (!gotLock)
            {
                std::unique_lock lock(rl.mutex);
                if (!rl.write && rl.readCount == 0)
                {
                    rl.write = true;
                    gotLock = true;
                }
            }

            // Отправляем запись
            std::ostringstream oss;
            oss << "OK\n" << employees[i].num << '\n'
                << employees[i].name << '\n'
                << employees[i].hours << '\n';
            std::string out = oss.str();
            WriteFile(hPipe, out.c_str(), (DWORD)out.size(), &bytesRead, nullptr);
        }
        else if (cmd == "MODIFY")
        {
            int id; iss >> id;
            int newID; iss >> newID;
            std::string newName; iss >> newName;
            double newHours; iss >> newHours;

            auto it = idx.find(id);
            if (it == idx.end())
            {
                std::string err = "ERROR: No employee with ID " + std::to_string(id) + "\n";
                WriteFile(hPipe, err.c_str(), (DWORD)err.size(), &bytesRead, nullptr);
                continue;
            }

            size_t i = it->second;
            auto &rl = locks[i];

            // Учитываем, что запись уже держит эксклюзивный блок (write==true)
            employees[i].num = newID;
            strncpy(employees[i].name, newName.c_str(), sizeof(employees[i].name));
            employees[i].name[sizeof(employees[i].name)-1] = '\0';
            employees[i].hours = newHours;

            // Обновили индекс, если ID поменялся
            if (newID != id)
            {
                idx.erase(id);
                idx[newID] = i;
            }

            // Снимаем блок
            {
                std::unique_lock lock(rl.mutex);
                rl.write = false;
                rl.readCount = 0;
            }

            std::string ok = "OK\n";
            WriteFile(hPipe, ok.c_str(), (DWORD)ok.size(), &bytesRead, nullptr);
        }
        else if (cmd == "RELEASE")
        {
            int id; iss >> id;
            auto it = idx.find(id);
            if (it != idx.end())
            {
                size_t i = it->second;
                auto &rl = locks[i];
                std::unique_lock lock(rl.mutex);
                if (rl.readCount > 0) --rl.readCount;
                // write==true – не снимаем в RELEASE, только в MODIFY
            }
        }
        else if (cmd == "EXIT")
        {
            std::string ok = "OK\n";
            WriteFile(hPipe, ok.c_str(), (DWORD)ok.size(), &bytesRead, nullptr);
            serverRunning = false;
        }
        else
        {
            std::string err = "ERROR: Unknown command\n";
            WriteFile(hPipe, err.c_str(), (DWORD)err.size(), &bytesRead, nullptr);
        }
    }

    // ----------- 6. Печатаем окончательный файл ----------------------
    std::cout << "\nModified file:\n";
    ReadEmployees(fileName, employees);
    PrintEmployees(employees);

    std::cout << "\nPress Enter to quit.\n";
    std::cin.get();

    // ----------- 7. Завершаем ----------------------
    DisconnectNamedPipe(hPipe);
    CloseHandle(hPipe);
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    return 0;
}
