## Мини‑пример однопоточного «асинхронного» сервера на C  
*Псевдопараллельная обработка клиентов с `select()`.*

```c
/*
 * echo_server_select.c
 *
 * Сокет‑сервер, который слушает порт 12345 и отсылает обратно всё, что
 * пришло от клиента (echo).  
 * Работает одним потоком, использует multiplexing через select().
 *
 * Компиляция:
 *   gcc -Wall -O2 echo_server_select.c -o echo_server_select
 *
 * Запуск:
 *   ./echo_server_select
 *
 * Клиентом можно пользоваться telnet:
 *   telnet 127.0.0.1 12345
 *
 * Примечание:
 *   Это простейший пример. В реальном коде надо обрабатывать ошибки более
 *   подробно, хранить состояние клиентов, делать неблокирующие операции и т.д.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/select.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define LISTEN_PORT 12345
#define MAX_CLIENTS FD_SETSIZE          /* максимальное число дескрипторов */
#define BUF_SIZE   4096

/* --------------------------------------------------------------- */
/*  Удаляем все открытые дескрипторы при завершении программы     */
static int server_fd = -1;

static void cleanup(void)
{
    if (server_fd != -1) close(server_fd);
}

static void sigint_handler(int /*sig*/)
{
    printf("\nОстановка сервера...\n");
    cleanup();
    exit(0);
}
/* --------------------------------------------------------------- */

int main(void)
{
    struct sockaddr_in serv_addr;
    int opt = 1;

    /* 1. Создаём прослушивающий сокет -------------------------------- */
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* Включаем опцию SO_REUSEADDR, чтобы быстро перезапустить сервер */
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    /* Привязываем к адресу 0.0.0.0:12345 */
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family      = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port        = htons(LISTEN_PORT);

    if (bind(server_fd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("bind");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    /* Слушаем входящие подключения */
    if (listen(server_fd, SOMAXCONN) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    /* Устанавливаем обработчик SIGINT, чтобы закрыть сокеты */
    signal(SIGINT, sigint_handler);

    /* 2. Инициализируем множества дескрипторов для select()  ----------- */
    fd_set master_set, read_fds;
    FD_ZERO(&master_set);
    FD_SET(server_fd, &master_set);
    int max_fd = server_fd;

    printf("Сервер запущен на порту %d. Ждем подключений...\n", LISTEN_PORT);

    /* 3. Главный цикл ---------------------------------------------- */
    while (1) {
        read_fds = master_set;              /* копируем, т.к. select меняет */
        int ready = select(max_fd + 1, &read_fds, NULL, NULL, NULL);

        if (ready < 0) {
            if (errno == EINTR) continue;   /* сигнал прервал select */
            perror("select");
            break;
        }

        /* Перебираем все дескрипторы */
        for (int fd = 0; fd <= max_fd; ++fd) {
            if (!FD_ISSET(fd, &read_fds)) continue;   /* нет события */

            if (fd == server_fd) {
                /* 3.1 Новый клиент ----------------------------------- */
                struct sockaddr_in cli_addr;
                socklen_t cli_len = sizeof(cli_addr);
                int new_fd = accept(server_fd, (struct sockaddr *)&cli_addr, &cli_len);

                if (new_fd < 0) {
                    perror("accept");
                    continue;
                }

                /* Добавляем в множество активных дескрипторов */
                FD_SET(new_fd, &master_set);
                if (new_fd > max_fd) max_fd = new_fd;

                char ip_str[INET_ADDRSTRLEN];
                inet_ntop(AF_INET, &cli_addr.sin_addr, ip_str, sizeof(ip_str));
                printf("Новый клиент: %s:%d (fd=%d)\n",
                       ip_str, ntohs(cli_addr.sin_port), new_fd);
            } else {
                /* 3.2 Существующий клиент --------------------------------- */
                char buf[BUF_SIZE];
                ssize_t n = recv(fd, buf, sizeof(buf), 0);

                if (n > 0) {
                    /* Отсылаем клиенту обратно (echo) */
                    ssize_t sent = 0;
                    while (sent < n) {
                        ssize_t m = send(fd, buf + sent, n - sent, 0);
                        if (m < 0) {
                            perror("send");
                            break;
                        }
                        sent += m;
                    }
                } else if (n == 0) {
                    /* Клиент закрыл соединение */
                    printf("Клиент (fd=%d) отключился\n", fd);
                    close(fd);
                    FD_CLR(fd, &master_set);
                } else {
                    /* Ошибка чтения */
                    perror("recv");
                    close(fd);
                    FD_CLR(fd, &master_set);
                }
            }
        }
    }

    cleanup();
    return 0;
}
```

### Что делает код

| Шаг | Что происходит | Почему это «асинхронно»? |
|-----|----------------|--------------------------|
| 1   | Создаём один прослушивающий сокет, `listen()` | Один поток, один сокет. |
| 2   | Инициализируем `fd_set` и помещаем в него дескриптор сервера | `fd_set` хранит все активные сокеты. |
| 3   | В бесконечном цикле вызываем `select(max_fd+1, &read_fds, ...)` | `select()` блокируется, пока *не* станет готов хотя бы один сокет. |
| 3.1 | Если готов дескриптор сервера, принимаем новое подключение и добавляем его в `fd_set`. | Новые клиенты обслуживаются «параллельно» без потоков. |
| 3.2 | Если готов клиентский сокет, читаем данные, пишем ответ и, при `recv()==0`, закрываем соединение. | Один дескриптор обрабатывается в тот момент, когда он готов, остальные ждут. |

> **Псевдопараллелизм** достигается тем, что сервер не «заблокирован» одним клиентом: пока один клиент ждёт ответа, другие клиенты могут продолжать работать, потому что `select()` сообщает, какие из них готовы к чтению/записи.

### Как расширить

* Хранить буфер для каждого клиента и состояние (например, «ожидаю данные», «готовлю ответ»).  
* Делать сокеты неблокирующими (`fcntl(fd, F_SETFL, O_NONBLOCK)`) и обрабатывать `EAGAIN`.  
* Использовать `poll()` или `epoll()` для больших количеств соединений.  
* Добавить тайм‑ауты, чтобы закрывать «мертвые» соединения.  

Этот пример иллюстрирует принцип однопоточного асинхронного сервера и легко переносится на более сложные сценарии. Happy coding!

