#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <ctype.h>
#include <errno.h>
#include <sys/types.h>

/* ---------- Data structures ---------- */

typedef struct {
    pid_t pid;
    pid_t ppid;
    char state;      /* 'R','S','D','Z','T','X', ... */
} ProcInfo;

/* Simple dynamic integer list */
typedef struct {
    int *data;
    size_t size;
    size_t cap;
} IntList;

static void intlist_init(IntList *l)
{
    l->data = NULL;
    l->size = 0;
    l->cap  = 0;
}

static void intlist_add(IntList *l, int v)
{
    if (l->size == l->cap) {
        size_t newcap = (l->cap == 0) ? 16 : l->cap * 2;
        int *tmp = realloc(l->data, newcap * sizeof(int));
        if (!tmp) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        l->data = tmp;
        l->cap  = newcap;
    }
    l->data[l->size++] = v;
}

static int intlist_contains(const IntList *l, int v)
{
    for (size_t i = 0; i < l->size; ++i)
        if (l->data[i] == v) return 1;
    return 0;
}

static void intlist_free(IntList *l)
{
    free(l->data);
    l->data = NULL;
    l->size = l->cap = 0;
}

/* ---------- /proc reading ---------- */

/* Read /proc/<pid>/stat and extract PPID and state */
static int read_proc_stat(pid_t pid, pid_t *ppid, char *state)
{
    char path[64];
    snprintf(path, sizeof(path), "/proc/%d/stat", pid);

    FILE *fp = fopen(path, "r");
    if (!fp) return -1;

    /* stat format: pid (comm) state ppid ... */
    int dummy;
    char comm[256];
    char st;
    int ppid_tmp;

    /* Use fscanf that skips the comm field correctly */
    if (fscanf(fp, "%d (%[^)]) %c %d", &dummy, comm, &st, &ppid_tmp) != 4) {
        fclose(fp);
        return -1;
    }
    fclose(fp);

    *ppid = (pid_t)ppid_tmp;
    *state = st;
    return 0;
}

