/* ---------- Tree traversal utilities ---------- */

/* Recursively collect all descendants of 'root' */
static void collect_descendants(const ProcInfo *list, size_t cnt,
                                pid_t root, IntList *desc)
{
    for (size_t i = 0; i < cnt; ++i) {
        if (list[i].ppid == root) {
            if (!intlist_contains(desc, list[i].pid))
                intlist_add(desc, list[i].pid);
            collect_descendants(list, cnt, list[i].pid, desc);
        }
    }
}

/* Return the list of direct children of a given PID */
static IntList direct_children(const ProcInfo *list, size_t cnt, pid_t parent)
{
    IntList children;
    intlist_init(&children);
    for (size_t i = 0; i < cnt; ++i) {
        if (list[i].ppid == parent)
            intlist_add(&children, list[i].pid);
    }
    return children;
}

/* ---------- Option handlers ---------- */

/* Print a list of PIDs, one per line */
static void print_pid_list(const IntList *lst)
{
    for (size_t i = 0; i < lst->size; ++i)
        printf("%d\n", lst->data[i]);
}

/* Option -nd : non‑direct descendants of pid1 */
static void handle_nd(const ProcInfo *list, size_t cnt, pid_t pid1)
{
    IntList all, direct;
    intlist_init(&all);
    intlist_init(&direct);

    /* collect all descendants (recursively) */
    collect_descendants(list, cnt, pid1, &all);
    /* direct children */
    direct = direct_children(list, cnt, pid1);

    /* output all except direct children */
    for (size_t i = 0; i < all.size; ++i) {
        if (!intlist_contains(&direct, all.data[i]))
            printf("%d\n", all.data[i]);
    }

    intlist_free(&all);
    intlist_free(&direct);
}

/* Option -dd : direct descendants */
static void handle_dd(const ProcInfo *list, size_t cnt, pid_t pid1)
{
    IntList children = direct_children(list, cnt, pid1);
    print_pid_list(&children);
    intlist_free(&children);
}

/* Option -sb : siblings of pid1 */
static void handle_sb(const ProcInfo *list, size_t cnt, pid_t pid1)
{
    const ProcInfo *p1 = find_proc(list, cnt, pid1);
    if (!p1) return;
    IntList siblings = direct_children(list, cnt, p1->ppid);
    for (size_t i = 0; i < siblings.size; ++i)
        if (siblings.data[i] != pid1)
            printf("%d\n", siblings.data[i]);
    intlist_free(&siblings);
}

/* Option -sz : sibling defunct processes */
static void handle_sz(const ProcInfo *list, size_t cnt, pid_t pid1)
{
    const ProcInfo *p1 = find_proc(list, cnt, pid1);
    if (!p1) return;
    IntList siblings = direct_children(list, cnt, p1->ppid);
    for (size_t i = 0; i < siblings.size; ++i) {
        if (siblings.data[i] == pid1) continue;
        const ProcInfo *sib = find_proc(list, cnt, siblings.data[i]);
        if (sib && sib->state == 'Z')
            printf("%d\n", sib->pid);
    }
    intlist_free(&siblings);
}

/* Option -gc : grandchildren of pid1 */
static void handle_gc(const ProcInfo *list, size_t cnt, pid_t pid1)
{
    /* direct children of pid1 */
    IntList children = direct_children(list, cnt, pid1);
    /* grandchildren: children of each child */
    for (size_t i = 0; i < children.size; ++i) {
        IntList gc = direct_children(list, cnt, children.data[i]);
        print_pid_list(&gc);
        intlist_free(&gc);
    }
    intlist_free(&children);
}

/* Option -zz : print status of pid1 */
static void handle_zz(const ProcInfo *list, size_t cnt, pid_t pid1)
{
    const ProcInfo *p1 = find_proc(list, cnt, pid1);
    if (!p1) return;
    if (p1->state == 'Z')
        printf("Defunct\n");
    else
        printf("Not Defunct\n");
}

/* Option -zc : defunct direct descendants of pid1 */
static void handle_zc(const ProcInfo *list, size_t cnt, pid_t pid1)
{
    IntList children = direct_children(list, cnt, pid1);
    for (size_t i = 0; i < children.size; ++i) {
        const ProcInfo *c = find_proc(list, cnt, children.data[i]);
        if (c && c->state == 'Z')
            printf("%d\n", c->pid);
    }
    intlist_free(&children);
}

/* ---------- Main program ---------- */

int main(int argc, char *argv[])
{
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <root> <pid1> [<pid2> ... <pid5>] <OPTION>\n", argv[0]);
        return EXIT_FAILURE;
    }

    /* Parse root PID */
    pid_t root_pid = (pid_t)atoi(argv[1]);

    /* Number of target PIDs */
    int n_pids = argc - 3;          /* root + pids + option = argc */
    if (n_pids < 1 || n_pids > 5) {
        fprintf(stderr, "Error: must specify 1–5 process IDs\n");
        return EXIT_FAILURE;
    }

    pid_t *target_pids = malloc(n_pids * sizeof(pid_t));
    for (int i = 0; i < n_pids; ++i)
        target_pids[i] = (pid_t)atoi(argv[2 + i]);

    const char *option = argv[argc - 1];

    /* Build the process list */
    size_t proc_cnt;
    ProcInfo *proc_list = scan_all_procs(&proc_cnt);

    /* Build the descendant set of root_pid */
    IntList descendant_set;
    intlist_init(&descendant_set);
    /* root itself is part of the tree */
    intlist_add(&descendant_set, root_pid);
    collect_descendants(proc_list, proc_cnt, root_pid, &descendant_set);

    /* Print PID/PPID of each target PID that belongs to the tree */
    for (int i = 0; i < n_pids; ++i) {
        pid_t pid = target_pids[i];
        if (!intlist_contains(&descendant_set, pid))
            continue;    /* not in the tree */

        const ProcInfo *p = find_proc(proc_list, proc_cnt, pid);
        if (p)
            printf("PID: %d  PPID: %d\n", p->pid, p->ppid);
    }

    /* Handle options that refer to process_id1 (the first target) */
    pid_t pid1 = target_pids[0];
    const ProcInfo *p1 = find_proc(proc_list, proc_cnt, pid1);

    if (p1) {
        if (strcmp(option, "-nd") == 0)
            handle_nd(proc_list, proc_cnt, pid1);
        else if (strcmp(option, "-dd") == 0)
            handle_dd(proc_list, proc_cnt, pid1);
        else if (strcmp(option, "-sb") == 0)
            handle_sb(proc_list, proc_cnt, pid1);
        else if (strcmp(option, "-sz") == 0)
            handle_sz(proc_list, proc_cnt, pid1);
        else if (strcmp(option, "-gc") == 0)
            handle_gc(proc_list, proc_cnt, pid1);
        else if (strcmp(option, "-zz") == 0)
            handle_zz(proc_list, proc_cnt, pid1);
        else if (strcmp(option, "-zc") == 0)
            handle_zc(proc_list, proc_cnt, pid1);
        else
            fprintf(stderr, "Unknown option '%s'\n", option);
    } else {
        fprintf(stderr, "Process %d not found.\n", pid1);
    }

    /* Clean up */
    intlist_free(&descendant_set);
    free(target_pids);
    free(proc_list);
    return EXIT_SUCCESS;
}
```

### How the program works

1. **Parse the command line**  
   `root_process`, between 1 and 5 `process_id`s, and an option are extracted.  
   The first `process_id` is treated specially by all options.

2. **Scan `/proc`**  
   All numeric directories under `/proc` are read.  
   For each PID the program extracts the *PPID* and *state* from `/proc/<pid>/stat`.

3. **Build the process tree**  
   A simple recursive DFS collects every descendant of the supplied *root* PID.  
   All descendants (including the root itself) are stored in an integer list.

4. **Print requested PIDs**  
   For each queried PID that lies in the descendant set, the program prints  
   `PID: <pid>  PPID: <ppid>`.

5. **Option handling**  
   Every option operates on the **first** queried PID (`process_id1`):
   * `-nd` – non‑direct descendants  
   * `-dd` – direct descendants  
   * `-sb` – siblings  
   * `-sz` – defunct siblings  
   * `-gc` – grandchildren  
   * `-zz` – print defunct status  
   * `-zc` – defunct direct descendants  

   The output is one PID per line unless the option is `-zz` (which prints a single status line).

### Build and run

```sh
gcc -Wall -O2 -o prcinfo prcinfo.c
./prcinfo 1234 5678 9101 -dd
```

Replace the numbers and option with your own values. The program requires **read access** to `/proc`, which is normally granted to all users on Linux.

