下面给出一份 **C 语言** 实现的“万年历实验”示例程序。  
程序的主要功能：

|  功能  | 说明 |
| :------ | :-- |
| **初始化** | 通过键盘输入 **年、月、日**，并记录为“原始时间”。 |
| **调整日期** | ① 增加/减少年份、月份、日期。<br>② 每次操作后立即打印当前日期。 |
| **重置时间** | 直接把当前日期恢复为最初输入的“原始时间”。（不需要再输入任何信息） |
| **退出** | 结束程序。 |

---

## 1. 关键技术点

1. **闰年判断**  
   `is_leap(year)`：如果 `year % 400 == 0` 或者 `(year % 4 == 0 && year % 100 != 0)` 则为闰年。

2. **每月天数**  
   `days_in_month(year, month)`：根据月份和闰年返回该月天数。

3. **日期增减**  
   * `add_day()`、`sub_day()`、`add_month()`、`sub_month()`、`add_year()`、`sub_year()`  
     通过检查边界（如 31 天后跨月、12 月后跨年）来完成日期调整。  
   * 对月份的调整后，若当前日 `day` 超出了新月份的天数，则自动截断为该月最大天数（这与多数日历的“保持同一天数”做法一致）。

---

## 2. 代码

```c
/********************************************************************
 * 万年历实验（C 版）
 * 功能：通过键盘输入初始时间，增减年/月/日，可重置为原始时间
 * 说明：程序仅演示核心逻辑，未做完整的输入合法性校验
 ********************************************************************/
#include <stdio.h>
#include <stdbool.h>

/*--------------------- 数据结构 ---------------------*/
typedef struct {
    int year;
    int month;  /* 1 ~ 12 */
    int day;    /* 1 ~ 31 */
} Date;

/*--------------------- 工具函数 ---------------------*/
bool is_leap(int year) {
    return (year % 400 == 0) || ((year % 4 == 0) && (year % 100 != 0));
}

int days_in_month(int year, int month) {
    static const int mdays[12] = { 31,28,31,30,31,30,31,31,30,31,30,31 };
    if (month == 2 && is_leap(year)) return 29;
    return mdays[month - 1];
}

void print_date(const Date *d) {
    printf("当前日期: %04d-%02d-%02d\n", d->year, d->month, d->day);
}

/*--------------------- 日期增减实现 ---------------------*/
void add_year(Date *d) { d->year++; }
void sub_year(Date *d) { d->year--; }

void add_month(Date *d) {
    if (d->month == 12) {
        d->month = 1;
        d->year++;
    } else {
        d->month++;
    }
    /* 调整天数：若当前天在新月份不存在，则截断 */
    if (d->day > days_in_month(d->year, d->month))
        d->day = days_in_month(d->year, d->month);
}

void sub_month(Date *d) {
    if (d->month == 1) {
        d->month = 12;
        d->year--;
    } else {
        d->month--;
    }
    if (d->day > days_in_month(d->year, d->month))
        d->day = days_in_month(d->year, d->month);
}

void add_day(Date *d) {
    d->day++;
    if (d->day > days_in_month(d->year, d->month)) {
        d->day = 1;
        add_month(d);  /* 月份已处理 */
    }
}

void sub_day(Date *d) {
    d->day--;
    if (d->day < 1) {
        sub_month(d);   /* 月份已处理 */
        d->day = days_in_month(d->year, d->month);
    }
}

/*--------------------- 主程序 ---------------------*/
int main(void) {
    Date origin, current;
    int y, m, d;

    printf("请输入初始日期（年 月 日，用空格分隔）: ");
    if (scanf("%d %d %d", &y, &m, &d) != 3) {
        printf("输入错误！\n");
        return 1;
    }

    /* 校验输入的年月日范围（简化） */
    if (y < 1 || m < 1 || m > 12 || d < 1 || d > days_in_month(y, m)) {
        printf("日期不合法！\n");
        return 1;
    }

    origin.year = y; origin.month = m; origin.day = d;
    current = origin;

    printf("\n=== 万年历实验开始 ===\n");
    print_date(&current);

    while (1) {
        printf("\n--- 请选择操作 ---\n");
        printf("1. 加 1 年\n");
        printf("2. 减 1 年\n");
        printf("3. 加 1 月\n");
        printf("4. 减 1 月\n");
        printf("5. 加 1 天\n");
        printf("6. 减 1 天\n");
        printf("7. 重置为原始时间\n");
        printf("8. 退出程序\n");
        printf("输入选项: ");

        int choice;
        if (scanf("%d", &choice) != 1) {
            printf("输入错误，程序结束。\n");
            break;
        }

        switch (choice) {
            case 1: add_year(&current); break;
            case 2: sub_year(&current); break;
            case 3: add_month(&current); break;
            case 4: sub_month(&current); break;
            case 5: add_day(&current); break;
            case 6: sub_day(&current); break;
            case 7: current = origin; printf("已重置为原始时间。\n"); break;
            case 8: printf("退出程序。\n"); return 0;
            default: printf("无效选项，请重新输入。\n"); continue;
        }
        print_date(&current);
    }

    return 0;
}
```

