#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_NAME_LEN 60

typedef struct {
    char masv[20];          /* Student ID          */
    char hoten[MAX_NAME_LEN]; /* Full name         */
    float toan;             /* Mathematics score   */
    float ly;               /* Physics score       */
    float hoa;              /* Chemistry score     */
    float tong;             /* Total score         */
} Student;

/* --------------------------------------------------------------- */
/*  Helper: read a line and split it into ID, name, three scores    */
/* --------------------------------------------------------------- */
int read_student(Student *s)
{
    /* Read a line */
    char buffer[256];
    if (!fgets(buffer, sizeof(buffer), stdin))
        return 0;               /* EOF */

    /* Trim trailing newline */
    buffer[strcspn(buffer, "\n")] = '\0';

    /* Parse: id name toan ly hoa  */
    /* We assume that the name has no spaces. If the name may contain
     * spaces, a more sophisticated parser would be required.  */
    if (sscanf(buffer, "%19s %59s %f %f %f",
               s->masv, s->hoten, &s->toan, &s->ly, &s->hoa) != 5)
    {
        /* Wrong format – treat as failure */
        return 0;
    }

    s->tong = s->toan + s->ly + s->hoa;
    return 1;
}

/* --------------------------------------------------------------- */
/*  Main program                                                     */
/* --------------------------------------------------------------- */
int main(void)
{
    int n, i;
    if (scanf("%d", &n) != 1 || n <= 0) {
        fprintf(stderr, "Invalid number of students.\n");
        return EXIT_FAILURE;
    }

    /* Consume the rest of the line after the integer */
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF);

    Student *students = malloc(n * sizeof(Student));
    if (!students) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    /* Read each student */
    for (i = 0; i < n; ++i) {
        if (!read_student(&students[i])) {
            fprintf(stderr, "Error reading student %d.\n", i + 1);
            free(students);
            return EXIT_FAILURE;
        }
    }

    /* Find the best student among those with no score below 5 */
    int best_index = -1;
    for (i = 0; i < n; ++i) {
        if (students[i].toan < 5.0f ||
            students[i].ly   < 5.0f ||
            students[i].hoa  < 5.0f)
            continue;          /* Does not satisfy the condition */

        if (best_index == -1 ||
            students[i].tong > students[best_index].tong)
        {
            best_index = i;
        }
    }

    /* Output */
    if (best_index == -1) {
        printf("Không có sinh viên nào thỏa mãn điều kiện.\n");
    } else {
        Student *best = &students[best_index];
        printf("Sinh viên có tổng điểm cao nhất và không có môn nào dưới 5:\n");
        printf("Mã sinh viên: %s\n", best->masv);
        printf("Họ và tên   : %s\n", best->hoten);
        printf("Điểm Toán   : %.2f\n", best->toan);
        printf("Điểm Lý     : %.2f\n", best->ly);
        printf("Điểm Hóa    : %.2f\n", best->hoa);
        printf("Tổng điểm   : %.2f\n", best->tong);
    }

    free(students);
    return EXIT_SUCCESS;
}
