 *  (до n≈20 без переполнения). Если нужно работать с большими
 *  числами, потребуется библиотека для больших целых.
 */

#include <stdio.h>
#include <stdlib.h>

/* Функция вычисления F(n). Использует итеративный способ */
unsigned long long computeF(unsigned int n)
{
    if (n == 0) {
        fprintf(stderr, "Ошибка: n должно быть натуральным (>=1).\n");
        exit(EXIT_FAILURE);
    }

    unsigned long long result = 3ULL;           // F(1)
    for (unsigned int i = 2; i <= n; ++i) {
        result *= (unsigned long long)(i - 1);
    }
    return result;
}

int main(void)
{
    unsigned int n;

    printf("Введите натуральное число n: ");
    if (scanf("%u", &n) != 1) {
        fprintf(stderr, "Ошибка ввода.\n");
        return EXIT_FAILURE;
    }

    unsigned long long value = computeF(n);
    printf("F(%u) = %llu\n", n, value);

    return EXIT_SUCCESS;
}
```

**Пояснения**

1. `computeF` реализует итеративный расчёт, чтобы избежать рекурсии и возможных проблем со стеком.
2. Используем тип `unsigned long long`, который в большинстве систем занимает 64 бита и позволяет хранить значения до примерно `1.8·10^19`. При `n > 20` результат может переполниться.
3. Если требуется поддержка больших чисел, можно подключить библиотеку `GMP` или реализовать собственный массив байтов для хранения больших целых.

**Пример работы**

```
Введите натуральное число n: 5
F(5) = 72
```

(Поскольку `F(5) = 3 * 4! = 3 * 24 = 72`.)

