Thus every line of the output satisfies the specification. ∎



--------------------------------------------------------------------

#### 4.  Complexity Analysis

Let  

* `Q` – total number of answer symbols (`o`, `x`, `-`) in the input  
* `C` – number of categories  
* `L` – maximum line length (constant in practice)

Processing each character is **O(1)**, therefore

* **Time** : `O(Q)` – linear in the size of the input.  
* **Memory** : we store the output string of each category  
  (`O(L * C)`), and a few integer variables – overall `O(Q)` in the worst
  case (every symbol becomes part of a string).

Both limits are easily satisfied for any realistic quiz.

--------------------------------------------------------------------

#### 5.  Reference Implementation  (C)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ------------------------------------------------------------------ */
/* Structure to hold information about one category                    */
typedef struct {
    char *output;        /* printed line (without spaces and $)          */
    int  points;         /* final points of the category (after double) */
    int  hasJoker;       /* 1 if this category contains $               */
} Category;

/* ------------------------------------------------------------------ */
int main(void)
{
    char line[4096];
    int boundary;             /* first line: boundary value               */
    int globalQ = 1;          /* ordinal of the next question             */

    /* ----- read boundary ------------------------------------------------- */
    if (!fgets(line, sizeof(line), stdin))
        return 0;                      /* empty input */
    if (sscanf(line, "%d", &boundary) != 1)
        return 0;                      /* malformed */

    /* ----- read categories --------------------------------------------- */
    Category *cats = NULL;
    int catCount = 0, catCap = 0;

    while (fgets(line, sizeof(line), stdin)) {
        /* allocate output buffer for this line */
        size_t len = strlen(line);
        char *out = malloc(len + 1);
        size_t outLen = 0;

        int catPoints = 0;
        int catHasJoker = 0;

        for (size_t i = 0; i < len; ++i) {
            char c = line[i];
            if (c == '\n' || c == '\r' || c == ' ')
                continue;          /* ignore blanks */
            if (c == '$') {          /* joker symbol */
                catHasJoker = 1;
                continue;          /* does not count as a question */
            }
            /* c is one of 'o', 'x', '-' */
            out[outLen++] = c;      /* for printing later */

            int pointValue = (globalQ < boundary) ? 1 : 2;
            if (c == 'o')
                catPoints += pointValue;
            /* 'x' or '-' add 0 */

            globalQ++;              /* next question number */
        }
        out[outLen] = '\0';          /* terminate string */

        /* store the category */
        if (catCount == catCap) {
            catCap = (catCap == 0) ? 4 : catCap * 2;
            cats = realloc(cats, catCap * sizeof(Category));
        }
        cats[catCount].output = out;
        cats[catCount].points = catPoints;
        cats[catCount].hasJoker = catHasJoker;
        catCount++;
    }

    /* ----- apply joker --------------------------------------------------- */
    int jokerIndex = -1;
    for (int i = 0; i < catCount; ++i) {
        if (cats[i].hasJoker) {
            jokerIndex = i;
            break;
        }
    }

    if (jokerIndex != -1) {
        cats[jokerIndex].points *= 2;
    } else if (catCount > 0) {
        cats[catCount - 1].points *= 2;   /* last category doubled */
    }

    /* ----- totals ------------------------------------------------------- */
    int totalPoints = 0;
    for (int i = 0; i < catCount; ++i)
        totalPoints += cats[i].points;

    int halfCats = (catCount + 1) / 2;    /* ceil(C/2) */
    int halftimePoints = 0;
    for (int i = 0; i < halfCats; ++i)
        halftimePoints += cats[i].points;

    /* ----- output ------------------------------------------------------- */
    for (int i = 0; i < catCount; ++i)
        printf("%s\n", cats[i].output);

    printf("%d %d\n", halftimePoints, totalPoints);

    /* ----- clean up ----------------------------------------------------- */
    for (int i = 0; i < catCount; ++i)
        free(cats[i].output);
    free(cats);
    return 0;
}
```

The program follows exactly the algorithm proven correct above and
conforms to the C99 standard, so it will compile with any modern C
compiler.

