下面给出一个 **C 语言** 示例，演示如何用 **libwebsockets + libuv** 构建一个 WebSocket 客户端。  
代码采用 libwebsockets 0.3.x（支持 libuv）的 API，整体思路：

1. **准备事件循环** – 让 libwebsockets 直接把 I/O 事件交给 libuv。
2. **创建 `lws_context`** – 传入 `LWS_USE_LIBUV` 选项，让 libwebsockets 把文件描述符注册到 libuv。
3. **连接服务器** – 通过 `lws_client_connect_via_info()` 打开一个 WS 连接。
4. **实现回调** – 处理连接、接收、发送等事件。
5. **启动 libuv** – 调用 `uv_run()`，从此 libwebsockets 负责所有网络 I/O。

> **提示**：如果你只想做一个最简单的“发送一次、等待一次”客户端，完全可以把步骤 4 里的回调只实现 `LWS_CALLBACK_CLIENT_ESTABLISHED`、`LWS_CALLBACK_CLIENT_RECEIVE` 以及 `LWS_CALLBACK_CLIENT_WRITEABLE` 三种。

---

## 1. 环境准备

| 软件 | 版本 | 安装方式 |
|------|------|----------|
| libwebsockets | ≥ 0.3.x | `sudo apt-get install libwebsockets-dev`  <br>或 `brew install libwebsockets` |
| libuv | ≥ 1.0 | `sudo apt-get install libuv1-dev`  <br>或 `brew install libuv` |
| pkg-config | - | 预装在大多数 Linux/OS X 系统 |

> **重要**：要让 libwebsockets 能够使用 libuv，需要在编译时定义 `LWS_WITH_LIBUV` 或者在编译命令里加 `-DLWS_WITH_LIBUV`。  
> 如果你用的是官方发行版的 libwebsockets，默认已经开启了 libuv 支持。

---

## 2. 完整代码

> **文件名**：`ws_client.c`

```c
/*
 *  libwebsockets + libuv WebSocket client demo
 *
 *  Build (Ubuntu / macOS):
 *      gcc ws_client.c $(pkg-config --cflags --libs libwebsockets libuv) -o ws_client
 *
 *  Run:
 *      ./ws_client
 *
 *  说明：
 *    - 连接到 ws://echo.websocket.events（公开 echo 服务）
 *    - 连接建立后立即发送一句 "Hello, libwebsockets + libuv!"
 *    - 接收服务器回显后退出
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <libwebsockets.h>
#include <uv.h>

/* 你想要连接的服务器地址 */
static const char *host = "echo.websocket.events";
static int port = 80;        /* 80 = ws, 443 = wss */
static const char *path = "/";
static const char *protocols = "http,websocket";

/* 需要传给 libwebsockets 的协议描述数组 */
static struct lws_protocols proto_list[] = {
    /* 第一个元素是自定义协议，后面是 libwebsockets 内置协议 */
    {
        .name = "my-client-protocol",
        .callback = NULL,      /* 在后面手动填 */
        .per_session_data_size = 0,
        .rx_buffer_size = 0,
    },
    { NULL, NULL, 0, 0 } /* 必须以空元素结尾 */
};

/* 用于传递给回调的数据结构（这里用最小化的示例） */
struct per_session_data {
    int  finished;         /* 连接是否完成 */
    char msg[256];
};

/* 需要在回调里使用的全局变量（简化示例） */
static struct lws_context *context = NULL;
static int stop = 0;   /* 主循环结束标记 */

/* 信号处理：Ctrl+C 结束程序 */
static void signal_handler(int sig) {
    fprintf(stderr, "\nSignal %d received, shutting down...\n", sig);
    stop = 1;
}

/* ====================  回调函数 ==================== */
static int
callback_my_client(struct lws *wsi,
                   enum lws_callback_reasons reason,
                   void *user,
                   void *in, size_t len)
{
    struct per_session_data *ps = (struct per_session_data *)user;

    switch (reason) {

    case LWS_CALLBACK_CLIENT_ESTABLISHED:
        fprintf(stdout, "Connection established.\n");
        /* 发送一条消息 */
        snprintf(ps->msg, sizeof(ps->msg),
                 "Hello, libwebsockets + libuv! (%u)",
                 (unsigned)time(NULL));
        /* 立即标记为可写 */
        lws_callback_on_writable(wsi);
        break;

    case LWS_CALLBACK_CLIENT_RECEIVE:
        fprintf(stdout, "Received: %.*s\n", (int)len, (char *)in);
        /* 收到一次后结束 */
        stop = 1;
        break;

    case LWS_CALLBACK_CLIENT_WRITEABLE:
        /* 发送消息：lws_write 需要先加上 LWS_PRE 缓冲 */
        {
            size_t msg_len = strlen(ps->msg);
            unsigned char buf[LWS_PRE + msg_len];
            memcpy(&buf[LWS_PRE], ps->msg, msg_len);
            int n = lws_write(wsi, &buf[LWS_PRE], msg_len,
                              LWS_WRITE_TEXT);
            if (n < 0) {
                fprintf(stderr, "lws_write failed: %d\n", n);
                return -1;
            }
            fprintf(stdout, "Sent: %s\n", ps->msg);
        }
        break;

    case LWS_CALLBACK_CLIENT_CONNECTION_ERROR:
        fprintf(stderr, "Connection error.\n");
        stop = 1;
        break;

    case LWS_CALLBACK_CLOSED:
        fprintf(stderr, "Connection closed.\n");
        stop = 1;
        break;

    default:
        break;
    }
    return 0;
}

/* ====================  主程序 ==================== */
int main(int argc, char **argv)
{
    /* 1. 注册信号处理 */
    signal(SIGINT, signal_handler);

    /* 2. 填写 lws_context_creation_info */
    struct lws_context_creation_info info;
    memset(&info, 0, sizeof(info));

    /* libuv 事件循环 */
    uv_loop_t *uv_loop = uv_default_loop();

    info.port = CONTEXT_PORT_NO_LISTEN;          /* 作为客户端不监听端口 */
    info.iface = NULL;
    info.protocols = proto_list;
    info.extensions = NULL;
    info.ssl_ca_filepath = NULL;
    info.ssl_cert_filepath = NULL;
    info.ssl_private_key_filepath = NULL;
    info.gid = -1;
    info.uid = -1;
    info.options = LWS_SERVER_OPTION_EXPLICIT_VHOSTS | LWS_SERVER_OPTION_LIBUV;
    info.fd_limit_per_thread = 5000;
    info.max_http_headers = 15;
    info.max_http_header_pool = 10;
    info.ssl_cert_filepath = NULL;
    info.ssl_private_key_filepath = NULL;
    info.vhost_name = NULL;
    info.loop = uv_loop;            /* libwebsockets 用 libuv 的事件循环 */
    info.user = NULL;               /* 用户自定义数据（不需要） */

    /* 3. 创建上下文（此时会把所有 socket 注册到 libuv） */
    context = lws_create_context(&info);
    if (!context) {
        fprintf(stderr, "lws_create_context failed!\n");
        return EXIT_FAILURE;
    }

    /* 4. 连接服务器 */
    struct lws_client_connect_info ccinfo;
    memset(&ccinfo, 0, sizeof(ccinfo));
    ccinfo.context = context;
    ccinfo.address = host;
    ccinfo.port = port;
    ccinfo.path = path;
    ccinfo.host = host;
    ccinfo.origin = host;
    ccinfo.protocol = proto_list[0].name;
    ccinfo.ssl_connection = LWS_USE_SSL_NONE;   /* wss 需要 LWS_USE_SSL_WEBSOCKET */
    ccinfo.userdata = NULL;
    ccinfo.pwsi = NULL;        /* libwebsockets 会自动分配 */

    if (!lws_client_connect_via_info(&ccinfo)) {
        fprintf(stderr, "lws_client_connect_via_info failed!\n");
        lws_context_destroy(context);
        return EXIT_FAILURE;
    }

    /* 5. 进入 libuv 事件循环（libwebsockets 会把事件回调到你的回调中） */
    fprintf(stdout, "Starting libuv loop...\n");
    uv_run(uv_loop, UV_RUN_DEFAULT);

    /* 6. 清理 */
    lws_context_destroy(context);
    fprintf(stdout, "Client finished.\n");
    return EXIT_SUCCESS;
}
```

### 代码说明

| 行 | 作用 |
|----|------|
| `proto_list` | 定义自定义协议 `my-client-protocol`，它的回调在 `callback_my_client` 中实现。 |
| `struct per_session_data` | 每个连接会有一份 `per_session_data`，这里只用了一个字段。 |
| `callback_my_client` | 处理 WebSocket 生命周期事件：连接、写入、读取、关闭等。 |
| `lws_context_creation_info` | `options` 里加入 `LWS_SERVER_OPTION_LIBUV`，告诉 libwebsockets 用 libuv。 |
| `info.loop = uv_loop` | 把 libuv 的 `uv_loop_t` 传给 libwebsockets。 |
| `lws_client_connect_via_info` | 建立客户端连接。 |
| `uv_run` | 进入 libuv 主循环，libwebsockets 通过 libuv 的事件机制驱动。 |

> **注意**：如果你想使用 **wss**（加密 WebSocket），把 `port` 改成 `443` 并把 `ccinfo.ssl_connection = LWS_USE_SSL_WEBSOCKET;`。

---

## 3. 编译 & 运行

```bash
# 安装依赖（Ubuntu）
sudo apt-get update
sudo apt-get install libwebsockets-dev libuv1-dev pkg-config

# 编译
gcc ws_client.c $(pkg-config --cflags --libs libwebsockets libuv) -o ws_client

# 运行
./ws_client
```

**输出示例**

```
Starting libuv loop...
Connection established.
Sent: Hello, libwebsockets + libuv! (1706740013)
Received: Hello, libwebsockets + libuv! (1706740013)
Client finished.
