#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/* ------------------------------------------------------------------ */
/* ---------- 1) Naïve nested‑loops implementation (O(n²))  --------- */
/* ------------------------------------------------------------------ */
int count_repeats_naive(const int *a, int n)
{
    int repeats = 0;          /* number of *distinct* numbers that repeat */
    bool *seen = calloc(n, sizeof(bool));  /* tracks which positions were already counted */

    for (int i = 0; i < n; ++i) {
        if (seen[i]) continue;          /* already part of a repeated group */

        bool is_repeat = false;          /* does a[i] appear later? */

        for (int j = i + 1; j < n; ++j) {
            if (a[i] == a[j]) {
                is_repeat = true;
                seen[j] = true;           /* mark the duplicate so we don't double‑count it */
            }
        }
        if (is_repeat) ++repeats;        /* a[i] is a repeated value */
    }

    free(seen);
    return repeats;
}

/* ------------------------------------------------------------------ */
/* ---------- 2) Sorting + linear scan (O(n log n)) -------------- */
/* ------------------------------------------------------------------ */
/* Comparator for qsort */
int cmp_int(const void *p1, const void *p2)
{
    int v1 = *(const int *)p1;
    int v2 = *(const int *)p2;
    return (v1 > v2) - (v1 < v2);      /* simple numeric comparison */
}

int count_repeats_sorted(int *a, int n)
{
    if (n <= 1) return 0;

    /* Sort the array – O(n log n) */
    qsort(a, n, sizeof(int), cmp_int);

    int repeats = 0;          /* distinct repeated values */
    int i = 0;

    while (i < n) {
        int j = i + 1;
