```c
/*  udp_broadcast.c
 *
 *  Compilez :
 *        gcc -Wall -O2 -o udp_broadcast udp_broadcast.c
 *
 *  Utilisation :
 *        ./udp_broadcast "ma chaine"
 *
 *  Le programme fork deux processus : le premier envoie la chaîne,
 *  le second écoute et affiche la table d’expéditeurs toutes les 30 s.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/wait.h>

#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/select.h>

#define PORT           2346
#define BROADCAST_IP   "255.255.255.255"
#define BUF_SIZE       1024
#define MAX_TABLE      100          /* nombre d’expéditeurs à garder */

/* -------------------------------------- */
/*  Gestion d’un arrêt propre              */
static volatile sig_atomic_t stop = 0;
static void sigint_handler(int sig)
{
    (void)sig;
    stop = 1;
}
/* -------------------------------------- */

/*  Structure d’une entrée de la table  */
typedef struct {
    char ip[INET_ADDRSTRLEN];
    int  port;
} entry_t;

/*  ---------------------------------------------------------- */
/*  Processus émetteur : envoie la chaîne toutes les 1 s       */
static void run_sender(const char *msg)
{
    int sock;
    struct sockaddr_in dst;

    /* Création du socket UDP */
    if ((sock = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* Autoriser le broadcast */
    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_BROADCAST, &opt, sizeof(opt)) < 0) {
        perror("setsockopt SO_BROADCAST");
        close(sock);
        exit(EXIT_FAILURE);
    }

    /* Destination : 255.255.255.255 :2346 */
    memset(&dst, 0, sizeof(dst));
    dst.sin_family = AF_INET;
    dst.sin_port   = htons(PORT);
    if (inet_aton(BROADCAST_IP, &dst.sin_addr) == 0) {
        fprintf(stderr, "invalid broadcast IP\n");
        close(sock);
        exit(EXIT_FAILURE);
    }

    /* Boucle d’envoi */
    while (!stop) {
        ssize_t sent = sendto(sock, msg, strlen(msg), 0,
                              (struct sockaddr *)&dst, sizeof(dst));
        if (sent < 0) {
            perror("sendto");
            /* on ne quitte pas pour un échec ponctuel */
        }
        sleep(1);
    }

    close(sock);
    _exit(0);   /* fini proprement */
}

/*  ---------------------------------------------------------- */
/*  Processus récepteur + affichage                           */
static void run_receiver(const char *msg)
{
    int sock;
    struct sockaddr_in local_addr;

    /* Table d’expéditeurs */
    entry_t table[MAX_TABLE];
    size_t table_len = 0;

    /* Création du socket UDP */
    if ((sock = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* Bind sur 0.0.0.0:2346 */
    memset(&local_addr, 0, sizeof(local_addr));
    local_addr.sin_family = AF_INET;
    local_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    local_addr.sin_port = htons(PORT);

    if (bind(sock, (struct sockaddr *)&local_addr, sizeof(local_addr)) < 0) {
        perror("bind");
        close(sock);
        exit(EXIT_FAILURE);
    }

    /* On ne bloque pas sur recvfrom : on utilisera select() */
    int flags = fcntl(sock, F_GETFL, 0);
    fcntl(sock, F_SETFL, flags | O_NONBLOCK);

    /* Boucle principale */
    unsigned int sec_counter = 0;
    while (!stop) {
        fd_set rfds;
        struct timeval tv;

        FD_ZERO(&rfds);
        FD_SET(sock, &rfds);

        /* 1 seconde de timeout */
        tv.tv_sec  = 1;
        tv.tv_usec = 0;

        int rv = select(sock + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue; /* interruption d'un signal */
            perror("select");
            break;
        }

        if (rv > 0 && FD_ISSET(sock, &rfds)) {
            /* donnée disponible */
            char buf[BUF_SIZE];
            struct sockaddr_in from;
            socklen_t fromlen = sizeof(from);
            ssize_t n = recvfrom(sock, buf, sizeof(buf) - 1, 0,
                                 (struct sockaddr *)&from, &fromlen);
            if (n > 0) {
                buf[n] = '\0';
                if (strcmp(buf, msg) == 0) {
                    /* on stocke l'expéditeur */
                    if (table_len < MAX_TABLE) {
                        inet_ntop(AF_INET, &from.sin_addr,
                                  table[table_len].ip,
                                  sizeof(table[table_len].ip));
                        table[table_len].port = ntohs(from.sin_port);
                        ++table_len;
                    }
                }
            }
        }

        /* chaque seconde incrément */
        ++sec_counter;
        if (sec_counter % 30 == 0) {
            /* affichage de la table */
            printf("\n=== Tableau des expéditeurs (string : \"%s\") ===\n",
                   msg);
            for (size_t i = 0; i < table_len; ++i) {
                printf("%2zu : %s:%d\n", i + 1,
                       table[i].ip, table[i].port);
            }
            printf("=== Fin ===\n");
        }
    }

    close(sock);
    _exit(0);   /* fini proprement */
}

/*  ---------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage : %s <chaine a diffuser>\n", argv[0]);
        return EXIT_FAILURE;
    }

    /* Gestion d’interruption (Ctrl‑C) */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    pid_t pid_sender = fork();
    if (pid_sender < 0) {
        perror("fork");
        return EXIT_FAILURE;
    }

    if (pid_sender == 0) {   /* Processus fils – émetteur */
        run_sender(argv[1]);
    }

    /* Parent attend que le fils d’envoi soit créé avant de fork le récepteur */
    pid_t pid_receiver = fork();
    if (pid_receiver < 0) {
        perror("fork");
        kill(pid_sender, SIGTERM);
        return EXIT_FAILURE;
    }

    if (pid_receiver == 0) {   /* Processus fils – récepteur */
        run_receiver(argv[1]);
    }

    /* Le parent ne fait rien de plus ; il attend les deux enfants */
    int status;
    while ((waitpid(-1, &status, 0)) > 0)
        ;   /* rien */

    return EXIT_SUCCESS;
}
```

### Points clés de l’implémentation

| Élément | Pourquoi ? | Comment ? |
|--------|------------|------------|
| **`SO_BROADCAST`** | Nécessaire pour pouvoir envoyer sur `255.255.255.255`. | `setsockopt()` |
| **`select()`** | Permet de ne pas bloquer indéfiniment sur `recvfrom()` tout en ayant un temporisateur de 1 s. | Boucle `select()` avec timeout 1 s. |
| **Table d’expéditeurs** | Stockage simple d’adresse IP + port dans un tableau statique. | Structure `entry_t` + tableau `table`. |
| **Affichage toutes les 30 s** | Comptage de secondes via `sec_counter` (incrémenté après chaque `select()`). | Vérification `sec_counter % 30 == 0`. |
| **Gestion des signaux** | Pour quitter proprement en cas de `Ctrl‑C`. | `sigaction(SIGINT, …)` et variable `volatile sig_atomic_t stop`. |
| **Fork de deux processus** | Le processus père ne fait rien ; il attend les deux enfants. | Deux `fork()` distincts. |

### Compilation & exécution

```bash
$ gcc -Wall -O2 -o udp_broadcast udp_broadcast.c
$ ./udp_broadcast "Mon message"
```

Le programme continuera à fonctionner jusqu’à ce que vous l’interrompiez (Ctrl‑C).  
Vous devriez voir, toutes les 30 s, la liste des adresses IP et ports ayant envoyé exactement le même message.

