    int cnt = 0;
    while (cnt < MAX_STUDENTS && fscanf(fp, "%d %19s %d",
                                         &s[cnt].stnr,
                                         s[cnt].name,
                                         &s[cnt].grade) == 3)
    {
        cnt++;
    }

    fclose(fp);
    return cnt;
}

/*--------------------------------------------------------------------
 *  Function:  binary_search
 *  Purpose:   Binary search of a sorted array of StudInfo.
 *  Returns:   Index of the found element or -1 if not found.
 *--------------------------------------------------------------------*/
int binary_search(const StudInfo s[], int n, int target)
{
    int left  = 0;
    int right = n - 1;

    while (left <= right)
    {
        int mid = left + (right - left) / 2;

        if (s[mid].stnr == target)
            return mid;                 /* found */
        else if (s[mid].stnr < target)
            left = mid + 1;              /* search right half */
        else
            right = mid - 1;             /* search left half */
    }
    return -1;                           /* not found */
}

/*--------------------------------------------------------------------
 *  Main function
 *--------------------------------------------------------------------*/
int main(void)
{
    StudInfo students[MAX_STUDENTS];
    int count = read_students("C:\\cmpe231\\2009Spring\\student.txt",
                              students);

    if (count == 0)
    {
        fprintf(stderr, "No student data available.\n");
        return EXIT_FAILURE;
    }

    /* 1‑based position will be reported to the user. */
    int target;
    printf("Enter student number to search: ");
    if (scanf("%d", &target) != 1)
    {
        fprintf(stderr, "Invalid input.\n");
        return EXIT_FAILURE;
    }

    int idx = binary_search(students, count, target);

    if (idx >= 0)
    {
        printf("\nStudent found!\n");
        printf("Name   : %s\n", students[idx].name);
        printf("Grade  : %d\n", students[idx].grade);
        printf("Array position: %d\n", idx + 1);   /* 1‑based */
    }
    else
    {
        printf("\nStudent number %d not found.\n", target);
    }

    return EXIT_SUCCESS;
}
```

---

### How the program works

| Step | Action |
|------|--------|
| **1** | `read_students()` opens the file and reads up to 10 lines. The line format must be `int string int` (e.g., `123 Ahmet 88`). The array is guaranteed to be sorted by `stnr`. |
| **2** | The user is prompted for the student number (`stnr`). |
| **3** | `binary_search()` performs a classic binary search on the sorted array. Because the array is sorted, the search is `O(log n)` (log₂ 10 ≈ 4). |
| **4** | If the student number is found, the program prints the name, grade and the array position (index + 1). If not found, a message is displayed. |

---

### Sample data file (`student.txt`)

```
123 Ahmet     88
456 Cemal     99
633 Sevgi     75
776 Meral     66
792 Kemal     88
845 Hakan     91
876 Arif      73
823 Yigit     84
8879 Meral    81
9999 Ali      90
```

*Note*: The numbers are strictly increasing, so the array is sorted and binary search will work correctly.

---

### Compiling & Running

```bash
gcc -std=c11 -Wall -o binary_search binary_search.c
./binary_search
```

Enter a student number when prompted, e.g.:

```
Enter student number to search: 776
```

The output will be:

```
Student found!
Name   : Meral
Grade  : 66
Array position: 4
```

Feel free to adjust the file path, number of records, or field widths as needed.

