```java
// common/MessageType.java
public enum MessageType {
    TEXT(1),
    IMAGE(2),
    FILE(3),
    REFUSE(4),
    BUSY(5);

    private final int code;
    MessageType(int code) { this.code = code; }
    public int getCode() { return code; }

    public static MessageType fromCode(int code) {
        for (MessageType mt : values())
            if (mt.code == code) return mt;
        return null;
    }
}

// common/ChatUtils.java
public class ChatUtils {
    /** 读写字符串，先写/读长度+字节 */
    public static void writeString(DataOutputStream out, String s) throws IOException {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        out.writeInt(bytes.length);
        out.write(bytes);
    }

    public static String readString(DataInputStream in) throws IOException {
        int len = in.readInt();
        byte[] bytes = new byte[len];
        in.readFully(bytes);
        return new String(bytes, StandardCharsets.UTF_8);
    }

    /** 写入文件（图片、普通文件） */
    public static void sendFile(DataOutputStream out, File f, MessageType type) throws IOException {
        writeString(out, type.name());                 // 标记类型
        writeString(out, f.getName());                 // 文件名
        out.writeLong(f.length());                     // 文件大小
        try (FileInputStream fis = new FileInputStream(f)) {
            byte[] buffer = new byte[8192];
            int n;
            while ((n = fis.read(buffer)) != -1) {
                out.write(buffer, 0, n);
            }
        }
        out.flush();
    }

    /** 接收文件 */
    public static void receiveFile(DataInputStream in, File targetDir) throws IOException {
        String fileName = readString(in);
        long fileSize = in.readLong();
        File outFile = new File(targetDir, fileName);
        try (FileOutputStream fos = new FileOutputStream(outFile)) {
            byte[] buffer = new byte[8192];
            long received = 0;
            int n;
            while (received < fileSize && (n = in.read(buffer, 0,
                    (int)Math.min(buffer.length, fileSize - received))) != -1) {
                fos.write(buffer, 0, n);
                received += n;
            }
        }
        System.out.println("Saved file: " + outFile.getAbsolutePath());
    }
}
```

