### 3.2 `ClientHandler`

```java
// server/ClientHandler.java
package server;

import common.*;

import java.awt.image.BufferedImage;
import java.io.*;
import java.net.Socket;
import java.text.SimpleDateFormat;
import java.util.Date;
import javax.imageio.ImageIO;
import javax.swing.*;

public class ClientHandler implements Runnable {

    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private String userName;          // 客户端登录名
    private File logFile;             // 聊天记录文件

    // 线程安全写日志（简单同步即可）
    private final Object logLock = new Object();

    public ClientHandler(Socket socket) throws IOException {
        this.socket = socket;
        in  = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
        out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));
    }

    @Override
    public void run() {
        try {
            // 第一条消息：客户端发送用户名
            userName = ChatUtils.readString(in);
            System.out.println("User [" + userName + "] connected.");

            // 打开日志文件（按用户名）
            logFile = new File("logs" + File.separator + userName + ".txt");
            if (!logFile.exists()) logFile.getParentFile().mkdirs();
            // 写入打开日志
            log("[SERVER] " + userName + " started chat.");

            // 通知管理员（这里直接打印到控制台，可改为 GUI）
            System.out.println("⚡️ New user waiting: " + userName);

            // 业务循环
            while (true) {
                // 读取协议头
                int typeCode = in.readInt();
                MessageType type = MessageType.fromCode(typeCode);
                if (type == null) throw new IOException("Unknown message type");

                switch (type) {
                    case TEXT:
                        handleText();
                        break;
                    case IMAGE:
                        handleImage();
                        break;
                    case FILE:
                        handleFile();
                        break;
                    default:
                        throw new IOException("Unsupported type " + type);
                }
            }
        } catch (IOException e) {
            System.out.println("Connection closed for user: " + userName);
        } finally {
            try { socket.close(); } catch (Exception ignored) {}
        }
    }

    /* ---------- 处理各类型 ---------- */
    private void handleText() throws IOException {
        String msg = ChatUtils.readString(in);
        log("[CLIENT] " + msg);
        // 对话框展示（这里简单回显，实际业务可弹窗/GUI）
        System.out.println(userName + ": " + msg);
        // 你可以在这里做自动回复，或者把消息写入日志等
    }

    private void handleImage() throws IOException {
        String fileName = ChatUtils.readString(in); // 这里直接把图片保存为临时文件
        long fileSize = in.readLong();

        File temp = new File("tmp" + File.separator + fileName);
        temp.getParentFile().mkdirs();
        try (FileOutputStream fos = new FileOutputStream(temp)) {
            byte[] buffer = new byte[8192];
            long received = 0;
            int n;
            while (received < fileSize && (n = in.read(buffer, 0,
                    (int)Math.min(buffer.length, fileSize - received))) != -1) {
                fos.write(buffer, 0, n);
                received += n;
            }
        }
        // 记录日志
        log("[CLIENT] sent image: " + fileName);
        // 这里可以把图片显示出来，或者转发给客服端
    }

    private void handleFile() throws IOException {
        // 文件名、大小已经在 sendFile 里写过，直接接收
        ChatUtils.receiveFile(in, new File("received_files" + File.separator + userName));
        log("[CLIENT] sent file");
    }

    /* ---------- 日志 ---------- */
    private void log(String msg) {
        synchronized (logLock) {
            try (PrintWriter pw = new PrintWriter(new FileWriter(logFile, true))) {
                String time = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date());
                pw.println(time + " " + msg);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /* ---------- 发送给客服端 ---------- */
    public void sendMessage(String txt) throws IOException {
        out.writeInt(MessageType.TEXT.getCode());
        ChatUtils.writeString(out, txt);
        out.flush();
        log("[SERVER] " + txt);
    }

    // 发送文件
    public void sendFile(File f) throws IOException {
        ChatUtils.sendFile(out, f, MessageType.FILE);
        log("[SERVER] sent file: " + f.getName());
    }

    // 发送图片
    public void sendImage(BufferedImage img, String fileName) throws IOException {
        // 把 BufferedImage 写到 ByteArrayOutputStream
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageIO.write(img, "jpg", baos);
        byte[] bytes = baos.toByteArray();

        out.writeInt(MessageType.IMAGE.getCode());
        ChatUtils.writeString(out, fileName);
        out.writeLong(bytes.length);
        out.write(bytes);
        out.flush();

        log("[SERVER] sent image: " + fileName);
    }
}
```

> **提示**：  
> 1. 上面 `ClientHandler` 只负责单个用户的读写。若要实现“客服端可选服务/拒绝”，需要把 `ClientHandler` 交给 **客服窗口** 控制，或者在 `run()` 里先发送 `BUSY`，客服端决定是否继续。  
> 2. 你可以把 `ClientHandler` 的 `sendMessage`、`sendFile` 等方法封装到一个 `CustomerServiceUI` 中，让 UI 能主动给对应用户发送消息。  

