## 4. 客户端实现（Swing）

### 4.1 UI 基本结构

```java
// client/ClientGUI.java
package client;

import common.*;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;
import java.nio.file.Files;
import java.util.concurrent.*;

public class ClientGUI extends JFrame {
    private JTextArea chatArea;
    private JTextField inputField;
    private JButton sendBtn, imgBtn, fileBtn;
    private String userName;
    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;

    // 用于定时检查服务端是否回应
    private ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
    private volatile long lastServerMsg = System.currentTimeMillis();

    public ClientGUI(String userName) {
        this.userName = userName;
        initUI();
        connectToServer();
        startServerListener();
    }

    private void initUI() {
        setTitle("电商客服 - " + userName);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(600, 500);
        setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        inputField = new JTextField();
        sendBtn = new JButton("发送");
        imgBtn = new JButton("图片");
        fileBtn = new JButton("文件");

        bottom.add(inputField, BorderLayout.CENTER);
        JPanel btns = new JPanel();
        btns.add(imgBtn); btns.add(fileBtn); btns.add(sendBtn);
        bottom.add(btns, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        // 事件
        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());

        imgBtn.addActionListener(e -> sendImage());
        fileBtn.addActionListener(e -> sendFile());

        // 异常捕捉
        addWindowListener(new WindowAdapter() {
            public void windowClosing(WindowEvent e) {
                try { socket.close(); } catch (Exception ignored) {}
                scheduler.shutdownNow();
            }
        });

        setVisible(true);
    }

    private void connectToServer() {
        try {
            socket = new Socket("127.0.0.1", 12345);
            in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
            out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));

            // 发送用户名
            ChatUtils.writeString(out, userName);
            out.flush();

            log("[SYSTEM] 已连接服务器。");
        } catch (IOException e) {
            showError("连接失败: " + e.getMessage());
        }
    }

    /* ---------- 发送文本 ---------- */
    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            out.writeInt(MessageType.TEXT.getCode());
            ChatUtils.writeString(out, txt);
            out.flush();
            appendToChat("我: " + txt);
            inputField.setText("");
        } catch (IOException e) {
            showError("发送失败: " + e.getMessage());
        }
    }

    /* ---------- 发送图片 ---------- */
    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("图片", "jpg","jpeg","png","bmp"));
        if (fc.showOpenDialog(this) != JFileChooser.APPROVE_OPTION) return;
        File imgFile = fc.getSelectedFile();
        try {
            BufferedImage img = ImageIO.read(imgFile);
            // 先把图片写成字节数组
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ImageIO.write(img, "jpg", baos);
            byte[] imgBytes = baos.toByteArray();

            out.writeInt(MessageType.IMAGE.getCode());
            ChatUtils.writeString(out, imgFile.getName());
            out.writeLong(imgBytes.length);
            out.write(imgBytes);
            out.flush();

            appendToChat("[我] 发送图片: " + imgFile.getName());
        } catch (IOException ex) {
            showError("图片发送失败: " + ex.getMessage());
        }
    }

    /* ---------- 发送文件 ---------- */
    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) != JFileChooser.APPROVE_OPTION) return;
        File file = fc.getSelectedFile();
        try {
            ChatUtils.sendFile(out, file, MessageType.FILE);
            out.flush();
            appendToChat("[我] 发送文件: " + file.getName());
        } catch (IOException e) {
            showError("文件发送失败: " + e.getMessage());
        }
    }

    /* ---------- 接收服务器消息 ---------- */
    private void startServerListener() {
        new Thread(() -> {
            try {
                while (true) {
                    int typeCode = in.readInt();
                    lastServerMsg = System.currentTimeMillis(); // 收到消息，重置计时

                    MessageType type = MessageType.fromCode(typeCode);
                    switch (type) {
                        case TEXT:
                            String msg = ChatUtils.readString(in);
                            appendToChat("[客服] " + msg);
                            break;
                        case IMAGE:
                            receiveAndShowImage();
                            break;
                        case FILE:
                            receiveAndSaveFile();
                            break;
                        case BUSY:
                            showBusy();
                            break;
                        default:
                            System.out.println("未知类型: " + typeCode);
                    }
                }
            } catch (IOException e) {
                showError("连接异常: " + e.getMessage());
            }
        }).start();

        // 开启“忙提示”定时检查
        scheduler.scheduleAtFixedRate(() -> {
            if (System.currentTimeMillis() - lastServerMsg > 30000) {
                SwingUtilities.invokeLater(() -> showBusy());
            }
        }, 1, 1, TimeUnit.SECONDS);
    }

    /* ---------- 接收图片 ---------- */
    private void receiveAndShowImage() throws IOException {
        String fileName = ChatUtils.readString(in);
        long size = in.readLong();
        byte[] bytes = new byte[(int)size];
        in.readFully(bytes);
        BufferedImage img = ImageIO.read(new ByteArrayInputStream(bytes));
        ImageIcon icon = new ImageIcon(img);
        chatArea.append("[客服] 发送图片: " + fileName + "\n");
        chatArea.setIcon(icon); // 简单演示，实际可弹窗
    }

    /* ---------- 接收文件 ---------- */
    private void receiveAndSaveFile() throws IOException {
        ChatUtils.receiveFile(in, new File("downloads" + File.separator + userName));
        appendToChat("[客服] 已收到文件。");
    }

    /* ---------- 工具 ---------- */
    private void appendToChat(String msg) {
        SwingUtilities.invokeLater(() -> chatArea.append(msg + "\n"));
    }

    private void showError(String msg) {
        SwingUtilities.invokeLater(() ->
                JOptionPane.showMessageDialog(this, msg, "错误", JOptionPane.ERROR_MESSAGE));
    }

    private void showBusy() {
        JOptionPane.showMessageDialog(this, "客服繁忙，请稍后再试！", "提示", JOptionPane.WARNING_MESSAGE);
    }

    public static void main(String[] args) {
        String name = JOptionPane.showInputDialog("请输入用户名：");
        if (name == null || name.trim().isEmpty()) return;
        SwingUtilities.invokeLater(() -> new ClientGUI(name.trim()));
    }
}
```

> **说明**  
> - `lastServerMsg` 用来记录最后一次收到服务器消息的时间，**如果 30 秒内没有收到任何消息就弹窗提示客服繁忙**。  
> - `startServerListener()` 在一个后台线程里读数据；UI 更新必须通过 `SwingUtilities.invokeLater()`。  
> - 对图片和文件的接收与存储与服务端保持一致，保存路径为 `downloads/<userName>/`。  

