## 2. 服务器端实现

### 2.1 ChatServer（核心业务）

```java
package server;

import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.*;

public class ChatServer {

    // 服务器监听端口
    private final int port;
    // 最大并发客服人数
    private final int MAX_ACTIVE = 5;
    // 当前活动会话计数
    private final AtomicInteger activeCount = new AtomicInteger(0);
    // 客户端连接线程池
    private final ExecutorService pool = new ThreadPoolExecutor(
            10, 20, 60L, TimeUnit.SECONDS, new LinkedBlockingQueue<>());
    // 记录已连接的所有客服
    private final List<ClientHandler> clients = new CopyOnWriteArrayList<>();

    public ChatServer(int port) {
        this.port = port;
    }

    public void start() throws IOException {
        try (ServerSocket ss = new ServerSocket(port)) {
            System.out.println("Server started, listening on " + port);
            while (true) {
                Socket clientSocket = ss.accept();
                System.out.println("New client connected from " + clientSocket.getRemoteSocketAddress());

                // 判断是否已满
                if (activeCount.get() >= MAX_ACTIVE) {
                    // 直接发送 BUSY 消息
                    Protocol.sendBusy(clientSocket);
                    clientSocket.close();
                    continue;
                }

                // 创建处理线程
                ClientHandler handler = new ClientHandler(clientSocket, this);
                activeCount.incrementAndGet();
                clients.add(handler);
                pool.execute(handler);
            }
        }
    }

    // 关闭某个客服
    void removeHandler(ClientHandler handler) {
        clients.remove(handler);
        activeCount.decrementAndGet();
    }

    public static void main(String[] args) throws IOException {
        new ChatServer(9000).start();
    }
}
```

