    public ClientHandler(Socket socket, ChatServer server) {
        this.socket = socket;
        this.server = server;
        // 以 socket 远程地址命名文件，保证唯一
        String userId = UUID.randomUUID().toString();
        this.recordFile = Paths.get("chat_records", userId + ".txt");
        try {
            Files.createDirectories(recordFile.getParent());
            Files.createFile(recordFile);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void run() {
        try {
            in = new BufferedInputStream(socket.getInputStream());
            out = new BufferedOutputStream(socket.getOutputStream());

            while (true) {
                Map<String, Object> msg = Protocol.readMessage(in);
                if (msg == null) break; // 连接关闭

                String type = (String) msg.get("type");
                switch (type) {
                    case "TEXT":
                        handleText(msg);
                        break;
                    case "IMAGE":
                        handleImage(msg);
                        break;
                    case "FILE":
                        handleFile(msg);
                        break;
                    default:
                        System.err.println("Unknown type: " + type);
                }
            }
        } catch (IOException e) {
            System.err.println("Client disconnected: " + e.getMessage());
        } finally {
            cleanup();
        }
    }

    private void handleText(Map<String, Object> msg) throws IOException {
        String content = (String) msg.get("content");
        System.out.println("Text from client: " + content);
        // 记录到文件
        Files.write(recordFile, ("[Client] " + content + System.lineSeparator()).getBytes(),
                StandardOpenOption.APPEND);
        // 这里可以把消息推送给客服端 UI
    }

    private void handleImage(Map<String, Object> msg) throws IOException {
        long size = Long.parseLong(msg.get("size").toString());
        String filename = (String) msg.get("filename");
        Path imgPath = Paths.get("images", filename);
        Files.createDirectories(imgPath.getParent());
        Files.copy(in, imgPath, StandardCopyOption.REPLACE_EXISTING);
        System.out.println("Image received: " + imgPath);
        // 记录路径
        Files.write(recordFile, ("[Image] " + imgPath + System.lineSeparator()).getBytes(),
                StandardOpenOption.APPEND);
    }

    private void handleFile(Map<String, Object> msg) throws IOException {
        long size = Long.parseLong(msg.get("size").toString());
        String filename = (String) msg.get("filename");
        Path filePath = Paths.get("files", filename);
        Files.createDirectories(filePath.getParent());
        Files.copy(in, filePath, StandardCopyOption.REPLACE_EXISTING);
        System.out.println("File received: " + filePath);
        Files.write(recordFile, ("[File] " + filePath + System.lineSeparator()).getBytes(),
                StandardOpenOption.APPEND);
    }

    private void cleanup() {
        try {
            in.close();
        } catch (IOException ignored) {}
        try {
            out.close();
        } catch (IOException ignored) {}
        try {
            socket.close();
        } catch (IOException ignored) {}
        server.removeHandler(this);
    }
}
```

### 2.3 Protocol（消息读写）

```java
package server;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.Map;

public class Protocol {
    private static final ObjectMapper mapper = new ObjectMapper();

    public static Map<String,Object> readMessage(InputStream in) throws IOException {
        // 先读 4 字节长度
        byte[] lenBuf = new byte[4];
        if (in.read(lenBuf) != 4) return null;
        int len = ByteBuffer.wrap(lenBuf).getInt();
        byte[] jsonBuf = new byte[len];
        int read = 0;
        while (read < len) {
            int r = in.read(jsonBuf, read, len - read);
            if (r == -1) return null;
            read += r;
        }
        String json = new String(jsonBuf);
        return mapper.readValue(json, Map.class);
    }

    public static void sendBusy(Socket s) throws IOException {
        Map<String,Object> busy = Map.of("type","BUSY","content","客服已满，请稍后再试");
        sendMessage(s.getOutputStream(), busy);
    }

    public static void sendMessage(OutputStream out, Map<String,Object> msg) throws IOException {
        byte[] json = mapper.writeValueAsBytes(msg);
        out.write(ByteBuffer.allocate(4).putInt(json.length).array());
        out.write(json);
        out.flush();
    }
}
```

> **说明**  
> - 服务器不需要 UI，所有聊天记录直接写文件。  
> - 若需要把聊天内容推送到客服端 UI，可在 `ClientHandler` 内部维护一个事件监听器（Observer），客服端通过 `ClientHandler` 监听消息。  

