### 3.3 ClientConnection（后台网络线程）

```java
package client;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.awt.image.BufferedImage;
import java.io.*;
import java.net.Socket;
import java.nio.ByteBuffer;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;

public class ClientConnection {

    private final String host;
    private final int port;
    private final ClientGUI gui;
    private Socket socket;
    private BufferedOutputStream out;
    private BufferedInputStream in;
    private volatile boolean running = true;
    private Thread recvThread;

    private static final ObjectMapper mapper = new ObjectMapper();

    public ClientConnection(String host, int port, ClientGUI gui) {
        this.host = host;
        this.port = port;
        this.gui = gui;
    }

    public void start() throws IOException {
        socket = new Socket(host, port);
        out = new BufferedOutputStream(socket.getOutputStream());
        in = new BufferedInputStream(socket.getInputStream());
        recvThread = new Thread(this::receiveLoop);
        recvThread.start();
    }

    // 发送文本
    public void sendText(String text) throws IOException {
        Map<String,Object> msg = Map.of("type","TEXT","content",text);
        sendMessage(msg);
    }

    // 发送文件
    public void sendFile(File file) throws IOException {
        Map<String,Object> msg = Map.of(
                "type","FILE",
                "filename", file.getName(),
                "size", file.length()
        );
        sendMessage(msg);
        Files.copy(file.toPath(), out);
        out.flush();
    }

    // 发送图片
    public void sendImage(File img) throws IOException {
        Map<String,Object> msg = Map.of(
                "type","IMAGE",
                "filename", img.getName(),
                "size", img.length()
        );
        sendMessage(msg);
        Files.copy(img.toPath(), out);
        out.flush();
    }

    private void sendMessage(Map<String,Object> msg) throws IOException {
        byte[] json = mapper.writeValueAsBytes(msg);
        out.write(ByteBuffer.allocate(4).putInt(json.length).array());
        out.write(json);
        out.flush();
    }

    // 接收线程
    private void receiveLoop() {
        try {
            while (running) {
                Map<String,Object> msg = readMessage(in);
                if (msg == null) break;
                String type = (String)msg.get("type");
                switch (type) {
                    case "TEXT":
                        gui.appendChat("[客服] " + msg.get("content"));
                        break;
                    case "IMAGE":
                        handleRecvImage(msg);
                        break;
                    case "FILE":
                        handleRecvFile(msg);
                        break;
                    case "BUSY":
                        gui.showError((String)msg.get("content"));
                        break;
                    default:
                        System.err.println("Unknown msg type: " + type);
                }
            }
        } catch (IOException e) {
            if (running) gui.showError("连接异常：" + e.getMessage());
        } finally {
            close();
        }
    }

    private void handleRecvImage(Map<String,Object> msg) throws IOException {
        long size = Long.parseLong(msg.get("size").toString());
        String filename = (String)msg.get("filename");
        Path imgPath = Paths.get("recv_images", filename);
        Files.createDirectories(imgPath.getParent());
        Files.copy(in, imgPath, StandardCopyOption.REPLACE_EXISTING);
        gui.appendChat("[客服] 发送图片：" + imgPath);
        // 预览
        BufferedImage bi = ImageIO.read(imgPath.toFile());
        ImageIcon icon = new ImageIcon(bi.getScaledInstance(200,-1,Image.SCALE_SMOOTH));
        gui.appendChat("\n" + icon + "\n");
    }

    private void handleRecvFile(Map<String,Object> msg) throws IOException {
        long size = Long.parseLong(msg.get("size").toString());
        String filename = (String)msg.get("filename");
        Path filePath = Paths.get("recv_files", filename);
        Files.createDirectories(filePath.getParent());
        Files.copy(in, filePath, StandardCopyOption.REPLACE_EXISTING);
        gui.appendChat("[客服] 发送文件：" + filePath);
    }

    private Map<String,Object> readMessage(InputStream in) throws IOException {
        byte[] lenBuf = new byte[4];
        if (in.read(lenBuf) != 4) return null;
        int len = ByteBuffer.wrap(lenBuf).getInt();
        byte[] jsonBuf = new byte[len];
        int read = 0;
        while (read < len) {
            int r = in.read(jsonBuf, read, len - read);
            if (r == -1) return null;
            read += r;
        }
        return mapper.readValue(jsonBuf, Map.class);
    }

    public void close() {
        running = false;
        try { in.close(); } catch (IOException ignored) {}
        try { out.close(); } catch (IOException ignored) {}
        try { socket.close(); } catch (IOException ignored) {}
    }
}
```

