// com.example.jwt.service.SessionService
package com.example.jwt.service;

import com.example.jwt.model.Session;
import com.example.jwt.model.User;
import com.example.jwt.repository.SessionRepository;
import com.example.jwt.repository.UserRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Service;
import org.springframework.security.core.userdetails.UsernameNotFoundException;

import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

/**
 * Handles session creation, validation, revocation and user loading by id.
 */
@Service
public class SessionService {

    @Autowired
    private SessionRepository sessionRepository;

    @Autowired
    private UserRepository userRepository;

    /**
     * Create a new session record and return its id.
     */
    public String createSession(String userId) {
        String sessionId = UUID.randomUUID().toString();
        Session session = Session.builder()
                .id(sessionId)
                .userId(userId)
                .createdAt(Instant.now())
                .expiresAt(null) // could be set based on config
                .active(true)
                .build();
        sessionRepository.save(session);
        return sessionId;
    }

    /**
     * Checks if session id corresponds to an active session.
     */
    public boolean isSessionActive(String sessionId) {
        Optional<Session> opt = sessionRepository.findByIdAndActiveTrue(sessionId);
        return opt.isPresent();
    }

    /**
     * Marks session as inactive (logout).
     */
    public void invalidateSession(String sessionId) {
        sessionRepository.findByIdAndActiveTrue(sessionId)
                .ifPresent(session -> {
                    session.setActive(false);
                    sessionRepository.save(session);
                });
    }

    /**
     * Loads UserDetails by userId stored in session.
     */
    public UserDetails loadUserById(String userId) {
        User user = userRepository.findById(userId)
                .orElseThrow(() -> new UsernameNotFoundException("User not found"));
        return new UserDetailsImpl(user);
    }
}
