// com.example.jwt.controller.AuthController
package com.example.jwt.controller;

import com.example.jwt.config.JwtTokenProvider;
import com.example.jwt.payload.AuthRequest;
import com.example.jwt.payload.AuthResponse;
import com.example.jwt.service.SessionService;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.AuthenticationException;
import org.springframework.web.bind.annotation.*;

import java.util.UUID;

/**
 * Handles login, logout and token refresh.
 */
@RestController
@RequestMapping("/auth")
public class AuthController {

    private final AuthenticationManager authManager;
    private final JwtTokenProvider tokenProvider;
    private final SessionService sessionService;

    public AuthController(AuthenticationManager authManager,
                          JwtTokenProvider tokenProvider,
                          SessionService sessionService) {
        this.authManager = authManager;
        this.tokenProvider = tokenProvider;
        this.sessionService = sessionService;
    }

    @PostMapping("/login")
    public AuthResponse login(@RequestBody AuthRequest request) {
        try {
            Authentication auth = authManager.authenticate(
                    new UsernamePasswordAuthenticationToken(
                            request.getUsername(), request.getPassword()));
            UserDetailsImpl userDetails = (UserDetailsImpl) auth.getPrincipal();

            String sessionId = sessionService.createSession(userDetails.getUserId());
            String token = tokenProvider.createToken(userDetails.getUserId(), sessionId);

            return new AuthResponse(token);
        } catch (AuthenticationException ex) {
            throw new RuntimeException("Invalid username/password");
        }
    }

    @PostMapping("/logout")
    public void logout(@RequestHeader("Authorization") String authHeader) {
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String token = authHeader.substring(7);
            String sessionId = tokenProvider.getSessionIdFromToken(token);
            sessionService.invalidateSession(sessionId);
        }
    }

    @PostMapping("/refresh")
    public AuthResponse refresh(@RequestHeader("Authorization") String authHeader) {
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String oldToken = authHeader.substring(7);
            if (!tokenProvider.validateToken(oldToken)) {
                throw new RuntimeException("Token not valid");
            }
            // Invalidate old session
            String oldSessionId = tokenProvider.getSessionIdFromToken(oldToken);
            sessionService.invalidateSession(oldSessionId);

            // Create new session & token
            String userId = tokenProvider.getUserIdFromToken(oldToken);
            String newSessionId = sessionService.createSession(userId);
            String newToken = tokenProvider.createToken(userId, newSessionId);
            return new AuthResponse(newToken);
        }
        throw new RuntimeException("Missing token");
    }
}
