    private String fileName;    // 对于 IMAGE / FILE
    private byte[] data;        // 文本或文件原始字节

    public Message(Type type, String sender, String fileName, byte[] data) {
        this.type = type;
        this.sender = sender;
        this.fileName = fileName;
        this.data = data;
    }

    // 下面的 getters / setters 可省略，直接使用 public 字段
}
