// Utils.java
import java.io.*;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.util.Date;

public class Utils {
    public static final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    /** 写入聊天记录 */
    public static synchronized void appendRecord(String user, String sender, Message.Type type, String content) throws IOException {
        String log = String.format("%s | %s | %s | %s\n", sdf.format(new Date()), sender, type, content);
        Files.write(Paths.get(user + ".txt"), log.getBytes(), StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    /** 读取聊天记录 */
    public static synchronized String readRecord(String user) throws IOException {
        Path p = Paths.get(user + ".txt");
        if (!Files.exists(p)) return "";
        return new String(Files.readAllBytes(p));
    }
}
