```java
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class Server {
    private static final int PORT = 12345;
    // 维护正在服务的用户名集合
    private static final Set<String> activeUsers = ConcurrentHashMap.newKeySet();
    // 连接到服务器的线程池
    private static final ExecutorService pool = Executors.newCachedThreadPool();
    // 用来阻塞服务器控制台等待管理员输入
    private static final BlockingQueue<Socket> newClients = new LinkedBlockingQueue<>();

    public static void main(String[] args) throws IOException {
        ServerSocket ss = new ServerSocket(PORT);
        System.out.println("客服服务器已启动，监听端口 " + PORT);

        // 线程：负责接收新连接
        new Thread(() -> {
            try {
                while (true) {
                    Socket s = ss.accept();
                    newClients.offer(s);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();

        // 主线程：处理管理员指令
        Scanner console = new Scanner(System.in);
        while (true) {
            Socket s = newClients.poll();
            if (s == null) {
                // 没有新的客户端等待，暂停一下
                Thread.sleep(200);
                continue;
            }

            // 读取客户端发来的用户名
            DataInputStream dis = new DataInputStream(s.getInputStream());
            DataOutputStream dos = new DataOutputStream(s.getOutputStream());
            String user = dis.readUTF();
            System.out.println("\n[新连接] 用户 " + user + " 请求客服。是否接收？(y/n)");

            String cmd = console.nextLine();
            if (cmd.equalsIgnoreCase("y")) {
                System.out.println("已接收用户 " + user);
                activeUsers.add(user);
                pool.execute(new ClientHandler(s, user));
            } else {
                System.out.println("已拒绝用户 " + user);
                dos.writeUTF("REJECTED");
                s.close();
            }
        }
    }

    /** 为每个用户服务的线程 */
    private static class ClientHandler implements Runnable {
        private Socket sock;
        private String user;

        ClientHandler(Socket sock, String user) {
            this.sock = sock;
            this.user = user;
        }

        @Override
        public void run() {
            try (DataInputStream dis = new DataInputStream(sock.getInputStream());
                 DataOutputStream dos = new DataOutputStream(sock.getOutputStream())) {

                // 先把之前的聊天记录发给客户端
                String history = Utils.readRecord(user);
                if (!history.isEmpty()) {
                    dos.writeUTF(history);
                } else {
                    dos.writeUTF(""); // 空行
                }

                // 进入消息循环
                while (true) {
                    // 读取客户端消息
                    Message.Type type = Message.Type.values()[dis.readByte()];
                    int len = dis.readInt();
                    byte[] body = new byte[len];
                    dis.readFully(body);

                    switch (type) {
                        case TEXT:
                            String txt = new String(body);
                            System.out.println("[客服] 收到来自 " + user + ": " + txt);
                            // 回复一条确认消息
                            String reply = "已收到: " + txt;
                            byte[] replyBytes = reply.getBytes();
                            dos.writeByte(Message.Type.TEXT.ordinal());
                            dos.writeInt(replyBytes.length);
                            dos.write(replyBytes);
                            // 记录聊天
                            Utils.appendRecord(user, user, Message.Type.TEXT, txt);
                            Utils.appendRecord(user, "客服", Message.Type.TEXT, reply);
                            break;
                        case IMAGE:
                            // 这里简单把图片存成文件
                            String imgFile = "recv_" + user + "_" + System.currentTimeMillis() + ".png";
                            Files.write(Paths.get(imgFile), body);
                            System.out.println("[客服] 收到图片，已保存为 " + imgFile);
                            // 回复文件名
                            byte[] imgName = imgFile.getBytes();
                            dos.writeByte(Message.Type.FILE.ordinal());
                            dos.writeInt(imgName.length);
                            dos.write(imgName);
                            Utils.appendRecord(user, user, Message.Type.IMAGE, imgFile);
                            Utils.appendRecord(user, "客服", Message.Type.FILE, imgFile);
                            break;
                        case FILE:
                            // 接收文件并保存
                            String fileName = new String(body);
                            dos.writeUTF("READY"); // 告诉客户端可以发送文件内容
                            // 接收文件内容
                            int fileLen = dis.readInt();
                            byte[] fileData = new byte[fileLen];
                            dis.readFully(fileData);
                            Files.write(Paths.get(fileName), fileData);
                            System.out.println("[客服] 收到文件 " + fileName);
                            // 回复确认
                            dos.writeByte(Message.Type.TEXT.ordinal());
                            dos.writeInt(("文件已保存: " + fileName).getBytes().length);
                            dos.write(("文件已保存: " + fileName).getBytes());
                            Utils.appendRecord(user, user, Message.Type.FILE, fileName);
                            Utils.appendRecord(user, "客服", Message.Type.TEXT, "文件已保存: " + fileName);
                            break;
                        default:
                            System.out.println("未知消息类型");
                    }
                }
            } catch (IOException e) {
                System.out.println("[客服] 用户 " + user + " 连接已关闭");
            } finally {
                activeUsers.remove(user);
                try { sock.close(); } catch (Exception ignored) {}
            }
        }
    }
}
```

