```java
import java.io.*;
import java.net.*;
import java.util.Scanner;

public class Client {
    private static final int PORT = 12345;
    private static final String SERVER = "localhost"; // 根据实际情况修改

    public static void main(String[] args) throws IOException {
        Scanner console = new Scanner(System.in);
        System.out.print("请输入用户名: ");
        String user = console.nextLine();

        Socket sock = new Socket();
        // 连接超时 5 秒；如果服务器长时间不响应，则后续 read 超时 10 秒
        sock.connect(new InetSocketAddress(SERVER, PORT), 5000);
        DataInputStream dis = new DataInputStream(sock.getInputStream());
        DataOutputStream dos = new DataOutputStream(sock.getOutputStream());

        // 先把用户名发给服务器
        dos.writeUTF(user);

        // 等待服务器返回聊天历史（可能为空）
        String history = dis.readUTF();
        if (!history.isEmpty()) {
            System.out.println("===== 以前聊天记录 =====");
            System.out.println(history);
            System.out.println("========================");
        }

        // 启动一个线程接收服务器推送
        new Thread(() -> {
            try {
                while (true) {
                    Message.Type type = Message.Type.values()[dis.readByte()];
                    int len = dis.readInt();
                    byte[] body = new byte[len];
                    dis.readFully(body);

                    switch (type) {
                        case TEXT:
                            System.out.println("\n[客服] " + new String(body));
                            break;
                        case FILE:
                            System.out.println("\n[客服] 收到文件: " + new String(body));
                            break;
                        default:
                            System.out.println("\n[客服] 发送未知类型");
                    }
                    System.out.print("> ");
                }
            } catch (SocketTimeoutException e) {
                System.out.println("\n[提示] 服务器忙，请稍后重试！");
            } catch (IOException e) {
                System.out.println("\n[提示] 服务器已关闭");
                System.exit(0);
            }
        }).start();

        // 主线程：发送用户输入
        System.out.println("输入 \"quit\" 退出；输入 \"text\" 发送文字；输入 \"image\" 发送图片；输入 \"file\" 发送文件");
        while (true) {
            System.out.print("> ");
            String cmd = console.nextLine();
            if (cmd.equalsIgnoreCase("quit")) {
                System.out.println("退出聊天");
                sock.close();
                break;
            } else if (cmd.equalsIgnoreCase("text")) {
                System.out.print("请输入内容: ");
                String msg = console.nextLine();
                byte[] body = msg.getBytes();
                dos.writeByte(Message.Type.TEXT.ordinal());
                dos.writeInt(body.length);
                dos.write(body);
                // 记录本地聊天
                System.out.println("[你] " + msg);
            } else if (cmd.equalsIgnoreCase("image")) {
                System.out.print("图片文件路径: ");
                String path = console.nextLine();
                File f = new File(path);
                if (!f.exists() || !f.isFile()) {
                    System.out.println("文件不存在！");
                    continue;
                }
                byte[] img = Files.readAllBytes(f.toPath());
                dos.writeByte(Message.Type.IMAGE.ordinal());
                dos.writeInt(img.length);
                dos.write(img);
                System.out.println("[你] 已发送图片 " + f.getName());
            } else if (cmd.equalsIgnoreCase("file")) {
                System.out.print("文件路径: ");
                String path = console.nextLine();
                File f = new File(path);
                if (!f.exists() || !f.isFile()) {
                    System.out.println("文件不存在！");
                    continue;
                }
                // 先发送文件名
                dos.writeByte(Message.Type.FILE.ordinal());
                dos.writeInt(f.getName().getBytes().length);
                dos.write(f.getName().getBytes());
                // 等客服回应
                String ack = dis.readUTF(); // 这里我们只在服务器里用了 READY
                if (!ack.equals("READY")) {
                    System.out.println("服务器未准备好接收文件");
                    continue;
                }
                byte[] data = Files.readAllBytes(f.toPath());
                dos.writeInt(data.length);
                dos.write(data);
                System.out.println("[你] 已发送文件 " + f.getName());
            } else {
                System.out.println("未知命令");
            }
        }
    }
}
