import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

import com.opencsv.*;

public class JiraExportParser {

    /* ------------------------------------------------------------ *
     *  POJO that represents a JIRA issue.  Add more fields as needed.*
     * ------------------------------------------------------------ */
    public static class Issue {
        public String key;        // e.g. PROJ‑123
        public String summary;
        public String status;
        public String assignee;
        public String created;
        public String updated;
        public String description;
        // You can add more fields here

        @Override
        public String toString() {
            return String.format("%s | %s | %s | %s | %s | %s | %s",
                    key, summary, status, assignee, created, updated, description);
        }
    }

    /* ------------------------------------------------------------ *
     *  Main entry point – simply call with the path to a CSV file.*
     * ------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        if (args.length != 1) {
            System.err.println("Usage: java JiraExportParser <path-to-csv-file>");
            System.exit(1);
        }

        String csvFilePath = args[0];
        List<Issue> issues = parseCsv(csvFilePath);

        // Example: print all issues
        System.out.println("Parsed " + issues.size() + " issues:");
        for (Issue issue : issues) {
            System.out.println(issue);
        }
    }

    /* ------------------------------------------------------------ *
     *  CSV parsing logic – uses OpenCSV for robust handling of
     *  quoted values, commas inside fields, etc.*
     * ------------------------------------------------------------ */
    private static List<Issue> parseCsv(String csvFilePath) throws IOException {
        List<Issue> issues = new ArrayList<>();

        try (Reader reader = Files.newBufferedReader(Paths.get(csvFilePath), StandardCharsets.UTF_8);
             CSVReader csvReader = new CSVReaderBuilder(reader)
                     .withSkipLines(0)          // We'll decide if header exists manually
                     .build()) {

            String[] header = csvReader.readNext();
            if (header == null) {
                return issues; // Empty file
            }

            // Map header columns to indices
            Map<String, Integer> columnIdx = new HashMap<>();
            for (int i = 0; i < header.length; i++) {
                columnIdx.put(header[i].trim().toLowerCase(), i);
            }

            // Common JIRA CSV column names (case‑insensitive)
            String[] required = {"issue key", "summary", "status", "assignee", "created", "updated", "description"};

            // Ensure required columns exist – otherwise just skip
            for (String col : required) {
                if (!columnIdx.containsKey(col)) {
                    System.err.println("Missing expected column: " + col);
                    // continue; // comment out if you want to abort
                }
            }

            String[] nextLine;
            while ((nextLine = csvReader.readNext()) != null) {
                Issue issue = new Issue();
                issue.key = getField(nextLine, columnIdx, "issue key");
                issue.summary = getField(nextLine, columnIdx, "summary");
                issue.status = getField(nextLine, columnIdx, "status");
                issue.assignee = getField(nextLine, columnIdx, "assignee");
                issue.created = getField(nextLine, columnIdx, "created");
                issue.updated = getField(nextLine, columnIdx, "updated");
                issue.description = getField(nextLine, columnIdx, "description");
                issues.add(issue);
            }
        }
        return issues;
    }

    /* ------------------------------------------------------------ *
     *  Helper to fetch a column value safely.  Returns empty string
     *  if the column is missing or the row is shorter than the index.*
     * ------------------------------------------------------------ */
    private static String getField(String[] row, Map<String, Integer> idxMap, String headerKey) {
        Integer idx = idxMap.get(headerKey.toLowerCase());
        if (idx == null || idx >= row.length) return "";
        return row[idx].trim();
    }

    /* ------------------------------------------------------------ *
     *  (Optional) XML parsing example – uncomment if you need it.
