import io.grpc.stub.StreamObserver;
import io.grpc.Server;
import io.grpc.ServerBuilder;

public class GrpcServer {
    public static void main(String[] args) throws Exception {
        Server server = ServerBuilder.forPort(9090)
                .addService(new GreeterImpl())
                .build()
                .start();
        System.out.println("gRPC server running on port 9090");
        server.awaitTermination();
    }

    static class GreeterImpl extends GreeterGrpc.GreeterImplBase {
        @Override
        public void sayHello(HelloRequest req, StreamObserver<HelloReply> respObserver) {
            String greeting = "Hello, " + req.getName();
            HelloReply reply = HelloReply.newBuilder().setMessage(greeting).build();
            respObserver.onNext(reply);
            respObserver.onCompleted();
        }
    }
}
```

