                .usePlaintext()
                .build();
        GreeterGrpc.GreeterBlockingStub stub = GreeterGrpc.newBlockingStub(channel);

        HelloReply reply = stub.sayHello(HelloRequest.newBuilder().setName("Alice").build());
        System.out.println(reply.getMessage());

        channel.shutdownNow();
    }
}
```

