import org.springframework.security.authentication.*;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthenticationManager authManager;
    private final UserService userService;
    private final JwtProvider jwtProvider;
    private final PasswordEncoder passwordEncoder;

    public AuthController(AuthenticationManager authManager,
                          UserService userService,
                          JwtProvider jwtProvider,
                          PasswordEncoder passwordEncoder) {
        this.authManager = authManager;
        this.userService = userService;
        this.jwtProvider = jwtProvider;
        this.passwordEncoder = passwordEncoder;
    }

    @PostMapping("/register")
    public ResponseEntity<?> register(@RequestBody RegistrationRequest request) {
        User user = userService.registerUser(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(user);
    }

    @PostMapping("/login")
    public ResponseEntity<JwtResponse> login(@RequestBody LoginRequest request) {
        try {
            Authentication authentication = authManager.authenticate(
                    new UsernamePasswordAuthenticationToken(request.getEmail(), request.getPassword())
            );

            UserDetails userDetails = (UserDetails) authentication.getPrincipal();
            String jwt = jwtProvider.generateToken(userDetails);

            return ResponseEntity.ok(JwtResponse.builder()
                    .token(jwt)
                    .id(((User) ((org.springframework.security.core.userdetails.User) userDetails).getDetails()).getId())
                    .email(request.getEmail())
                    .username(((User) ((org.springframework.security.core.userdetails.User) userDetails).getDetails()).getUsername())
                    .build());
        } catch (AuthenticationException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }
    }
}
```

> В примере `id`, `username` в `JwtResponse` заполняем простыми способами. Если вам нужны более чистые DTO, можно вынести маппинг в отдельный слой.

