// Message.java
package common;

import java.io.Serializable;

public class Message implements Serializable {
    private static final long serialVersionUID = 1L;

    /** 消息类型 */
    public enum Type {
        /** 客户端请求连接 */
        CONNECT,
        /** 客户端文字消息 */
        TEXT,
        /** 客户端图片或文件 */
        FILE,
        /** 服务器确认接收（客服接入） */
        ACCEPT,
        /** 服务器拒绝 */
        REJECT,
        /** 服务器忙碌提示 */
        BUSY,
        /** 会话结束 */
        END
    }

