    /** 发送者 id（对方可以用用户名或 socket id） */
    private String sender;
    /** 文字内容（仅 type==TEXT 有效） */
    private String text;
    /** 文件名（仅 type==FILE 有效） */
    private String fileName;
    /** 文件/图片字节数组（仅 type==FILE 有效） */
    private byte[] data;

    /* ---------- 构造函数 & Get/Set ---------- */
    public Message(Type type, String sender) {
        this.type = type;
        this.sender = sender;
    }

    public static Message text(String sender, String txt) {
        Message m = new Message(Type.TEXT, sender);
        m.text = txt;
        return m;
    }

    public static Message file(String sender, String fileName, byte[] data) {
        Message m = new Message(Type.FILE, sender);
        m.fileName = fileName;
        m.data = data;
        return m;
    }

    public static Message simple(Type type, String sender) {
