```java
// Client.java
package client;

import common.Message;
import util.FileUtils;

import javax.swing.*;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.io.*;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.Date;

public class Client {

    private static final String SERVER_HOST = "localhost";
    private static final int SERVER_PORT = 5000;
    private static final String USER_ID = "user_" + System.currentTimeMillis();

    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private ClientUI ui;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            Client c = new Client();
            c.ui = new ClientUI(c);
            c.ui.setVisible(true);
        });
    }

    /** 与服务器建立连接 */
    public void connect() {
        try {
            socket = new Socket(SERVER_HOST, SERVER_PORT);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());

            // 发送 CONNECT 请求
            out.writeObject(Message.simple(Message.Type.CONNECT, USER_ID));
            out.flush();

            // 启动后台监听线程
            new Thread(this::listenServer).start();
            ui.setStatus("已连接，等待客服响应…");
        } catch (IOException e) {
            ui.showError("连接失败: " + e.getMessage());
        }
    }

    /** 监听服务器发来的消息 */
    private void listenServer() {
        try {
            while (true) {
                Message msg = (Message) in.readObject();
                handleServerMessage(msg);
            }
        } catch (EOFException e) {
            // 服务器关闭
            ui.showError("服务器已关闭连接");
        } catch (Exception e) {
            ui.showError("接收消息异常: " + e.getMessage());
        }
    }

    /** 根据消息类型更新 UI 或做相应操作 */
    private void handleServerMessage(Message msg) {
        switch (msg.getType()) {
            case BUSY:
                ui.setStatus("客服忙碌，请稍后再试");
                break;
            case ACCEPT:
                ui.setStatus("已与客服连接");
                break;
            case REJECT:
                ui.setStatus("客服拒绝服务");
                break;
            case TEXT:
                ui.appendChat(msg.getSender(), msg.getText());
                break;
            case FILE:
                // 保存收到的文件
                try {
                    File outFile = new File("downloads", msg.getFileName());
                    outFile.getParentFile().mkdirs();
                    FileUtils.writeBytesToFile(msg.getData(), outFile);
                    ui.appendChat(msg.getSender(), "[图片/文件] " + msg.getFileName() + " 已下载");
                } catch (IOException e) {
                    ui.appendChat(msg.getSender(), "[错误] 文件下载失败: " + e.getMessage());
                }
                break;
            case END:
                ui.setStatus("会话结束");
                break;
        }
    }

    /** 发送文字消息 */
    public void sendText(String txt) {
        try {
            out.writeObject(Message.text(USER_ID, txt));
            out.flush();
            ui.appendChat("我", txt);
        } catch (IOException e) {
            ui.showError("发送失败: " + e.getMessage());
        }
    }

    /** 发送图片/文件 */
    public void sendFile(File file) {
        try {
            byte[] data = FileUtils.readFileToBytes(file);
            out.writeObject(Message.file(USER_ID, file.getName(), data));
            out.flush();
            ui.appendChat("我", "[文件] " + file.getName() + " 已发送");
        } catch (IOException e) {
            ui.showError("文件发送失败: " + e.getMessage());
        }
    }

    /** 断开连接 */
    public void disconnect() {
        try {
            if (out != null) out.close();
            if (in != null) in.close();
            if (socket != null && !socket.isClosed()) socket.close();
        } catch (IOException ignored) { }
    }

    /** 注册窗口关闭时的资源释放 */
    public void addWindowListener(WindowAdapter adapter) {
        ui.addWindowListener(adapter);
    }
}
```

