```java
// Server.java
package server;

import common.Message;

import javax.swing.*;
import java.awt.*;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.*;
import java.util.concurrent.*;

public class Server {

    private static final int PORT = 5000;
    private ServerSocket serverSocket;
    private ExecutorService pool = Executors.newCachedThreadPool();

    /** 显示在服务器 UI 中的所有等待中的用户 */
    private final List<String> pendingUsers = new CopyOnWriteArrayList<>();
    /** 显示在服务器 UI 中的已接入会话 */
    private final Map<String, ClientHandler> activeSessions = new ConcurrentHashMap<>();

    private ServerUI ui;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            Server s = new Server();
            s.ui = new ServerUI(s);
            s.ui.setVisible(true);
            s.startServer();
        });
    }

    /** 启动监听线程 */
    public void startServer() {
        new Thread(() -> {
            try {
                serverSocket = new ServerSocket(PORT);
                System.out.println("Server listening on port " + PORT);
                while (true) {
                    Socket clientSock = serverSocket.accept();
                    ClientHandler handler = new ClientHandler(clientSock, this);
                    pool.execute(handler);
                }
            } catch (IOException e) {
                e.printStackTrace();
                JOptionPane.showMessageDialog(ui, "服务器异常: " + e.getMessage(), "错误", JOptionPane.ERROR_MESSAGE);
            }
        }).start();
    }

    /** 服务器 UI 用来更新 pendingUsers 列表 */
    public List<String> getPendingUsers() {
        return pendingUsers;
    }

    public Map<String, ClientHandler> getActiveSessions() {
        return activeSessions;
    }

    /** 当有新用户连接时调用 */
    public void addPendingUser(String userId, ClientHandler handler) {
        pendingUsers.add(userId);
        ui.refreshPendingList();
        handler.setPending(true);
    }

    /** 服务器 UI 通过此方法接受或拒绝用户 */
    public void handleDecision(String userId, boolean accept) {
        ClientHandler h = activeSessions.get(userId);
        if (h == null) {
            // 可能已经被拒绝或已接入
            return;
        }
        if (accept) {
            h.sendAccept();
        } else {
            h.sendReject();
        }
        pendingUsers.remove(userId);
        ui.refreshPendingList();
    }

    /** 关闭服务器 */
    public void stopServer() {
        try {
            serverSocket.close();
            pool.shutdownNow();
        } catch (IOException ignored) { }
    }
}
