### 4.2 客户端处理线程（ClientHandler.java）

```java
// ClientHandler.java
package server;

import common.Message;
import util.FileUtils;

import javax.swing.*;
import java.io.*;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.util.Date;

public class ClientHandler implements Runnable {

    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private Server server;
    private String userId;
    private boolean pending = false;
    private final File chatLog; // 聊天记录文件

    public ClientHandler(Socket socket, Server server) throws IOException {
        this.socket = socket;
        this.server = server;
        this.out = new ObjectOutputStream(socket.getOutputStream());
        this.in = new ObjectInputStream(socket.getInputStream());
        this.chatLog = new File("logs", "chat_" + System.currentTimeMillis() + ".txt");
        chatLog.getParentFile().mkdirs();
    }

    public void setPending(boolean val) { pending = val; }

    /** 服务器向客户端发送 ACCEPT */
    public void sendAccept() throws IOException {
        out.writeObject(Message.simple(Message.Type.ACCEPT, "server"));
        out.flush();
    }

    /** 服务器向客户端发送 REJECT */
    public void sendReject() throws IOException {
        out.writeObject(Message.simple(Message.Type.REJECT, "server"));
        out.flush();
        close();
    }

    @Override
    public void run() {
        try {
            // 阻塞读取第一条消息（CONNECT）
            Message m = (Message) in.readObject();
            if (m.getType() == Message.Type.CONNECT) {
                userId = m.getSender();
                server.addPendingUser(userId, this);
                // 服务器 UI 等待管理员决策
            }

            // 之后进入消息循环
            while (true) {
                Message msg = (Message) in.readObject();
                handleMessage(msg);
            }
        } catch (EOFException e) {
            // 客户端关闭
            close();
        } catch (Exception e) {
            e.printStackTrace();
            close();
        }
    }

    /** 处理收到的消息（来自客户） */
    private void handleMessage(Message msg) throws IOException {
        // 写入聊天记录
        logMessage(msg);

        switch (msg.getType()) {
            case TEXT:
                // 这里示例仅在服务器上打印；若想转发给客服 UI，可以在 ServerUI 里做
                System.out.println("[" + userId + "] " + msg.getText());
                break;
            case FILE:
                // 保存收到的文件到服务器本地
                Path outFile = Paths.get("server_uploads", msg.getFileName());
                outFile.getParent().toFile().mkdirs();
                Files.write(outFile, msg.getData());
                System.out.println("[" + userId + "] 收到文件 " + msg.getFileName());
                break;
            default:
                break;
        }
    }

    /** 在聊天记录文件里追加一行 */
    private void logMessage(Message msg) {
        try (FileWriter fw = new FileWriter(chatLog, true);
             BufferedWriter bw = new BufferedWriter(fw)) {
            String time = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date());
            String line;
            if (msg.getType() == Message.Type.TEXT) {
                line = String.format("[%s][%s] %s%n", time, msg.getSender(), msg.getText());
            } else if (msg.getType() == Message.Type.FILE) {
                line = String.format("[%s][%s] 文件 %s (%d bytes)%n", time, msg.getSender(), msg.getFileName(), msg.getData().length);
            } else {
                line = String.format("[%s][%s] %s%n", time, msg.getSender(), msg.getType());
            }
            bw.write(line);
        } catch (IOException ignored) { }
    }

    /** 客户端主动发消息给客服（此示例不实现客服 UI 直接发送，留给 ServerUI） */
    public void sendMessage(Message msg) {
        try {
            out.writeObject(msg);
            out.flush();
            logMessage(msg);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 关闭连接 */
    public void close() {
        try {
            if (out != null) out.close();
            if (in != null) in.close();
            if (socket != null && !socket.isClosed()) socket.close();
        } catch (IOException ignored) { }
        server.getActiveSessions().remove(userId);
    }
}
```

