package com.example.mytcpapp;

import android.os.Handler;
import android.os.Looper;
import android.util.Log;

import java.io.IOException;
import java.net.Socket;

/**
 * Handles a TCP socket connection in a background thread.
 */
public class NetworkConnection implements Runnable {

    private static final String TAG = "NetworkConnection";

    private final String host;
    private final int port;
    private final ConnectionCallback callback;
    private final Handler mainHandler; // to post results to UI thread
    private Thread thread;
    private volatile boolean running = false;

    /**
     * Callback interface to inform the caller about status changes.
     */
    public interface ConnectionCallback {
        void onConnected();
        void onFailed(String reason);
        void onDisconnected();
    }

    /**
     * @param host     remote host to connect to
     * @param port     remote port
     * @param callback callback for connection events
     */
    public NetworkConnection(String host, int port, ConnectionCallback callback) {
        this.host = host;
        this.port = port;
        this.callback = callback;
        this.mainHandler = new Handler(Looper.getMainLooper());
    }

    /** Starts the thread. */
    public void start() {
        if (running) return;          // already running
        running = true;
        thread = new Thread(this, "NetworkConnectionThread");
        thread.start();
    }

    /** Stops the thread and closes the socket. */
    public void stop() {
        running = false;
        if (thread != null && thread.isAlive()) {
            thread.interrupt();
        }
    }

    @Override
    public void run() {
        Log.d(TAG, "Thread started: attempting connection to " + host + ":" + port);
        try (Socket socket = new Socket(host, port)) {
            // If we reach here, the connection succeeded.
            Log.d(TAG, "Connected to server");
            postOnConnected();

            // Keep the socket alive as long as the thread is running.
            while (running && !Thread.currentThread().isInterrupted()) {
                // Simple keep‑alive: sleep for a while.
                // In a real app you would read/write to the socket here.
                Thread.sleep(2000);
            }
        } catch (IOException e) {
            Log.e(TAG, "IOException during connection", e);
            postOnFailed(e.getMessage());
        } catch (InterruptedException e) {
            // Thread was interrupted – treat as a normal disconnect.
            Log.d(TAG, "Thread interrupted, stopping");
        } finally {
            postOnDisconnected();
        }
    }

    /* ----------- Helper methods to post callbacks on UI thread ----------- */

    private void postOnConnected() {
        if (callback != null) {
            mainHandler.post(callback::onConnected);
        }
    }

    private void postOnFailed(String reason) {
        if (callback != null) {
            mainHandler.post(() -> callback.onFailed(reason));
        }
    }

    private void postOnDisconnected() {
        if (callback != null) {
            mainHandler.post(callback::onDisconnected);
        }
    }
}
```

> **Notes on the implementation**  
> * We use `try‑with‑resources` so the socket is automatically closed when the thread exits.  
> * `running` is a `volatile` flag so that the main thread can stop the loop safely.  
> * The `Callback` is invoked on the **main thread** via a `Handler` so the UI can be updated safely.

