    public static void main(String[] args) {
        ExecutorService pool = Executors.newFixedThreadPool(THREAD_POOL);

        try (ServerSocket ss = new ServerSocket(PORT)) {
            System.out.println("TCPPacketServer listening on port " + PORT);

            while (true) {
                Socket client = ss.accept();
                pool.execute(new ClientHandler(client));
            }
        } catch (IOException e) {
            System.err.println("Server exception: " + e.getMessage());
        } finally {
            pool.shutdown();
        }
    }

    /** Handles one client connection. */
    private static class ClientHandler implements Runnable {
        private final Socket socket;

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                /* -------- Step 1 – read a Packet ----------
                 *  We use an ObjectInputStream only for the
                 *  first object.  Afterwards we switch to a
                 *  plain text protocol (BufferedReader /
                 *  PrintWriter). */
                ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
                Object obj = ois.readObject();

                if (!(obj instanceof Packet)) {
                    System.err.println("Expected Packet, got " + obj.getClass().getName());
                    socket.close();
                    return;
                }

                Packet pkt = (Packet) obj;
                System.out.printf("Received from %s: %s%n",
                        socket.getRemoteSocketAddress(), pkt);

                /* -------- Step 2 – send ACK ----------
                 *  We reply with a plain text line so
                 *  the client can read it with BufferedReader. */
                PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
                out.println("ACK");

                /* -------- Step 3 – echo upper‑case ----------
                 *  After the ACK the client may send any
                 *  number of text lines.  The server replies
                 *  with the same line converted to upper‑case.
                 *  If the client sends "CLOSE" (any case),
                 *  the server responds with "CLOSE" and
                 *  terminates the connection. */
                BufferedReader in = new BufferedReader(
                        new InputStreamReader(socket.getInputStream()));

                String line;
                while ((line = in.readLine()) != null) {
                    if ("CLOSE".equalsIgnoreCase(line.trim())) {
                        out.println("CLOSE");
                        break;
                    }
                    out.println(line.toUpperCase());
                }

                System.out.println("Connection closed: " + socket.getRemoteSocketAddress());

            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Client handler exception: " + e.getMessage());
            } finally {
                try {
                    socket.close();
                } catch (IOException ignore) {}
            }
        }
    }
}
```

