## 3. `TCPPacketClient.java`

```java
import java.io.*;
import java.net.*;

public class TCPPacketClient {
    private static final String HOST = "localhost";
    private static final int PORT = 1024;

    public static void main(String[] args) {
        try (
            Socket socket = new Socket(HOST, PORT);

            /* ObjectOutputStream – used for sending the
             * first Packet object.  It must be flushed
             * before we switch to the text protocol. */
            ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
            /* BufferedReader – for reading server replies. */
            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            /* PrintWriter – for the subsequent text protocol. */
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            /* Console input. */
            BufferedReader console = new BufferedReader(new InputStreamReader(System.in));
        ) {
            /* -------- Step 1 – send a Packet ----------
             *  For demo purposes we always use serialNo=1
             *  and a static message. */
            int serialNo = 1;
            String data = "Hello Server";
            Packet pkt = new Packet(serialNo, data);
            oos.writeObject(pkt);
            oos.flush();

            /* -------- Step 2 – read ACK ----------
             *  The server replies with the text line "ACK". */
            String ack = in.readLine();
            System.out.println("Server says: " + ack);

            /* -------- Step 3 – interactive text ----------
             *  The user can type any line.  When "CLOSE"
             *  is entered the session ends. */
            String line;
            while (true) {
                System.out.print("Enter text (or CLOSE to exit): ");
                line = console.readLine();
                out.println(line);

                if ("CLOSE".equalsIgnoreCase(line.trim())) {
                    /* The server also replies with "CLOSE". */
                    String reply = in.readLine();
                    System.out.println("Server says: " + reply);
                    break;
                }

                String reply = in.readLine();
                System.out.println("From server (upper‑cased): " + reply);
            }

        } catch (IOException e) {
            System.err.println("Client error: " + e.getMessage());
        }
    }
}
