package com.portfolio.todo;

import java.io.Serializable;
import java.time.LocalDate;
import java.util.Objects;

/**
 * Одна задача.
 * Сериализуется в файл, поэтому реализует Serializable.
 */
public class TodoItem implements Serializable {
    private static final long serialVersionUID = 1L;

    private String title;
    private String description;
    private LocalDate dueDate;
    private boolean done;

    public TodoItem(String title, String description, LocalDate dueDate) {
        this.title = title;
        this.description = description;
        this.dueDate = dueDate;
        this.done = false;
    }

    // Геттеры/сеттеры

    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public LocalDate getDueDate() { return dueDate; }
    public void setDueDate(LocalDate dueDate) { this.dueDate = dueDate; }

    public boolean isDone() { return done; }
    public void setDone(boolean done) { this.done = done; }

    @Override
    public String toString() {
        return String.format(
                "[%s] %s – %s (Срок: %s)",
                done ? "✓" : " ",
                title,
                description.isEmpty() ? "(без описания)" : description,
                dueDate == null ? "нет" : dueDate.toString()
        );
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof TodoItem)) return false;
        TodoItem todoItem = (TodoItem) o;
        return Objects.equals(title, todoItem.title) &&
                Objects.equals(dueDate, todoItem.dueDate);
    }

    @Override
    public int hashCode() {
