## 1. Matrix‑Multiplication

### 1.1. Java (ExecutorService)

```java
// MatrixMul.java
import java.util.concurrent.*;
import java.util.*;

public class MatrixMul {

    // matrix size
    private static final int N = 2000;     // change if you like
    static double[][] A = new double[N][N];
    static double[][] B = new double[N][N];
    static double[][] C = new double[N][N];

    public static void main(String[] args) throws Exception {
        int nThreads = Integer.parseInt(args[0]);

        // initialise A and B with random values
        Random rnd = new Random(1);
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++) {
                A[i][j] = rnd.nextDouble();
                B[i][j] = rnd.nextDouble();
            }

        long start = System.nanoTime();
        multiply(nThreads);
        long end = System.nanoTime();

        System.out.printf("threads=%d  time=%.3f s\n",
                          nThreads, (end - start) / 1e9);
    }

    /** Parallel matrix multiplication. */
    private static void multiply(int nThreads) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(nThreads);

        // split work row‑by‑row
        int rowsPerThread = N / nThreads;
        int rem = N % nThreads;

        List<Future<?>> futures = new ArrayList<>();

        int rowStart = 0;
        for (int t = 0; t < nThreads; t++) {
            int rowEnd = rowStart + rowsPerThread + (t < rem ? 1 : 0);
            final int r0 = rowStart, r1 = rowEnd;   // capture for lambda

            futures.add(pool.submit(() -> {
                for (int i = r0; i < r1; i++)
                    for (int j = 0; j < N; j++) {
                        double sum = 0;
                        for (int k = 0; k < N; k++)
                            sum += A[i][k] * B[k][j];
                        C[i][j] = sum;
                    }
            }));
            rowStart = rowEnd;
        }

        // wait for all workers to finish
        for (Future<?> f : futures) f.get();
        pool.shutdown();
    }
}
```

### 1.2. C++ (OpenMP)

```cpp
// MatrixMul.cpp
#include <iostream>
#include <vector>
#include <random>
#include <chrono>
#include <omp.h>

const int N = 2000;            // change if you like

int main(int argc, char** argv) {
    if (argc != 2) { std::cerr << "Usage: " << argv[0] << " <nThreads>\n"; return 1; }
    int nThreads = std::stoi(argv[1]);

    std::vector<std::vector<double>> A(N, std::vector<double>(N));
    std::vector<std::vector<double>> B(N, std::vector<double>(N));
    std::vector<std::vector<double>> C(N, std::vector<double>(N));

    // initialise A and B
    std::mt19937 rng(1);
    std::uniform_real_distribution<double> dist(0.0, 1.0);
    for (int i=0;i<N;i++)
        for (int j=0;j<N;j++) {
            A[i][j] = dist(rng);
            B[i][j] = dist(rng);
        }

    omp_set_num_threads(nThreads);
    auto start = std::chrono::high_resolution_clock::now();

    #pragma omp parallel for
    for (int i=0;i<N;i++) {
        for (int j=0;j<N;j++) {
            double sum = 0.0;
            for (int k=0;k<N;k++)
                sum += A[i][k] * B[k][j];
            C[i][j] = sum;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    double secs = std::chrono::duration<double>(end-start).count();
    std::cout << "threads=" << nThreads << "  time=" << secs << " s\n";
}
```

