## 2. Array Sum (Reduction)

### 2.1. Java (ExecutorService)

```java
// SumArray.java
import java.util.concurrent.*;
import java.util.*;

public class SumArray {
    private static final long SIZE = 1_000_000_000L;   // 1e9 elements
    static double[] arr = new double[(int)SIZE];

    public static void main(String[] args) throws Exception {
        int nThreads = Integer.parseInt(args[0]);

        // initialise the array
        Arrays.fill(arr, 1.0);   // each element is 1.0, so sum = SIZE

        long start = System.nanoTime();
        double sum = parallelSum(nThreads);
        long end   = System.nanoTime();

        System.out.printf("threads=%d  time=%.3f s  sum=%.0f\n",
                          nThreads, (end-start)/1e9, sum);
    }

    private static double parallelSum(int nThreads) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(nThreads);

        int chunk = (int)SIZE / nThreads;
        int rem   = (int)(SIZE % nThreads);

        List<Future<Double>> futures = new ArrayList<>();

        int offset = 0;
        for (int t=0; t<nThreads; t++) {
            int len   = chunk + (t < rem ? 1 : 0);
            final int off = offset, ln = len;

            futures.add(pool.submit(() -> {
                double s = 0;
                for (int i=off; i<off+ln; i++)
                    s += arr[i];
                return s;
            }));
            offset += len;
        }

        double total = 0;
        for (Future<Double> f : futures) total += f.get();

        pool.shutdown();
        return total;
    }
}
```

### 2.2. C++ (OpenMP)

```cpp
// SumArray.cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <omp.h>

int main(int argc, char** argv) {
    if (argc != 2) { std::cerr << "Usage: " << argv[0] << " <nThreads>\n"; return 1; }
    int nThreads = std::stoi(argv[1]);

    const size_t SIZE = 1'000'000'000;   // 1e9
    std::vector<double> arr(SIZE, 1.0);  // each element = 1.0

    omp_set_num_threads(nThreads);
    double sum = 0.0;

    auto start = std::chrono::high_resolution_clock::now();

    #pragma omp parallel for reduction(+:sum)
    for (size_t i=0; i<SIZE; ++i)
        sum += arr[i];

    auto end = std::chrono::high_resolution_clock::now();
    double secs = std::chrono::duration<double>(end-start).count();

    std::cout << "threads=" << nThreads << "  time=" << secs
              << " s  sum=" << sum << "\n";
}
```

