                }
                Message msg = new Message(type, "unknown", "unknown", text, filename, data);
                // 直接写入历史记录里，时间用原始时间
                setTimestamp(msg, ts);
                history.add(msg);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return history;
    }

    // Helper: escape '|' and '\n' in text
    private String escape(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("|", "\\|").replace("\n", "\\n");
    }

    private String unescape(String s) {
        return s.replace("\\n", "\n").replace("\\|", "|").replace("\\\\", "\\");
    }

    private void setTimestamp(Message msg, Date ts) {
        try {
            java.lang.reflect.Field f = Message.class.getDeclaredField("timestamp");
            f.setAccessible(true);
            f.set(msg, ts);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
