//===== server/Server.java =====
package server;

import common.Message;
import common.MessageType;
import chatlogger.ChatLogger;

import javax.swing.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class Server {

    // 端口号
    private static final int PORT = 5555;

    // 服务器主线程
    private ServerSocket serverSocket;

    // 显示在 UI 上的 Pending 列表
    private final Map<String, Socket> pendingClients = Collections.synchronizedMap(new HashMap<>());
    // 已接入的客户
    private final Map<String, ClientHandler> activeClients = Collections.synchronizedMap(new HashMap<>());

    // UI
    private ServerGUI gui;

    public Server() {
        try {
            serverSocket = new ServerSocket(PORT);
            gui = new ServerGUI(this);
        } catch (IOException e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(null, "启动服务器失败：" + e.getMessage(), "错误", JOptionPane.ERROR_MESSAGE);
            System.exit(1);
        }
    }

    /**
     * 开始监听客户端
     */
    public void start() {
        gui.show();

        new Thread(() -> {
            while (true) {
                try {
                    Socket clientSock = serverSocket.accept();
                    // 第一条消息是 JOIN
                    ObjectInputStream ois = new ObjectInputStream(clientSock.getInputStream());
                    Object obj = ois.readObject();
                    if (!(obj instanceof Message)) throw new IOException("不合法的协议");

                    Message msg = (Message) obj;
                    if (msg.getType() != MessageType.CONTROL || !"JOIN".equals(msg.getText())) {
                        clientSock.close();
                        continue;
                    }

                    String userId = msg.getFromId();

                    // 新用户到来
                    pendingClients.put(userId, clientSock);

                    // 在 UI 上显示
                    SwingUtilities.invokeLater(() -> gui.addPending(userId));
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }).start();
    }

    /**
     * 客服端点击“接入”按钮后调用
     */
    public void acceptClient(String userId) {
        Socket sock = pendingClients.remove(userId);
        if (sock == null) return;

        try {
            // 给客户端发送 OK
            ObjectOutputStream oos = new ObjectOutputStream(sock.getOutputStream());
            oos.writeObject(Message.control("server", userId, "OK")); // 这里的 OK 表示接入成功
            oos.flush();

            // 创建处理线程
            ClientHandler handler = new ClientHandler(sock, userId, this);
            activeClients.put(userId, handler);
            new Thread(handler).start();

            // 在 UI 上移动到 Active 列表
            SwingUtilities.invokeLater(() -> gui.moveToActive(userId));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * 客服端点击“拒绝”按钮后调用
     */
    public void rejectClient(String userId) {
        Socket sock = pendingClients.remove(userId);
        if (sock == null) return;

        try {
            ObjectOutputStream oos = new ObjectOutputStream(sock.getOutputStream());
            oos.writeObject(Message.control("server", userId, "REJECT")); // 服务器拒绝
            oos.flush();
            sock.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * 当客户端主动断开时调用
     */
    public void clientDisconnected(String userId) {
        activeClients.remove(userId);
        SwingUtilities.invokeLater(() -> gui.removeActive(userId));
    }

    /**
     * 发送消息给指定客户
     */
    public void sendToClient(String userId, Message msg) {
        ClientHandler handler = activeClients.get(userId);
        if (handler != null) {
            handler.sendMessage(msg);
        }
    }

    public static void main(String[] args) {
        Server srv = new Server();
        srv.start();
    }
}
