//===== server/ClientHandler.java =====
package server;

import common.Message;
import common.MessageType;
import chatlogger.ChatLogger;

import java.io.*;
import java.net.Socket;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * 每个客户端对应一个 ClientHandler，负责：
 * ① 读取客户端发来的消息，显示在服务器 UI 并记录日志
 * ② 接收服务器端通过 sendToClient() 发送的消息
 */
public class ClientHandler implements Runnable {
    private final Socket socket;
    private final String userId;
    private final Server server;
    private ObjectInputStream ois;
    private ObjectOutputStream oos;
    private final ChatLogger logger;
    private final AtomicBoolean running = new AtomicBoolean(true);

    public ClientHandler(Socket socket, String userId, Server server) throws IOException {
        this.socket = socket;
        this.userId = userId;
        this.server = server;
        ois = new ObjectInputStream(socket.getInputStream());
        oos = new ObjectOutputStream(socket.getOutputStream());
        logger = new ChatLogger(userId);
    }

    @Override
    public void run() {
        try {
            // 读取客户端消息
            while (running.get()) {
                Object obj = ois.readObject();
                if (obj == null) break;
                if (!(obj instanceof Message)) continue;
                Message msg = (Message) obj;
                // 记录日志
                logger.log(msg);

                // 如果 UI 需要显示
                SwingUtilities.invokeLater(() ->
                        server.gui.appendChat(msg));

                // 若是控制消息（如 客户端关闭），直接退出
                if (msg.getType() == MessageType.CONTROL &&
                        ("DISCONNECT".equals(msg.getText()) || "CLOSE".equals(msg.getText()))) {
                    break;
                }
            }
        } catch (Exception e) {
            // 可能是网络异常，直接退出
            System.out.println("Client " + userId + " 连接异常，已退出：" + e.getMessage());
        } finally {
            close();
        }
    }

    // 服务器向客户端发送消息
    public void sendMessage(Message msg) {
        try {
            oos.writeObject(msg);
            oos.flush();
            // 记录日志
            logger.log(msg);
            SwingUtilities.invokeLater(() -> server.gui.appendChat(msg));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 关闭连接
    public void close() {
        running.set(false);
        try { socket.close(); } catch (IOException ignored) {}
        server.clientDisconnected(userId);
    }
}
```

> **说明**  
> `ClientHandler` 只负责读取客户端发来的消息。  
> 若服务器想发送消息，只需 `handler.sendMessage(msg)`。  
> 所有日志均通过 `ChatLogger` 写入本地。

