//===== client/Client.java =====
package client;

import common.Message;
import common.MessageType;

import javax.swing.*;
import java.io.*;
import java.net.Socket;
import java.util.Date;

/**
 * 客户端入口
 */
public class Client {
    private static final String SERVER_HOST = "127.0.0.1";
    private static final int SERVER_PORT = 5555;

    private Socket socket;
    private ObjectInputStream ois;
    private ObjectOutputStream oos;
    private final String userId;
    private ClientGUI gui;

    public Client(String userId) {
        this.userId = userId;
    }

    public void start() {
        try {
            socket = new Socket(SERVER_HOST, SERVER_PORT);
            socket.setSoTimeout(0); // 只在等待服务器响应时用
            oos = new ObjectOutputStream(socket.getOutputStream());
            ois = new ObjectInputStream(socket.getInputStream());

            // 发送 JOIN
            Message joinMsg = Message.control(userId, "server", "JOIN");
            oos.writeObject(joinMsg);
            oos.flush();

            // 等待服务器返回 OK/REJECT，超时 10s
            try {
                socket.setSoTimeout(10_000); // 10 秒
                Object respObj = ois.readObject();
                if (!(respObj instanceof Message)) throw new IOException("协议错误");
                Message resp = (Message) respObj;
                if (resp.getText().equals("OK")) {
                    // 进入聊天
                    socket.setSoTimeout(0);
                    gui = new ClientGUI(this, userId);
                    gui.show();
                    // 读取历史记录并显示
                    gui.loadHistory();
                } else if (resp.getText().equals("REJECT")) {
                    JOptionPane.showMessageDialog(null, "客服拒绝接入，请稍后重试。");
                    close();
                } else {
                    JOptionPane.showMessageDialog(null, "未知服务器返回：" + resp.getText());
                    close();
                }
            } catch (SocketTimeoutException ste) {
                JOptionPane.showMessageDialog(null, "客服忙，请稍后再试。");
                close();
            }
        } catch (Exception e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(null, "连接失败：" + e.getMessage());
            System.exit(1);
        }
    }

    // 服务器往来消息，交给 GUI 处理
    public void listen() {
        new Thread(() -> {
            try {
                while (true) {
                    Object obj = ois.readObject();
                    if (obj == null) break;
                    if (!(obj instanceof Message)) continue;
                    Message msg = (Message) obj;
                    if (gui != null) {
                        gui.onMessageReceived(msg);
                    }
                }
            } catch (Exception e) {
                e.printStackTrace();
                if (gui != null) gui.showError("连接异常：" + e.getMessage());
            }
        }).start();
    }

    public void sendMessage(Message msg) {
        try {
            oos.writeObject(msg);
            oos.flush();
        } catch (IOException e) {
            e.printStackTrace();
            if (gui != null) gui.showError("发送失败：" + e.getMessage());
        }
    }

    public void close() {
        try {
            if (socket != null) socket.close();
        } catch (IOException ignored) {}
    }

    public static void main(String[] args) {
        String uid = JOptionPane.showInputDialog(null, "请输入用户 ID：", "登录", JOptionPane.QUESTION_MESSAGE);
        if (uid == null || uid.trim().isEmpty()) System.exit(0);
        Client client = new Client(uid.trim());
        client.start();
    }
}
