                Files.write(dest.toPath(), msg.getData());
                JOptionPane.showMessageDialog(this, "文件已保存到：" + dest.getAbsolutePath());
            } catch (IOException e) {
                e.printStackTrace();
                showError("文件保存失败：" + e.getMessage());
            }
        }
    }

    public void showError(String msg) {
        JOptionPane.showMessageDialog(this, msg, "错误", JOptionPane.ERROR_MESSAGE);
    }
}
