package com.example.demo.model;

import jakarta.persistence.*;
import java.time.Instant;
import lombok.*;

@Entity
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
@Table(name = "file_meta")
public class FileMeta {

    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String originalFilename;   // оригинальное имя файла
    private String storedFilename;     // имя, под которым сохраняем на диске
    private long size;                 // размер в байтах
    private Instant uploadTime;        // дата загрузки
    private String contentType;        // MIME‑тип

    // Поля, которые нужны, можно добавить (путь, описание, пользователь и т.д.)
}
