## 6. Контроллер

```java
package com.example.demo.controller;

import com.example.demo.model.FileMeta;
import com.example.demo.service.FileStorageService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
@RequiredArgsConstructor
public class UploadController {

    private final FileStorageService storageService;

    // Страница с формой
    @GetMapping("/")
    public String index() {
        return "index"; // thymeleaf template index.html
    }

    // Обработчик загрузки
    @PostMapping("/upload")
    public String handleFileUpload(@RequestParam("file") MultipartFile file,
                                   RedirectAttributes redirectAttrs) {
        try {
            FileMeta meta = storageService.store(file);
            redirectAttrs.addFlashAttribute("message",
                    "Файл успешно загружен: " + meta.getOriginalFilename());
        } catch (Exception e) {
            redirectAttrs.addFlashAttribute("error",
                    "Ошибка при загрузке: " + e.getMessage());
        }
        return "redirect:/";
    }

    // (Опционально) скачивание
    @GetMapping("/download/{id}")
    public ResponseEntity<Resource> download(@PathVariable Long id) throws IOException {
        FileMeta meta = storageService.repo.findById(id)
                .orElseThrow(() -> new RuntimeException("Файл не найден"));
        Path filePath = Paths.get(storageService.uploadDir)
                .resolve(meta.getStoredFilename())
                .normalize();
        Resource resource = new UrlResource(filePath.toUri());
        return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(meta.getContentType()))
                .header(HttpHeaders.CONTENT_DISPOSITION,
                        "attachment; filename=\"" + meta.getOriginalFilename() + "\"")
                .body(resource);
    }
}
```

> **Ключевые моменты**  
> * `RedirectAttributes` – чтобы показать сообщение после редиректа.  
> * `MultipartFile` автоматически мапится из `multipart/form-data`.  
> * `@RequestParam("file")` – имя поля в форме.  

