public class ChatLog {
    private final Path logPath;
    private final Gson gson = new Gson();

    public ChatLog(String userId) {
        this.logPath = Paths.get("logs", userId + ".json");
        try {
            if (!Files.exists(logPath.getParent())) Files.createDirectories(logPath.getParent());
            if (!Files.exists(logPath)) Files.createFile(logPath);
        } catch (IOException e) { e.printStackTrace(); }
    }

    public void append(Message msg) {
        try (BufferedWriter writer = Files.newBufferedWriter(logPath,
                StandardCharsets.UTF_8, StandardOpenOption.APPEND)) {
            writer.write(gson.toJson(msg));
            writer.newLine();
        } catch (IOException e) { e.printStackTrace(); }
    }

    public List<Message> loadAll() {
        List<Message> list = new ArrayList<>();
        try (Stream<String> lines = Files.lines(logPath, StandardCharsets.UTF_8)) {
            lines.forEach(line -> list.add(gson.fromJson(line, Message.class)));
        } catch (IOException e) { e.printStackTrace(); }
