import com.sun.net.httpserver.*;

import javax.net.ssl.*;
import java.io.*;
import java.net.InetSocketAddress;
import java.security.*;
import java.security.cert.CertificateException;

public class SimpleHttpsServer {

    // HTTPS port we will listen on
    private static final int HTTPS_PORT = 8443;

    public static void main(String[] args) throws Exception {
        // Load keystore (the same one you generated with keytool)
        char[] keyPassword = "changeit".toCharArray(); // key entry password

        // 1) Load the keystore from the file system
        KeyStore ks = KeyStore.getInstance("JKS");
        try (FileInputStream fis = new FileInputStream("mykeystore.jks")) {
            ks.load(fis, "changeit".toCharArray()); // keystore password
        }

        // 2) Initialize KeyManagerFactory with the keystore
        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, keyPassword);

        // 3) Create an SSLContext using the key managers
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(kmf.getKeyManagers(), null, new SecureRandom());

        // 4) Create the HTTPS server
        HttpsServer httpsServer = HttpsServer.create(new InetSocketAddress(HTTPS_PORT), 0);
        httpsServer.setHttpsConfigurator(new HttpsConfigurator(sslContext) {
            @Override
            public void configure(HttpsParameters params) {
                try {
                    // Get the default SSL parameters
                    SSLContext c = getSSLContext();
                    SSLEngine engine = c.createSSLEngine();
                    params.setNeedClientAuth(false);
                    params.setCipherSuites(engine.getEnabledCipherSuites());
                    params.setProtocols(engine.getEnabledProtocols());

                    // Set the SSL parameters
                    SSLParameters sslParameters = c.getSupportedSSLParameters();
                    params.setSSLParameters(sslParameters);
                } catch (Exception ex) {
                    System.err.println("Failed to create HTTPS port");
                }
            }
        });

        // 5) Add a simple handler that responds to all requests
        httpsServer.createContext("/", new MyHandler());

        // 6) Start the server
        httpsServer.setExecutor(null); // creates a default executor
        httpsServer.start();

        System.out.println("HTTPS server started on port " + HTTPS_PORT);
        System.out.println("Open https://localhost:" + HTTPS_PORT + "/ in a browser.");
    }

    // Simple HTTP handler that replies with a static message
    static class MyHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange t) throws IOException {
            String response = "Hello, HTTPS! (from SimpleHttpsServer)\n";
            t.getResponseHeaders().add("Content-Type", "text/plain; charset=utf-8");
            t.sendResponseHeaders(200, response.getBytes("UTF-8").length);
            try (OutputStream os = t.getResponseBody()) {
                os.write(response.getBytes("UTF-8"));
            }
        }
    }
}
```

### How it works

