                }
            }

            // 生成唯一文件名（可以根据需要自定义）
            String fileName = generateFileName(contentType);
            File outFile = new File(uploadDir, fileName);

            // 将请求体写入磁盘
            try (InputStream is = exchange.getRequestBody();
                 OutputStream os = new FileOutputStream(outFile)) {

                byte[] buffer = new byte[8192];
                int len;
                while ((len = is.read(buffer)) != -1) {
                    os.write(buffer, 0, len);
                }
            }

            // 返回成功响应
            String response = "File uploaded successfully: " + fileName;
            sendResponse(exchange, 200, response);
            System.out.println(response);
        }

        /**
         * 根据 Content-Type 生成合适的文件后缀
         */
        private String generateFileName(String contentType) {
            String ext = ".dat";
            if (contentType != null) {
                if (contentType.contains("image/jpeg")) {
                    ext = ".jpg";
                } else if (contentType.contains("image/png")) {
                    ext = ".png";
                } else if (contentType.contains("image/gif")) {
                    ext = ".gif";
                } else if (contentType.contains("image/bmp")) {
                    ext = ".bmp";
                } else if (contentType.contains("image/webp")) {
                    ext = ".webp";
                }
            }
            return "img_" + System.currentTimeMillis() + ext;
        }

        /**
         * 简单的响应封装
         */
        private void sendResponse(HttpExchange exchange, int statusCode, String msg) throws IOException {
            byte[] bytes = msg.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "text/plain; charset=UTF-8");
            exchange.sendResponseHeaders(statusCode, bytes.length);
            try (OutputStream os = exchange.getResponseBody()) {
                os.write(bytes);
            }
        }
    }
}
```

### 说明

| 步骤 | 内容 |
|------|------|
| 1. `HttpServer.create(...)` | 创建 HTTP 服务器实例，绑定端口 8000。 |
| 2. `createContext("/upload", handler)` | 注册处理器，所有访问 `/upload` 的请求都会进入 `UploadHandler`。 |
| 3. `handle(HttpExchange)` | 只处理 POST 请求，将请求体逐块读入，写入磁盘。 |
| 4. `generateFileName(...)` | 根据 Content‑Type 生成文件名，并给出默认后缀。 |
| 5. `sendResponse(...)` | 简易响应写回给客户端。 |

---

## 3. 客户端示例（curl）

> **纯二进制上传（最简单）**  

```bash
curl -X POST --data-binary @/path/to/your/image.jpg http://localhost:8000/upload
```

> **multipart/form-data 上传（常见于浏览器表单）**  
> 这时服务器需要解析 multipart。示例仅演示上传，若想在 Java 端解析，可以使用 `com.sun.net.httpserver.HttpExchange` 与 `java.nio.file.Files` 等基础工具，或者直接使用 `org.apache.commons.fileupload`（需 servlet API，略微复杂）。  

```bash
