        System.out.println("Listening on " + PORT);
        Socket client = ss.accept();
        System.out.println("Client connected");

        /* 1. 启动 FFmpeg 子进程：ffmpeg -f h264 -i pipe:0 -f image2pipe -pix_fmt rgb24 - */
        ProcessBuilder pb = new ProcessBuilder(
                "ffmpeg",
                "-f", "h264",
                "-i", "pipe:0",
                "-f", "image2pipe",
                "-pix_fmt", "rgb24",
                "-vcodec", "rawvideo",
                "-");

        pb.redirectError(ProcessBuilder.Redirect.INHERIT);
        Process ffmpeg = pb.start();

        // 2. 把 socket 读出的数据写入 ffmpeg 的 stdin
        new Thread(() -> {
            try (OutputStream os = ffmpeg.getOutputStream();
                 InputStream is = client.getInputStream()) {
                byte[] buf = new byte[4096];
                int n;
                while ((n = is.read(buf)) != -1) {
                    os.write(buf, 0, n);
                    os.flush();
                }
                os.close(); // 结束 ffmpeg 输入
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();

        // 3. 读取 ffmpeg 输出的 rawrgb 数据，按帧大小（宽×高×3）切割
        // 这里需要你知道视频分辨率，下面假设 640x480
        final int WIDTH = 640;
        final int HEIGHT = 480;
        final int FRAME_SIZE = WIDTH * HEIGHT * 3; // 3 bytes per pixel (RGB)
        InputStream ffmpegOut = ffmpeg.getInputStream();
        byte[] frameBuf = new byte[FRAME_SIZE];
        while (ffmpegOut.read(frameBuf) == FRAME_SIZE) {
            BufferedImage img = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_RGB);
            int idx = 0;
            for (int y = 0; y < HEIGHT; y++) {
                for (int x = 0; x < WIDTH; x++) {
                    int r = frameBuf[idx++] & 0xFF;
                    int g = frameBuf[idx++] & 0xFF;
                    int b = frameBuf[idx++] & 0xFF;
                    int rgb = (r << 16) | (g << 8) | b;
                    img.setRGB(x, y, rgb);
                }
            }
            SwingUtilities.invokeLater(() -> {
                label.setIcon(new ImageIcon(img));
                frame.pack();
            });
        }

        ffmpeg.waitFor();
    }
}
```

> **关键点**  
> - 通过 `ffmpeg -i pipe:0` 让 FFmpeg 直接从标准输入读取裸 H.264。  
> - `-f image2pipe -pix_fmt rgb24 -vcodec rawvideo -` 把每一帧以 RGB24 原始像素流输出到标准输出，Java 读取即可。  
> - 需要预先知道视频分辨率（或在命令行里加 `-s WxH` 让 FFmpeg 输出时就知道）。  
> - 该方案在 Windows / Linux 上都能运行，只要系统上已安装 FFmpeg。

---

## 四、客户端发送 H.264 示例（Java）

下面给出一个极简的客户端，演示如何把本地 H.264 文件（或流）通过 Socket 发送给服务端。

```java
import java.io.*;
import java.net.Socket;

public class H264ClientSender {

    private static final String SERVER = "127.0.0.1";
    private static final int PORT = 5000;
    // 本地 H.264 文件路径
    private static final String FILE = "video.h264";

    public static void main(String[] args) throws IOException {
        try (Socket s = new Socket(SERVER, PORT);
             OutputStream out = s.getOutputStream();
             FileInputStream fin = new FileInputStream(FILE)) {

            byte[] buf = new byte[4096];
            int n;
            System.out.println("Sending H.264 ...");
            while ((n = fin.read(buf)) != -1) {
                out.write(buf, 0, n);
                out.flush();
            }
            System.out.println("Done.");
        }
    }
}
```

