## 3. The Client (JavaFX)

```java
/*  TicTacToeClient.java  */
import javafx.application.Application;
import javafx.application.Platform;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.*;
import javafx.stage.Stage;

import java.io.*;
import java.net.Socket;

public class TicTacToeClient extends Application {
    private static final String SERVER = "localhost";
    private static final int PORT = 5555;

    private char mySymbol = ' ';
    private boolean myTurn = false;

    private Socket socket;
    private BufferedReader in;
    private PrintWriter out;

    private Button[][] cells = new Button[3][3];
    private Label statusLabel = new Label("Connecting...");

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage primaryStage) {
        GridPane grid = new GridPane();
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                Button btn = new Button("");
                btn.setPrefSize(100, 100);
                int rr = r, cc = c;
                btn.setOnAction(e -> sendMove(rr, cc));
                cells[r][c] = btn;
                grid.add(btn, c, r);
            }
        }

        BorderPane root = new BorderPane();
        root.setCenter(grid);
        root.setBottom(statusLabel);
        BorderPane.setAlignment(statusLabel, javafx.geometry.Pos.CENTER);

        primaryStage.setTitle("Tic‑Tac‑Toe Client");
        primaryStage.setScene(new Scene(root));
        primaryStage.show();

        connectToServer();
    }

    private void connectToServer() {
        new Thread(() -> {
            try {
                socket = new Socket(SERVER, PORT);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new PrintWriter(socket.getOutputStream(), true);

                // Listen for server messages
                String line;
                while ((line = in.readLine()) != null) {
                    final String msg = line;
                    Platform.runLater(() -> handleServerMessage(msg));
                }
            } catch (IOException e) {
                e.printStackTrace();
                Platform.runLater(() -> statusLabel.setText("Connection failed"));
            }
        }).start();
    }

    private void sendMove(int r, int c) {
        if (!myTurn) return;
        out.println("MOVE " + r + " " + c);
    }

    private void handleServerMessage(String msg) {
        if (msg.startsWith("SYMBOL")) {                     // SYMBOL X or SYMBOL O
            mySymbol = msg.charAt(7);
            statusLabel.setText("You are '" + mySymbol + "'");
        } else if (msg.equals("YOUR_TURN")) {              // it is my turn
            myTurn = true;
            statusLabel.setText("Your turn");
            enableCells(true);
        } else if (msg.equals("WAIT")) {                    // opponent's turn
            myTurn = false;
            statusLabel.setText("Opponent's turn");
            enableCells(false);
        } else if (msg.startsWith("UPDATE")) {             // board update
            String boardStr = msg.substring(7);
            for (int i = 0; i < 9; i++) {
                char ch = boardStr.charAt(i);
                int r = i / 3;
                int c = i % 3;
                cells[r][c].setText(ch == '.' ? "" : String.valueOf(ch));
            }
        } else if (msg.startsWith("END")) {                // game over
            myTurn = false;
            enableCells(false);
            String result = msg.substring(4).trim();
            if ("DRAW".equals(result))
                statusLabel.setText("Draw!");
            else
                statusLabel.setText("Player " + result + " won!");
        } else if (msg.startsWith("ERROR")) {              // any error
            statusLabel.setText(msg);
        }
    }

    private void enableCells(boolean enable) {
        for (int r = 0; r < 3; r++)
            for (int c = 0; c < 3; c++)
                cells[r][c].setDisable(!enable || !cells[r][c].getText().isEmpty());
    }
}
```

**Client behaviour**

* Connects to the server on `localhost:5555`.  
* Receives its symbol (`X` or `O`) and the current board state.  
* When it is the client’s turn the board cells are enabled, otherwise they are disabled.  
* Clicking an empty cell sends `MOVE r c` to the server.  
* The client updates its UI whenever it receives an `UPDATE` or `END` message.

