import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.MemoryCacheImageOutputStream;

public class VideoSender {

    private static final String SERVER_HOST = "127.0.0.1";
    private static final int SERVER_PORT = 5000;
    private static final double JPEG_QUALITY = 0.9;  // 0~1

    public static void main(String[] args) {
        // 1. 创建帧抓取器（摄像头）或读取文件
        OpenCVFrameGrabber grabber = new OpenCVFrameGrabber(0);   // 0: 默认摄像头
        // OpenCVFrameGrabber grabber = new OpenCVFrameGrabber("sample.mp4");

        // 2. 连接服务器
        try (Socket socket = new Socket(SERVER_HOST, SERVER_PORT);
             DataOutputStream dos = new DataOutputStream(socket.getOutputStream())) {

            grabber.start();
            System.out.println("Started grabber and connected to server");

            // 3. 开始循环抓帧
            Frame frame;
            Java2DFrameConverter converter = new Java2DFrameConverter();
            AtomicBoolean stop = new AtomicBoolean(false);

            // 可选：另起线程监听键盘或 UI 事件来 set stop=true
            // 这里直接 30 秒后停止
            Thread stopper = new Thread(() -> {
                try {
                    Thread.sleep(30_000);
                } catch (InterruptedException ignored) {}
                stop.set(true);
            });
            stopper.start();

            while (!stop.get() && (frame = grabber.grab()) != null) {
                // 4. 转为 BufferedImage
                BufferedImage image = converter.getBufferedImage(frame);

                // 5. JPEG 编码
                byte[] jpegBytes = encodeJpeg(image, JPEG_QUALITY);

                // 6. 发送长度 + 数据
                dos.writeInt(jpegBytes.length);
                dos.write(jpegBytes);
                dos.flush();

                // 7. 控制帧率（可选）
                // Thread.sleep(33); // ~30fps
            }

            grabber.stop();
            System.out.println("Stopped grabbing");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /** JPEG 编码 helper */
    private static byte[] encodeJpeg(BufferedImage img, double quality) throws IOException {
        try (MemoryCacheImageOutputStream out = new MemoryCacheImageOutputStream(new java.io.ByteArrayOutputStream())) {
            // 取得 JPEG writer
            ImageWriter writer = ImageIO.getImageWritersByFormatName("jpg").next();
            writer.setOutput(out);

            ImageWriteParam param = writer.getDefaultWriteParam();
            param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
            param.setCompressionQuality((float) quality);

            writer.write(null, new IIOImage(img, null, null), param);
            writer.dispose();

            return ((java.io.ByteArrayOutputStream) out.getOutputStream()).toByteArray();
        }
    }
}
