## 2. 服务器端

### 2.1 `ChatServer.java`

```java
package com.ecommerce.chat;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class ChatServer {

    // 服务器监听端口
    private static final int PORT = 9876;

    // 用于记录已连接的客服会话（用户名 -> ClientHandler）
    private final Map<String, ClientHandler> clients = new ConcurrentHashMap<>();

    // 服务器主线程（监听新连接）
    public static void main(String[] args) {
        new ChatServer().startServer();
    }

    private void startServer() {
        System.out.println("ChatServer 启动，监听端口 " + PORT);
        try (ServerSocket ss = new ServerSocket(PORT)) {
            while (true) {
                Socket clientSocket = ss.accept();
                new Thread(new AcceptThread(clientSocket)).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /* ------------------- 内部线程 ------------------- */

    /** 处理新来的用户连接 */
    private class AcceptThread implements Runnable {
        private Socket socket;

        AcceptThread(Socket socket) { this.socket = socket; }

        @Override
        public void run() {
            try (
                ObjectInputStream ois  = new ObjectInputStream(socket.getInputStream());
                ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
            ) {
                // 先读取用户请求的用户名
                Message req = (Message) ois.readObject();
                if (req.getType() != Message.Type.TEXT) {
                    throw new IllegalStateException("第一次消息必须是用户名");
                }
                String username = req.getContent().trim();
                System.out.println("新用户 [" + username + "] 连接，等待客服响应…");

                // 弹窗提示客服端：接收还是拒绝
                SwingUtilities.invokeLater(() -> {
                    int choice = javax.swing.JOptionPane.showConfirmDialog(
                            null,
                            "用户 [" + username + "] 请求聊天，是否同意？",
                            "新会话请求",
                            javax.swing.JOptionPane.YES_NO_OPTION);
                    boolean accept = (choice == javax.swing.JOptionPane.YES_OPTION);
                    // 给客户端发送系统消息
                    Message resp = new Message(
                            Message.Type.SYSTEM,
                            accept ? "客服已同意接入" : "客服已拒绝接入",
                            null,
                            "客服");
                    try {
                        oos.writeObject(resp);
                        oos.flush();
                    } catch (IOException e) { e.printStackTrace(); }

                    if (accept) {
                        // 开启客服会话线程
                        ClientHandler handler = new ClientHandler(
                                username, socket, ois, oos);
                        clients.put(username, handler);
                        new Thread(handler).start();
                    } else {
                        // 拒绝后关闭连接
                        socket.close();
                    }
                });

            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
                try { socket.close(); } catch (IOException ignored) {}
            }
        }
    }

    /** 为单个客服会话服务：读写消息、记录聊天 */
    private class ClientHandler implements Runnable {
        private String username;
        private Socket socket;
        private ObjectInputStream  ois;
        private ObjectOutputStream oos;
        private File chatFile;        // 聊天记录文件

        ClientHandler(String username,
                      Socket socket,
                      ObjectInputStream ois,
                      ObjectOutputStream oos) throws IOException {
            this.username = username;
            this.socket   = socket;
            this.ois      = ois;
            this.oos      = oos;
            this.chatFile = new File("chat_history_" + username + ".txt");
            // 如果文件已存在，先把内容发给客户端
            if (chatFile.exists()) {
                List<String> lines = java.nio.file.Files.readAllLines(chatFile.toPath());
                for (String line : lines) {
                    // 直接写回给客户端，客户端会把它显示在聊天框
                    oos.writeObject(new Message(
                            Message.Type.SYSTEM,
                            line, null, "客服"));
                    oos.flush();
                }
            }
        }

        @Override
        public void run() {
            System.out.println("客服会话 [" + username + "] 开始");
            try {
                while (true) {
                    Message msg = (Message) ois.readObject();
                    // 写入聊天文件
                    saveToHistory(msg);

                    // 这里把消息简单转发回客户端（因为是双向聊天）
                    // 只要服务器收到，直接写给对应的客户端
                    // （在多客服场景下可能还需转发给其它客服）
                    oos.writeObject(msg);
                    oos.flush();
                }
            } catch (IOException | ClassNotFoundException e) {
                System.out.println("客服会话 [" + username + "] 关闭");
            } finally {
                clients.remove(username);
                try { socket.close(); } catch (IOException ignored) {}
            }
        }

        private void saveToHistory(Message msg) {
            String line = String.format("[%s] %s: %s\n",
                    msg.getTimestamp(), msg.getFrom(), msg.getContent());
            try (FileWriter fw = new FileWriter(chatFile, true)) {
                fw.write(line);
            } catch (IOException e) { e.printStackTrace(); }
        }
    }
}
```

> **说明**  
> * 服务器启动后，监听 `PORT`，每个连接都交给 `AcceptThread` 处理。  
> * `AcceptThread` 首先读取用户的用户名，弹窗询问客服是否同意。若同意，创建 `ClientHandler` 并开启线程；若拒绝，直接关闭连接。  
> * `ClientHandler` 负责与单个用户的持续通信：读取 `Message`、写入聊天文件、原样回写给客户端。  
> * 聊天记录文件采用 **txt** 存储，简单明了；如果想要更结构化可改成 JSON 或数据库。

