        String[] suits = {"Heart", "Diamond", "Spade", "Club"};
        for (String suit : suits) {
            cards.add(new Card(suit, "Ace", 1));
            for (int n = 2; n <= 10; n++)
                cards.add(new Card(suit, Integer.toString(n), n));
            cards.add(new Card(suit, "Jack", 10));
            cards.add(new Card(suit, "Queen", 10));
            cards.add(new Card(suit, "King", 10));
        }
    }

    public void shuffle() { Collections.shuffle(cards); }

    public Card dealCard() { return cards.remove(0); }
}
