public class AdminModule {
    private static final String ADMIN_FILE   = "admin.txt";
    private static final String PLAYERS_FILE = "players.bin";

    private String adminHash;            // stored SHA‑256 hash
    private final List<Player> players = new ArrayList<>();

    /* ----------------------------------------------------------------- */
    /*  Persistence helpers                                              */
    /* ----------------------------------------------------------------- */
    private void loadAdmin() {
        try (BufferedReader br = new BufferedReader(new FileReader(ADMIN_FILE))) {
            adminHash = br.readLine().trim();
        } catch (IOException e) {
            System.out.println("Admin file not found – creating default admin.");
            adminHash = Utility.getHash("admin123");   // default password
            saveAdmin();                              // create file
        }
    }

    private void saveAdmin() {
        try (PrintWriter pw = new PrintWriter(new FileWriter(ADMIN_FILE))) {
            pw.println(adminHash);
        } catch (IOException e) {
            System.err.println("Unable to write admin file: " + e.getMessage());
        }
    }

    @SuppressWarnings("unchecked")
    private void loadPlayers() {
        File f = new File(PLAYERS_FILE);
        if (!f.exists()) {                 // first run – create empty list
            System.out.println("No players file found – starting fresh.");
            return;
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            Object obj = ois.readObject();
            if (obj instanceof List<?>) {
                for (Object o : (List<?>) obj) {
                    if (o instanceof Player) players.add((Player) o);
                }
            }
        } catch (Exception e) {
            System.err.println("Error reading players.bin: " + e.getMessage());
        }
    }

    private void savePlayers() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYERS_FILE))) {
            oos.writeObject(players);
        } catch (IOException e) {
            System.err.println("Error writing players.bin: " + e.getMessage());
        }
    }

    /* ----------------------------------------------------------------- */
    /*  Admin operations                                                 */
    /* ----------------------------------------------------------------- */
    private void createPlayer() {
        String name = Keyboard.readString("Enter new player name: ");
        String pwd  = Keyboard.readString("Enter password: ");
        int chips   = Keyboard.readInt("Initial chips: ");
        players.add(new Player(name, pwd, chips));
        System.out.println("Player created.");
    }

    private void deletePlayer() {
        String name = Keyboard.readString("Enter player name to delete: ");
        Optional<Player> opt = players.stream()
                                      .filter(p -> p.getLoginName().equals(name))
                                      .findFirst();
        if (opt.isPresent()) {
            players.remove(opt.get());
            System.out.println("Player deleted.");
        } else {
            System.out.println("Player not found.");
        }
    }

    private void viewAllPlayers() {
        System.out.println("\n--- All Players ---");
        for (Player p : players) {
            System.out.println(p.getLoginName() + " | Chips: " + p.getChips());
        }
        System.out.println("-------------------\n");
