    private void resetPassword() {
        String name = Keyboard.readString("Enter player name: ");
        Optional<Player> opt = players.stream()
                                      .filter(p -> p.getLoginName().equals(name))
                                      .findFirst();
        if (opt.isPresent()) {
            String newPwd = Keyboard.readString("Enter new password: ");
            opt.get().setPassword(newPwd);
            System.out.println("Password reset.");
        } else {
            System.out.println("Player not found.");
        }
