    private void changeAdminPassword() {
        String oldPwd = Keyboard.readString("Enter current admin password: ");
        if (!adminHash.equals(Utility.getHash(oldPwd))) {
            System.out.println("Wrong password.");
            return;
        }
        String newPwd = Keyboard.readString("Enter new admin password: ");
        adminHash = Utility.getHash(newPwd);
        System.out.println("Admin password changed.");
        saveAdmin();
