    /* ----------------------------------------------------------------- */
    /*  Main admin UI                                                    */
    /* ----------------------------------------------------------------- */
    private void run() {
        loadAdmin();
        loadPlayers();

        while (true) {
            System.out.println("\n=== HighSum Admin Module ===");
            System.out.println("1. Create a player");
            System.out.println("2. Delete a player");
            System.out.println("3. View all players");
            System.out.println("4. Issue more chips to a player");
            System.out.println("5. Reset player’s password");
            System.out.println("6. Change administrator’s password");
            System.out.println("7. Logout");
            int choice = Keyboard.readInt("Select an option: ");

            switch (choice) {
                case 1: createPlayer(); break;
                case 2: deletePlayer(); break;
                case 3: viewAllPlayers(); break;
                case 4: issueChips(); break;
                case 5: resetPassword(); break;
                case 6: changeAdminPassword(); break;
                case 7:
                    System.out.println("Logging out…");
                    savePlayers();     // persist changes before exit
                    return;
                default:
                    System.out.println("Invalid choice.");
            }
        }
    }

    /* ----------------------------------------------------------------- */
    /*  Entry point                                                      */
    /* ----------------------------------------------------------------- */
    public static void main(String[] args) {
        // Admin login first
        System.out.println("=== HighSum Administration Login ===");
        boolean loggedIn = false;
        while (!loggedIn) {
            String pwd = Keyboard.readString("Enter admin password: ");
            if (Utility.getHash(pwd).equals(new AdminModule().adminHash)) {
                loggedIn = true;
            } else {
                System.out.println("Wrong password – try again.");
            }
        }

        // Start the admin menu
        new AdminModule().run();
    }
}
```

> **How the login works**  
> The `AdminModule` constructor reads the hashed password from `admin.txt`.  
> In `main()` we read the entered password, hash it, and compare with the stored hash.  
> If it matches we instantiate the module and start the menu.

