```java
import java.util.*;

public class GameModule {
    private static final String PLAYERS_FILE = "players.bin";
    private final List<Player> players = new ArrayList<>();

    /* ----------------------------------------------------------------- */
    /*  Load / save player list                                           */
    /* ----------------------------------------------------------------- */
    @SuppressWarnings("unchecked")
    private void loadPlayers() {
        File f = new File(PLAYERS_FILE);
        if (!f.exists()) {
            System.out.println("No player data found. Please create a player in the admin module first.");
            System.exit(0);
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            Object obj = ois.readObject();
            if (obj instanceof List<?>) {
                for (Object o : (List<?>) obj) {
                    if (o instanceof Player) players.add((Player) o);
                }
            }
        } catch (Exception e) {
            System.err.println("Failed to read players.bin: " + e.getMessage());
            System.exit(0);
        }
    }

    /* ----------------------------------------------------------------- */
    /*  Find player helper                                               */
    /* ----------------------------------------------------------------- */
    private Player findPlayer(String name) {
        return players.stream()
                      .filter(p -> p.getLoginName().equals(name))
                      .findFirst()
                      .orElse(null);
    }

    /* ----------------------------------------------------------------- */
    /*  Main game loop                                                   */
    /* ----------------------------------------------------------------- */
    public void run() {
        loadPlayers();                      // load all registered players

        System.out.println("HighSum GAME");
        System.out.println("==================================================================");

        /* ---------- login ------------------------------------------------- */
        Player player = null;
        while (player == null) {
            String name = Keyboard.readString("Enter Login name > ");
            String pwd  = Keyboard.readString("Enter Password > ");

            Player tmp = findPlayer(name);
            if (tmp != null && tmp.checkPassword(pwd)) {
                player = tmp;
                System.out.println("Login successful – welcome " + player.getLoginName());
            } else {
                System.out.println("Username or Password is incorrect. Please try again.");
            }
        }

        Dealer dealer = new Dealer();
        Deck deck     = new Deck();

        boolean nextGame = true;
        int    betOnTable;
        boolean playerQuit = false;

        /* ---------- game loop ------------------------------------------- */
        while (nextGame) {
            System.out.println("==================================================================");
            System.out.println(player.getLoginName() + ", you have " + player.getChips() + " chips");
            System.out.println("------------------------------------------------------------------");
            System.out.println("Game starts – Dealer shuffles deck.");

            deck.shuffle();
            dealer.clearCardsOnHand();
            player.clearCardsOnHand();

            // Deal two cards to dealer & player (dealer first)
            for (int i = 0; i < 2; i++) {
                dealer.addCard(deck.dealCard());
                player.addCard(deck.dealCard());
            }

            betOnTable = 0;
            int round = 1;

            while (round <= 4) {
                System.out.println("------------------------------------------------------------------");
                System.out.println("Dealer dealing cards – ROUND " + round);

                if (round == 2) {
                    dealer.addCard(deck.dealCard());
                    player.addCard(deck.dealCard());
                }

                dealer.showCardsOnHand();
                player.showCardsOnHand();
                System.out.println("Value: " + player.getTotalCardsValue());

                if (round > 1) {
                    dealer.addCard(deck.dealCard());
                    player.addCard(deck.dealCard());
                }

                if (round == 4) dealer.revealHiddenCard();

                /* ---------- betting logic ------------------------------------ */
                if (round >= 2) {
                    if (player.getTotalCardsValue() > dealer.getTotalCardsValue()) {
                        boolean validChoice = false;
                        while (!validChoice) {
                            String prompt = (round == 2)
                                ? "Do you want to follow? [Y/N]: "
                                : "Player call, do you want to [C]all or [Q]uit?: ";
                            String choice = Keyboard.readString(prompt).toLowerCase();
                            if (choice.equals("c") || choice.equals("y")) {
                                validChoice = true;
                                int playerBet = Keyboard.readInt("Player, state your bet > ");

                                if (playerBet > 100) {
                                    System.out.println("Insufficient chips");
                                    validChoice = false;
                                } else if (playerBet <= 0) {
                                    System.out.println("Invalid bet");
                                    validChoice = false;
                                } else {
                                    betOnTable += playerBet;
                                    player.deductChips(playerBet);
                                    System.out.println("Player bet: " + playerBet);
                                    System.out.println("You have " + player.getChips() + " chips");
                                    System.out.println("Bet on table: " + betOnTable);
                                    round++;
                                }
                            } else if (choice.equals("q") || choice.equals("n")) {
                                validChoice = true;
                                nextGame = false;
                                round = 5;
                                playerQuit = true;
                                System.out.println("Player quit – Dealer wins all chips on table.");
                                System.out.println("Dealer Wins");
                                break;
                            }
                        }
                    } else {
                        int dealerBet = Math.min(new Random().nextInt(11), 10);
                        betOnTable += dealerBet;
                        System.out.println("Dealer bet: " + dealerBet);
                        System.out.println("You have " + player.getChips() + " chips");
                        System.out.println("Bet on table: " + betOnTable);
                        round++;
                    }
                } else {
                    int dealerBet = 10;
                    betOnTable += dealerBet;
                    player.deductChips(dealerBet);
                    System.out.println("Dealer bet: " + dealerBet);
                    System.out.println("You have " + player.getChips() + " chips");
                    System.out.println("Bet on table: " + betOnTable);
                    round++;
                }
            }

            /* ---------- determine winner ----------------------------------- */
            if (!playerQuit) {
                System.out.println("------------------------------------------------------------------");
                System.out.println("Game End – Dealer reveals hidden cards");
                System.out.println("------------------------------------------------------------------");
                dealer.showCardsOnHand();
                System.out.println("Dealer value: " + dealer.getTotalCardsValue());
                System.out.println("Player value: " + player.getTotalCardsValue());

                if (player.getTotalCardsValue() > dealer.getTotalCardsValue()) {
                    System.out.println(player.getLoginName() + " Wins");
                    player.addChips(betOnTable);
                } else {
                    System.out.println("Dealer Wins");
                }

                System.out.println(player.getLoginName() + ", you have " + player.getChips() + " chips");
                System.out.println("Dealer shuffles used cards and places them behind the deck.");
            }

            /* ---------- next round? ---------------------------------------- */
            while (true) {
                String input = Keyboard.readString("Next Game? (Y/N) > ").toLowerCase();
                if (input.equals("y")) {
                    playerQuit = false;
                    nextGame = true;
                    break;
                } else if (input.equals("n")) {
                    nextGame = false;
                    break;
                } else {
                    System.out.println("*** Please enter Y or N ***");
                }
            }
        }

        /* ----------------------------------------------------------------- */
        /*  Persist any chip changes back to players.bin                      */
        /* ----------------------------------------------------------------- */
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYERS_FILE))) {
            oos.writeObject(players);
        } catch (IOException e) {
            System.err.println("Failed to write players.bin: " + e.getMessage());
        }
    }

    /* ----------------------------------------------------------------- */
    /*  Entry point                                                      */
    /* ----------------------------------------------------------------- */
    public static void main(String[] args) {
        new GameModule().run();
    }
}
```

> **Why `players` is saved again**  
> The player object that has been modified during the game (chips have changed) is the same instance that is stored inside the `players` list. Therefore writing the list back to `players.bin` automatically persists all chip changes.

