// JwtUtil.java
package com.example.websocket.service;

import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.DecodedJWT;
import org.springframework.stereotype.Component;

import java.util.Date;

@Component
public class JwtUtil {
    private final String secret = "VerySecretKeyVerySecretKey";
    private final long expireMs = 60 * 60 * 1000; // 1h

    public String generateToken(String username) {
        return JWT.create()
                .withSubject(username)
                .withIssuedAt(new Date())
                .withExpiresAt(new Date(System.currentTimeMillis() + expireMs))
                .sign(Algorithm.HMAC256(secret));
    }

    public String validateToken(String token) {
        DecodedJWT decoded = JWT.require(Algorithm.HMAC256(secret)).build().verify(token);
        return decoded.getSubject();
    }
}
```

> 生产环境请把 secret 存在配置中心或环境变量。

