    private final WebSocketAuthInterceptor authInterceptor;

    public WebSocketConfig(WebSocketAuthInterceptor authInterceptor) {
        this.authInterceptor = authInterceptor;
    }

    @Override
    public void registerStompEndpoints(StompEndpointRegistry registry) {
        registry.addEndpoint("/ws")      // 浏览器握手地址
                .setAllowedOrigins("https://yourdomain.com") // CORS
                .addInterceptors(authInterceptor)          // 绑定 Principal
                .withSockJS(); // 可选（回退）
    }

    @Override
    public void configureMessageBroker(MessageBrokerRegistry config) {
        config.enableSimpleBroker("/topic", "/queue"); // 代理路径
        config.setApplicationDestinationPrefixes("/app"); // 客户端发送前缀
        config.setUserDestinationPrefix("/user"); // 个人消息前缀
    }
