### 4.2 `WebSocketAuthInterceptor`

```java
// WebSocketAuthInterceptor.java
package com.example.websocket.handler;

import com.example.websocket.service.JwtUtil;
import org.springframework.http.server.ServerHttpRequest;
import org.springframework.http.server.ServerHttpResponse;
import org.springframework.messaging.simp.SimpMessageHeaderAccessor;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.stereotype.Component;
import org.springframework.web.socket.WebSocketHandler;
import org.springframework.web.socket.server.HandshakeInterceptor;

import java.util.Collections;
import java.util.Map;

@Component
public class WebSocketAuthInterceptor implements HandshakeInterceptor {

    private final JwtUtil jwtUtil;

    public WebSocketAuthInterceptor(JwtUtil jwtUtil) {
        this.jwtUtil = jwtUtil;
    }

    @Override
    public boolean beforeHandshake(
            ServerHttpRequest request,
            ServerHttpResponse response,
            WebSocketHandler wsHandler,
            Map<String, Object> attributes) {

        // 1️⃣ 取出 Authorization header
        String token = request.getHeaders().getFirst("Authorization");
        if (token == null || !token.startsWith("Bearer ")) {
            return false; // 拒绝握手
        }
        token = token.substring(7);

        try {
            // 2️⃣ 验证 token，获取 username
            String username = jwtUtil.validateToken(token);

            // 3️⃣ 用 Spring Security 的 Authentication 对象包装
            UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken(
                    username, null,
                    Collections.singletonList(new SimpleGrantedAuthority("ROLE_USER"))
            );
            // 4️⃣ 放进 attributes，后面会在 Principal 中使用
            attributes.put("user", auth);
        } catch (Exception ex) {
            return false;
        }
        return true;
    }

    @Override
    public void afterHandshake(
            ServerHttpRequest request,
            ServerHttpResponse response,
            WebSocketHandler wsHandler,
            Exception exception) {
        // nothing to do
    }
}
```

> **说明**  
> * `HandshakeInterceptor` 只会在第一次握手时触发。  
> * 把 `Authentication` 放进 `attributes` 后，Spring 会把它自动转成 `Principal`。  
> * 若你想使用 Cookie+Session，只需把 `HttpSession` 从 `request` 里取出来即可。

