    console.log('connected', frame);
    // ① 订阅公共频道
    stomp.subscribe('/topic/public', function(msg) {
        appendMessage(JSON.parse(msg.body));
    });
    // ② 订阅私聊
    stomp.subscribe('/user/queue/private', function(msg) {
        appendMessage(JSON.parse(msg.body));
    });
});

function send() {
    let content = document.getElementById('msg').value;
    stomp.send("/app/chat/public", {}, JSON.stringify({'content': content, 'type': 'TEXT'}));
}

