import java.io.*;
import java.net.*;
import java.text.SimpleDateFormat;
import java.util.Date;

/**
 * 服务器端实现
 * 监听端口 12345，处理客户端请求
 */
class TimeServer implements Runnable {

    private final int port;
    private ServerSocket serverSocket;
    private volatile boolean running = true;   // 标记服务器是否继续监听

    public TimeServer(int port) {
        this.port = port;
    }

    public void run() {
        try {
            serverSocket = new ServerSocket(port);
            System.out.println("[Server] 已启动，等待客户端连接…");

            while (running) {
                Socket client = serverSocket.accept();
                System.out.println("[Server] 与客户端建立连接：" + client.getRemoteSocketAddress());

                // 处理客户端请求的线程
                new Thread(() -> handleClient(client)).start();
            }
        } catch (IOException e) {
            if (running) { // 只在异常是非正常关闭时打印
                e.printStackTrace();
            }
        }
    }

    /**
     * 处理单个客户端的请求
     */
    private void handleClient(Socket client) {
        try (
                BufferedReader in  = new BufferedReader(
                        new InputStreamReader(client.getInputStream(), "UTF-8"));
                BufferedWriter out = new BufferedWriter(
                        new OutputStreamWriter(client.getOutputStream(), "UTF-8"))
        ) {
            String line;
            while ((line = in.readLine()) != null) {
                System.out.println("[Server] 收到：" + line);

                // 解析 “From 学号 姓名： 语句”
                // 只需要提取姓名和后面要执行的命令
                String[] parts = line.split("：", 2); // 2 表示最多分成 2 份
                if (parts.length != 2) {
                    out.write("[Server] 解析错误，格式不正确\n");
                    out.flush();
                    continue;
                }
                String from = parts[0].trim();      // From 学号 姓名
                String command = parts[1].trim();   // 语句

                // 从 from 字符串里提取姓名（姓名在最后一个空格后面）
                String name = from.substring(from.lastIndexOf(' ') + 1);

                if (command.equalsIgnoreCase("Exit")) {
                    String byeMsg = "To " + name + "：Bye";
                    out.write(byeMsg + "\n");
                    out.flush();
                    System.out.println("[Server] 发送：" + byeMsg);
                    break; // 退出循环，关闭连接
                } else { // 其它命令，返回当前时间
                    String now = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date());
                    String timeMsg = "To " + name + "：当前时间是 " + now;
                    out.write(timeMsg + "\n");
                    out.flush();
                    System.out.println("[Server] 发送：" + timeMsg);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                client.close();
                System.out.println("[Server] 与客户端断开连接");
            } catch (IOException ignored) { }
        }
    }

    public void stop() {
        running = false;
        try {
            serverSocket.close();
        } catch (IOException ignored) { }
    }
}

/**
 * 客户端实现
 * 负责向服务器发送请求并读取返回值
