```java
package com.example.dao;

import com.example.model.Unit;
import com.example.util.DBUtil;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class UnitDAO {
    public List<Unit> findByParent(Integer parentId) throws SQLException {
        String sql = "SELECT id, name, parent_id, level FROM units WHERE parent_id " + (parentId==null ? "IS NULL" : "= ?");
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            if (parentId != null) ps.setInt(1, parentId);
            ResultSet rs = ps.executeQuery();
            List<Unit> list = new ArrayList<>();
            while (rs.next()) {
                Unit u = new Unit();
                u.setId(rs.getInt("id"));
                u.setName(rs.getString("name"));
                u.setParentId(rs.getObject("parent_id") != null ? rs.getInt("parent_id") : null);
                u.setLevel(rs.getInt("level"));
                list.add(u);
            }
            return list;
        }
    }

    public Unit findById(int id) throws SQLException {
        String sql = "SELECT id, name, parent_id, level FROM units WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, id);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                Unit u = new Unit();
                u.setId(id);
                u.setName(rs.getString("name"));
                u.setParentId(rs.getObject("parent_id") != null ? rs.getInt("parent_id") : null);
                u.setLevel(rs.getInt("level"));
                return u;
            }
            return null;
        }
    }
}
```

