package com.example.dao;

import com.example.model.Customer;
import com.example.util.DBUtil;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class CustomerDAO {
    public void insert(Customer c) throws SQLException {
        String sql = "INSERT INTO customers(unit_id, name, phone, mobile, qq, email) VALUES(?,?,?,?,?,?)";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, c.getUnitId());
            ps.setString(2, c.getName());
            ps.setString(3, c.getPhone());
            ps.setString(4, c.getMobile());
            ps.setString(5, c.getQq());
            ps.setString(6, c.getEmail());
            ps.executeUpdate();
        }
    }

    public void update(Customer c) throws SQLException {
        String sql = "UPDATE customers SET unit_id=?, name=?, phone=?, mobile=?, qq=?, email=? WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, c.getUnitId());
            ps.setString(2, c.getName());
            ps.setString(3, c.getPhone());
            ps.setString(4, c.getMobile());
            ps.setString(5, c.getQq());
            ps.setString(6, c.getEmail());
            ps.setInt(7, c.getId());
            ps.executeUpdate();
        }
    }

    public void delete(int id) throws SQLException {
        String sql = "DELETE FROM customers WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, id);
            ps.executeUpdate();
        }
    }

    public Customer findById(int id) throws SQLException {
        String sql = "SELECT * FROM customers WHERE id=?";
        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setInt(1, id);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                Customer c = new Customer();
                c.setId(rs.getInt("id"));
                c.setUnitId(rs.getInt("unit_id"));
                c.setName(rs.getString("name"));
                c.setPhone(rs.getString("phone"));
                c.setMobile(rs.getString("mobile"));
                c.setQq(rs.getString("qq"));
                c.setEmail(rs.getString("email"));
                return c;
            }
            return null;
        }
    }

    /*** 按姓名 / 单位 / 模糊搜索 ***/
    public List<Customer> search(String name, Integer unitId, String keyword) throws SQLException {
        StringBuilder sb = new StringBuilder("SELECT c.*, u.name AS unitName FROM customers c JOIN units u ON c.unit_id=u.id WHERE 1=1");
        List<Object> params = new ArrayList<>();
        if (name!=null && !name.isEmpty()) {
            sb.append(" AND c.name LIKE ?");
            params.add("%"+name+"%");
        }
        if (unitId!=null) {
            sb.append(" AND c.unit_id=?");
            params.add(unitId);
        }
        if (keyword!=null && !keyword.isEmpty()) {
            sb.append(" AND (c.name LIKE ? OR c.phone LIKE ? OR c.mobile LIKE ? OR c.qq LIKE ? OR c.email LIKE ?)");
            String k = "%"+keyword+"%";
            for(int i=0;i<5;i++) params.add(k);
        }

        try (Connection conn = DBUtil.getConnection();
             PreparedStatement ps = conn.prepareStatement(sb.toString())) {
            for (int i = 0; i < params.size(); i++) ps.setObject(i+1, params.get(i));
            ResultSet rs = ps.executeQuery();
            List<Customer> list = new ArrayList<>();
            while (rs.next()) {
                Customer c = new Customer();
                c.setId(rs.getInt("id"));
                c.setUnitId(rs.getInt("unit_id"));
                c.setName(rs.getString("name"));
                c.setPhone(rs.getString("phone"));
                c.setMobile(rs.getString("mobile"));
                c.setQq(rs.getString("qq"));
                c.setEmail(rs.getString("email"));
                list.add(c);
            }
            return list;
        }
    }
}
