### 3.1 UnitAjaxServlet.java（返回单位列表 JSON）

```java
package com.example.servlet;

import com.example.dao.UnitDAO;
import com.example.model.Unit;
import com.fasterxml.jackson.databind.ObjectMapper;   // Jackson 依赖
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;
import java.io.IOException;
import java.sql.SQLException;
import java.util.List;

@WebServlet("/ajax/getUnits")
public class UnitAjaxServlet extends HttpServlet {
    private final UnitDAO dao = new UnitDAO();
    private final ObjectMapper mapper = new ObjectMapper();

    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        Integer parent = null;
        try { parent = Integer.valueOf(req.getParameter("parent")); } catch (Exception ignored) {}
        try {
            List<Unit> units = dao.findByParent(parent);
            resp.setContentType("application/json;charset=UTF-8");
            mapper.writeValue(resp.getWriter(), units);
        } catch (SQLException e) {
            throw new ServletException(e);
        }
    }
}
```

> **依赖**：`com.fasterxml.jackson.core:jackson-databind`。

