## 5. JavaScript：三级级联

**`/js/cascade.js`**

```javascript
/**
 * loadNext(parentLevel, parentId, nextLevel, selectedUnitId)
 * @param parentLevel 0 表示从根层级开始
 * @param parentId 父级 id（null 时表示无父级）
 * @param nextLevel 要加载的下一级 (1,2,3)
 * @param selectedUnitId 当前选中的单位 id（可选，用于回填）
 */
function loadNext(parentLevel, parentId, nextLevel, selectedUnitId) {
    const sel = $('#level' + nextLevel);
    sel.empty().append('<option value="">-- 请选择 --</option>');
    // 如果是层级 1 则直接请求顶层单位
    if (parentLevel === 0) parentId = null;

    $.getJSON('${pageContext.request.contextPath}/ajax/getUnits', {parent: parentId}, function(units){
        $.each(units, function(i,u){
            const opt = $('<option>').val(u.id).text(u.name);
            if(selectedUnitId && u.id == selectedUnitId) opt.attr('selected',true);
            sel.append(opt);
        });
        // 如果已经有选中的 id，继续向下加载
        if(selectedUnitId){
            // 递归：先找出当前 id 对应的 parent，然后再加载
            // 这里简化，直接从后端获取子级并回填
            $.getJSON('${pageContext.request.contextPath}/ajax/getUnits', {parent: selectedUnitId}, function(sub){
                if(sub.length>0){
                    loadNext(nextLevel, selectedUnitId, nextLevel+1, selectedUnitId);
                }
            });
        }
    });
}
```

> 该脚本基于 jQuery，使用 `$.getJSON` 异步调用 `UnitAjaxServlet`。  
> 只要把 **单位的 id** 填在 `name="unitId"` 的 `<select>` 上，表单提交时就能得到最终的 `unitId`。

