## 5. Android（MediaCodec）示例

```java
import android.graphics.Bitmap;
import android.media.MediaCodec;
import android.media.MediaFormat;
import android.view.Surface;
import java.io.OutputStream;
import java.net.Socket;
import java.nio.ByteBuffer;

public class AndroidEncoder {
    private MediaCodec encoder;
    private int width, height, bitrate;
    private Socket socket;
    private OutputStream out;

    public AndroidEncoder(int width, int height, int bitrate, String host, int port) throws Exception {
        this.width = width;
        this.height = height;
        this.bitrate = bitrate;

        encoder = MediaCodec.createEncoderByType("video/avc");
        MediaFormat format = MediaFormat.createVideoFormat("video/avc", width, height);
        format.setInteger(MediaFormat.KEY_BIT_RATE, bitrate);
        format.setInteger(MediaFormat.KEY_FRAME_RATE, 30);
        format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL, 2);
        format.setInteger(MediaFormat.KEY_COLOR_FORMAT,
                MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);
        encoder.configure(format, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE);
        encoder.start();

        socket = new Socket(host, port);
        out = socket.getOutputStream();
    }

    public void encodeAndSend(Bitmap bmp) throws Exception {
        // 将 Bitmap 转成 YUV420 并写入 encoder 的 surface
        // 这里略去实现细节，你可以用 RenderScript 或 NV21
        // 或者直接把 Surface 绑定到 TextureView 并 drawBitmap

        // 读取输出
        MediaCodec.BufferInfo info = new MediaCodec.BufferInfo();
        while (true) {
            int outIndex = encoder.dequeueOutputBuffer(info, 0);
            if (outIndex >= 0) {
                ByteBuffer buffer = encoder.getOutputBuffer(outIndex);
                byte[] data = new byte[info.size];
                buffer.get(data);
                out.write(intToBytes(data.length));
                out.write(data);
                encoder.releaseOutputBuffer(outIndex, false);
                break;
            } else if (outIndex == MediaCodec.INFO_TRY_AGAIN_LATER) {
                break; // 还没生成帧
            }
        }
    }

    public void close() throws Exception {
        encoder.stop();
        encoder.release();
        out.close();
        socket.close();
    }

    private static byte[] intToBytes(int v) {
        return new byte[] {
                (byte) (v >>> 24),
                (byte) (v >>> 16),
                (byte) (v >>> 8),
                (byte) v
        };
    }
}
```

> **Android 版**  
> * 需要把 `Bitmap` 先渲染到 `Surface`（例如 `SurfaceTexture`）再让 `MediaCodec` 编码。  
> * 编码后的输出是 `AVC` NAL 包，和 JavaCV 的返回值结构相同。  
> * 发送时同样加长度前缀。

