import java.io.IOException;
import java.io.PrintWriter;
import java.net.Socket;
import java.net.UnknownHostException;
import java.util.Scanner;

public class ClientMain {

    /* ------------------------------------------------------------------ */
    /*  Utility – prints the menu that the user can choose from           */
    /* ------------------------------------------------------------------ */
    private static void printMenu() {
        System.out.println("\n===== Hotel‑Service Client Menu =====");
        System.out.println("  register <username> <password>          – Create a new account");
        System.out.println("  login    <username> <password>          – Login to an existing account");
        System.out.println("  logout   <username>                    – Logout from the account");
        System.out.println("  searchHotel <hotelName> <city>          – Find a specific hotel");
        System.out.println("  searchAllHotels <city>                 – List all hotels in a city");
        System.out.println("  showMyBadges                           – Show the badges of the logged user");
        System.out.println("  quit | exit                            – Terminate the client");
        System.out.println("========================================");
        System.out.print("Enter a command: ");
    }

    /* ------------------------------------------------------------------ */
    /*  Main routine – handles the socket, the menu and the command flow   */
    /* ------------------------------------------------------------------ */
    public static void main(String[] args) {
        String serverIP = "127.0.0.1";
        int serverPort = 10000;          // port on which the server listens

        Scanner console = null;   // reads from System.in
        Scanner fromServer = null; // reads from the socket

        try (Socket socket = new Socket(serverIP, serverPort)) {

            console   = new Scanner(System.in);
            fromServer = new Scanner(socket.getInputStream());
            PrintWriter toServer = new PrintWriter(socket.getOutputStream(), true);

            while (true) {
                printMenu();
                String line = console.nextLine().trim();

                if (line.isEmpty()) {
                    continue; // no command entered
                }

                // split only the first token (command) from the rest of the line
                String[] tokens = line.split("\\s+", 2);
                String command = tokens[0].toLowerCase();

                // ---------- handle special commands that do not need server interaction ----------
                if ("quit".equals(command) || "exit".equals(command)) {
                    System.out.println("Closing the client. Goodbye!");
                    break;
                }

                // ---------- validate the number of arguments ----------
                boolean valid = true;
                switch (command) {
                    case "register":
                    case "login":
                        valid = tokens.length == 2 && tokens[1].trim().split("\\s+").length == 2;
                        break;
                    case "logout":
                        valid = tokens.length == 2 && !tokens[1].trim().isEmpty();
                        break;
                    case "searchhotel":
                        valid = tokens.length == 2 && tokens[1].trim().split("\\s+").length == 2;
                        break;
                    case "searchallhotels":
                        valid = tokens.length == 2 && !tokens[1].trim().isEmpty();
                        break;
                    case "showmybadges":
                        valid = tokens.length == 1;
                        break;
                    default:
                        System.out.println("Unknown command: " + command);
                        continue;
                }

                if (!valid) {
                    System.out.println("Incorrect usage of command '" + command + "'.");
                    continue;
                }

                /* ------------------------------------------------------------------ */
                /*  Send the command line verbatim to the server and print the reply   */
                /* ------------------------------------------------------------------ */
                toServer.println(line);          // send the full line to the server
                String response = fromServer.nextLine(); // read the server's reply
                System.out.println("Server: " + response);
            }
        } catch (UnknownHostException e) {
            System.out.println("Server address could not be resolved: " + e.getMessage());
        } catch (IOException e) {
            System.out.println("I/O error: " + e.getMessage());
        } finally {
            // Close the scanners (the socket will be closed automatically by try-with-resources)
            if (console != null) console.close();
            if (fromServer != null) fromServer.close();
        }
    }
}
```

### What the code does

1. **Menu** – Each loop iteration prints a clear menu so the user knows how to format the commands.
2. **Command parsing** – The first word of the line is interpreted as the command; the rest of the line is the arguments.
3. **Argument validation** – Before sending anything to the server, the program checks that the right number of arguments are provided. If not, it shows a friendly message and prompts again.
4. **Special commands** – `quit` / `exit` stop the client without communicating with the server.
5. **Client‑Server protocol** – The entire line entered by the user is sent as-is to the server. The client then waits for a single reply line and prints it. (The server is assumed to understand the same textual format.)
6. **Resource cleanup** – The socket and scanners are closed correctly in the `finally` block.

Feel free to adjust the command‑parsing logic or the message format to match the exact protocol expected by your server.

