    public static final ConcurrentMap<String, ClientHandler> userMap = new ConcurrentHashMap<>();
    public static final ExecutorService threadPool = Executors.newCachedThreadPool();

    public static void main(String[] args) {
        System.out.println("客服系统启动，监听端口 " + PORT);
        try (ServerSocket ss = new ServerSocket(PORT)) {
            // 开启一个后台线程负责显示客服窗口
            OperatorUI operatorUI = new OperatorUI();
            operatorUI.setVisible(true);

            while (true) {
                Socket socket = ss.accept();            // 接收用户请求
                ClientHandler handler = new ClientHandler(socket);
                threadPool.execute(handler);            // 交给线程池处理
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            threadPool.shutdown();
        }
    }
}
```

