            this.in = new DataInputStream(socket.getInputStream());
            this.out = new DataOutputStream(socket.getOutputStream());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void run() {
        try {
            // 第一步：读取 CONNECT 消息
            Message connect = Message.read(in);
            if (connect.getType() != MessageType.CONNECT) {
                close();
                return;
            }
            username = new String(connect.getContent(), "UTF-8");
            logFile = Paths.get("logs", username + ".log");
            // 将用户加入全局映射，供客服端 UI 访问
            ServerMain.userMap.put(username, this);

            // 通知客服 UI 有新用户
            SwingUtilities.invokeLater(() ->
                    OperatorUI.notifyNewUser(username, this));

            // 这里先让客服端自行决定是否接收
            // 通过 OperatorUI 里的按钮事件回调来发送 ACK/REJECT
            // 只等待客服端的回复
            // 这里我们保持阻塞直到收到 ACK 或 REJECT
            Message response;
            while (true) {
                response = Message.read(in);
                if (response.getType() == MessageType.ACK ||
                        response.getType() == MessageType.REJECT) {
                    break;
                }
                // 若收到其它类型，直接忽略或抛异常
            }

            if (response.getType() == MessageType.REJECT) {
                sendText("客服已拒绝服务，稍后再试");
                close();
                return;
            } else {
                // ACK：服务开始
                sendText("客服已接入，开始聊天");
            }

            // 开始循环接收用户发来的消息
            while (true) {
                Message msg = Message.read(in);
                if (msg == null) break;
                handleMessage(msg);
            }

        } catch (IOException e) {
            System.out.println("与用户 " + username + " 的连接异常：" + e.getMessage());
        } finally {
            cleanup();
        }
    }

    private void handleMessage(Message msg) throws IOException {
        // 根据类型进行不同处理
        switch (msg.getType()) {
            case TEXT:
                broadcast(msg);
                break;
            case IMAGE:
                broadcast(msg);
                break;
            case FILE:
                broadcast(msg);
                break;
            case DISCONNECT:
                close();
                break;
            default:
                System.out.println("未知消息类型: " + msg.getType());
        }
    }

    private void broadcast(Message msg) throws IOException {
        // 记录到本地文件
        appendToLog(msg);
        // 直接转发给客服 UI
        SwingUtilities.invokeLater(() -> OperatorUI.appendMessage(username, msg));
    }

    private void appendToLog(Message msg) throws IOException {
        // 这里我们简单把文本写到文件，图片/文件同理
        try (BufferedWriter bw = Files.newBufferedWriter(logFile,
                StandardOpenOption.CREATE, StandardOpenOption.APPEND)) {
            bw.write(Message.toLogLine(msg));
            bw.newLine();
        }
    }

    /** 给客服端发送文本 */
    public void sendText(String text) throws IOException {
        sendMessage(new Message(MessageType.TEXT, text.getBytes("UTF-8")));
    }

    /** 发送通用消息 */
    public void sendMessage(Message msg) throws IOException {
        msg.write(out);
        out.flush();
    }

    public void close() {
        try { socket.close(); } catch (IOException ignored) {}
    }

    private void cleanup() {
        ServerMain.userMap.remove(username);
        OperatorUI.removeUser(username);
        close();
        System.out.println("用户 " + username + " 退出聊天");
    }
}
