## 5. 客户端实现

### 5.1 ClientMain.java

```java
package client;

import common.Message;
import common.MessageType;

import javax.swing.*;
import java.io.*;
import java.net.Socket;
import java.nio.file.*;

public class ClientMain {

    private static Socket socket;
    private static DataInputStream in;
    private static DataOutputStream out;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            ChatUI ui = new ChatUI();
            ui.setVisible(true);
        });
    }

    /** 连接服务器，传入用户名 */
    public static void connect(String host, int port, String username) {
        try {
            socket = new Socket(host, port);
            in = new DataInputStream(socket.getInputStream());
            out = new DataOutputStream(socket.getOutputStream());

            // 先发送 CONNECT
            Message connect = new Message(MessageType.CONNECT,
                    username.getBytes("UTF-8"));
            connect.write(out);
            out.flush();

            // 监听服务端的 ACK/REJECT
            Message resp = Message.read(in);
            if (resp.getType() == MessageType.REJECT) {
                JOptionPane.showMessageDialog(null,
                        "客服拒绝服务：" + new String(resp.getContent()));
                socket.close();
                System.exit(0);
            } else if (resp.getType() != MessageType.ACK) {
                JOptionPane.showMessageDialog(null, "未知响应，连接失败");
                socket.close();
                System.exit(0);
            }

            // 连接成功，开启监听线程
            new Thread(ClientMain::listen).start();

        } catch (IOException e) {
            JOptionPane.showMessageDialog(null, "连接失败: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /** 监听服务器端发来的消息 */
    private static void listen() {
        try {
            while (true) {
                Message msg = Message.read(in);
                if (msg == null) break;
                SwingUtilities.invokeLater(() ->
                        ChatUI.receiveMessage(msg));
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try { socket.close(); } catch (IOException ignored) {}
        }
    }

    /** 发送文字 */
    public static void sendText(String text) {
        try {
            Message msg = new Message(MessageType.TEXT,
                    text.getBytes("UTF-8"));
            msg.write(out);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 发送图片（以 JPEG/PNG 为例） */
    public static void sendImage(Path imgPath) {
        try {
            byte[] data = Files.readAllBytes(imgPath);
            Message msg = new Message(MessageType.IMAGE, data);
            msg.write(out);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 发送文件（任意二进制） */
    public static void sendFile(Path filePath) {
        try {
            byte[] data = Files.readAllBytes(filePath);
            Message msg = new Message(MessageType.FILE, data);
            msg.write(out);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 断开连接 */
    public static void disconnect() {
        try {
            Message msg = new Message(MessageType.DISCONNECT, new byte[0]);
            msg.write(out);
            out.flush();
        } catch (IOException ignored) {}
        try { socket.close(); } catch (IOException ignored) {}
    }
}
```

