## 6. 通用工具类

### 6.1 Message.java

```java
package common;

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

public class Message {
    private MessageType type;
    private byte[] content; // 可为文本、图片或文件

    public Message(MessageType type, byte[] content) {
        this.type = type;
        this.content = content;
    }

    public MessageType getType() { return type; }
    public byte[] getContent() { return content; }

    /** 写入流 */
    public void write(DataOutputStream out) throws IOException {
        // 头部: TYPE|LEN
        String header = type.name() + "|" + content.length;
        out.writeUTF(header);
        // 主体
        out.write(content);
    }

    /** 从流读取 */
    public static Message read(DataInputStream in) throws IOException {
        try {
            String header = in.readUTF(); // 读取头
            String[] parts = header.split("\\|");
            if (parts.length != 2) throw new IOException("非法头部格式");
            MessageType type = MessageType.valueOf(parts[0]);
            int len = Integer.parseInt(parts[1]);

            byte[] data = new byte[len];
            in.readFully(data);
            return new Message(type, data);
        } catch (EOFException e) {
            return null; // 连接已关闭
        }
    }

    /** 写到聊天记录文件 */
    public static String toLogLine(Message msg) {
        switch (msg.getType()) {
            case TEXT:
                return "[TEXT] " + new String(msg.getContent(), StandardCharsets.UTF_8);
            case IMAGE:
                return "[IMAGE] (" + msg.getContent().length + " bytes)";
            case FILE:
                return "[FILE] (" + msg.getContent().length + " bytes)";
            default:
                return "[UNKNOWN]";
        }
    }
}
