<html>
<head>
    <meta charset="UTF-8">
    <title>Chat – SSE 逐字推送</title>
    <style> #chatBox{font-family:monospace; white-space:pre-wrap;} </style>
</head>
<body>
    <input id="userInput" type="text" placeholder="输入消息..." />
    <button id="sendBtn">发送</button>
    <div id="chatBox"></div>

    <script>
    const sendBtn = document.getElementById('sendBtn');
    const chatBox = document.getElementById('chatBox');
    const input = document.getElementById('userInput');
    let eventSource = null; // 当前 SSE 连接

    sendBtn.addEventListener('click', () => {
        const msg = input.value.trim();
        if (!msg) return;

        chatBox.textContent += `> ${msg}\n`;
        // 关闭旧连接（若有）
        if (eventSource) eventSource.close();

        // 创建新的 SSE 连接
        eventSource = new EventSource(`/api/chat/sse-reply?userMsg=${encodeURIComponent(msg)}`);
        eventSource.addEventListener('chat', e => {
            // 每次收到一个字符（或一段文本）
            chatBox.textContent += e.data;
            chatBox.scrollTop = chatBox.scrollHeight;
        });

        // 关闭连接后做点事（可选）
        eventSource.addEventListener('error', () => {
            eventSource.close();
            chatBox.textContent += '\n';
        });
    });
    </script>
