//  File: MouseRecorderApp.java

import org.jnativehook.GlobalScreen;
import org.jnativehook.NativeHookException;
import org.jnativehook.keyboard.*;
import org.jnativehook.dispatcher.*;

import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.logging.*;

// ---------------------------------------------------------------------------
// Data model – a single recording
// ---------------------------------------------------------------------------

class Recording implements Serializable {
    private static final long serialVersionUID = 1L;

    private final int id;                // unique id
    private final long startTimeMs;      // epoch millis
    private final List<Point> points;    // absolute screen coordinates
    private final List<Long> timestamps; // relative to start, ms

    public Recording(int id, long startTimeMs, List<Point> points, List<Long> timestamps) {
        this.id = id;
        this.startTimeMs = startTimeMs;
        this.points = points;
        this.timestamps = timestamps;
    }

    public int getId() { return id; }
    public long getStartTimeMs() { return startTimeMs; }
    public List<Point> getPoints() { return points; }
    public List<Long> getTimestamps() { return timestamps; }
    public long getDurationMs() { return timestamps.isEmpty() ? 0 : timestamps.get(timestamps.size()-1); }
}

// ---------------------------------------------------------------------------
// Main application
// ---------------------------------------------------------------------------

public class MouseRecorderApp {

    // -----------------------------------------------------------------------
    // Configuration
    // -----------------------------------------------------------------------

    private static final String DATA_FILE = "recordings.ser";
    private static final int POLL_INTERVAL_MS = 10;
    private static final int REPLAY_DELAY_MS = 10; // between points

    // -----------------------------------------------------------------------
    // State
    // -----------------------------------------------------------------------

    private final Map<Integer, Recording> recordings = new LinkedHashMap<>();
    private final AtomicBoolean recordingActive = new AtomicBoolean(false);
    private Thread recordingThread;
    private int nextRecordingId = 1;

    // GUI components
    private JFrame frame;
    private JTable table;
    private RecordingTableModel tableModel;
    private JButton replayButton;
    private JLabel statusLabel;

    // -----------------------------------------------------------------------
    // Main
    // -----------------------------------------------------------------------

    public static void main(String[] args) {
        // Disable default JNativeHook logging
        Logger.getLogger(GlobalScreen.class.getPackage().getName()).setLevel(Level.WARNING);

        SwingUtilities.invokeLater(() -> {
            try {
                new MouseRecorderApp().start();
            } catch (Exception e) {
                e.printStackTrace();
                System.exit(1);
            }
        });
    }

    // -----------------------------------------------------------------------
    // Startup
    // -----------------------------------------------------------------------

    private void start() throws IOException, ClassNotFoundException, NativeHookException {
        // 1. Detect screen size
        Dimension screenSize = Toolkit.getDefaultToolkit().getScreenSize();
        System.out.println("Screen size: " + screenSize.width + "x" + screenSize.height);

        // 2. Load saved recordings
        loadRecordings();

        // 3. Build GUI
        buildGui();

        // 4. Register global hot‑keys
        registerHotkeys();
    }

    // -----------------------------------------------------------------------
    // Load / Save
    // -----------------------------------------------------------------------

    @SuppressWarnings("unchecked")
    private void loadRecordings() throws IOException, ClassNotFoundException {
        Path path = Paths.get(DATA_FILE);
        if (!Files.exists(path)) {
            System.out.println("No previous recordings found.");
            return;
        }
        try (ObjectInputStream ois = new ObjectInputStream(Files.newInputStream(path))) {
            Object obj = ois.readObject();
            if (obj instanceof Map) {
                Map<Integer, Recording> map = (Map<Integer, Recording>) obj;
                recordings.putAll(map);
                // Update nextRecordingId
                if (!recordings.isEmpty()) {
                    nextRecordingId = Collections.max(recordings.keySet()) + 1;
                }
                System.out.println("Loaded " + recordings.size() + " recordings.");
            }
        }
    }

    private void saveRecordings() {
        try (ObjectOutputStream oos = new ObjectOutputStream(Files.newOutputStream(Paths.get(DATA_FILE)))) {
            oos.writeObject(recordings);
            System.out.println("Saved " + recordings.size() + " recordings.");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // -----------------------------------------------------------------------
    // GUI
    // -----------------------------------------------------------------------

    private void buildGui() {
        frame = new JFrame("Mouse Recorder & Player");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLayout(new BorderLayout(10,10));

        // Table
        tableModel = new RecordingTableModel(recordings.values());
        table = new JTable(tableModel);
        table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        JScrollPane scroll = new JScrollPane(table);

        // Buttons
        JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        replayButton = new JButton("Replay");
        replayButton.setEnabled(false);
        replayButton.addActionListener(e -> replaySelectedRecording());
        buttonPanel.add(replayButton);

        // Status bar
        statusLabel = new JLabel("Press Shift+P to start recording, Shift+L to stop.");
        statusLabel.setBorder(BorderFactory.createEmptyBorder(5,5,5,5));

        // Layout
        frame.add(scroll, BorderLayout.CENTER);
        frame.add(buttonPanel, BorderLayout.SOUTH);
        frame.add(statusLabel, BorderLayout.NORTH);

        // Listeners
        table.getSelectionModel().addListSelectionListener(e -> {
            boolean selection = table.getSelectedRow() != -1;
            replayButton.setEnabled(selection);
        });

        // Size
        frame.setSize(600, 400);
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }

    // -----------------------------------------------------------------------
    // Recording logic
    // -----------------------------------------------------------------------

    private void startRecording() {
        if (recordingActive.get()) {
            statusLabel.setText("Recording is already running.");
            return;
        }
        recordingActive.set(true);
        statusLabel.setText("Recording… (press Shift+L to stop)");
        recordingThread = new Thread(this::recordLoop);
        recordingThread.start();
    }

    private void stopRecording() {
        if (!recordingActive.get()) {
            statusLabel.setText("No active recording.");
            return;
        }
        recordingActive.set(false);
        try {
            recordingThread.join();
        } catch (InterruptedException ignored) {}

        statusLabel.setText("Recording finished.");
    }

    private void recordLoop() {
        List<Point> points = new ArrayList<>();
        List<Long> timestamps = new ArrayList<>();

        long start = System.currentTimeMillis();

        while (recordingActive.get()) {
            Point p = MouseInfo.getPointerInfo().getLocation();
            points.add(p);
            timestamps.add(System.currentTimeMillis() - start);

            try {
                Thread.sleep(POLL_INTERVAL_MS);
            } catch (InterruptedException ignored) {}
        }

        // Create Recording instance
        Recording rec = new Recording(nextRecordingId, start, points, timestamps);
        recordings.put(nextRecordingId, rec);
        nextRecordingId++;

        // Update UI
        SwingUtilities.invokeLater(() -> {
            tableModel.addRecording(rec);
        });

        // Persist to disk
        saveRecordings();
    }

    // -----------------------------------------------------------------------
    // Replay logic
    // -----------------------------------------------------------------------

    private void replaySelectedRecording() {
        int selectedRow = table.getSelectedRow();
        if (selectedRow == -1) {
            JOptionPane.showMessageDialog(frame, "Please select a recording to replay.", "No selection", JOptionPane.WARNING_MESSAGE);
            return;
        }
        Recording rec = tableModel.getRecordingAt(selectedRow);
        new Thread(() -> replay(rec)).start();
    }

    private void replay(Recording rec) {
        try {
            Robot robot = new Robot();
            // Optionally, you might want to move the cursor to the first point first:
            if (!rec.getPoints().isEmpty()) {
                robot.mouseMove(rec.getPoints().get(0).x, rec.getPoints().get(0).y);
            }
            List<Point> points = rec.getPoints();
            List<Long> timestamps = rec.getTimestamps();
            long start = System.currentTimeMillis();

            for (int i = 0; i < points.size(); i++) {
                long targetTime = timestamps.get(i);
                long now = System.currentTimeMillis() - start;
                long wait = targetTime - now;
                if (wait > 0) Thread.sleep(wait);
                Point p = points.get(i);
                robot.mouseMove(p.x, p.y);
            }
            SwingUtilities.invokeLater(() -> statusLabel.setText("Replay finished."));
        } catch (Exception ex) {
            ex.printStackTrace();
            SwingUtilities.invokeLater(() -> statusLabel.setText("Error during replay."));
        }
    }

    // -----------------------------------------------------------------------
    // Global hot‑key registration
    // -----------------------------------------------------------------------

    private void registerHotkeys() throws NativeHookException {
        GlobalScreen.registerNativeHook();
        GlobalScreen.addNativeKeyListener(new NativeKeyListener() {

            @Override
            public void nativeKeyPressed(NativeKeyEvent e) {
                // Shift + P : start
                if (e.getKeyCode() == NativeKeyEvent.VC_P && isShiftPressed(e)) {
                    SwingUtilities.invokeLater(() -> startRecording());
                }
                // Shift + L : stop
                if (e.getKeyCode() == NativeKeyEvent.VC_L && isShiftPressed(e)) {
                    SwingUtilities.invokeLater(() -> stopRecording());
                }
            }

            @Override
            public void nativeKeyReleased(NativeKeyEvent e) { }

            @Override
            public void nativeKeyTyped(NativeKeyEvent e) { }

            private boolean isShiftPressed(NativeKeyEvent e) {
                return (e.getModifiers() & NativeKeyEvent.SHIFT_MASK) != 0;
            }
        });
    }

    // -----------------------------------------------------------------------
    // Table model for recordings
    // -----------------------------------------------------------------------

    private static class RecordingTableModel extends AbstractTableModel {
        private final String[] columns = {"ID", "Start Time", "Duration (ms)", "# Points"};
        private final List<Recording> data;

        public RecordingTableModel(Collection<Recording> recordings) {
            this.data = new ArrayList<>(recordings);
        }

        @Override
        public int getRowCount() { return data.size(); }

        @Override
        public int getColumnCount() { return columns.length; }

        @Override
        public String getColumnName(int col) { return columns[col]; }

        @Override
        public Object getValueAt(int row, int col) {
            Recording r = data.get(row);
            switch (col) {
                case 0: return r.getId();
                case 1: return new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date(r.getStartTimeMs()));
                case 2: return r.getDurationMs();
                case 3: return r.getPoints().size();
                default: return null;
            }
        }

        public void addRecording(Recording rec) {
            data.add(rec);
            fireTableRowsInserted(data.size()-1, data.size()-1);
        }

        public Recording getRecordingAt(int row) {
            return data.get(row);
        }
    }
}
