import java.io.*;
import java.net.*;

public class H264Server {
    private static final int PORT = 5000;   // 监听端口

    public static void main(String[] args) throws IOException {
        ServerSocket server = new ServerSocket(PORT);
        System.out.println("Server listening on port " + PORT);

        Socket client = server.accept();
        System.out.println("Client connected from " + client.getInetAddress());

        InputStream in = client.getInputStream();
        // 将收到的原始 H.264 bitstream 写到一个临时文件
        File tmpFile = File.createTempFile("h264_", ".h264");
        try (OutputStream out = new FileOutputStream(tmpFile)) {
            byte[] buf = new byte[4096];
            int len;
            while ((len = in.read(buf)) != -1) {
                out.write(buf, 0, len);
            }
        }
        System.out.println("Stream saved to " + tmpFile.getAbsolutePath());
        // 下面可以直接用 JavaCV 读取 tmpFile 进行解码播放
