## 6. MyBatis Mapper 接口与 XML

> **注**：Spring‑MyBatis 自动帮你把 `mapperLocations` 下的 XML 绑定到接口。

### 6.1 `UserMapper.java`

```java
package com.example.dao.mapper;

import com.example.model.User;
import org.apache.ibatis.annotations.*;

import java.util.List;

@Mapper
public interface UserMapper {

    @Select("SELECT * FROM `user` WHERE id = #{id}")
    User findById(Long id);

    @Select("SELECT * FROM `user` WHERE username = #{username}")
    User findByUsername(String username);

    @Insert("INSERT INTO `user`(username, password, full_name, email, phone, org_id) " +
            "VALUES(#{username}, #{password}, #{fullName}, #{email}, #{phone}, #{orgId})")
    @Options(useGeneratedKeys = true, keyProperty = "id")
    void insert(User user);

    @Update("UPDATE `user` SET full_name = #{fullName}, email = #{email}, phone = #{phone}, org_id = #{orgId} WHERE id = #{id}")
    void update(User user);

    @Delete("DELETE FROM `user` WHERE id = #{id}")
    void delete(Long id);

    @Select("SELECT u.*, o.id as org_id, o.name as org_name, o.parent_id as org_parent_id, o.description as org_desc " +
            "FROM `user` u LEFT JOIN organization o ON u.org_id = o.id " +
            "WHERE u.id = #{id}")
    @Results({
        @Result(property = "id", column = "id"),
        @Result(property = "username", column = "username"),
        @Result(property = "password", column = "password"),
        @Result(property = "fullName", column = "full_name"),
        @Result(property = "email", column = "email"),
        @Result(property = "phone", column = "phone"),
        @Result(property = "orgId", column = "org_id"),
        @Result(property = "organization.id", column = "org_id"),
        @Result(property = "organization.name", column = "org_name"),
        @Result(property = "organization.parentId", column = "org_parent_id"),
        @Result(property = "organization.description", column = "org_desc")
    })
    User findByIdWithOrg(Long id);

    // 通过用户 id 获取角色列表
    @Select("SELECT r.* FROM role r " +
            "JOIN user_role ur ON r.id = ur.role_id " +
            "WHERE ur.user_id = #{userId}")
    List<Role> findRolesByUserId(Long userId);
}
```

> `@Results` 用来把联合查询的结果映射到 `User` 对象中，包含 `Organization` 子对象。

