### 7.2 `UserServiceImpl.java`

```java
package com.example.service.impl;

import com.example.dao.mapper.UserMapper;
import com.example.dao.mapper.UserRoleMapper;
import com.example.model.User;
import com.example.model.Role;
import com.example.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.password.PasswordEncoder;

import java.util.List;
import java.util.stream.Collectors;

@Service
public class UserServiceImpl implements UserService {

    @Autowired
    private UserMapper userMapper;

    @Autowired
    private UserRoleMapper userRoleMapper;

    @Autowired
    private PasswordEncoder passwordEncoder;

    @Override
    public User findById(Long id) {
        return userMapper.findById(id);
    }

    @Override
    public User findByUsername(String username) {
        return userMapper.findByUsername(username);
    }

    @Override
    public User findByIdWithOrg(Long id) {
        return userMapper.findByIdWithOrg(id);
    }

    @Override
    @Transactional
    public void register(User user) {
        // 密码加盐 + 哈希
        String hashed = passwordEncoder.encode(user.getPassword());
        user.setPassword(hashed);
        userMapper.insert(user);
    }

    @Override
    @Transactional
    public void update(User user) {
        userMapper.update(user);
    }

    @Override
    @Transactional
    public void delete(Long id) {
        userMapper.delete(id);
    }

    @Override
    public List<User> findAll() {
        return userMapper.findAll();
    }

    @Override
    @Transactional
    public void assignRoles(Long userId, List<Long> roleIds) {
        // 先删再加，保持幂等
        userRoleMapper.removeRolesFromUser(userId);
        if (roleIds != null && !roleIds.isEmpty()) {
            roleIds.forEach(rid -> userRoleMapper.addRoleToUser(userId, rid));
        }
    }

    @Override
    @Transactional
    public void removeAllRoles(Long userId) {
        userRoleMapper.removeRolesFromUser(userId);
    }

    // 可选：获取用户角色列表
    public List<Role> getRolesByUserId(Long userId) {
        return userMapper.findRolesByUserId(userId);
    }
}
```

