## 8. Controller

### 8.1 `LoginController.java`

```java
package com.example.controller;

import com.example.model.User;
import com.example.model.Role;
import com.example.service.UserService;
import com.example.service.RoleService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;

import javax.servlet.http.HttpSession;
import java.util.List;

@Controller
public class LoginController {

    @Autowired
    private UserService userService;

    @Autowired
    private RoleService roleService;

    /** -------- 登录相关 -------- **/

    @GetMapping("/login")
    public String loginPage() {
        return "login";
    }

    @PostMapping("/login")
    public String doLogin(@RequestParam String username,
                          @RequestParam String password,
                          HttpSession session,
                          Model model) {
        User user = userService.findByUsername(username);
        if (user == null) {
            model.addAttribute("msg", "用户名不存在");
            return "login";
        }
        // 检验密码
        if (!org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder.checkpw(password, user.getPassword())) {
            model.addAttribute("msg", "密码错误");
            return "login";
        }

        // 登录成功：把用户信息放到 session
        session.setAttribute("loginUser", user);

        // 也可以把角色列表放进去，供页面使用
        List<Role> roles = userService.findRolesByUserId(user.getId());
        session.setAttribute("userRoles", roles);

        return "redirect:/home";
    }

    @GetMapping("/logout")
    public String logout(HttpSession session) {
        session.invalidate();
        return "redirect:/login";
    }

    /** -------- 首页 -------- **/

    @GetMapping("/home")
    public String homePage(HttpSession session, Model model) {
        User user = (User) session.getAttribute("loginUser");
        if (user == null) {
            return "redirect:/login";
        }
        model.addAttribute("user", user);

        List<Role> roles = (List<Role>) session.getAttribute("userRoles");
        model.addAttribute("roles", roles);

        return "home";
    }

    /** -------- 注册 -------- **/

    @GetMapping("/register")
    public String registerPage() {
        return "register";
    }

    @PostMapping("/register")
    public String doRegister(@ModelAttribute User user, HttpSession session, Model model) {
        if (userService.findByUsername(user.getUsername()) != null) {
            model.addAttribute("msg", "用户名已存在");
            return "register";
        }
        userService.register(user);
        // 自动登录
        User saved = userService.findByUsername(user.getUsername());
        session.setAttribute("loginUser", saved);
        session.setAttribute("userRoles", List.of()); // 无角色
        return "redirect:/home";
    }
}
```

> **说明**  
> - `BCryptPasswordEncoder.checkpw` 不是 Spring 自带方法，直接使用 `passwordEncoder.matches(raw, encoded)` 更简洁；示例中演示了手工校验。  
> - 业务逻辑（如判断账号是否锁定、IP 记录、验证码等）可以根据需要添加。  

