## 1. Сервер

```java
// ChatServer.java
import java.io.*;
import java.net.*;
import java.util.*;

public class ChatServer {

    private static final int PORT = 12345;
    // Список потоков вывода, чтобы пересылать сообщения
    private final Set<PrintWriter> clientWriters = Collections.synchronizedSet(new HashSet<>());

    public static void main(String[] args) throws IOException {
        new ChatServer().start();
    }

    public void start() throws IOException {
        System.out.println("Chat server is starting on port " + PORT);
        ServerSocket serverSocket = new ServerSocket(PORT);
        try {
            while (true) {
                Socket socket = serverSocket.accept();   // ждём нового клиента
                System.out.println("New client connected: " + socket);
                // Создаём поток вывода для этого клиента и добавляем его в список
                PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
                clientWriters.add(out);
                // Запускаем отдельный поток для чтения от этого клиента
                new Thread(new ClientHandler(socket, out)).start();
            }
        } finally {
            serverSocket.close();
        }
    }

    // Обработчик одного клиента
    private class ClientHandler implements Runnable {
        private final Socket socket;
        private final PrintWriter out;

        ClientHandler(Socket socket, PrintWriter out) {
            this.socket = socket;
            this.out = out;
        }

        @Override
        public void run() {
            try (
                BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()))
            ) {
                String msg;
                // Читаем пока клиент не закроет соединение
                while ((msg = in.readLine()) != null) {
                    System.out.println("Received: " + msg);
                    broadcast(msg);
                }
            } catch (IOException e) {
                System.err.println("Error handling client " + socket + ": " + e.getMessage());
            } finally {
                // Удаляем клиента из списка
                clientWriters.remove(out);
                try {
                    socket.close();
                } catch (IOException ignored) {}
                System.out.println("Client disconnected: " + socket);
            }
        }
    }

    // Пересылаем сообщение всем клиентам
    private void broadcast(String msg) {
        synchronized (clientWriters) {
            for (PrintWriter writer : clientWriters) {
                writer.println(msg);
            }
        }
    }
}
```

### Как собрать и запустить

```bash
javac ChatServer.java
java ChatServer
```

