## 5.  Server – Implementazione in Python (sintetica)

```python
# hotelier_server.py
import json, socket, threading, bcrypt, sys
from pathlib import Path

HOST = "0.0.0.0"
PORT = 5555

class HotelierServer(threading.Thread):
    def __init__(self, addr, hotel_file="hotels.json", user_file="users.json"):
        super().__init__()
        self.addr = addr
        self.hotel_file = Path(hotel_file)
        self.user_file = Path(user_file)
        self.hotels = {}
        self.users = {}           # username -> User
        self.lock = threading.Lock()
        self.load_hotels()
        self.load_users()

    def run(self):
        with socket.socket() as s:
            s.bind(self.addr)
            s.listen(5)
            print(f"Server listening on {self.addr}")
            while True:
                client_sock, addr = s.accept()
                threading.Thread(target=self.handle_client,
                                 args=(client_sock, addr),
                                 daemon=True).start()

    # --------------------- load / save --------------------------------

    def load_hotels(self):
        with open(self.hotel_file) as f:
            data = json.load(f)
            for h in data["hotels"]:
                self.hotels[h["id"]] = Hotel(**h)

    def load_users(self):
        if not self.user_file.exists():
            return
        with open(self.user_file) as f:
            data = json.load(f)
            for username, info in data.items():
                self.users[username] = User(username,
                                            info["password_hash"],
                                            bool(info["logged_in"]))

    def persist_users(self):
        data = {u.username: {"password_hash": u.password_hash,
                             "logged_in": u.logged_in}
                for u in self.users.values()}
        with open(self.user_file, "w") as f:
            json.dump(data, f, indent=2)

    # --------------------- client handler --------------------------------

    def handle_client(self, sock, addr):
        print(f"Connection from {addr}")
        with sock:
            while True:
                try:
                    data = self.recv_msg(sock)
                    if not data:
                        break
                    resp = self.process_request(json.loads(data))
                    self.send_msg(sock, json.dumps(resp).encode())
                except ConnectionResetError:
                    break
                except Exception as e:
                    print(f"Error handling request from {addr}: {e}")
                    break
        print(f"Connection closed {addr}")

    # --------------------- helpers --------------------------------

    def recv_msg(self, sock):
        # protocol: 4‑byte big‑endian length + payload
        raw_len = sock.recv(4)
        if not raw_len:
            return None
        msg_len = int.from_bytes(raw_len, "big")
        return sock.recv(msg_len)

    def send_msg(self, sock, payload):
        msg_len = len(payload).to_bytes(4, "big")
        sock.sendall(msg_len + payload)

    # --------------------- request handling --------------------------------

    def process_request(self, req):
        action = req.get("action")
        payload = req.get("payload", {})
        try:
            if action == "register":
                return self.handle_register(payload)
            if action == "login":
                return self.handle_login(payload)
            if action == "logout":
                return self.handle_logout(payload)
            if action == "get_hotels":
                return self.handle_get_hotels()
            # aggiungere altre azioni (search, reserve, …)
            return {"status": "ERROR",
                    "code": 99,
                    "message": f"Unknown action {action}"}
        except Exception as e:
            return {"status": "ERROR",
                    "code": 98,
                    "message": str(e)}

    # --------------------- action handlers --------------------------------

    def handle_register(self, payload):
        username = payload["username"]
        password = payload["password"]
        if not password:
            return {"status": "ERROR", "code": 2,
                    "message": "Password cannot be empty"}
        with self.lock:
            if username in self.users:
                return {"status": "ERROR", "code": 1,
                        "message": "Username already exists"}
            pw_hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()
            self.users[username] = User(username, pw_hash)
            self.persist_users()
        return {"status": "OK", "code": 0,
                "message": "Registration successful"}

    def handle_login(self, payload):
        username = payload["username"]
        password = payload["password"]
        with self.lock:
            user = self.users.get(username)
            if user is None:
                return {"status": "ERROR", "code": 3,
                        "message": "Username not found"}
            if user.logged_in:
                return {"status": "ERROR", "code": 5,
                        "message": "User already logged in"}
            if not bcrypt.checkpw(password.encode(), user.password_hash.encode()):
                return {"status": "ERROR", "code": 4,
                        "message": "Wrong password"}
            user.logged_in = True
            self.persist_users()
        return {"status": "OK", "code": 0,
                "message": "Login successful"}

    def handle_logout(self, payload):
        username = payload["username"]
        with self.lock:
            user = self.users.get(username)
            if user is None or not user.logged_in:
                return {"status": "ERROR", "code": 6,
                        "message": "User not logged in"}
            user.logged_in = False
            self.persist_users()
        return {"status": "OK", "code": 0,
                "message": "Logout successful"}

    def handle_get_hotels(self):
        hotels = [h.__dict__ for h in self.hotels.values()]
        return {"status": "OK",
                "code": 0,
                "data": hotels}


# ---------- main ----------

if __name__ == "__main__":
    srv = HotelierServer((HOST, PORT))
    srv.start()
    try:
        while True:
            threading.Event().wait(1)
    except KeyboardInterrupt:
        print("\nShutting down...")
        sys.exit(0)
```

> **Come funziona il “messaggio di lunghezza”?**  
> Per evitare problemi di frammentazione (TCP è stream‑based). Il client deve inviare 4 byte che rappresentano la lunghezza del payload successivo.

