## 6.  Client – Implementazione in Python (sintetica)

```python
# hotelier_client.py
import socket, json, sys

HOST = "127.0.0.1"
PORT = 5555

def send_recv(sock, msg):
    # serializza con lunghezza + payload
    payload = json.dumps(msg).encode()
    sock.sendall(len(payload).to_bytes(4, "big") + payload)
    raw_len = sock.recv(4)
    if not raw_len:
        raise ConnectionError("Server closed connection")
    msg_len = int.from_bytes(raw_len, "big")
    data = sock.recv(msg_len)
    return json.loads(data.decode())

def prompt_register(sock):
    username = input("Username: ")
    password = input("Password: ")
    req = {"action":"register","payload":{"username":username,"password":password}}
    resp = send_recv(sock, req)
    print(resp["message"])

def prompt_login(sock):
    username = input("Username: ")
    password = input("Password: ")
    req = {"action":"login","payload":{"username":username,"password":password}}
    resp = send_recv(sock, req)
    print(resp["message"])

def prompt_logout(sock):
    username = input("Username: ")
    req = {"action":"logout","payload":{"username":username}}
    resp = send_recv(sock, req)
    print(resp["message"])

def prompt_get_hotels(sock):
    req = {"action":"get_hotels","payload":{}}
    resp = send_recv(sock, req)
    if resp["status"] == "OK":
        for h in resp["data"]:
            print(f"{h['id']} - {h['name']} ({h['city']}) rating:{h['rating']}")
    else:
        print(resp["message"])

def main():
    with socket.socket() as s:
        s.connect((HOST, PORT))
        print("Connected to HOTELIER server.")
        while True:
            print("\n=== MENU ===")
            print("1. Register")
            print("2. Login")
            print("3. Logout")
            print("4. Get list of hotels")
            print("5. Exit")
            choice = input("Choose: ").strip()
            if choice == "1":
                prompt_register(s)
            elif choice == "2":
                prompt_login(s)
            elif choice == "3":
                prompt_logout(s)
            elif choice == "4":
                prompt_get_hotels(s)
            elif choice == "5":
                print("Bye!")
                break
            else:
                print("Invalid choice")

if __name__ == "__main__":
    main()
```

