import org.java_websocket.server.WebSocketServer;
import org.java_websocket.WebSocket;
import org.java_websocket.handshake.ClientHandshake;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.*;
import java.net.InetSocketAddress;
import java.util.concurrent.TimeUnit;

public class FFmpegPipeDemo {

    /** -------------------- WebSocket 服务器 -------------------- */
    static class WS extends WebSocketServer {
        public WS(int port) { super(new InetSocketAddress(port)); }

        @Override public void onOpen(WebSocket conn, ClientHandshake handshake) { }
        @Override public void onClose(WebSocket conn, int code, String reason, boolean remote) { }
        @Override public void onMessage(WebSocket conn, String message) { }
        @Override public void onError(WebSocket conn, Exception ex) { ex.printStackTrace(); }
        @Override public void onStart() { System.out.println("WebSocket started"); }
    }

    public static void main(String[] args) throws Exception {
        // 1. 启动 WebSocket 服务器
        WS ws = new WS(8888);
        ws.start();
        System.out.println("WS listening on 8888");

        // 2. 准备 ffmpeg 进程（stdin 传图片，stdout 读 H.264）
        ProcessBuilder pb = new ProcessBuilder(
                "ffmpeg",
                "-y",
                "-f", "image2pipe",   // 接收管道里的图片序列
                "-i", "-",            // 从 stdin 读取
                "-an",                // 没音频
                "-vcodec", "libx264",
                "-preset", "ultrafast",
                "-tune", "zerolatency",
                "-f", "h264",         // 输出纯 H.264
                "-"
        );
        pb.redirectErrorStream(true); // 把 stderr 合并到 stdout，方便调试
        Process ffmpeg = pb.start();

        OutputStream ffmpegIn  = ffmpeg.getOutputStream(); // 写图片给 ffmpeg
        InputStream ffmpegOut = ffmpeg.getInputStream();   // 读 H.264
        // 3. 读取本地图片（一次性读完）
        BufferedImage img = ImageIO.read(FFmpegPipeDemo.class.getResourceAsStream("/demo.png"));
        ByteArrayOutputStream imgBuf = new ByteArrayOutputStream();
        ImageIO.write(img, "png", imgBuf);
        byte[] imgBytes = imgBuf.toByteArray();

        // 4. 按帧速率把图片写给 ffmpeg（每帧都写相同图片）
        for (int i = 0; i < 120; i++) {
            ffmpegIn.write(imgBytes);        // 写图片
            ffmpegIn.flush();                // 立即写入
            // 让 ffmpeg 有时间编码（这里我们简单睡眠 33ms）
            TimeUnit.MILLISECONDS.sleep(33);
        }
        ffmpegIn.close(); // 关闭 stdin，让 ffmpeg 结束

        // 5. 读取 ffmpeg 输出，按块送给 WebSocket
        byte[] buf = new byte[65536];
        int len;
        while ((len = ffmpegOut.read(buf)) != -1) {
            byte[] frame = new byte[len];
            System.arraycopy(buf, 0, frame, 0, len);
            for (WebSocket conn : ws.getConnections()) {
                conn.send(frame); // binary frame
            }
        }

        ffmpeg.waitFor();
        ws.stop();
    }
}
```

> **要点**  
> * `-f image2pipe -i -` 让 FFmpeg 从标准输入读取一连串图片。  
> * `-f h264 -` 让 FFmpeg 输出纯 H.264 NAL 单元到标准输出。  
> * 你可以把 `ImageIO.write` 换成 `JPG`、`BMP`，甚至直接把 `BufferedImage` 转成字节流（`ImageIO.write`）即可。  
> * **不要把图片写在磁盘**，直接写到 FFmpeg 的 stdin 能显著降低 IO 开销。  

