### 2.2 关键代码

#### 2.2.1 数据库模型（`User.js`）

```js
// src/models/User.js
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');

const userSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true, index: true },
  passwordHash: { type: String, required: true },
  email: { type: String, required: true },
  roles: { type: [String], default: ['USER'] },
  createdAt: { type: Date, default: Date.now }
});

// 密码校验方法
userSchema.methods.validatePassword = async function(rawPassword) {
  return bcrypt.compare(rawPassword, this.passwordHash);
};

module.exports = mongoose.model('User', userSchema);
```

> **Tip**  
> - 若使用 MySQL/ PostgreSQL，用 Sequelize 定义相同字段即可。

#### 2.2.2 登录 Controller（`authController.js`）

```js
// src/controllers/authController.js
const userService = require('../services/userService');
const captchaService = require('../services/captchaService');
const jwt = require('jsonwebtoken');
const config = require('../config/jwt');
const logger = require('../utils/logger');

exports.login = async (req, res, next) => {
  try {
    const { username, password, captcha, deviceId, rememberMe } = req.body;

    // 1️⃣ 验证验证码（可选）
    const captchaValid = await captchaService.verify(captcha);
    if (!captchaValid) {
      return res.status(400).json({ code: 'INVALID_CAPTCHA', message: '验证码错误' });
    }

    // 2️⃣ 获取用户
    const user = await userService.findByUsername(username);
    if (!user) {
      logger.warn(`login failed: user not found (${username})`);
      return res.status(401).json({ code: 'INVALID_CREDENTIALS', message: '用户名或密码错误' });
    }

    // 3️⃣ 校验密码
    const pwdOk = await user.validatePassword(password);
    if (!pwdOk) {
      logger.warn(`login failed: wrong password (${username})`);
      return res.status(401).json({ code: 'INVALID_CREDENTIALS', message: '用户名或密码错误' });
    }

    // 4️⃣ 生成 JWT
    const payload = { sub: user._id, username: user.username, roles: user.roles };
    const expiresIn = rememberMe ? config.expiresInLong : config.expiresInShort;
    const token = jwt.sign(payload, config.secret, { expiresIn });

    // 5️⃣ 响应
    res.json({
      token,
      expiresIn,
      user: { id: user._id, username: user.username, roles: user.roles }
    });
  } catch (err) {
    next(err);
  }
};
```

> **说明**  
> - `captchaService.verify` 可调用第三方服务（Google reCAPTCHA、阿里云验证码等）。  
> - `config.jwt` 里可存放 `secret`、`expiresInShort`（15m）和 `expiresInLong`（7d）。  
> - 所有错误统一交给 `errorHandler` 处理。

#### 2.2.3 路由（`auth.js`）

