#### 3.2.3 JWT 生成/解析（`TokenService.java`）

```java
// src/main/java/com/example/auth/service/TokenService.java
package com.example.auth.service;

import com.example.auth.dto.LoginResponse;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import jakarta.annotation.PostConstruct;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import java.util.Date;

@Service
@RequiredArgsConstructor
public class TokenService {

    private final JwtProperties jwtProps;
    private String secretKey;

    @PostConstruct
    public void init() {
        // 可以把 secretKey 从配置文件读取
        secretKey = jwtProps.getSecret();
    }

    public String createToken(String username, String userId, String[] roles, boolean rememberMe) {
        long expMillis = rememberMe ? jwtProps.getLongExpires() : jwtProps.getShortExpires();
        Date now = new Date();
        return Jwts.builder()
                .setSubject(userId)
                .claim("username", username)
                .claim("roles", roles)
                .setIssuedAt(now)
                .setExpiration(new Date(now.getTime() + expMillis))
                .signWith(SignatureAlgorithm.HS256, secretKey)
                .compact();
    }
}
