#### 3.2.4 控制器（`AuthController.java`）

```java
// src/main/java/com/example/auth/controller/AuthController.java
package com.example.auth.controller;

import com.example.auth.dto.LoginRequest;
import com.example.auth.dto.LoginResponse;
import com.example.auth.entity.User;
import com.example.auth.exception.AuthException;
import com.example.auth.service.CaptchaService;
import com.example.auth.service.TokenService;
import com.example.auth.service.UserService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.security.authentication.*;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authManager;
    private final UserService userService;
    private final CaptchaService captchaService;
    private final TokenService tokenService;

    @PostMapping("/login")
    @ResponseStatus(HttpStatus.OK)
    public LoginResponse login(@Valid @RequestBody LoginRequest req) {
        // 1️⃣ 验证验证码
        if (!captchaService.verify(req.getCaptcha())) {
            throw new AuthException("INVALID_CAPTCHA", "验证码错误");
        }

        // 2️⃣ Spring Security 进行用户名/密码校验
        UsernamePasswordAuthenticationToken token =
                new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword());
        try {
            authManager.authenticate(token);
        } catch (BadCredentialsException e) {
            throw new AuthException("INVALID_CREDENTIALS", "用户名或密码错误");
        }

        // 3️⃣ 生成 JWT
        User user = userService.findByUsername(req.getUsername());
        String jwt = tokenService.createToken(user.getUsername(), user.getId().toString(),
                user.getRoles().toArray(new String[0]), req.isRememberMe());

        // 4️⃣ 响应
        return new LoginResponse(jwt, req.isRememberMe() ? 604800 : 900, user.toDto());
    }
}
```

> `LoginRequest`、`LoginResponse`、`AuthException`、`GlobalExceptionHandler` 均用 Lombok 简化。

