```java
// src/main/java/com/example/auth/exception/GlobalExceptionHandler.java
package com.example.auth.exception;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(AuthException.class)
    public ResponseEntity<?> handleAuth(AuthException ex) {
        return ResponseEntity.status(ex.getStatus())
                .body(Map.of("code", ex.getCode(), "message", ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<?> handleValidation(MethodArgumentNotValidException ex) {
        var fieldError = ex.getBindingResult().getFieldError();
        return ResponseEntity.badRequest()
                .body(Map.of("code", "VALIDATION_ERROR", "message", fieldError != null ? fieldError.getDefaultMessage() : "参数错误"));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<?> handleOther(Exception ex) {
        ex.printStackTrace(); // 可集成日志
        return ResponseEntity.status(500).body(Map.of("code", "INTERNAL_ERROR", "message", "服务器内部错误"));
    }
}
