                            System.out.println("Invalid bet – you lose the round.");
                            playerQuit = true;
                            betOnTable += bet;
                            player.deductChips(bet);
                            break;
                        }
                        betOnTable += bet;
                        player.deductChips(bet);
                        System.out.println("Bet added. Total on table: " + betOnTable);
                        round++;
                    } else {
                        playerQuit = true;
                        System.out.println("\nYou quit – dealer wins the current bet of " + betOnTable + ".");
