```java
// File: Message.java
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.Date;

public class Message {
    public enum Type {
        CONNECT, TEXT, FILE, IMAGE, ACCEPT, REJECT, BUSY, LOGOUT, HEARTBEAT
    }

    private Type type;
    private String payload;           // 纯文本或文件名+长度等信息
    private byte[] data;              // 只在 FILE/IMAGE 时使用

    public Message(Type type, String payload, byte[] data) {
        this.type = type;
        this.payload = payload;
        this.data = data;
    }

    public Message(Type type, String payload) {
        this(type, payload, null);
    }

    public Message(Type type) {
        this(type, null, null);
    }

    // Serialize to DataOutputStream
    public void write(DataOutputStream out) throws IOException {
        // 先写类型
        out.writeUTF(type.name());
        // 先写payload长度
        if (payload != null) {
            out.writeInt(payload.getBytes(StandardCharsets.UTF_8).length);
            out.write(payload.getBytes(StandardCharsets.UTF_8));
        } else {
            out.writeInt(0);
        }
        // 写数据长度
        if (data != null) {
            out.writeInt(data.length);
            out.write(data);
        } else {
            out.writeInt(0);
        }
        out.flush();
    }

    // Deserialize from DataInputStream
    public static Message read(DataInputStream in) throws IOException {
        Type type = Type.valueOf(in.readUTF());
        int payloadLen = in.readInt();
        String payload = null;
        if (payloadLen > 0) {
            byte[] tmp = new byte[payloadLen];
            in.readFully(tmp);
            payload = new String(tmp, StandardCharsets.UTF_8);
        }
        int dataLen = in.readInt();
        byte[] data = null;
        if (dataLen > 0) {
            data = new byte[dataLen];
            in.readFully(data);
        }
        return new Message(type, payload, data);
    }

    // Getters
    public Type getType() { return type; }
    public String getPayload() { return payload; }
    public byte[] getData() { return data; }

    // 工具：时间戳字符串
    public static String now() {
        return new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date());
    }
}
```

