// File: ServerMain.java
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class ServerMain {
    public static final int PORT = 12345;
    // 所有活跃聊天的用户映射：clientId -> ClientHandler
    private static final ConcurrentHashMap<Integer, ClientHandler> activeClients = new ConcurrentHashMap<>();
    // 等待中的用户列表：clientId -> username
    private static final ConcurrentLinkedQueue<PendingUser> pendingQueue = new ConcurrentLinkedQueue<>();
    // 生成唯一 clientId
    private static final AtomicInteger clientIdGen = new AtomicInteger(1000);

    // 共享给 UI 用
    public static StaffGUI staffGUI;          // 只在主线程里实例化

    public static void main(String[] args) throws IOException {
        ServerSocket ss = new ServerSocket(PORT);
        System.out.println("客服服务器已启动，监听端口 " + PORT);

        // 启动客服 UI
        SwingUtilities.invokeLater(() -> {
            staffGUI = new StaffGUI();
            staffGUI.setVisible(true);
        });

        while (true) {
            Socket s = ss.accept();
            int clientId = clientIdGen.getAndIncrement();
            ClientHandler handler = new ClientHandler(s, clientId);
            handler.start();
        }
    }

    // 供 UI 处理接受/拒绝请求
    public static boolean acceptUser(int clientId, String username) {
        ClientHandler ch = activeClients.get(clientId);
        if (ch == null) return false;
        ch.sendMessage(new Message(Message.Type.ACCEPT, username));
        return true;
    }

    public static boolean rejectUser(int clientId) {
        ClientHandler ch = activeClients.get(clientId);
        if (ch == null) return false;
        ch.sendMessage(new Message(Message.Type.REJECT));
        return true;
    }

    // 内部类：等待中的用户
