            // 保存到日志
            ChatLog.append(username, "[User] " + msg.getPayload());
            // 如果是文件/图片，直接写日志
            if (msg.getType() == Message.Type.FILE || msg.getType() == Message.Type.IMAGE) {
                ChatLog.append(username, "[User] file: " + msg.getPayload());
            }
        }

        public void sendMessage(Message m) {
            try {
                m.write(out);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public void close() {
            running = false;
            try {
                if (!socket.isClosed()) socket.close();
            } catch (IOException ignored) {}
            // 从活跃列表移除
            activeClients.remove(clientId);
            // 从等待队列移除
            pendingQueue.removeIf(pu -> pu.id == clientId);
            // 通知 UI
            SwingUtilities.invokeLater(() -> staffGUI.removePendingUser(clientId));
        }
    }
}
