// File: ClientUI.java
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;

public class ClientUI extends JFrame {
    private final JTextArea chatArea = new JTextArea();
    private final JTextField inputField = new JTextField();
    private final JButton sendBtn = new JButton("发送");
    private final JButton imgBtn = new JButton("发送图片");

    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private Thread listenerThread;
    private String username;
    private String host;
    private int port;

    public ClientUI(String host, int port) {
        super("电商客服 - 用户端");
        this.host = host;
        this.port = port;
        setSize(500, 400);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());
        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(inputField, BorderLayout.CENTER);
        bottom.add(sendBtn, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        JPanel top = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        top.add(imgBtn);
        add(top, BorderLayout.NORTH);

        sendBtn.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> sendImage());
        inputField.addActionListener(e -> sendText());

        // 连接
        connect();
    }

    private void connect() {
        username = JOptionPane.showInputDialog(this, "请输入用户名", "连接", JOptionPane.QUESTION_MESSAGE);
        if (username == null || username.trim().isEmpty()) {
            System.exit(0);
        }
        try {
            socket = new Socket(host, port);
            in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
            out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));
            // 发送 CONNECT 包
            Message.connectMsg = new Message(Message.Type.CONNECT, username);
            out.writeUTF(Message.connectMsg.getType().name());
            out.writeInt(username.getBytes(StandardCharsets.UTF_8).length);
            out.write(username.getBytes(StandardCharsets.UTF_8));
            out.writeInt(0); // no data
            out.flush();

            // 启动监听线程
            listenerThread = new Thread(() -> listen());
            listenerThread.start();
        } catch (IOException e) {
            showError("连接失败: " + e.getMessage());
            System.exit(0);
        }
    }

    private void listen() {
        try {
            while (true) {
                Message msg = Message.read(in);
                switch (msg.getType()) {
                    case ACCEPT:
                        chatArea.append("[客服] 连接已接受，开始聊天\n");
                        // 加载历史记录
                        loadHistory(msg.getPayload());
                        break;
                    case REJECT:
                        showError("客服拒绝接待，请稍后再试");
                        socket.close();
                        System.exit(0);
                        break;
                    case BUSY:
                        showError("客服繁忙，稍后请再来");
                        socket.close();
                        System.exit(0);
                        break;
                    case TEXT:
                        chatArea.append("[客服] " + msg.getPayload() + "\n");
                        // 保存到日志
                        ChatLog.append(username, "[客服] " + msg.getPayload());
                        break;
                    case FILE:
                    case IMAGE:
                        // 处理文件/图片
                        handleFile(msg);
                        break;
                    default:
                        break;
                }
            }
        } catch (IOException e) {
            // 断开
            e.printStackTrace();
            showError("网络错误，已断开");
        }
    }

    private void handleFile(Message msg) {
        try {
            String[] parts = msg.getPayload().split("\\|");
            String fileName = parts[0];
            int size = Integer.parseInt(parts[1]);
            byte[] data = msg.getData();

            // 保存文件
            File outFile = new File("downloads", fileName);
            outFile.getParentFile().mkdirs();
            try (FileOutputStream fos = new FileOutputStream(outFile)) {
                fos.write(data);
            }
            chatArea.append("[客服] 发送文件: " + fileName + " (" + size + " 字节)\n");
            ChatLog.append(username, "[客服] 发送文件 " + fileName);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void loadHistory(String filename) {
        // 读取聊天记录
        for (String line : ChatLog.read(username)) {
            chatArea.append(line + "\n");
        }
    }

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            Message msg = new Message(Message.Type.TEXT, txt);
            out.writeUTF(msg.getType().name());
            out.writeInt(txt.getBytes(StandardCharsets.UTF_8).length);
            out.write(txt.getBytes(StandardCharsets.UTF_8));
            out.writeInt(0);
            out.flush();
            chatArea.append("[自己] " + txt + "\n");
            ChatLog.append(username, "[自己] " + txt);
            inputField.setText("");
        } catch (IOException e) {
            e.printStackTrace();
            showError("发送失败: " + e.getMessage());
        }
    }

    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        int ret = fc.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;
        File file = fc.getSelectedFile();
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] data = fis.readAllBytes();
            Message msg = new Message(Message.Type.IMAGE, file.getName() + "|" + data.length, data);
            out.writeUTF(msg.getType().name());
            out.writeInt(msg.getPayload().getBytes(StandardCharsets.UTF_8).length);
            out.write(msg.getPayload().getBytes(StandardCharsets.UTF_8));
            out.writeInt(data.length);
            out.write(data);
            out.flush();

            chatArea.append("[自己] 发送图片 " + file.getName() + "\n");
            ChatLog.append(username, "[自己] 发送图片 " + file.getName());
        } catch (IOException e) {
            e.printStackTrace();
            showError("发送图片失败: " + e.getMessage());
        }
    }

    private void showError(String msg) {
        SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this, msg, "错误", JOptionPane.ERROR_MESSAGE));
    }
}
