// File: ChatLog.java
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class ChatLog {
    private static final String LOG_DIR = "logs";

    static {
        new File(LOG_DIR).mkdirs();
    }

    public static synchronized void append(String username, String line) {
        File file = new File(LOG_DIR, username + ".txt");
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(file, true))) {
            writer.write(Message.now() + " " + line);
            writer.newLine();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static synchronized List<String> read(String username) {
        File file = new File(LOG_DIR, username + ".txt");
        List<String> res = new ArrayList<>();
        if (!file.exists()) return res;
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) res.add(line);
        } catch (IOException e) {
            e.printStackTrace();
        }
        return res;
    }
}
