// server/ClientHandler.java
package server;

import common.ChatMessage;
import common.ChatHistoryManager;

import java.io.*;
import java.net.Socket;
import java.util.concurrent.atomic.AtomicInteger;

public class ClientHandler implements Runnable {
    private static final AtomicInteger USER_SEQ = new AtomicInteger(0);

    private final Socket socket;
    private final ServerDashboard dashboard;
    private final String userId; // 生成的用户 ID
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private volatile boolean running = true;

    public ClientHandler(Socket socket, ServerDashboard dashboard) {
        this.socket = socket;
        this.dashboard = dashboard;
        this.userId = "U" + USER_SEQ.incrementAndGet();
    }

    @Override
    public void run() {
        try {
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());
            // 先把自己放到等待列表
            dashboard.addWaitingClient(userId, this);

            // 监听客户端消息
            while (running) {
                Object obj = in.readObject();
                if (obj instanceof ChatMessage) {
                    ChatMessage msg = (ChatMessage) obj;
                    // 写入日志
                    ChatHistoryManager.appendMessage(userId, msg);
                    // 这里可以做转发给客服端等
                }
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            cleanup();
        }
    }

    /** 供客服端主动发送消息 */
    public void sendMessage(ChatMessage msg) {
        try { out.writeObject(msg); out.flush(); } catch (IOException ignored) {}
    }

    /** 客户端断开后释放资源 */
    private void cleanup() {
        running = false;
        try { in.close(); } catch (Exception ignored) {}
        try { out.close(); } catch (Exception ignored) {}
        try { socket.close(); } catch (Exception ignored) {}
        dashboard.removeClient(userId);
    }

    public String getUserId() { return userId; }
}
