        <maven.compiler.target>1.8</maven.compiler.target>
        <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>
    </properties>

    <dependencies>
        <!-- Servlet API（仅在容器中提供）-->
        <dependency>
            <groupId>javax.servlet</groupId>
            <artifactId>javax.servlet-api</artifactId>
            <version>4.0.1</version>
            <scope>provided</scope>
        </dependency>
    </dependencies>
</project>
```

> 只要把 `javax.servlet-api` 设为 `provided`，Tomcat 等容器会自行提供该 API。

---

## 3. `EncodingFilter.java`

```java
package com.example.filter;

import java.io.IOException;
import javax.servlet.*;
import javax.servlet.annotation.WebFilter;

/**
 * <p>
 * 统一处理请求/响应字符编码的 Filter。<br>
 * 1. 在请求进入 Servlet 之前，将 request 的编码设置为 UTF-8。<br>
 * 2. 在响应输出前，设置 response 的编码为 UTF-8，并确保 Content-Type 里包含 charset。<br>
 * 3. 过滤链继续向下执行（doFilter）。<br>
 * </p>
 */
@WebFilter("/*") // 注解方式，拦截所有请求
public class EncodingFilter implements Filter {

    private static final String ENCODING = "UTF-8";

    @Override
    public void init(FilterConfig filterConfig) throws ServletException {
        // 这里可以读取配置文件或初始化资源
        System.out.println("[EncodingFilter] 初始化，编码：" + ENCODING);
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response,
                         FilterChain chain) throws IOException, ServletException {
        // ① 设置请求编码（必要时，最好放在 chain.doFilter 之前）
        if (!request.getCharacterEncoding().equalsIgnoreCase(ENCODING)) {
            request.setCharacterEncoding(ENCODING);
        }

        // ② 设置响应编码
        response.setCharacterEncoding(ENCODING);
        // 如果是文本类型，最好同时设置 content type
        if (response.getContentType() == null ||
            !response.getContentType().toLowerCase().contains("charset")) {
            response.setContentType("text/html;charset=" + ENCODING);
        }

        // ③ 继续过滤链
        chain.doFilter(request, response);
    }

    @Override
    public void destroy() {
        // 资源释放
        System.out.println("[EncodingFilter] 销毁");
    }
}
```

> **关键点**  
> - `request.setCharacterEncoding(...)` 必须在 *读取任何参数* 之前调用。  
> - `response.setContentType("text/html;charset=UTF-8")` 让浏览器知道响应使用 UTF‑8。  
> - 若你使用 JSP，最好在 JSP 页面顶部加 `<%@ page pageEncoding="UTF-8" contentType="text/html;charset=UTF-8" %>`，但 Filter 仍然是全局统一处理的好办法。

---

## 4. 示例 Servlet

### 4.1 `HelloServlet.java`

```java
package com.example.filter;

import java.io.IOException;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;

@WebServlet("/hello")
public class HelloServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;

    /** POST 请求（常见表单提交） */
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        // 由于 EncodingFilter 已经 setCharacterEncoding("UTF-8"),
        // 这里直接获取参数即可得到正确的中文
        String name = req.getParameter("name");
        if (name == null) {
            name = "世界";
        }

        resp.setContentType("text/html;charset=UTF-8");
        resp.getWriter().write("<h1>Hello, " + name + "!</h1>");
    }

    /** GET 请求（示例用） */
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        doPost(req, resp);
    }
}
```

> **使用说明**  
> 1. 访问 `http://localhost:8080/java-web-filter-encoding/hello?name=张三`  
>    (GET 请求，参数直接放在 URL 里)  
> 2. 使用 Postman 或 HTML `<form>` 提交 `POST` 请求，body 里 `name=李四`（POST body 必须采用 UTF‑8，Filter 会自动处理）。

### 4.2 `TestServlet.java`（演示 GET 参数的编码处理）

```java
