import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class TCPPacketServer {

    private static final int PORT = 1024;
    private static final ExecutorService pool = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        System.out.println("Opening port…");            // <<< NEW
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            while (true) {
                Socket clientSocket = serverSocket.accept();
                pool.execute(new ClientHandler(clientSocket));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        pool.shutdown();
    }

    /** Handle one client connection */
    private static class ClientHandler implements Runnable {
        private final Socket socket;

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (   // keep the streams open for the whole session
                    ObjectInputStream ois =
                            new ObjectInputStream(socket.getInputStream());
                    ObjectOutputStream oos =
                            new ObjectOutputStream(socket.getOutputStream());
                 ) {

                while (true) {
                    Object obj = ois.readObject();
                    if (!(obj instanceof Packet)) {
                        System.err.println("Received unknown object");
                        break;
                    }
                    Packet packet = (Packet) obj;

                    // 1️⃣ Print what the spec demands
                    System.out.println(
                            "Recieving From Clients Packet’s serialNo#" + packet.getSerialNo()
                    );
                    System.out.println(
                            "and packet’s Data is " + packet.getData()
                    );

                    // 2️⃣ If the client wants to close the connection
                    if ("CLOSE".equalsIgnoreCase(packet.getData())) {
                        break;
                    }

                    // 3️⃣ Respond with a packet that has the same serialNo
                    //    (you can change the logic if you prefer)
                    Packet response = new Packet(
                            packet.getSerialNo(),
                            packet.getData().toUpperCase()
                    );
                    oos.writeObject(response);
                    oos.flush();
                }
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            } finally {
                try {
                    socket.close();
                } catch (IOException ignore) {}
            }
        }
    }
}
