import java.io.*;
import java.net.*;

public class TCPPacketClient {

    private static final String PROMPT = "Enter the data packet: ";

    public static void main(String[] args) {
        try (Socket socket = new Socket("localhost", 1024);
             ObjectOutputStream oos =
                     new ObjectOutputStream(socket.getOutputStream());
             ObjectInputStream ois =
                     new ObjectInputStream(socket.getInputStream());
             BufferedReader console = new BufferedReader(
                     new InputStreamReader(System.in));
        ) {

            int serialNo = 1;
            while (true) {
                System.out.print(PROMPT);
                String line = console.readLine();

                if (line == null) {   // EOF from console
                    break;
                }

                // 1️⃣ Send the packet
                Packet packet = new Packet(serialNo++, line);
                oos.writeObject(packet);
                oos.flush();

                // 2️⃣ Receive the server’s acknowledgement
                Object obj = ois.readObject();
                if (!(obj instanceof Packet)) {
                    System.err.println("Received unknown object from server");
                    break;
                }
                Packet response = (Packet) obj;
                System.out.println(
                        "FROM SERVER:Packet SerialNo#" +
                                response.getSerialNo() +
                                " is recieved"
                );

                // 3️⃣ Stop if we sent the “CLOSE” command
                if ("CLOSE".equalsIgnoreCase(line)) {
                    break;
                }
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
}
