#### 2.2.2 服务器端（纯 Java）

```java
// File: ImageWebSocketServer.java
import org.java_websocket.WebSocket;
import org.java_websocket.handshake.ClientHandshake;
import org.java_websocket.server.WebSocketServer;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.file.Files;
import java.nio.file.Paths;

public class ImageWebSocketServer extends WebSocketServer {

    public ImageWebSocketServer(int port) {
        super(new InetSocketAddress(port));
    }

    @Override
    public void onOpen(WebSocket conn, ClientHandshake handshake) {
        System.out.println("New connection: " + conn.getRemoteSocketAddress());
    }

    @Override
    public void onClose(WebSocket conn, int code, String reason, boolean remote) {
        System.out.println("Closed connection: " + conn.getRemoteSocketAddress() + " Code: " + code);
    }

    @Override
    public void onMessage(WebSocket conn, String message) {
        // 服务器端不使用文本消息
    }

    @Override
    public void onMessage(WebSocket conn, ByteBuffer bytes) {
        System.out.println("Received image of length " + bytes.remaining() + " bytes");
        try {
            String outFile = "received_" + conn.getRemoteSocketAddress() + ".png";
            Files.write(Paths.get(outFile), bytes.array());
            System.out.println("Saved to " + outFile);
            conn.send("Image received, size=" + bytes.remaining());  // 回复
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void onError(WebSocket conn, Exception ex) {
        ex.printStackTrace();
    }

    @Override
    public void onStart() {
        System.out.println("Server started on " + getAddress());
    }

    public static void main(String[] args) {
        int port = 8080;
        new ImageWebSocketServer(port).start();
    }
}
```

#### 2.2.3 客户端（纯 Java）

```java
// File: ImageWebSocketClient.java
import org.java_websocket.client.WebSocketClient;
import org.java_websocket.handshake.ServerHandshake;

import java.net.URI;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;

public class ImageWebSocketClient extends WebSocketClient {

    private final byte[] imageBytes;

    public ImageWebSocketClient(URI serverUri, byte[] imageBytes) {
        super(serverUri);
        this.imageBytes = imageBytes;
    }

    @Override
    public void onOpen(ServerHandshake handshakedata) {
        System.out.println("Connected to server");
        send(imageBytes);  // 发送二进制
    }

    @Override
    public void onMessage(String message) {
        System.out.println("Server says: " + message);
        close();
    }

    @Override
    public void onMessage(ByteBuffer bytes) {
        // 服务器可以返回二进制
    }

    @Override
    public void onClose(int code, String reason, boolean remote) {
        System.out.println("Connection closed. Code: " + code + " Reason: " + reason);
    }

    @Override
    public void onError(Exception ex) {
        ex.printStackTrace();
    }

    public static void main(String[] args) throws Exception {
        if (args.length < 2) {
            System.err.println("Usage: java ImageWebSocketClient <ws-url> <image-path>");
            System.exit(1);
        }
        String wsUrl = args[0];
        String imagePath = args[1];
        byte[] bytes = Files.readAllBytes(Path.of(imagePath));

        ImageWebSocketClient client = new ImageWebSocketClient(URI.create(wsUrl), bytes);
        client.connectBlocking();  // 阻塞等待连接
    }
}
```

> **运行**  
> ```bash
> java ImageWebSocketServer
> java ImageWebSocketClient ws://localhost:8080/ /path/to/your/image.png
> ```

