## 5️⃣ SocketThreadPool.java（线程池封装）

```java
package com.example.socketreceiver.service;

import com.example.socketreceiver.config.SocketConfig;
import org.springframework.stereotype.Component;

import javax.annotation.PostConstruct;
import javax.annotation.PreDestroy;
import java.util.concurrent.*;

@Component
public class SocketThreadPool {

    private final SocketConfig config;
    private ExecutorService executor;

    public SocketThreadPool(SocketConfig config) {
        this.config = config;
    }

    @PostConstruct
    public void init() {
        executor = new ThreadPoolExecutor(
                config.getThreadPool().getCoreSize(),
                config.getThreadPool().getMaxSize(),
                60L,
                TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(config.getThreadPool().getQueueCapacity()),
                new ThreadPoolExecutor.AbortPolicy()
        );
        System.out.println("Socket thread pool initialized.");
    }

    @PreDestroy
    public void shutdown() {
        if (executor != null) {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
            System.out.println("Socket thread pool shut down.");
        }
    }

    public void submit(Runnable task) {
        executor.submit(task);
    }
}
```

