## 6️⃣ SocketHandler.java（单个连接处理器）

```java
package com.example.socketreceiver.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import java.net.Socket;

/**
 * 负责对一个客户端连接进行读写。这里演示最简单的文本协议：
 *  - 客户端发送一句话，服务器返回 "收到: <原句>"
 *  - 以 '\n' 结束一行。
 *
 * 如果你需要更复杂的协议（如二进制帧、序列化对象等），请自行改造。
 */
public class SocketHandler implements Runnable {

    private static final Logger log = LoggerFactory.getLogger(SocketHandler.class);

    private final Socket clientSocket;

    public SocketHandler(Socket clientSocket) {
        this.clientSocket = clientSocket;
    }

    @Override
    public void run() {
        String clientAddr = clientSocket.getRemoteSocketAddress().toString();
        log.info("Handling connection from {}", clientAddr);
        try (BufferedReader br = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
             BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(clientSocket.getOutputStream()))) {

            String line;
            while ((line = br.readLine()) != null) {
                log.info("Received from {}: {}", clientAddr, line);
                // 业务处理：这里简单回显
                String response = "收到: " + line;
                bw.write(response);
                bw.newLine();
                bw.flush();
            }
        } catch (IOException e) {
            log.error("I/O error with {}: {}", clientAddr, e.getMessage());
        } finally {
            try {
                clientSocket.close();
                log.info("Connection closed: {}", clientAddr);
            } catch (IOException e) {
                log.warn("Error closing socket {}: {}", clientAddr, e.getMessage());
            }
        }
    }
}
```

