## 7️⃣ SocketServer.java（ServerSocket 主线程）

```java
package com.example.socketreceiver.service;

import com.example.socketreceiver.config.SocketConfig;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

import javax.annotation.PostConstruct;
import javax.annotation.PreDestroy;
import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;

/**
 * 在 Spring Boot 启动时创建 ServerSocket，监听客户端连接。
 * 每接收到一个连接后，交给 SocketThreadPool 处理。
 */
@Component
public class SocketServer {

    private static final Logger log = LoggerFactory.getLogger(SocketServer.class);

    private final SocketConfig config;
    private final SocketThreadPool threadPool;

    private ServerSocket serverSocket;
    private volatile boolean running = true;

    public SocketServer(SocketConfig config, SocketThreadPool threadPool) {
        this.config = config;
        this.threadPool = threadPool;
    }

    @PostConstruct
    public void startServer() {
        new Thread(this::runServer, "Socket-Server-Thread").start();
        log.info("Socket server thread started.");
    }

    private void runServer() {
        try {
            serverSocket = new ServerSocket(config.getPort());
            log.info("TCP Socket Server listening on port {}", config.getPort());

            while (running) {
                try {
                    Socket client = serverSocket.accept(); // 阻塞
                    log.info("Accepted connection from {}", client.getRemoteSocketAddress());
                    // 让线程池来处理
                    threadPool.submit(new SocketHandler(client));
                } catch (IOException e) {
                    if (!running) {
                        // 服务器正在关闭时抛出的异常可忽略
                        break;
                    }
                    log.error("Error accepting connection: {}", e.getMessage());
                }
            }
        } catch (IOException e) {
            log.error("Could not start server socket: {}", e.getMessage());
        } finally {
            closeServer();
        }
    }

    @PreDestroy
    public void stopServer() {
        running = false;
        closeServer();
        log.info("Socket server stopped.");
    }

    private void closeServer() {
        if (serverSocket != null && !serverSocket.isClosed()) {
            try {
                serverSocket.close();
                log.info("Server socket closed.");
            } catch (IOException e) {
                log.warn("Error closing server socket: {}", e.getMessage());
            }
        }
    }
}
```

