        IntVector iv = new IntVector("int", allocator);
        VarCharVector vv = new VarCharVector("str", allocator);
        iv.allocateNew(3);
        vv.allocateNew(3);

        iv.set(0, 10); iv.set(1, 20); iv.set(2, 30);
        vv.set(0, "a".getBytes()); vv.set(1, "b".getBytes()); vv.set(2, "c".getBytes());

        iv.setValueCount(3);
        vv.setValueCount(3);

        VectorSchemaRoot root = new VectorSchemaRoot(iv, vv);
        root.setRowCount(3);

        // 写到文件（可以改成内存或套接字）
        try (ArrowStreamWriter writer = new ArrowStreamWriter(root, null, new FileOutputStream("arrow.arrow").getChannel())) {
            writer.start();
            writer.writeBatch();
            writer.end();
        }
    }
}
```

