### iOS

**URLSessionDelegate**：在 `didReceiveChallenge` 中验证服务器信任。  
```swift
class NetworkDelegate: NSObject, URLSessionDelegate {
    func urlSession(_ session: URLSession, 
                    didReceive challenge: URLAuthenticationChallenge, 
                    completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
        guard let serverTrust = challenge.protectionSpace.serverTrust,
              let cert = SecTrustGetCertificateAtIndex(serverTrust, 0) else {
            completionHandler(.cancelAuthenticationChallenge, nil)
            return
        }

        // 计算证书 SHA256
        var certData = SecCertificateCopyData(cert) as Data
        let hash = Insecure.SHA256.hash(data: certData)
        let hashBase64 = Data(hash).base64EncodedString()

        // 与硬编码的 SHA256 比对
        if hashBase64 == "XXXXXXXXXXXXXXXXXXXX==" ||
           hashBase64 == "YYYYYYYYYYYYYYYYYYYY==" {
            completionHandler(.useCredential, URLCredential(trust: serverTrust))
        } else {
            completionHandler(.cancelAuthenticationChallenge, nil)
        }
    }
}
```
> **提示**：若使用 **App Transport Security (ATS)**，默认已开启 TLS 1.2+，但 ATS 仅保证最低级别的加密；若想更细粒度控制，需要自行实现 `URLSessionDelegate`。

