```java
package com.example.json2xml;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * JSON 转 XML 工具类
 */
public final class JsonToXmlConverter {

    private static final ObjectMapper JSON_MAPPER = new ObjectMapper(new JsonFactory());
    private static final XmlMapper XML_MAPPER = new XmlMapper();

    private JsonToXmlConverter() {
        // 工具类不实例化
    }

    /**
     * 将 JSON 字符串转换为 XML 字符串
     *
     * @param jsonStr 输入的 JSON 字符串
     * @return XML 字符串
     * @throws JsonProcessingException 解析错误
     */
    public static String convertString(String jsonStr) throws JsonProcessingException {
        JsonNode node = JSON_MAPPER.readTree(jsonStr);
        return XML_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(node);
    }

    /**
     * 将 JSON 文件转换为 XML 文件
     *
     * @param jsonFile   JSON 源文件
     * @param xmlFile    输出的 XML 文件
     * @throws IOException IO异常
     */
    public static void convertFile(Path jsonFile, Path xmlFile) throws IOException {
        JsonNode node = JSON_MAPPER.readTree(Files.newBufferedReader(jsonFile, StandardCharsets.UTF_8));
        try (BufferedWriter writer = Files.newBufferedWriter(xmlFile, StandardCharsets.UTF_8)) {
            XML_MAPPER.writerWithDefaultPrettyPrinter().writeValue(writer, node);
        }
    }

    /**
     * 将 JSON 输入流转换为 XML 输出流
     *
     * @param jsonInput  JSON 输入流
     * @param xmlOutput  XML 输出流
     * @throws IOException IO异常
     */
    public static void convertStream(InputStream jsonInput, OutputStream xmlOutput) throws IOException {
        JsonNode node = JSON_MAPPER.readTree(jsonInput);
        XML_MAPPER.writerWithDefaultPrettyPrinter().writeValue(xmlOutput, node);
    }

    /** 简单测试 */
    public static void main(String[] args) {
        // 示例 1: 字符串
        String json = """
                {
                  "name": "Alice",
                  "age": 30,
                  "skills": ["Java", "Kotlin"],
                  "address": {
                    "city": "Shanghai",
                    "zip": "200000"
                  }
                }
                """;

        try {
            String xml = convertString(json);
            System.out.println("=== XML ===");
            System.out.println(xml);
        } catch (JsonProcessingException e) {
            e.printStackTrace();
        }

        // 示例 2: 文件
        Path jsonPath = Path.of("sample.json");
        Path xmlPath = Path.of("sample.xml");

        try {
            // 若 sample.json 不存在，可先写入
            if (!Files.exists(jsonPath)) {
                Files.writeString(jsonPath, json, StandardCharsets.UTF_8);
            }
            convertFile(jsonPath, xmlPath);
            System.out.println("XML 写入成功: " + xmlPath.toAbsolutePath());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

### 说明

| 方法 | 作用 | 参数 | 返回值 |
|------|------|------|--------|
| `convertString(String)` | JSON 字符串 → XML 字符串 | `jsonStr` | XML 字符串 |
| `convertFile(Path, Path)` | JSON 文件 → XML 文件 | `jsonFile`、`xmlFile` | 无 |
| `convertStream(InputStream, OutputStream)` | JSON 输入流 → XML 输出流 | `jsonInput`、`xmlOutput` | 无 |
| `main(String[])` | 简单测试 | 无 | 无 |

- `XmlMapper` 默认会把根节点命名为 `<JsonNode>`，如果你想自定义根节点名称，可以在调用前用 `XML_MAPPER.setDefaultUseWrapper(false)` 或在 `JsonNode` 上使用 `withName("root")` 之类的方式调整。  
- 代码中使用 `writerWithDefaultPrettyPrinter()` 让输出 XML 具备可读性；若不需要格式化，可去掉它。

---

## 3. 如何运行

1. **使用 Maven**  
   ```bash
   mvn compile
   mvn exec:java -Dexec.mainClass="com.example.json2xml.JsonToXmlConverter"
   ```
2. **手动编译**  
   ```bash
   javac -cp "libs/*" -d out src/com/example/json2xml/JsonToXmlConverter.java
   java -cp "out:libs/*" com.example.json2xml.JsonToXmlConverter
   ```
3. **IDE**  
   - 把上述代码复制到 `src/com/example/json2xml/JsonToXmlConverter.java`。  
   - 在 IDE 的 Maven 或 Gradle 配置里引入 Jackson 依赖。  
   - 运行 `JsonToXmlConverter.main()`。

---

## 4. 进阶：自定义根节点 & 属性

如果你想让生成的 XML 有自己的根标签名，例如 `<person>`，可以这样做：

```java
public static String convertStringWithRoot(String jsonStr, String rootName) throws JsonProcessingException {
    JsonNode node = JSON_MAPPER.readTree(jsonStr);
    // 把 node 包装进一个新的根节点
    JsonNode wrapped = JSON_MAPPER.createObjectNode().set(rootName, node);
    return XML_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(wrapped);
}
```

使用示例：

```java
String xml = convertStringWithRoot(json, "person");
```

---

## 5. 参考资料

- [Jackson 官方文档 – XML Module](https://github.com/FasterXML/jackson-dataformat-xml)  
- [Jackson 2.x API Docs](https://fasterxml.github.io/jackson-databind/javadoc/2.17/)  

