        DataStore.load();

        while (true) {
            Socket client = serverSocket.accept();
            pool.submit(() -> handleClient(client));
        }
    }

    private static void handleClient(Socket socket) {
        try (BufferedReader in = new BufferedReader(
                 new InputStreamReader(socket.getInputStream()));
             BufferedWriter out = new BufferedWriter(
                 new OutputStreamWriter(socket.getOutputStream()))) {

            String line;
            while ((line = in.readLine()) != null) {
                JsonNode request = JsonUtils.fromString(line);
                JsonNode response = processRequest(request);
                out.write(JsonUtils.toString(response));
                out.newLine();
                out.flush();
            }
        } catch (IOException e) { /* log */ }
    }

    private static JsonNode processRequest(JsonNode request) {
        String op = request.get("op").asText();
        JsonNode data = request.get("data");
        try {
            switch (op) {
                case "register": return handleRegister(data);
                case "login":    return handleLogin(data);
                case "logout":   return handleLogout(data);
                case "searchHotel":        return handleSearchHotel(data);
                case "searchAllHotels":    return handleSearchAllHotels(data);
                case "insertReview":       return handleInsertReview(data);
                case "showMyBadges":       return handleShowBadges(data);
                default: return error("UNKNOWN_OP", "Operazione non riconosciuta");
            }
        } catch (Exception e) {
            return error("SERVER_ERROR", e.getMessage());
        }
    }

    /* --- metodi di supporto --- */
    private static JsonNode handleRegister(JsonNode data) { /* ... */ }
    private static JsonNode handleLogin(JsonNode data) { /* ... */ }
    /* ... e così via ... */
}
