            }
        }
    }

    /* --- implementazioni delle comandi --- */
    private void register(String[] parts) throws IOException {
        if (parts.length < 3) { System.out.println("Usage: register <user> <pass>"); return; }
        ObjectNode data = JsonNodeFactory.instance.objectNode();
        data.put("username", parts[1]);
        data.put("password", parts[2]);
        send("register", data);
    }

    private void login(String[] parts) throws IOException {
        if (parts.length < 3) { System.out.println("Usage: login <user> <pass>"); return; }
        ObjectNode data = JsonNodeFactory.instance.objectNode();
        data.put("username", parts[1]);
        data.put("password", parts[2]);
        send("login", data);
    }

    private void logout() throws IOException {
        send("logout", JsonNodeFactory.instance.objectNode());
    }

    private void searchHotel(String[] parts) throws IOException {
        if (parts.length < 3) { System.out.println("Usage: search <hotel> <city>"); return; }
        ObjectNode data = JsonNodeFactory.instance.objectNode();
        data.put("nomeHotel", parts[1]);
        data.put("citta", parts[2]);
        send("searchHotel", data);
    }

    private void searchAllHotels(String[] parts) throws IOException {
        if (parts.length < 2) { System.out.println("Usage: searchall <city>"); return; }
        ObjectNode data = JsonNodeFactory.instance.objectNode();
        data.put("citta", parts[1]);
        send("searchAllHotels", data);
    }

    private void insertReview(String[] parts) throws IOException {
        if (parts.length < 5) {
            System.out.println("Usage: review <hotel> <city> <global> <category1=score1> ...");
            return;
        }
        ObjectNode data = JsonNodeFactory.instance.objectNode();
        data.put("nomeHotel", parts[1]);
        data.put("nomeCitta", parts[2]);
        data.put("globalScore", Double.parseDouble(parts[3]));

        ObjectNode single = JsonNodeFactory.instance.objectNode();
        for (int i = 4; i < parts.length; i++) {
            String[] kv = parts[i].split("=");
            single.put(kv[0], Double.parseDouble(kv[1]));
