```java
private static JsonNode handleRegister(JsonNode data) {
    String user = data.get("username").asText();
    String pass = data.get("password").asText();

    if (user.isEmpty() || pass.isEmpty())
        return error("EMPTY_FIELDS", "Username o password vuoti");

    if (users.containsKey(user))
        return error("USER_EXISTS", "Username già presente");

    String hashed = PasswordUtils.hash(pass);   // bcrypt / PBKDF2
    User u = new User(user, hashed);
    users.put(user, u);

    return ok("User registrato con successo");
}
