     * Sends raw bytes to the server.
     *
     * @param data data to send
     * @throws IOException if the socket is not connected or write fails
     */
    public void send(@NonNull byte[] data) throws IOException {
        if (out == null) throw new SocketException("Socket not connected");
        out.write(data);
        out.flush();
    }

    /**
     * Reads up to {@code buffer.length} bytes.
     *
     * @param buffer destination array
     * @return number of bytes read, or -1 if end‑of‑stream
     * @throws IOException if the socket is not connected or read fails
     */
    public int read(@NonNull byte[] buffer) throws IOException {
        if (in == null) throw new SocketException("Socket not connected");
        return in.read(buffer);
    }

    /**
     * Reads a line terminated by '\n' (CR or CRLF allowed).
     *
     * @return line without line‑ending, or null on EOF
     * @throws IOException
     */
    public @Nullable String readLine() throws IOException {
        if (in == null) throw new SocketException("Socket not connected");
        StringBuilder sb = new StringBuilder();
        int ch;
        while ((ch = in.read()) != -1) {
            if (ch == '\r') continue;  // ignore carriage return
            if (ch == '\n') break;
            sb.append((char) ch);
        }
        if (ch == -1 && sb.length() == 0) return null;  // EOF
        return sb.toString();
    }

    /* -------------------------------------------------------------------- */
    /*  Static helpers for creating “trust‑all” socket factories            */
    /* -------------------------------------------------------------------- */

    /**
     * Creates an SSLSocketFactory that trusts **all** certificates.
     * <b>Only for debugging or environments you control.</b>
     *
     * @return a permissive SSLSocketFactory
     */
    @SuppressLint("BadHostnameVerifier")
    public static SSLSocketFactory createTrustAllSocketFactory() {
        try {
            // 1. Create a TrustManager that trusts everything
            TrustManager[] trustAllCerts = new TrustManager[] {
                    new X509TrustManager() {
                        public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
                        public void checkClientTrusted(X509Certificate[] chain, String authType) { /* no-op */ }
                        public void checkServerTrusted(X509Certificate[] chain, String authType) { /* no-op */ }
                    }
            };

            // 2. Install the all‑trusting TrustManager
            SSLContext sc = SSLContext.getInstance("TLS");
            sc.init(null, trustAllCerts, new SecureRandom());

            // 3. Return the socket factory from the context
            return sc.getSocketFactory();
        } catch (Exception e) {
            throw new RuntimeException("Failed to create trust‑all socket factory", e);
        }
    }

    /* -------------------------------------------------------------------- */
    /*  Helper – enable TLS1.2 on older Android versions                  */
    /* -------------------------------------------------------------------- */

    /**
     * Force the socket to enable TLS1.2/TLS1.3 when running on Android < 6.0.
     * On newer OSes this is a no‑op because TLS1.2+ is enabled by default.
     */
    private static void setSupportedProtocolsAndCiphers(SSLSocket socket) {
        if (Build.VERSION.SDK_INT <= Build.VERSION_CODES.M) {
            // Android 5.0–5.1 default to TLS1.0/1.1; enable 1.2
            String[] protocols = socket.getSupportedProtocols();
            boolean hasTLS12 = false;
            for (String p : protocols) {
                if ("TLSv1.2".equals(p)) {
                    hasTLS12 = true;
                    break;
                }
            }
            if (hasTLS12) {
                socket.setEnabledProtocols(new String[] {"TLSv1.2"});
            }
        }
    }
}
```

---

## 2.  How to use it

```java
// Example: a very small background worker that talks to example.com:443
new Thread(() -> {
    SslTcpClient client = new SslTcpClient("example.com", 443);

    try {
        client.connect();

        // Send an HTTP GET request (no SSL handshake needed – we already did that)
        String httpReq = "GET / HTTP/1.1\r\n" +
                         "Host: example.com\r\n" +
                         "Connection: close\r\n\r\n";
        client.send(httpReq.getBytes(StandardCharsets.US_ASCII));

        // Read the response line‑by‑line
        String line;
        while ((line = client.readLine()) != null) {
            Log.d("SslTcpClient", line);
        }
    } catch (IOException e) {
        Log.e("SslTcpClient", "Network error", e);
    } finally {
        try { client.disconnect(); } catch (IOException ignored) {}
    }
}).start();
```

### Custom certificate / CA

If your server uses a *self‑signed* certificate or a private CA, replace the default socket factory with a custom one that loads your trusted certificates:

```java
KeyStore ks = KeyStore.getInstance(KeyStore.getDefaultType());
InputStream caInput = context.getResources().openRawResource(R.raw.my_ca); // e.g. res/raw/my_ca.crt
ks.load(null, null);
CertificateFactory cf = CertificateFactory.getInstance("X.509");
X509Certificate ca = (X509Certificate) cf.generateCertificate(caInput);
ks.setCertificateEntry("my_ca", ca);

TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
tmf.init(ks);
SSLContext ctx = SSLContext.getInstance("TLS");
ctx.init(null, tmf.getTrustManagers(), new SecureRandom());
SSLSocketFactory factory = ctx.getSocketFactory();

SslTcpClient client = new SslTcpClient("my.server.com", 443, factory, HttpsURLConnection.getDefaultHostnameVerifier());
```

---

## 3.  Things to keep in mind

| Topic | Recommendation |
|-------|----------------|
| **Threading** | Do **not** call `connect()`, `send()`, or `read()` on the UI thread. Use an `ExecutorService` or Kotlin `suspend` function. |
| **Certificate validation** | The default constructor trusts everything. In production **never** use that. Use a real TrustManager that validates the server’s certificate. |
| **Hostname verification** | The default uses `HttpsURLConnection.getDefaultHostnameVerifier()` which checks that the cert’s CN/SAN matches the host you’re connecting to. Replace it only if you have a very specific requirement. |
| **TLS versions** | Android 6.0+ enables TLS 1.2+ by default. For older devices, `setSupportedProtocolsAndCiphers()` in the helper forces TLS 1.2. |
| **Error handling** | Wrap I/O in try/catch. Close the socket in a `finally` block. |
| **Performance** | Reuse a single `SSLSocketFactory` across many connections to avoid the costly SSL context initialization. |
| **Timeouts** | The plain `Socket` constructor accepts a timeout. If you need read/write timeouts, call `socket.setSoTimeout(...)` after creation. |

---

## 4.  Summary

* `SslTcpClient` opens a **secure TCP socket** (`SSLSocket`) to any host/port.  
* It provides simple `connect()`, `send()`, `read()`/`readLine()`, and `disconnect()` methods.  
* It supports custom `SSLSocketFactory` and `HostnameVerifier` so you can work with self‑signed certificates or custom CA chains.  
* The example demonstrates an HTTP GET request, but you can exchange any binary protocol you need.  

Copy the class into your project, add the INTERNET permission, and you’re ready to talk to a remote server over a TLS‑protected socket from Android. Happy coding!

