package com.studentms;

import java.util.*;
import java.util.stream.Collectors;

/**
 * In‑memory implementation of StudentRepository.
 * Uses a HashMap for O(1) id lookup and an ArrayList for ordered traversal.
 */
public class StudentRepositoryImpl implements StudentRepository<Student> {

    private final Map<Integer, Student> byId = new HashMap<>();

    @Override
    public boolean add(Student student) {
        if (byId.containsKey(student.getId())) {
            return false;   // duplicate id
        }
        byId.put(student.getId(), student);
        return true;
    }

    @Override
    public boolean remove(int id) {
        return byId.remove(id) != null;
    }

    @Override
    public boolean update(Student student) {
        int id = student.getId();
        if (!byId.containsKey(id)) return false;
        byId.put(id, student);
        return true;
    }

    @Override
    public Student findById(int id) {
        return byId.get(id);
    }

    @Override
    public List<Student> findByName(String name) {
        String lc = name.toLowerCase();
        return byId.values().stream()
                .filter(s -> s.getName().toLowerCase().contains(lc))
                .collect(Collectors.toList());
    }

    @Override
    public List<Student> findAll() {
        return new ArrayList<>(byId.values());
    }
}
