        IMAGE,     // 图片
        FILE,      // 文件
        JOIN,      // 用户请求客服
        ACCEPT,    // 客服接收
        REJECT,    // 客服拒绝
        BUSY,      // 客服繁忙（超时未响应）
        EXIT       // 结束会话
