    private final String sender;    // 发送者（用户名或客服名）
    private final String receiver;  // 接收者（客服或用户）
    private final String body;      // 文本内容（若是文件或图片则为文件名）
    private final long  fileSize;   // 对于 FILE/IMAGE 的字节长度

    public Message(Type type, String sender, String receiver, String body, long fileSize) {
        this.type = type; this.sender = sender; this.receiver = receiver;
        this.body = body; this.fileSize = fileSize;
    }

    // 省略 getters、toString、equals、hashCode
}
