    public void notifyAgentNewUser(ClientHandler handler) {
        waitingQueue.offer(handler);
    }

    public ClientHandler pollWaiting() {
        return waitingQueue.poll();
    }

    public void addActiveUser(String username, ClientHandler handler) {
        activeUsers.put(username, handler);
    }

    public void removeActiveUser(String username) {
        activeUsers.remove(username);
    }

    public ClientHandler getActiveHandler(String username) {
        return activeUsers.get(username);
