```java
/**
 * 每个连接对应一个 ClientHandler。
 * 负责与单一用户进行通信，转发消息给 Agent GUI。
 */
public class ClientHandler implements Runnable {
    private final Socket socket;
    private final ChatServer server;
    private final String user; // 用户名，从第一次 JOIN 消息中获取
    private DataInputStream in;
    private DataOutputStream out;
    private volatile boolean running = true;

    // 关联的客服窗口（若已被接收）
    private AgentChatWindow chatWindow;

    public ClientHandler(Socket socket, ChatServer server) {
        this.socket = socket;
        this.server = server;
        this.user = null; // 先未确定
    }

    @Override
    public void run() {
        try (DataInputStream in = new DataInputStream(socket.getInputStream());
             DataOutputStream out = new DataOutputStream(socket.getOutputStream())) {
            this.in = in;
            this.out = out;

            // 步骤 1：接收 JOIN 请求
            Message join = receiveMessage();
            if (join.type != Message.Type.JOIN) throw new IllegalStateException("First msg must be JOIN");
            this.user = join.sender;

            // 通知客服端 GUI
            server.notifyAgentNewUser(this);

            // 等待客服端的 ACCEPT / REJECT
            // 这里用一个简单的等待锁，若 15 秒未响应则自动 BUSY
            synchronized (this) {
                wait(15000); // 线程等待，收到客服端通知后 notify()
            }
            // 若此时 chatWindow 为空，说明被拒绝或超时
            if (chatWindow == null) {
                sendMessage(new Message(Message.Type.BUSY, "Server", user, "", 0));
                close();
                return;
            }

            // 进入正常聊天循环
            while (running) {
                Message msg = receiveMessage();
                if (msg == null) break;
                // 按需转发给客服端
                chatWindow.forwardFromClient(msg);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            close();
        }
    }

    /* 客服端发送消息给用户 */
    public void sendMessage(Message msg) {
        try {
            synchronized (out) {
                writeMessage(msg);
            }
        } catch (IOException e) {
            e.printStackTrace();
            close();
        }
    }

    /* 关联客服聊天窗口 */
    public void setChatWindow(AgentChatWindow window) {
        this.chatWindow = window;
        synchronized (this) {
            notify(); // 唤醒等待
        }
    }

    /* 关闭连接 */
    public void close() {
        running = false;
        server.removeActiveUser(user);
        try { socket.close(); } catch (IOException ignored) {}
    }

    /* ----------------- 下面是协议读写工具 ----------------- */

    private Message receiveMessage() throws IOException {
        // 读取长度
        int len = in.readInt();
        if (len <= 0) return null;
        byte[] data = new byte[len];
        in.readFully(data);

        // 解析字符串
        String s = new String(data, StandardCharsets.UTF_8);
        String[] parts = s.split("\\|", 5);
        Message.Type type = Message.Type.valueOf(parts[0]);
        String sender = parts[1];
        String receiver = parts[2];
        String body = parts[3];
        long fileSize = Long.parseLong(parts[4]);

        // 若是 FILE/IMAGE，需要读取后续字节
        if ((type == Message.Type.FILE || type == Message.Type.IMAGE) && fileSize > 0) {
            byte[] fileBytes = new byte[(int) fileSize];
            in.readFully(fileBytes);
            // 这里我们把文件直接保存在本地 temp 目录下
            Path path = Paths.get("temp", body);
            Files.createDirectories(path.getParent());
            Files.write(path, fileBytes);
            // 对于 GUI 我们可以直接把路径返回
            body = path.toString();
        }
        return new Message(type, sender, receiver, body, fileSize);
    }

    private void writeMessage(Message msg) throws IOException {
        String header = String.format("%s|%s|%s|%s|%d",
                msg.type, msg.sender, msg.receiver, msg.body, msg.fileSize);
        byte[] headerBytes = header.getBytes(StandardCharsets.UTF_8);
        out.writeInt(headerBytes.length);
        out.write(headerBytes);
        out.flush();

        // 对于 FILE/IMAGE，写出文件字节
        if ((msg.type == Message.Type.FILE || msg.type == Message.Type.IMAGE)
                && msg.fileSize > 0 && Files.exists(Paths.get(msg.body))) {
            byte[] fileBytes = Files.readAllBytes(Paths.get(msg.body));
            out.write(fileBytes);
            out.flush();
        }
    }
}
```

> **说明**  
> - `ClientHandler` 负责与单一用户的完整通信。  
> - 当用户 JOIN 后，先把自身放入 `waitingQueue`，等待客服端 GUI 的 ACCEPT/REJECT。  
> - 采用 `wait/notify` 机制实现 15 秒超时后自动返回 BUSY。  
> - 文件/图片在接收时先把字节流写到 `temp` 目录，随后在 GUI 里直接加载。  

