## 5. 用户端 GUI (`UserClient.java`)

```java
/**
 * 简易用户端 GUI，演示连接、发送文字/图片、等待客服响应。
 */
public class UserClient extends JFrame {
    private final JTextField txtUser = new JTextField(10);
    private final JTextField txtAddr = new JTextField("127.0.0.1");
    private final JTextField txtPort = new JTextField("9090");
    private final JButton btnConnect = new JButton("连接");

    private final JTextArea chatArea = new JTextArea();
    private final JTextField inputField = new JTextField();
    private final JButton sendBtn = new JButton("发送");
    private final JButton imgBtn = new JButton("发送图片");

    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;

    private volatile boolean connected = false;

    public UserClient() {
        setTitle("电商客服 - 用户端");
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setSize(600, 500);
        setLocationRelativeTo(null);
        initUI();
    }

    private void initUI() {
        JPanel top = new JPanel();
        top.add(new JLabel("用户名:"));
        top.add(txtUser);
        top.add(new JLabel("IP:"));
        top.add(txtAddr);
        top.add(new JLabel("Port:"));
        top.add(txtPort);
        top.add(btnConnect);
        add(top, BorderLayout.NORTH);

        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel south = new JPanel(new BorderLayout());
        south.add(inputField, BorderLayout.CENTER);
        JPanel btns = new JPanel();
        btns.add(sendBtn);
        btns.add(imgBtn);
        south.add(btns, BorderLayout.EAST);
        add(south, BorderLayout.SOUTH);

        btnConnect.addActionListener(e -> connect());
        sendBtn.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> sendImage());
    }

    /* 连接服务器并发送 JOIN */
    private void connect() {
        if (connected) return;
        try {
            socket = new Socket(txtAddr.getText().trim(), Integer.parseInt(txtPort.getText().trim()));
            in = new DataInputStream(socket.getInputStream());
            out = new DataOutputStream(socket.getOutputStream());
            // 发送 JOIN
            sendMessage(new Message(Message.Type.JOIN, txtUser.getText().trim(), "Agent", "", 0));
            // 启动接收线程
            new Thread(this::listenServer).start();
            connected = true;
            btnConnect.setEnabled(false);
            chatArea.append("已连接，等待客服响应...\n");
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this, "连接失败: " + ex.getMessage());
        }
    }

    /* 监听服务器消息 */
    private void listenServer() {
        try {
            while (true) {
                Message msg = receiveMessage();
                if (msg == null) break;
                switch (msg.type) {
                    case TEXT -> SwingUtilities.invokeLater(() -> chatArea.append("[客服] " + msg.body + "\n"));
                    case IMAGE -> SwingUtilities.invokeLater(() -> {
                        // 简化：仅显示文件路径，实际可使用 ImageIcon
                        chatArea.append("[客服] [图片] " + msg.body + "\n");
                    });
                    case FILE -> SwingUtilities.invokeLater(() ->
                            chatArea.append("[客服] [文件] " + msg.body + "\n"));
                    case BUSY -> SwingUtilities.invokeLater(() ->
                            JOptionPane.showMessageDialog(this, "客服繁忙，稍后再来！"));
                    case REJECT -> SwingUtilities.invokeLater(() -> {
                        JOptionPane.showMessageDialog(this, "客服拒绝服务");
                        closeConn();
                    });
                    case ACCEPT -> SwingUtilities.invokeLater(() -> chatArea.append("客服已接入！\n"));
                    case EXIT -> break;
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(this, "连接异常，已断开");
        } finally {
            closeConn();
        }
    }

    /* 发送文字 */
    private void sendText() {
        if (!connected) return;
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        sendMessage(new Message(Message.Type.TEXT, txtUser.getText().trim(),
                "Agent", txt, 0));
        chatArea.append("[你] " + txt + "\n");
        inputField.setText("");
    }

    /* 发送图片 */
    private void sendImage() {
        if (!connected) return;
        JFileChooser chooser = new JFileChooser();
        int opt = chooser.showOpenDialog(this);
        if (opt != JFileChooser.APPROVE_OPTION) return;
        File img = chooser.getSelectedFile();
        if (!img.exists()) return;

        // 简化：将文件直接拷贝到 temp 目录，后续服务器会读取
        try {
            Path tempPath = Paths.get("temp", img.getName());
            Files.createDirectories(tempPath.getParent());
            Files.copy(img.toPath(), tempPath, StandardCopyOption.REPLACE_EXISTING);
            Message msg = new Message(Message.Type.IMAGE, txtUser.getText().trim(),
                    "Agent", img.getName(), img.length());
            sendMessage(msg);
            chatArea.append("[你] [图片] " + img.getName() + "\n");
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this, "发送失败: " + ex.getMessage());
        }
    }

    /* 发送通用消息 */
    private synchronized void sendMessage(Message msg) {
        try {
            byte[] header = String.format("%s|%s|%s|%s|%d",
                    msg.type, msg.sender, msg.receiver, msg.body, msg.fileSize)
                    .getBytes(StandardCharsets.UTF_8);
            out.writeInt(header.length);
            out.write(header);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
            closeConn();
        }
    }

    /* 接收消息（用于后台线程） */
    private Message receiveMessage() throws IOException {
        int len = in.readInt();
        if (len <= 0) return null;
        byte[] data = new byte[len];
        in.readFully(data);
        String s = new String(data, StandardCharsets.UTF_8);
        String[] parts = s.split("\\|", 5);
        Message.Type type = Message.Type.valueOf(parts[0]);
        String sender = parts[1];
        String receiver = parts[2];
        String body = parts[3];
        long fileSize = Long.parseLong(parts[4]);

        // 读取文件/图片字节（如果有）
        if ((type == Message.Type.FILE || type == Message.Type.IMAGE) && fileSize > 0) {
            byte[] fileBytes = new byte[(int) fileSize];
            in.readFully(fileBytes);
            Path path = Paths.get("temp", body);
            Files.createDirectories(path.getParent());
            Files.write(path, fileBytes);
            body = path.toString();
        }
        return new Message(type, sender, receiver, body, fileSize);
    }

    /* 断开连接 */
    private void closeConn() {
        connected = false;
        try { socket.close(); } catch (IOException ignored) {}
        SwingUtilities.invokeLater(() -> btnConnect.setEnabled(true));
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new UserClient().setVisible(true));
    }
}
```

> **说明**  
> - `connect()` 之后立即发送 `JOIN`。  
> - 通过后台线程 `listenServer()` 处理服务器发来的各种消息。  
> - 简化了图片、文件的接收：直接保存在 `temp` 目录，用户可自行打开。  

