## 5. SecurityConfig.java (CAS client configuration)

```java
package com.eduverse.lms.config;

import com.eduverse.lms.service.CasUserDetailsService;
import org.jasig.cas.client.authentication.AuthenticationFilter;
import org.jasig.cas.client.authentication.AuthenticationHandler;
import org.jasig.cas.client.authentication.handler.support.SimpleUsernamePasswordAuthenticationHandler;
import org.jasig.cas.client.validation.Cas20ServiceTicketValidator;
import org.jasig.cas.client.validation.TicketValidator;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationProvider;
import org.springframework.security.cas.authentication.CasAuthenticationProvider;
import org.springframework.security.cas.web.CasAuthenticationEntryPoint;
import org.springframework.security.cas.web.CasAuthenticationFilter;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.authentication.www.BasicAuthenticationFilter;
import org.springframework.security.web.authentication.session.SessionAuthenticationStrategy;
import org.springframework.security.web.session.InvalidSessionStrategy;
import org.springframework.security.web.session.HttpSessionEventPublisher;
import org.springframework.security.web.util.matcher.AntPathRequestMatcher;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Value("${cas.serverUrl}")
    private String casServerUrl;

    @Value("${cas.serviceUrl}")
    private String casServiceUrl;

    /**
     * Validate the ticket returned by the CAS server.
     */
    @Bean
    public TicketValidator ticketValidator() {
        return new Cas20ServiceTicketValidator(casServerUrl);
    }

    /**
     * The filter that kicks in on every request to /cas, redirects to CAS, and
     * handles the ticket validation.
     */
    @Bean
    public CasAuthenticationFilter casAuthenticationFilter() {
        CasAuthenticationFilter filter = new CasAuthenticationFilter();
        filter.setFilterProcessesUrl("/cas");  // the endpoint we expose
        filter.setAuthenticationManager(authenticationManager());
        return filter;
    }

    /**
     * Provider that turns a valid CAS ticket into an authenticated Spring Security user.
     */
    @Bean
    public AuthenticationProvider casAuthenticationProvider() {
        CasAuthenticationProvider provider = new CasAuthenticationProvider();
        provider.setAuthenticationUserDetailsService(userDetailsService());
        provider.setServiceProperties(serviceProperties());
        provider.setTicketValidator(ticketValidator());
        provider.setKey("eduverse-lms");
        return provider;
    }

    /**
     * Where CAS will redirect the user after login.
     */
    @Bean
    public org.jasig.cas.client.authentication.ServiceProperties serviceProperties() {
        org.jasig.cas.client.authentication.ServiceProperties sp = new org.jasig.cas.client.authentication.ServiceProperties();
        sp.setService(casServiceUrl + "/cas"); // <-- the callback URL
        sp.setSendRenew(false);
        return sp;
    }

    /**
     * Basic user details service – we just expose the username returned by CAS.
     */
    @Bean
    public CasUserDetailsService userDetailsService() {
        return new CasUserDetailsService();
    }

    /**
     * The entry point for unauthenticated requests – it redirects to the CAS server.
     */
    @Bean
    public CasAuthenticationEntryPoint casEntryPoint() {
        CasAuthenticationEntryPoint entryPoint = new CasAuthenticationEntryPoint();
        entryPoint.setLoginUrl(casServerUrl + "/login");
        entryPoint.setServiceProperties(serviceProperties());
        return entryPoint;
    }

    @Bean
    public org.springframework.security.authentication.AuthenticationManager authenticationManager() {
        // The manager is just the provider we defined
        return authentication -> casAuthenticationProvider().authenticate(authentication);
    }

    @Bean
    public SessionAuthenticationStrategy sessionAuthenticationStrategy() {
        return new org.springframework.security.web.authentication.session.RegisterSessionAuthenticationStrategy(
                new org.springframework.security.web.authentication.session.SessionRegistryImpl()
        );
    }

    @Bean
    public HttpSessionEventPublisher httpSessionEventPublisher() {
        return new HttpSessionEventPublisher();
    }

    /**
     * Security filter chain – protect all URLs except static resources and login endpoint.
     */
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {

        http
            .csrf().disable()   // For simplicity – not recommended for prod
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/css/**", "/js/**", "/images/**", "/index.html").permitAll()
                .anyRequest().authenticated()
            )
            .exceptionHandling()
                .authenticationEntryPoint(casEntryPoint())
            .and()
            .addFilterBefore(casAuthenticationFilter(), BasicAuthenticationFilter.class)
            .sessionManagement()
                .sessionAuthenticationStrategy(sessionAuthenticationStrategy());

        return http.build();
    }
}
```

> **How it works**  
> 1. A user hits `/dashboard`.  
> 2. Because the URL is protected, Spring Security invokes the `CasAuthenticationEntryPoint`.  
> 3. The entry point redirects the browser to `https://cas.eduverse.edu/login?service=https://lms.eduverse.edu/cas`.  
> 4. The user logs in **once** (using Apereo CAS).  
> 5. CAS redirects back to `/cas` with a `ticket` parameter.  
> 6. `CasAuthenticationFilter` intercepts `/cas`, validates the ticket using `Cas20ServiceTicketValidator`, and on success authenticates the user in Spring Security.  
> 7. The user is now able to access `/dashboard`.

