## 2.  Implementation – `EncyclopediaImpl.java`

```java
package encyclopedia;

import java.rmi.RemoteException;
import java.rmi.server.UnicastRemoteObject;
import java.util.*;
import java.util.concurrent.*;

public class EncyclopediaImpl extends UnicastRemoteObject implements Encyclopedia {

    private final String[] words;          // 300 random words
    private final boolean multiThreaded;   // flag: true = multi‑threaded

    protected EncyclopediaImpl(boolean multiThreaded) throws RemoteException {
        super();
        this.multiThreaded = multiThreaded;
        this.words = generateRandomWords(300);
    }

    /* ------------------------------------------------------------------ */
    /*  ----------  Helper – word generator  --------------------------- */
    /* ------------------------------------------------------------------ */
    private static String[] generateRandomWords(int n) {
        Random r = new Random();
        String[] w = new String[n];
        for (int i = 0; i < n; i++) {
            int len = 3 + r.nextInt(7);              // word length 3..9
            StringBuilder sb = new StringBuilder(len);
            for (int j = 0; j < len; j++)
                sb.append((char) ('a' + r.nextInt(26)));
            w[i] = sb.toString();
        }
        return w;
    }

    /* ------------------------------------------------------------------ */
    /*  ----------  Implementation – single‑threaded  ------------------- */
    /* ------------------------------------------------------------------ */
    private int singleThreadedCount() {
        int sum = 0;
        for (String s : words) {
            sum += s.length() + 1;   // +1 for the space that separates words
        }
        return sum;
    }

    private Set<String> singleThreadedRepeated() {
        Map<String, Integer> freq = new HashMap<>();
        for (String s : words) freq.merge(s, 1, Integer::sum);
        Set<String> repeated = new HashSet<>();
        for (Map.Entry<String,Integer> e : freq.entrySet())
            if (e.getValue() > 1) repeated.add(e.getKey());
        return repeated;
    }

    private String singleThreadedLongest() {
        String max = "";
        for (String s : words)
            if (s.length() > max.length()) max = s;
        return max;
    }

    private String singleThreadedShortest() {
        String min = words[0];
        for (String s : words)
            if (s.length() < min.length()) min = s;
        return min;
    }

    private Map<String,Integer> singleThreadedRepeat() {
        Map<String,Integer> freq = new HashMap<>();
        for (String s : words) freq.merge(s, 1, Integer::sum);
        return freq;
    }

    /* ------------------------------------------------------------------ */
    /*  ----------  Implementation – multi‑threaded  ------------------- */
    /* ------------------------------------------------------------------ */
    private int multiThreadedCount() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<Callable<Integer>> tasks = new ArrayList<>();
        for (String s : words) tasks.add(() -> s.length() + 1);
        List<Future<Integer>> results = pool.invokeAll(tasks);
        pool.shutdown();

        int sum = 0;
        for (Future<Integer> f : results) {
            try { sum += f.get(); } catch (ExecutionException ignored) {}
        }
        return sum;
    }

    private Set<String> multiThreadedRepeated() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        ConcurrentMap<String,Integer> freq = new ConcurrentHashMap<>();

        for (String s : words)
            pool.submit(() -> freq.merge(s, 1, Integer::sum));

        pool.shutdown();
        pool.awaitTermination(1, TimeUnit.MINUTES);

        Set<String> repeated = new HashSet<>();
        freq.forEach((k,v) -> { if (v > 1) repeated.add(k); });
        return repeated;
    }

    private String multiThreadedLongest() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletableFuture<String> max = CompletableFuture.supplyAsync(() -> words[0]);

        for (String s : words) {
            String cur = s;
            max = max.thenCombine(CompletableFuture.supplyAsync(() -> cur),
                    (a, b) -> a.length() >= b.length() ? a : b);
        }
        pool.shutdown();
        pool.awaitTermination(1, TimeUnit.MINUTES);
        return max.join();
    }

    private String multiThreadedShortest() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        CompletableFuture<String> min = CompletableFuture.supplyAsync(() -> words[0]);

        for (String s : words) {
            String cur = s;
            min = min.thenCombine(CompletableFuture.supplyAsync(() -> cur),
                    (a, b) -> a.length() <= b.length() ? a : b);
        }
        pool.shutdown();
        pool.awaitTermination(1, TimeUnit.MINUTES);
        return min.join();
    }

    private Map<String,Integer> multiThreadedRepeat() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        ConcurrentMap<String,Integer> freq = new ConcurrentHashMap<>();

        for (String s : words)
            pool.submit(() -> freq.merge(s, 1, Integer::sum));

        pool.shutdown();
        pool.awaitTermination(1, TimeUnit.MINUTES);
        return new HashMap<>(freq);
    }

    /* ------------------------------------------------------------------ */
    /*  ----------  RMI Methods ---------------------------------------- */
    /* ------------------------------------------------------------------ */

    @Override public int Count() throws RemoteException {
        try {
            if (multiThreaded) return multiThreadedCount();
            else return singleThreadedCount();
        } catch (InterruptedException e) { throw new RemoteException(e); }
    }

    @Override public String[] repeatedwords() throws RemoteException {
        try {
            Set<String> set = multiThreaded ? multiThreadedRepeated() : singleThreadedRepeated();
            return set.toArray(new String[0]);
        } catch (InterruptedException e) { throw new RemoteException(e); }
    }

    @Override public String longest() throws RemoteException {
        try {
            return multiThreaded ? multiThreadedLongest() : singleThreadedLongest();
        } catch (InterruptedException e) { throw new RemoteException(e); }
    }

    @Override public String shortest() throws RemoteException {
        try {
            return multiThreaded ? multiThreadedShortest() : singleThreadedShortest();
        } catch (InterruptedException e) { throw new RemoteException(e); }
    }

    @Override public Map<String, Integer> Repeat() throws RemoteException {
        try {
            return multiThreaded ? multiThreadedRepeat() : singleThreadedRepeat();
        } catch (InterruptedException e) { throw new RemoteException(e); }
    }
}
```

> *The heavy lifting is done in the two private “singleThreaded… ” and “multiThreaded… ” methods.  
> The RMI stubs just decide which version to invoke.*

