```java
package encyclopedia;

import javax.swing.*;
import java.awt.*;
import java.rmi.Naming;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class Client extends JFrame {

    private final JTextArea output = new JTextArea(15, 50);
    private final JButton runBtn = new JButton("Run");
    private final JComboBox<String> modeBox = new JComboBox<>(new String[]{"Single‑threaded", "Multi‑threaded"});

    public Client() {
        setTitle("Encyclopedia RMI Demo");
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        JPanel top = new JPanel();
        top.add(new JLabel("Choose mode:"));
        top.add(modeBox);
        top.add(runBtn);
        add(top, BorderLayout.NORTH);

        output.setEditable(false);
        add(new JScrollPane(output), BorderLayout.CENTER);

        runBtn.addActionListener(e -> runDemo());

        pack();
        setLocationRelativeTo(null);
        setVisible(true);
    }

    private void runDemo() {
        runBtn.setEnabled(false);
        output.setText("");

        try {
            // Look up the remote object
            Encyclopedia svc = (Encyclopedia) Naming.lookup("rmi://localhost/Encyclopedia");

            // --- 1. Single‑threaded ------------------------------------
            long start = System.nanoTime();
            int letters = svc.Count();                // 1
            String[] repeated = svc.repeatedwords();  // 2
            String longest = svc.longest();           // 3
            String shortest = svc.shortest();         // 4
            Map<String,Integer> repeatMap = svc.Repeat(); // 5
            long single = System.nanoTime() - start;

            // Print single‑threaded results
            output.append("=== Single‑threaded ===\n");
            output.append("Letters (including spaces): " + letters + "\n");
            output.append("Repeated words: " + String.join(", ", repeated) + "\n");
            output.append("Longest word: " + longest + "\n");
            output.append("Shortest word: " + shortest + "\n");
            output.append("Repetition map:\n");
            repeatMap.forEach((k,v) -> output.append(String.format("  %-8s : %d%n", k, v)));

            // --- 2. Multi‑threaded ------------------------------------
            // Switch the server to MT mode for the second run
            // (In this demo we start a fresh instance; in practice you could
            //  have the server expose a “setMode” method.)
            // For simplicity we’ll just start a new service locally
            // by re‑binding on the same name.  This keeps the example short.

            // unbind & rebind
            Registry reg = LocateRegistry.getRegistry();
            reg.unbind("Encyclopedia");
            EncyclopediaImpl mtImpl = new EncyclopediaImpl(true);  // now MT
            reg.rebind("Encyclopedia", mtImpl);

            // Give the registry a tiny moment to propagate the change
            Thread.sleep(200);

            svc = (Encyclopedia) Naming.lookup("rmi://localhost/Encyclopedia");

            start = System.nanoTime();
            letters = svc.Count();
            repeated = svc.repeatedwords();
            longest = svc.longest();
            shortest = svc.shortest();
            repeatMap = svc.Repeat();
            long multi = System.nanoTime() - start;

            output.append("\n=== Multi‑threaded ===\n");
            output.append("Letters (including spaces): " + letters + "\n");
            output.append("Repeated words: " + String.join(", ", repeated) + "\n");
            output.append("Longest word: " + longest + "\n");
            output.append("Shortest word: " + shortest + "\n");
            output.append("Repetition map:\n");
            repeatMap.forEach((k,v) -> output.append(String.format("  %-8s : %d%n", k, v)));

            // --- 3. Speed‑up -----------------------------------------
            long diff = single - multi;   // single – multi (ms)
            output.append("\nSpeed‑up (ms): " + diff + "\n");

        } catch (Exception ex) {
            ex.printStackTrace();
            output.append("\nError: " + ex.getMessage());
        } finally {
            runBtn.setEnabled(true);
        }
    }

    public static void main(String[] args) throws Exception {
        // Start the server in a separate thread so the GUI can continue
        new Thread(() -> {
            try {
                Server.main(null);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }).start();

        // Give the server a moment to bind
        Thread.sleep(500);

        SwingUtilities.invokeLater(Client::new);
    }
}
