> **Tip** – Use the official Forge Gradle *v1.1.0* for 1.8.9.  
> If you prefer the *Gradle kotlin‑script* (`build.gradle.kts`) version, the config is identical; just use the `kotlin` block.

### 1.2 Folder layout

```
src/
 ├─ main/
 │   ├─ java/          # Optional: pure Java helpers
 │   ├─ kotlin/        # Your Kotlin mod code
 │   ├─ resources/
 │   │   ├─ minecraft/
 │   │   │   └─ ...    # Mod resources (textures, configs)
 │   │   └─ js/
 │   │       ├─ core.js     # The NodeJS‑like shim
 │   │       └─ mymodule.js # Sample module
 └─ test/
```

---

## 2. The Mod Core

### 2.1 Mod annotation

```kotlin
package com.example.mod

import net.minecraftforge.fml.common.Mod
import net.minecraftforge.fml.common.Mod.EventHandler
import net.minecraftforge.fml.common.event.FMLInitializationEvent

@Mod(
    modid = KotlinJsMod.MOD_ID,
    name = KotlinJsMod.NAME,
    version = KotlinJsMod.VERSION,
    acceptableRemoteVersions = "*"
)
class KotlinJsMod {

    companion object {
        const val MOD_ID = "kotlinjsmod"
        const val NAME = "Kotlin JS Mod"
        const val VERSION = "1.0.0"
    }

    @EventHandler
    fun init(event: FMLInitializationEvent) {
        ScriptManager.init()
        println("$NAME loaded!")
    }
}
```

> This is the minimal Forge entry point.  
> All heavy lifting is delegated to `ScriptManager`.

---

## 3. The Script Manager

`ScriptManager` is a **singleton** that

* holds the `ScriptEngine` (Nashorn),
* loads the *shim* (`core.js`) that gives you `require`, `console`, etc.,
* exposes a public API (`loadModule(name)`, `reloadModule(name)`) so the rest of the mod can talk to JS modules.

```kotlin
package com.example.mod

import org.mozilla.javascript.Context
import org.mozilla.javascript.ScriptableObject
import java.io.File
import java.io.InputStreamReader
import java.nio.file.*
import java.util.concurrent.ConcurrentHashMap
import javax.script.Invocable
import javax.script.ScriptEngine
import javax.script.ScriptEngineManager

object ScriptManager {
    private val engine: ScriptEngine = ScriptEngineManager().getEngineByName("nashorn")
    private val bindings: ScriptableObject = (engine as? Context)?.initializeStandardObjects()
    private val moduleCache = ConcurrentHashMap<String, Any?>()   // module.exports
    private val nodeInterface = NodeInterface()
    private val moduleDir: Path

    /**
     * Initializes everything: loads core.js, sets up the `require` function, starts folder watcher.
     */
    fun init() {
        // 1. Load the core shim
        val coreStream = KotlinJsMod::class.java.classLoader.getResourceAsStream("js/core.js")
            ?: error("core.js not found in resources")
        engine.eval(InputStreamReader(coreStream))

        // 2. Expose the Node‑like interface
        engine.put("node", nodeInterface)

        // 3. Expose a global `require` that delegates to our loader
        engine.eval(
            """
            var require = function(name) {
                return node.require(name);
            };
            """
        )

        // 4. Prepare module directory
        moduleDir = Paths.get("mods", KotlinJsMod.MOD_ID, "js")
        if (!Files.exists(moduleDir)) Files.createDirectories(moduleDir)

        // 5. Watch folder for changes (optional)
        Thread(::watchModules).start()

        // 6. (Optional) Load a bootstrap module
        loadModule("bootstrap")   // you can create bootstrap.js to wire things up
    }

    /** Loads a JS file by its module id (filename without extension). */
    fun loadModule(id: String): Any? {
        val jsFile = moduleDir.resolve("$id.js")
        if (!Files.exists(jsFile)) {
            nodeInterface.warn("Module $id not found at $jsFile")
            return null
        }

        val source = Files.readString(jsFile)
        val script = engine.eval(source)   // execute module

        // `module.exports` is set by the shim, read it
        val moduleExports = (engine as? Invocable)?.invokeFunction("getModuleExports", id)
        moduleCache[id] = moduleExports
        nodeInterface.info("Loaded module '$id'")
        return moduleExports
    }

    /** Forces re‑loading of a module (clears cache first). */
    fun reloadModule(id: String) {
        moduleCache.remove(id)
        loadModule(id)
    }

    /** Watch the JS folder for changes and reload automatically. */
    private fun watchModules() {
        val watcher = FileSystems.getDefault().newWatchService()
        moduleDir.register(
            watcher,
            StandardWatchEventKinds.ENTRY_MODIFY,
            StandardWatchEventKinds.ENTRY_CREATE,
            StandardWatchEventKinds.ENTRY_DELETE
        )
        while (true) {
            val key = watcher.take()
            for (event in key.pollEvents()) {
                val kind = event.kind()
                val fileName = event.context() as Path
                val moduleName = fileName.toString().removeSuffix(".js")
                when (kind) {
                    StandardWatchEventKinds.ENTRY_MODIFY,
                    StandardWatchEventKinds.ENTRY_CREATE -> reloadModule(moduleName)
                    StandardWatchEventKinds.ENTRY_DELETE -> moduleCache.remove(moduleName)
                }
            }
            key.reset()
        }
    }
}
```

### 3.1 The Node‑style shim (`core.js`)

Place this file in `src/main/resources/js/core.js`.

```js
// core.js – minimal CommonJS shim
var module = {
    exports: {}
};
var exports = module.exports;

// Simple in‑memory module registry
var _moduleCache = {};

function getModuleExports(id) {
    return _moduleCache[id];
}

// The `node` object will be injected by Kotlin. We wrap it so the JS API looks like Node's.
var nodeShim = {
    require: function(id) {
        if (_moduleCache[id]) return _moduleCache[id];
        // In reality the Java side will execute the module file
        var exports = node.requireModule(id);  // Java call
        _moduleCache[id] = exports;
        return exports;
    },
    console: node.console,      // forwarded to Java console
    warn: node.warn,
    error: node.error,
    info: node.info
};

exports.nodeShim = nodeShim;
```

> **Why this shim?**  
> Nashorn doesn’t provide a CommonJS loader. By providing `node.requireModule` from Java (see below), we can keep the API close to Node’s.

---

## 4. The Java‑side Node Interface

`NodeInterface` implements the Java side of the shim. It is **exposed** to Nashorn as `node`.  
It implements:

| Method | Purpose |
|--------|---------|
| `requireModule(id)` | Called from JS to load a module file. Delegates to `ScriptManager.loadModule`. |
| `console` | Simple console object that forwards `log`, `error`, etc. to the real console. |
| `warn`, `error`, `info` | Convenience wrappers for logs. |
| `spawnNodeProcess()` | (Optional) Starts a real NodeJS process and forwards console output there. |

```kotlin
package com.example.mod

import java.io.BufferedReader
import java.io.InputStreamReader

class NodeInterface {

    /** Called from JS: node.requireModule(id) */
    fun requireModule(id: String): Any? {
        return ScriptManager.loadModule(id)
    }

    /** Simple console forwarding. */
    val console = object {
        fun log(vararg args: Any?) {
            println("[JS] " + args.joinToString(" "))
        }

        fun warn(vararg args: Any?) {
            System.err.println("[JS WARNING] " + args.joinToString(" "))
        }

        fun error(vararg args: Any?) {
            System.err.println("[JS ERROR] " + args.joinToString(" "))
        }
    }

    // Convenience wrappers used by core.js
    fun warn(vararg args: Any?) = console.warn(*args)
    fun error(vararg args: Any?) = console.error(*args)
    fun info(vararg args: Any?) = console.log(*args)

    /** (Optional) Spawn a real Node.js process so you get a true Node terminal. */
    fun spawnNodeProcess() {
        val process = ProcessBuilder("node", "-e", "require('./main.js')") // path to your Node program
            .redirectErrorStream(true)
            .start()

        Thread {
            val reader = BufferedReader(InputStreamReader(process.inputStream))
            var line: String?
            while (reader.readLine().also { line = it } != null) {
                println("[Node] $line")
            }
        }.start()
    }
}
```

> If you want to pipe logs to an external terminal, just change `console.log` to write to the `process.getOutputStream()` of the Node process.

---

## 5. Sample JS Module (`mymodule.js`)

Place this in `src/main/resources/js/mymodule.js` (or in the folder on disk if you’re using the watcher).

```js
var mymodule = module.exports = {};

mymodule.greet = function(name) {
    console.log("Hello, " + name + "!");
};

mymodule.sum = function(a, b) {
    return a + b;
};
```

You can now call it from Kotlin:

```kotlin
