// HOTELIERServer.java
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.reflect.TypeToken;

import java.io.*;
import java.lang.reflect.Type;
import java.util.*;

public class HOTELIERServer {

    private List<Hotel> hotels;                 // In-memory store
    private final String jsonFilePath;          // File di persistenza

    // --------- Costruttore ---------
    public HOTELIERServer(String jsonFilePath) {
        this.jsonFilePath = jsonFilePath;
        loadHotelsFromJson();
    }

    // --------- Carica dalla persistenza ---------
    private void loadHotelsFromJson() {
        Gson gson = new Gson();
        try (Reader reader = new FileReader(jsonFilePath)) {
            Type type = new TypeToken<ArrayList<Hotel>>() {}.getType();
            hotels = gson.fromJson(reader, type);
            if (hotels == null) hotels = new ArrayList<>();
            // Assicuriamoci che tutti i punteggi siano 0 se mancanti
            for (Hotel h : hotels) {
                if (h.getRatings() == null) h.setRatings(new Hotel.Ratings());
            }
        } catch (FileNotFoundException e) {
            System.err.println("File JSON non trovato: " + jsonFilePath);
            hotels = new ArrayList<>();
        } catch (IOException e) {
            e.printStackTrace();
            hotels = new ArrayList<>();
        }
    }

    // --------- Salva su file ---------
    public void saveToJson() {
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
        try (Writer writer = new FileWriter(jsonFilePath)) {
            gson.toJson(hotels, writer);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // --------- CRUD ----------

    /** Aggiunge un nuovo hotel. Se l'id è già presente, non fa nulla. */
    public boolean addHotel(Hotel hotel) {
        if (hotel == null) return false;
        if (getHotelById(hotel.getId()) != null) {
            System.err.println("Hotel con ID " + hotel.getId() + " già esistente.");
            return false;
        }
        hotels.add(hotel);
        return true;
    }

    /** Restituisce l'hotel con l'id indicato, oppure null. */
    public Hotel getHotelById(int id) {
        for (Hotel h : hotels) {
            if (h.getId() == id) return h;
        }
        return null;
    }

    /** Aggiorna i punteggi di un hotel specificato per ID. */
    public boolean updateRatings(int hotelId, Hotel.Ratings newRatings) {
        Hotel h = getHotelById(hotelId);
        if (h == null) return false;
        h.updateRatings(newRatings);
        // Se vuoi aggiornare anche il punteggio sintetico
        int newRate = (int) Math.round(h.computeSyntheticRating());
        h.setRate(newRate);
        return true;
    }

    /** Ritorna tutti gli hotel della città indicata (case‑insensitive). */
    public List<Hotel> getHotelsInCity(String city) {
        List<Hotel> result = new ArrayList<>();
        for (Hotel h : hotels) {
            if (h.getCity() != null && h.getCity().equalsIgnoreCase(city)) {
                result.add(h);
            }
        }
        return result;
    }

    /** Ritorna l’hotel con il punteggio sintetico più alto nella città. */
    public Hotel getBestHotelInCity(String city) {
        List<Hotel> list = getHotelsInCity(city);
        return list.stream()
                .max(Comparator.comparingInt(Hotel::getRate))
                .orElse(null);
    }

    // --------- Utilità di debug ---------
    public void printAllHotels() {
        for (Hotel h : hotels) {
