## 2. Full source code

### 2.1 Block.java

```java
package blockchain;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;

/**
 * Immutable representation of a block in the chain.
 */
public final class Block {

    private final int index;
    private final long timestamp;
    private final String data;
    private final String previousHash;
    private final long nonce;
    private final String hash;

    public Block(int index, long timestamp, String data,
                 String previousHash, long nonce, String hash) {
        this.index = index;
        this.timestamp = timestamp;
        this.data = data;
        this.previousHash = previousHash;
        this.nonce = nonce;
        this.hash = hash;
    }

    /* --------------------------------------------------------------------- */
    /*  Factory & Mining helpers                                            */
    /* --------------------------------------------------------------------- */

    /**
     * Creates a *genesis* block (index 0, no previous hash, zero nonce).
     */
    public static Block genesis() {
        String genesisData = "Genesis Block";
        return mineBlock(0, 0, genesisData, "0");
    }

    /**
     * Mines a new block given the block details and the difficulty.
     *
     * @param index           position in the chain
     * @param previousHash    hash of the previous block
     * @param data            block payload
     * @param difficulty      number of leading zeros required
     * @return                 a fully mined block
     */
    public static Block mineBlock(int index, String previousHash,
                                  String data, int difficulty) {
        long timestamp = Instant.now().getEpochSecond();
        long nonce = 0;
        String hash;

        String target = "0".repeat(difficulty);

        do {
            nonce++;
            hash = calculateHash(index, timestamp, data, previousHash, nonce);
        } while (!hash.startsWith(target));

        return new Block(index, timestamp, data, previousHash, nonce, hash);
    }

    /* --------------------------------------------------------------------- */
    /*  Core hash calculation                                               */
    /* --------------------------------------------------------------------- */

    private static String calculateHash(int index, long timestamp,
                                         String data, String previousHash,
                                         long nonce) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            String input = index + Long.toString(timestamp) + data
                           + previousHash + Long.toString(nonce);
            byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 not available", e);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Getters & helpers                                                   */
    /* --------------------------------------------------------------------- */

    public int getIndex() { return index; }
    public long getTimestamp() { return timestamp; }
    public String getData() { return data; }
    public String getPreviousHash() { return previousHash; }
    public long getNonce() { return nonce; }
    public String getHash() { return hash; }

    @Override
    public String toString() {
        return String.format(
            "Block #%d\n" +
            "Timestamp   : %d\n" +
            "Previous    : %s\n" +
            "Hash        : %s\n" +
            "Nonce       : %d\n" +
            "Data        : %s\n",
            index, timestamp, previousHash, hash, nonce, data);
    }
}
```

### 2.2 Blockchain.java

```java
package blockchain;

import java.util.ArrayList;
import java.util.List;

/**
 * Very small blockchain implementation with basic PoW.
 */
public class Blockchain {

    private final List<Block> chain = new ArrayList<>();
    private final int difficulty;          // leading zeros required

    public Blockchain(int difficulty) {
        this.difficulty = difficulty;
        // add the genesis block automatically
        chain.add(Block.genesis());
    }

    public List<Block> getChain() { return chain; }

    /**
     * Appends a block after mining it with the current difficulty.
     *
     * @param data the payload for the new block
     * @return the mined block that was appended
     */
    public Block addBlock(String data) {
        Block lastBlock = chain.get(chain.size() - 1);
        int newIndex = lastBlock.getIndex() + 1;
        Block newBlock = Block.mineBlock(newIndex,
                                         lastBlock.getHash(),
                                         data, difficulty);
        chain.add(newBlock);
        return newBlock;
    }

    /**
     * Verifies the whole chain: hashes, PoW and linkage.
     */
    public boolean isChainValid() {
        String target = "0".repeat(difficulty);

        // Verify genesis block is unmodified
        Block genesis = chain.get(0);
        if (!genesis.getHash().equals(Block.calculateHash(0,
                genesis.getTimestamp(), genesis.getData(),
                genesis.getPreviousHash(), genesis.getNonce()))) {
            System.err.println("Genesis block hash invalid");
            return false;
        }

        // Validate each subsequent block
        for (int i = 1; i < chain.size(); i++) {
            Block curr = chain.get(i);
            Block prev = chain.get(i - 1);

            // Hash must match stored hash
            if (!curr.getHash().equals(
                    Block.calculateHash(curr.getIndex(),
                                        curr.getTimestamp(),
                                        curr.getData(),
                                        curr.getPreviousHash(),
                                        curr.getNonce()))) {
                System.err.printf("Block %d has invalid hash%n", curr.getIndex());
                return false;
            }

            // Must reference correct previous hash
            if (!curr.getPreviousHash().equals(prev.getHash())) {
                System.err.printf("Block %d has wrong previous hash%n", curr.getIndex());
                return false;
            }

            // Must satisfy difficulty target
            if (!curr.getHash().startsWith(target)) {
                System.err.printf("Block %d does not satisfy difficulty%n", curr.getIndex());
                return false;
            }
        }
        return true;
    }

    /**
     * Pretty prints the full chain.
     */
    public void printChain() {
        for (Block block : chain) {
            System.out.println(block);
        }
    }
}
```

