package bankaccountdemo;

import java.util.Random;

/**
 * 客户线程类
 */
public class Customer implements Runnable {

    private final BankAccount account;
    private final Random rand = new Random();
    private final boolean useSafe; // true: 使用加锁方法；false: 使用未加锁方法

    public Customer(BankAccount account, boolean useSafe) {
        this.account = account;
        this.useSafe = useSafe;
    }

    @Override
    public void run() {
        // 每个客户进行 5~10 次存款
        int operations = rand.nextInt(6) + 5;
        for (int i = 0; i < operations; i++) {
            int amount = rand.nextInt(2000) + 1;   // 随机金额 1~2000 元
            // 随机停顿（0~30 ms），模拟不同存款时间
            try { Thread.sleep(rand.nextInt(31)); } catch (InterruptedException ignored) {}

            if (useSafe) {
                account.depositSafe(amount);
            } else {
                account.depositUnSafe(amount);
            }
        }
    }
}
```

