Below is a **self‑contained** HTML/JS snippet that demonstrates the core ideas you asked for:

* a 3‑D grid that snaps to a set of “grid points”  
* a “wire‑frame” model that you can build line‑by‑line  
* the ability to rotate the entire model with the mouse  
* a tiny “VMC” context‑menu that appears when the cursor hovers over a grid point and lets you create a new line  

All of this is done **without any external libraries** and uses only the native Canvas 2‑D API.

> **NOTE** – This is intentionally written as a minimal working example.  
>  The code is commented heavily so you can expand it to a full‑featured application.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>3DM Matrix Wireframe (No lib)</title>
<style>
  body, html { margin:0; height:100%; overflow:hidden; }
  canvas { display:block; background:#111; }
  #vmcMenu {
    position:absolute;
    background:#222;
    color:white;
    padding:4px 8px;
    border-radius:3px;
    font-family:sans-serif;
    font-size:12px;
    pointer-events:none;          /* let mouse pass through */
    opacity:0;
    transition:opacity .15s;
  }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="vmcMenu">Add Line →</div>
<script>
/* --------------------------------------------------------------------- */
/* 1. Globals & Constants                                               */
/* --------------------------------------------------------------------- */
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const vmcMenu = document.getElementById('vmcMenu');

const GRID_SIZE = 10;            // 10x10x10 points
const GRID_SPACING = 30;         // pixels between points in world space
const SNAP_RADIUS = 12;          // pixels radius for snapping highlight
const ROTATE_SENS = 0.01;        // mouse drag sensitivity

let width, height;
let mouse = { x:0, y:0, down:false, dx:0, dy:0 };
let isRotating = false;

// 3 arrays as requested
let gridPoints = [];    // [{x, y, z}]  – world coordinates
let modelLines = [];    // [{p0:idx, p1:idx}] – indices into gridPoints
let drawingLines = [];  // [{x1,y1,z1, x2,y2,z2}] – temporarily drawn lines

// Model rotation (Euler angles)
let rot = { x:0, y:0, z:0 };   // rotation in radians

/* --------------------------------------------------------------------- */
/* 2. Utility Functions                                                */
/* --------------------------------------------------------------------- */
function resize() {
  width = canvas.width = window.innerWidth;
  height = canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();          // initial size

// Simple 3‑D vector operations
function vec3(x,y,z) { return {x,y,z}; }
function add(a,b){ return vec3(a.x+b.x,a.y+b.y,a.z+b.z); }
function sub(a,b){ return vec3(a.x-b.x,a.y-b.y,a.z-b.z); }
function mul(a,s){ return vec3(a.x*s,a.y*s,a.z*s); }

// Rotate a point around world origin
function rotatePoint(p) {
  // Rotation around X
  let x1 = p.x;
  let y1 = p.y * Math.cos(rot.x) - p.z * Math.sin(rot.x);
  let z1 = p.y * Math.sin(rot.x) + p.z * Math.cos(rot.x);

  // Rotation around Y
  let x2 = x1 * Math.cos(rot.y) + z1 * Math.sin(rot.y);
  let y2 = y1;
  let z2 = -x1 * Math.sin(rot.y) + z1 * Math.cos(rot.y);

  // Rotation around Z
  let x3 = x2 * Math.cos(rot.z) - y2 * Math.sin(rot.z);
  let y3 = x2 * Math.sin(rot.z) + y2 * Math.cos(rot.z);
  let z3 = z2;

  return vec3(x3, y3, z3);
}

// Simple orthographic projection to 2‑D
function project(p) {
  const scale = 1; // no perspective, just scale
  return {
    x: width/2 + p.x * scale,
    y: height/2 - p.y * scale   // y axis inverted for canvas
  };
}

// Find closest grid point to a canvas coordinate (if any)
function getSnappedPoint(mx,my) {
  let best = null, bestDist = Infinity;
  for (let i=0; i<gridPoints.length; i++) {
    const p3 = rotatePoint(gridPoints[i]);
    const p2 = project(p3);
    const dist = Math.hypot(p2.x - mx, p2.y - my);
    if (dist < bestDist && dist < SNAP_RADIUS) {
      bestDist = dist;
      best = {idx:i, dist};
    }
  }
  return best;
}

/* --------------------------------------------------------------------- */
/* 3. Grid Creation                                                    */
/* --------------------------------------------------------------------- */
function createGrid() {
  const half = GRID_SIZE/2;
  for (let x=-half; x<=half; x++) {
    for (let y=-half; y<=half; y++) {
      for (let z=-half; z<=half; z++) {
        gridPoints.push(vec3(x*GRID_SPACING, y*GRID_SPACING, z*GRID_SPACING));
      }
    }
  }
}
createGrid();

/* --------------------------------------------------------------------- */
/* 4. Input Handling                                                  */
/* --------------------------------------------------------------------- */
canvas.addEventListener('mousedown', e => {
  mouse.down = true;
  mouse.x = e.clientX;
  mouse.y = e.clientY;
  // Check if we are hovering a grid point for line‑draw
  const snap = getSnappedPoint(mouse.x, mouse.y);
  if (snap) {
    // Start a new line from this point
    drawingLines.push({p0: snap.idx});
  } else {
    // No grid point – treat as a rotation start
    isRotating = true;
  }
});
canvas.addEventListener('mousemove', e => {
  mouse.dx = e.clientX - mouse.x;
  mouse.dy = e.clientY - mouse.y;
  mouse.x = e.clientX;
  mouse.y = e.clientY;

  // Rotation
  if (isRotating) {
    rot.y += mouse.dx * ROTATE_SENS;
    rot.x += mouse.dy * ROTATE_SENS;
  }

  // Update VMC menu position / visibility
  const snap = getSnappedPoint(mouse.x, mouse.y);
  if (snap) {
    vmcMenu.style.left = (mouse.x + 10) + 'px';
    vmcMenu.style.top = (mouse.y + 10) + 'px';
    vmcMenu.style.opacity = 1;
  } else {
    vmcMenu.style.opacity = 0;
  }

  // If we are in the middle of a drawing line, update its end
  if (drawingLines.length && drawingLines[drawingLines.length-1].p1 === undefined) {
    const snap2 = getSnappedPoint(mouse.x, mouse.y);
    if (snap2) {
      drawingLines[drawingLines.length-1].p1 = snap2.idx;
    } else {
      drawingLines[drawingLines.length-1].p1 = null;  // free end
    }
  }
});
canvas.addEventListener('mouseup', e => {
  mouse.down = false;
  if (isRotating) isRotating = false;
  // Finalise drawing
  if (drawingLines.length) {
    const line = drawingLines.pop();
    if (line.p1 !== undefined && line.p1 !== null) {
      // Snap both ends (first end is already snapped)
      modelLines.push({p0: line.p0, p1: line.p1});
    }
  }
});

// Simple key to clear all lines
window.addEventListener('keydown', e => {
  if (e.key === 'c') {
    modelLines = [];
    drawingLines = [];
  }
});

/* --------------------------------------------------------------------- */
/* 5. Rendering Loop                                                 */
/* --------------------------------------------------------------------- */
function render() {
  ctx.clearRect(0,0,width,height);

  // 5.1 Draw grid points
  for (let i=0; i<gridPoints.length; i++) {
    const p = rotatePoint(gridPoints[i]);
    const proj = project(p);
    // Highlight if snapped
    const snap = getSnappedPoint(proj.x, proj.y);
    const isSnap = snap && snap.idx === i;
    ctx.fillStyle = isSnap ? '#0f0' : '#555';
    ctx.beginPath();
    ctx.arc(proj.x, proj.y, 3, 0, Math.PI*2);
    ctx.fill();
  }

  // 5.2 Draw existing model lines
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let line of modelLines) {
    const p0 = rotatePoint(gridPoints[line.p0]);
    const p1 = rotatePoint(gridPoints[line.p1]);
    const q0 = project(p0);
    const q1 = project(p1);
    ctx.moveTo(q0.x, q0.y);
    ctx.lineTo(q1.x, q1.y);
  }
  ctx.stroke();

  // 5.3 Draw drawing lines (in progress)
  if (drawingLines.length) {
    const line = drawingLines[drawingLines.length-1];
    const p0 = rotatePoint(gridPoints[line.p0]);
    const q0 = project(p0);
    const p1 = line.p1 !== undefined && line.p1 !== null
              ? rotatePoint(gridPoints[line.p1])
              : null;
    const q1 = p1 ? project(p1) : null;

    ctx.strokeStyle = '#f00';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(q0.x, q0.y);
    if (q1) {
      ctx.lineTo(q1.x, q1.y);
    } else {
      // free line following mouse
      ctx.lineTo(mouse.x, mouse.y);
    }
    ctx.stroke();
  }

  requestAnimationFrame(render);
}
render();

/* --------------------------------------------------------------------- */
/* 6. VMC Menu Action                                                */
/* --------------------------------------------------------------------- */
/* Simple click on the menu adds a line from the hovered point to a new
   point that you can place by clicking elsewhere on the grid. */
vmcMenu.addEventListener('click', e => {
  // Find hovered point again
  const snap = getSnappedPoint(mouse.x, mouse.y);
  if (!snap) return;
  // Wait for next click to finalize the other end
  canvas.addEventListener('click', secondClickHandler, {once:true});
  vmcMenu.style.opacity = 0; // hide during placement
});

function secondClickHandler(e) {
  const secondSnap = getSnappedPoint(e.clientX, e.clientY);
  if (!secondSnap) return;
  modelLines.push({p0: getSnappedPoint(mouse.x, mouse.y).idx, p1: secondSnap.idx});
}

/* --------------------------------------------------------------------- */
/* 7. Cleanup / Additional UX (optional)                           */
/* --------------------------------------------------------------------- */
// Disable context‑menu on canvas so right‑click is free for rotation
canvas.addEventListener('contextmenu', e => e.preventDefault());

</script>
</body>
</html>
```

---

### How it works

| Feature | Implementation |
|---------|----------------|
| **3‑D Grid** | `gridPoints` stores every point of a `GRID_SIZE × GRID_SIZE × GRID_SIZE` lattice in world coordinates. |
| **Projection** | `rotatePoint()` applies the current Euler angles. `project()` maps a 3‑D point to 2‑D canvas coordinates (orthographic). |
| **Drawing / Snap** | On `mousedown` over a grid point a temporary line is started. While moving the mouse the line follows the nearest grid point (or the cursor if none). On `mouseup` the line is added to `modelLines`. |
| **Rotation** | When the mouse is dragged *without* starting a line, the entire model rotates. |
| **VMC Menu** | A tiny `div` is positioned next to the mouse when it hovers a snap point. Clicking the menu starts a “second‑click” mode that lets you pick a second point to finish the line. |
| **Arrays** |  
  * `gridPoints` – world coordinates of the lattice.  
  * `modelLines` – references to two indices in `gridPoints`.  
  * `drawingLines` – a buffer for lines being drawn interactively. |

---

### Extending the demo

* **Perspective Projection** – Replace `project()` with a perspective formula if you want depth cues.  
* **Free‑hand Lines** – Add a flag that skips snapping and records raw mouse coordinates instead of grid indices.  
* **Undo / Redo** – Keep a history stack of `modelLines`.  
* **Export / Import** – Serialize `gridPoints`/`modelLines` to JSON and load them back.  
* **UI Enhancements** – Add buttons for resetting view, changing snap size, toggling grid visibility, etc.  

Feel free to copy the code into a file, open it in a browser, and play around. Happy 3‑D modeling!

