const router = express.Router();

router.post('/register', async (req, res) => {
  try {
    const { email, password } = req.body;
    if (!email || !password) return res.status(400).json({msg:'Missing fields'});

    // 1) Czy użytkownik już istnieje?
    const existing = await User.findOne({ email });
    if (existing) return res.status(409).json({msg:'Email already in use'});

    // 2) Hash hasła
    const salt  = await bcrypt.genSalt(12);
    const hash  = await bcrypt.hash(password, salt);

    // 3) Token potwierdzenia
    const token = crypto.randomBytes(32).toString('hex');
    const expires = new Date(Date.now() + 24*60*60*1000); // 24h

    // 4) Zapisanie użytkownika
    const user = await new User({
      email,
      passwordHash: hash,
      confirmToken: token,
      tokenExpires: expires
    }).save();

    // 5) Wysłanie maila
    const confirmLink = `${process.env.FRONTEND_URL}/confirm?token=${token}`;
    await mailer.sendMail({
      to: email,
      subject: 'Potwierdź rejestrację',
      html: `<p>Witaj, <a href="${confirmLink}">kliknij tutaj</a>, aby potwierdzić e‑mail.</p>`
    });

    res.json({msg: 'Check your inbox to verify your account.'});
  } catch (err) {
    console.error(err);
    res.status(500).json({msg: 'Server error'});
  }
});
```

### 3.2  Weryfikacja linku

```js
router.get('/confirm', async (req, res) => {
  try {
    const { token } = req.query;
    if (!token) return res.status(400).send('Missing token');

    const user = await User.findOne({
      confirmToken: token,
      tokenExpires: { $gt: Date.now() }
    });

    if (!user) return res.status(400).send('Invalid or expired token');

    // 1) Ustaw verified na true, usuń token
    user.verified = true;
    user.confirmToken = undefined;
    user.tokenExpires = undefined;
    await user.save();

    // 2) Redirect do logowania lub strona powitalna
    res.redirect(`${process.env.FRONTEND_URL}/login?msg=verified`);
  } catch (err) {
    console.error(err);
    res.status(500).send('Server error');
  }
});
```

### 3.3  Logowanie

