### 4.2  Logowanie

```js
// login.js
async function login() {
  const email = document.getElementById('email').value;
  const pwd   = document.getElementById('password').value;

  const res = await fetch('/api/auth/login', {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify({email, password: pwd})
  });

  if (!res.ok) {
    const err = await res.json();
    alert(err.msg);
    return;
  }

  const data = await res.json();
  localStorage.setItem('jwt', data.token);  // lub sessionStorage
  location.reload(); // opcjonalnie: przeładowanie aby zaktualizować UI
}
document.getElementById('loginBtn').addEventListener('click', login);
```

### 4.3  Deklaracja zarejestrowanego użytkownika

```js
// util.js
export async function fetchUser() {
  const token = localStorage.getItem('jwt');
  if (!token) return null;
  try {
    const res = await fetch('/api/auth/me', {
      headers: {Authorization: `Bearer ${token}`}
    });
    if (!res.ok) return null;
    return await res.json();
  } catch (e) { return null; }
}
```

> **Uwaga:** `/api/auth/me` to endpoint, który zwraca aktualnego użytkownika (zabezpieczony przez `auth` middleware).

### 4.4  Blokowanie/odblokowywanie elementów

```js
async function updateUI() {
  const user = await fetchUser();
  const registerEl = document.getElementById('register');
  const loginEl    = document.getElementById('login');
  const dashboardEl = document.getElementById('dashboard');

  if (user) { // zalogowany
    registerEl.style.display = 'none';
    loginEl.style.display    = 'none';
    dashboardEl.style.display= 'block';
  } else { // niezalogowany
    registerEl.style.display = 'block';
    loginEl.style.display    = 'block';
    dashboardEl.style.display= 'none';
  }
}

document.addEventListener('DOMContentLoaded', updateUI);
```

---

## 5.  Szczegóły bezpieczeństwa

| Kwestia | Co zrobić | Dlaczego |
|---------|-----------|----------|
| **Hashowanie hasła** | bcrypt (12‑12 rounds) | Zapobiega odczytowi haseł w postaci czystego tekstu. |
| **Token weryfikacyjny** | Losowe 32‑bajtowe tokeny (hex) lub JWT | Unika manipulacji. |
| **Wygasanie tokenu** | `tokenExpires = now + 24h` | Token nie może być używany później. |
| **HTTPS** | Wymuszaj HTTPS | Chroni przed MITM i kradzieżą tokenów. |
| **CSRF** | Tokeny CSRF przy zapytaniach POST | Chroni przed atakami cross‑site. |
| **CORS** | Ogranicz do własnego domeny | Nie pozwala innym domenom na wysyłanie zapytań. |
| **Rate‑limit** | Limit 5 rejestracji / 30 logowań / min | Ogranicza brute‑force. |
| **Cookie flags** | HttpOnly, SameSite=Lax | Ogranicza dostęp JS i CSRF. |
| **JWT** | Zapisz `sub` i `role` | Ułatwia sprawdzanie uprawnień na backendzie. |
| **Weryfikacja email** | Nie pozwól na logowanie, dopóki `verified = true` | Zapobiega nieautoryzowanym kontom. |

---

## 6.  Szybki „mini‑demo” (Node + Express + MongoDB)

```bash
# 1. Zainicjuj projekt
npm init -y
npm i express mongoose bcrypt jsonwebtoken nodemailer dotenv cors helmet

# 2. Stwórz foldery: models, routes, utils, public
# 3. Skopiuj powyższy kod (User.js, auth.js, mailer.js)
# 4. Utwórz .env
#    MONGO_URI=mongodb://localhost:27017/registration_demo
#    FRONTEND_URL=http://localhost:3000
#    JWT_SECRET=superSecretKey
#    SMTP_HOST=smtp.gmail.com
#    SMTP_PORT=587
#    SMTP_USER=you@gmail.com
#    SMTP_PASS=yourPassword

# 5. Uruchom serwer
node server.js
```

```js
// server.js
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const mongoose = require('mongoose');

const authRoutes = require('./routes/auth');

mongoose.connect(process.env.MONGO_URI, { useNewUrlParser:true });

const app = express();
app.use(helmet());
app.use(cors({ origin: process.env.FRONTEND_URL, credentials: true }));
app.use(express.json());

app.use('/api/auth', authRoutes);

app.get('/', (req, res) => res.send('Hello world!'));

app.listen(5000, () => console.log('API running on http://localhost:5000'));
```

---

## 7.  Jak „zapisujemy” że użytkownik kliknął link?

**Gdy użytkownik klika link,** serwer otrzymuje zapytanie GET na `/api/auth/confirm?token=xxxx`. W tym momencie:

1. **Serwer sprawdza token** (`confirmToken`) oraz datę wygaśnięcia (`tokenExpires`).
2. **Jeśli token jest prawidłowy,** aktualizuje rekord użytkownika:
   ```js
   user.verified = true;
   user.confirmToken = undefined;
   user.tokenExpires = undefined;
   await user.save();
   ```
3. **To jest moment, w którym status zmienia się** z *unverified* → *verified*.  
4. Po tej zmianie użytkownik jest już „zarejestrowany” i może się logować.

---

## 8.  Blokowanie / odblokowywanie elementów na stronie

- **Backend**: `auth` middleware sprawdza, czy użytkownik ma `verified: true`. Jeśli nie – zwraca `403`.
- **Frontend**: po zalogowaniu (po odebraniu tokena JWT) zapisujemy go w `localStorage` i wywołujemy funkcję, która aktualizuje widoczność elementów.  
  *Przykład*:

```js
function showDashboard() {
  // pokaż elementy tylko dla zalogowanych
  document.querySelectorAll('.only-logged').forEach(el => el.style.display = 'block');
}
```

> **Kiedy**? Po **odczytaniu** tokena (np. po `location.reload()` lub przy `DOMContentLoaded`).  
> **Gdzie**? W pliku JavaScript, który jest podłączany do wszystkich stron (np. `app.js`).

---

## 9.  Dodatkowe sugestie

| Problem | Rozwiązanie |
|---------|-------------|
| **Re‑wysłanie linku potwierdzenia** | Endpoint `/api/auth/resend-confirmation`. Sprawdź, czy `verified=false`, wygeneruj nowy token i wyślij maila. |
| **Token jest już użyty** | Po potwierdzeniu ustaw `confirmToken=undefined`. |
| **Logowanie bez potwierdzenia** | `if (!user.verified) return res.status(403).json({msg:'Email not verified'});` |
| **Sesja po odświeżeniu** | Token JWT może być zapisany w cookie `HttpOnly`. |
| **Responsywność** | Użyj `async/await` i `try/catch` w fetchach, aby wyświetlić komunikaty o błędach. |

---

## 10.  Podsumowanie

| Co robimy | Dlaczego to ważne |
|-----------|-------------------|
| Rejestracja → `verified:false` | Zapobiega używaniu kont bez potwierdzenia |
| Token weryfikacji → 24h | Ogranicza ryzyko nadużyć |
| Po kliknięciu → `verified:true` | Umożliwia logowanie i dostęp do funkcji |
| Middleware `auth` | Chroni route’y backendowe |
| Frontend → ukrycie/wyświetlenie elementów | UX dla użytkowników |
| Bezpieczeństwo (bcrypt, HTTPS, CORS, CSRF, etc.) | Ochrona danych i integralności aplikacji |

Teraz masz kompletny opis procedury oraz gotowe fragmenty kodu – zarówno backend (Node/Express), jak i frontend (czysty JS) – które możesz w łatwy sposób włączyć do własnego projektu. Powodzenia!

