        NewsPopup.show(items);
   }
   ```

---

## 3. Минимальная UI‑компонента

```actionscript
// NewsPopup.as
package ui {
    import flash.display.Sprite;
    import flash.text.TextField;
    import flash.text.TextFormat;
    import flash.display.BitmapData;
    import flash.display.Bitmap;

    public class NewsPopup extends Sprite {
        private var bg:Sprite;
        private var tf:TextField;

        public function NewsPopup() {
            bg = new Sprite();
            bg.graphics.beginFill(0x000000, 0.8);
            bg.graphics.drawRect(0,0,400,300);
            bg.graphics.endFill();
            addChild(bg);

            tf = new TextField();
            tf.multiline = true;
            tf.wordWrap = true;
            tf.width = 380;
            tf.y = 10;
            addChild(tf);

            // Позиционируем окно в центре экрана
            this.x = (Main.stage.stageWidth - 400) / 2;
            this.y = (Main.stage.stageHeight - 300) / 2;
        }

        public static function show(items:Vector.<NewsItemServer>):void {
            var popup:NewsPopup = new NewsPopup();
            var text:String = "";
            for each (var itm:NewsItemServer in items) {
                text += itm.date + "\n" + itm.text + "\n\n";
            }
            popup.tf.text = text;
            Main.stage.addChild(popup);
        }
    }
}
```

> **Примечание**: `Main.stage` – ссылка на Stage вашего приложения. В реальном проекте можно использовать контейнер, управляющий окнами (PopupManager).

---

## 4. Как всё соединить

1. **Сервер** – добавляем массив новостей, метод `broadcastNews()` и вызывать его по необходимости.  
2. **Клиент** – оставляем существующий обработчик `show_news`.  
3. **UI** – создаём `NewsPopup` и вызываем `NewsPopup.show(news)` из `NewsModel.showNews`.

### Итоговый поток

| Шаг | Что происходит |
|-----|-----------------|
| 1 | Клиент подключается → сервер отправляет `show_news` (через `user_inited` или `broadcastNews`) |
| 2 | Клиент получает сообщение → ActionScript разбирает JSON → создаёт `NewsItemServer` |
| 3 | `NewsModel.showNews()` вызывает `NewsPopup.show()` → появляется всплывающее окно с новостями |

---

## 5. Тестовый пример

```js
// После запуска сервера (Lobby.js)
