    startBtn.textContent = 'Listening…';
    processAudio();
  } catch (e) {
    console.error(e);
    alert('Microphone access denied or unsupported browser.');
    startBtn.disabled = false;
    startBtn.textContent = 'Start Listening';
  }
};

/* ----------------------------------------------------------- */
async function initAudio() {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  micSource = audioCtx.createMediaStreamSource(stream);

  analyser = audioCtx.createAnalyser();
  analyser.fftSize = 2048;          // Higher fftSize → better time resolution
  micSource.connect(analyser);
  dataArray = new Uint8Array(analyser.frequencyBinCount);
}

/* ----------------------------------------------------------- */
function processAudio() {
  analyser.getByteTimeDomainData(dataArray);
  const rms = calcRMS(dataArray) / 128;   // Normalize RMS to 0‑1

  if (rms > THRESHOLD) {
    const now = Date.now();
    if (!lastPeakTime || now - lastPeakTime > MIN_GAP_MS) {
      lastPeakTime = now;
      peakTimes.push(now);

      if (peakTimes.length > 1) {
        const interval = peakTimes[peakTimes.length - 1] - peakTimes[peakTimes.length - 2];
        const bpm = Math.round(60000 / interval);
        bpmDisplay.textContent = `${bpm} BPM`;
      }
    }
  }

  requestAnimationFrame(processAudio);
}

/* ----------------------------------------------------------- */
function calcRMS(buffer) {
  let sum = 0;
  for (let i = 0; i < buffer.length; i++) {
    const val = (buffer[i] - 128) / 128;   // Center at 0, range [-1, 1]
    sum += val * val;
  }
  return Math.sqrt(sum / buffer.length);
}
</script>
</body>
</html>
```

---

### How it works

1. **Microphone access** – `navigator.mediaDevices.getUserMedia({ audio: true })` asks the user for permission and streams the mic input to the browser.
2. **Audio context** – `AudioContext` creates a processing graph; we connect the mic source to an `AnalyserNode`.
3. **Envelope calculation** – We read the time‑domain data, calculate the RMS (root‑mean‑square) amplitude, and use it as a simple envelope.
4. **Peak detection** – When the envelope rises above a threshold and is spaced by at least `MIN_GAP_MS` (to avoid double‑counting the same beat), we register a peak.
5. **BPM calculation** – The time difference between the last two peaks gives the beat period; BPM = 60 000 ms / period.  
   The value is updated in real‑time as the audio plays.

Feel free to tweak `THRESHOLD`, `MIN_GAP_MS`, or `fftSize` for better performance on different devices. The algorithm is intentionally simple and works well for steady rhythmic sources (clap, drum, metronome, etc.).

