const { Server } = require('socket.io');

const app = express();
app.use(cors({ origin: '*', credentials: true }));   // 开放所有跨域

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: '*',            // 也可以改成 ['http://localhost:3000', 'http://192.168.0.30:3000']
    methods: ['GET', 'POST'],
    credentials: true
  }
});

io.on('connection', (socket) => {
