```tsx
// PersonalForm.tsx
import React, { useState, ChangeEvent, FormEvent } from 'react';

/** 1️⃣ Тип, описывающий все поля формы */
interface FormValues {
  surname: string;     // Фамилия
  name: string;        // Имя
  patronymic: string;  // Отчество
}

/** 2️⃣ Тип ошибок валидации */
interface FormErrors {
  surname?: string;
  name?: string;
  patronymic?: string;
}

/** 3️⃣ Компонент */
const PersonalForm: React.FC = () => {
  // Состояние значений
  const [values, setValues] = useState<FormValues>({
    surname: '',
    name: '',
    patronymic: '',
  });

  // Состояние ошибок
  const [errors, setErrors] = useState<FormErrors>({});

  /** 4️⃣ Обработчик изменения любого поля */
  const handleChange = (
    e: ChangeEvent<HTMLInputElement>
  ): void => {
    const { name, value } = e.target;
    setValues(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  /** 5️⃣ Валидация: возвращает объект ошибок */
  const validate = (): FormErrors => {
    const newErrors: FormErrors = {};
    if (!values.surname.trim()) newErrors.surname = 'Фамилия обязательна';
    if (!values.name.trim()) newErrors.name = 'Имя обязательное';
    if (!values.patronymic.trim())
      newErrors.patronymic = 'Отчество обязательно';
    return newErrors;
  };

  /** 6️⃣ Обработчик сабмита */
  const handleSubmit = (e: FormEvent): void => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length === 0) {
      // Всё в порядке – отправляем данные
      console.log('Отправленные данные:', values);
      // Можно сбросить форму:
      // setValues({ surname: '', name: '', patronymic: '' });
      setErrors({});
    } else {
      // Показываем ошибки
      setErrors(validationErrors);
    }
  };

  /** 7️⃣ JSX‑рендер */
  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="surname">Фамилия:</label>
        <input
          id="surname"
          name="surname"
          type="text"
          value={values.surname}
          onChange={handleChange}
        />
        {errors.surname && (
          <span className="error">{errors.surname}</span>
        )}
      </div>

      <div>
        <label htmlFor="name">Имя:</label>
        <input
          id="name"
          name="name"
          type="text"
          value={values.name}
          onChange={handleChange}
        />
        {errors.name && (
          <span className="error">{errors.name}</span>
        )}
      </div>

      <div>
        <label htmlFor="patronymic">Отчество:</label>
        <input
          id="patronymic"
          name="patronymic"
          type="text"
          value={values.patronymic}
          onChange={handleChange}
        />
        {errors.patronymic && (
          <span className="error">{errors.patronymic}</span>
        )}
      </div>

      <button type="submit">Отправить</button>
    </form>
  );
};

export default PersonalForm;
```

