### 2.5 Сокеты – логика игрока

#### `server/sockets/player.js`

```js
const Player = require('../models/Player');
const jwt    = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'supersecret';

module.exports = (io) => {
  const connectedPlayers = new Map(); // userId => socket

  io.on('connection', socket => {
    console.log('Client connected', socket.id);

    /* Авторизация через токен */
    socket.on('authenticate', async (token, callback) => {
      try {
        const payload = jwt.verify(token, JWT_SECRET);
        const userId  = payload.id;

        /* Загружаем персонажа (или создаём новый) */
        let player = await Player.findOne({ user: userId }).populate('inventory');
        if (!player) {
          player = new Player({
            user: userId,
            nickname: payload.username,
            position: { x: 0, y: 0 },
            inventory: [],
            skills: ['fireball', 'heal']
          });
          await player.save();
        }

        connectedPlayers.set(userId, socket);
        socket.userId = userId;
        callback({ status: 'ok', player });

      } catch (err) {
        console.error('Auth error:', err);
        callback({ status: 'error', message: 'Invalid token' });
      }
    });

    /* Перемещение игрока */
    socket.on('move', async (dir, callback) => {
      if (!socket.userId) return callback({ status: 'error', message: 'Unauth' });

      const player = await Player.findOne({ user: socket.userId });
      if (!player) return callback({ status: 'error', message: 'Player not found' });

      const step = 10; // px per move
      switch (dir) {
        case 'up':    player.position.y -= step; break;
        case 'down':  player.position.y += step; break;
        case 'left':  player.position.x -= step; break;
        case 'right': player.position.x += step; break;
      }
      await player.save();
      io.emit('playerMoved', { userId: player.user, position: player.position });
      callback({ status: 'ok', position: player.position });
    });

    /* Применение навыка */
    const skillCooldown = new Map(); // userId_skill -> Date

    socket.on('useSkill', async (skillName, callback) => {
      if (!socket.userId) return callback({ status: 'error', message: 'Unauth' });

      const now = Date.now();
      const key = `${socket.userId}_${skillName}`;
      const lastUsed = skillCooldown.get(key) || 0;
      const cooldown = 5000; // 5 sec

      if (now - lastUsed < cooldown) {
        return callback({ status: 'error', message: 'Skill on cooldown' });
      }

      skillCooldown.set(key, now);

      // Простая логика навыка: разлетается в окружение (пример)
      console.log(`Player ${socket.userId} used ${skillName}`);
      io.emit('skillUsed', { userId: socket.userId, skill: skillName, position: (await Player.findOne({ user: socket.userId })).position });

      callback({ status: 'ok' });
    });

    socket.on('disconnect', () => {
      console.log('Client disconnected', socket.id);
      if (socket.userId) connectedPlayers.delete(socket.userId);
    });
  });
};
```

