```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Mini Tank Battle</title>
<style>
  body{margin:0; overflow:hidden; background:#222; color:#fff; font-family:Arial, sans-serif;}
  canvas{display:block; background:#444;}
  #info{position:absolute; top:10px; left:10px; color:#fff;}
</style>
</head>
<body>
<div id="info">
  <p><strong>Controls:</strong> Arrow keys to move, Space to shoot.</p>
</div>
<canvas id="gameCanvas"></canvas>

<script>
(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = window.innerWidth;
  const H = canvas.height = window.innerHeight;

  // ==============================
  // Helper functions
  // ==============================
  function clamp(val, min, max) { return Math.min(Math.max(val, min), max); }

  // ==============================
  // Game Entities
  // ==============================
  class Tank {
    constructor(x, y, color, isPlayer = false) {
      this.x = x; this.y = y;
      this.size = 30;
      this.color = color;
      this.speed = 2.5;
      this.rotation = 0; // rad
      this.isPlayer = isPlayer;
      this.shootCooldown = 0;
    }

    move(dx, dy) {
      this.x += dx * this.speed;
      this.y += dy * this.speed;
      this.x = clamp(this.x, this.size, W - this.size);
      this.y = clamp(this.y, this.size, H - this.size);
    }

    update() {
      if (this.shootCooldown > 0) this.shootCooldown--;
    }

    draw() {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.rotation);
      ctx.fillStyle = this.color;
      ctx.fillRect(-this.size/2, -this.size/2, this.size, this.size);
      // Cannon
      ctx.fillStyle = '#111';
      ctx.fillRect(0, -5, this.size/2, 10);
      ctx.restore();
    }

    fire() {
      if (this.shootCooldown > 0) return null;
      const rad = this.rotation;
      const bullet = new Bullet(
        this.x + Math.cos(rad) * this.size,
        this.y + Math.sin(rad) * this.size,
        rad,
        this.isPlayer ? '#0f0' : '#f00'
      );
      this.shootCooldown = 20; // frames
      return bullet;
    }
  }

  class Bullet {
    constructor(x, y, dir, color) {
      this.x = x; this.y = y;
      this.dir = dir; // rad
      this.speed = 6;
      this.r = 4;
      this.color = color;
      this.dead = false;
    }

    update() {
      this.x += Math.cos(this.dir) * this.speed;
      this.y += Math.sin(this.dir) * this.speed;
      if (this.x < 0 || this.x > W || this.y < 0 || this.y > H) this.dead = true;
    }

    draw() {
      ctx.fillStyle = this.color;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r, 0, Math.PI*2);
      ctx.fill();
    }
  }

  // ==============================
  // Game State
  // ==============================
  const player = new Tank(W*0.2, H/2, '#0af', true);
  const enemy  = new Tank(W*0.8, H/2, '#a00');
  let bullets = [];

  const keys = {};
  window.addEventListener('keydown', e => keys[e.key] = true);
  window.addEventListener('keyup',   e => keys[e.key] = false);

  // Enemy AI state
  let enemyDir = 1; // 1 = right, -1 = left

  // ==============================
  // Main Loop
  // ==============================
  function loop() {
    // Update
    update();
    // Draw
    draw();
    // Next frame
    requestAnimationFrame(loop);
  }

  function update() {
    // Player movement
    let moveX = 0, moveY = 0;
    if (keys['ArrowLeft'])  { moveX--; }
    if (keys['ArrowRight']) { moveX++; }
    if (keys['ArrowUp'])    { moveY--; }
    if (keys['ArrowDown'])  { moveY++; }

    // Normalize diagonal speed
    if (moveX !== 0 && moveY !== 0) {
      moveX *= Math.SQRT1_2; moveY *= Math.SQRT1_2;
    }

    // Rotate player tank to face movement direction
    if (moveX !== 0 || moveY !== 0) {
      player.rotation = Math.atan2(moveY, moveX);
    }

    player.move(moveX, moveY);
    player.update();

    // Player shooting
    if (keys[' ']) {
      const b = player.fire();
      if (b) bullets.push(b);
    }

    // Enemy AI: simple back‑and‑forth and shooting
    enemy.move(enemyDir * 0.5, 0);
    if (enemy.x <= W*0.7) enemyDir = 1;
    if (enemy.x >= W*0.9) enemyDir = -1;

    // Rotate enemy to face player
    const dx = player.x - enemy.x;
    const dy = player.y - enemy.y;
    enemy.rotation = Math.atan2(dy, dx);

    // Enemy shooting
    if (Math.random() < 0.015) {
      const b = enemy.fire();
      if (b) bullets.push(b);
    }
    enemy.update();

    // Update bullets
    bullets.forEach(b => b.update());
    bullets = bullets.filter(b => !b.dead);

    // Collision detection
    bullets.forEach(b => {
      if (!b.dead && Math.hypot(b.x - enemy.x, b.y - enemy.y) < (enemy.size/2 + b.r)) {
        b.dead = true;
        // You could add explosion, score, etc.
      }
      if (!b.dead && Math.hypot(b.x - player.x, b.y - player.y) < (player.size/2 + b.r)) {
        b.dead = true;
        // Player hit!
      }
    });
  }

  function draw() {
    ctx.clearRect(0,0,W,H);
    // Draw tanks
    player.draw();
    enemy.draw();
    // Draw bullets
    bullets.forEach(b => b.draw());
  }

  // Start game
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```

