## 🚀 Upload a “Big” File from Express → AWS S3 (Multipart + Progress)

Below is a **complete, production‑ready** recipe that

1. Accepts an upload through an `POST /upload` endpoint.  
2. Streams the file **directly** from the client to S3 – no temp file on disk.  
3. Uses **AWS SDK v3** (`@aws-sdk/client-s3` + `@aws-sdk/lib-storage`) to perform a multipart upload.  
4. Emits a per‑part progress event that you can pipe to the client (SSE, WebSocket, HTTP chunked body, etc.).

> **Why multipart?**  
> * 5 MiB minimum part size, up to 10 000 parts → ~5 TiB max.  
> * Uploads resume automatically if a part fails.  
> * You can see progress in real‑time.

---

## 1.  Install the deps

```bash
npm i express busboy @aws-sdk/client-s3 @aws-sdk/lib-storage dotenv
```

> `busboy` → raw streaming parser for multipart/form‑data.  
> `dotenv` → handy for dev config.

---

## 2.  Configure AWS SDK

Create a `.env` file:

```dotenv
AWS_ACCESS_KEY_ID=YOUR_KEY
AWS_SECRET_ACCESS_KEY=YOUR_SECRET
AWS_REGION=us-east-1
S3_BUCKET=your-bucket-name
```

```js
// aws.js
import { S3Client } from "@aws-sdk/client-s3";
import dotenv from "dotenv";

dotenv.config();

export const s3Client = new S3Client({
  region: process.env.AWS_REGION,
  credentials: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },
});
```

---

## 3.  Express + Busboy – streaming the incoming file

```js
// server.js
import express from "express";
import { s3Client } from "./aws.js";
import { Upload } from "@aws-sdk/lib-storage";
import Busboy from "busboy";
import { v4 as uuidv4 } from "uuid";

const app = express();
const PORT = process.env.PORT ?? 3000;

// ------------------------------------------------------------
//  Helper: create an upload stream that reports progress
// ------------------------------------------------------------
function createS3UploadStream(fileInfo) {
  const upload = new Upload({
    client: s3Client,
    params: {
      Bucket: process.env.S3_BUCKET,
      Key: fileInfo.key,           // e.g. "uploads/2026-01-31/file-12345.mp4"
      Body: fileInfo.stream,       // the readable stream from Busboy
      ContentType: fileInfo.mime,
      // you can add metadata, tags, ACL etc. here
    },
    partSize: 5 * 1024 * 1024, // 5 MiB – minimal part size
    queueSize: 4,              // parallel uploads
  });

  // Hook into the SDK progress events
  upload.on("httpUploadProgress", (progress) => {
    // progress.loaded / progress.total gives you the percent
    const pct = ((progress.loaded / progress.total) * 100).toFixed(2);
    fileInfo.onProgress?.({
      loaded: progress.loaded,
      total: progress.total,
      percent: pct,
    });
  });

  // Return the promise so we can await it
  return upload.done();
}

// ------------------------------------------------------------
//  Route: POST /upload
// ------------------------------------------------------------
app.post("/upload", (req, res) => {
  const busboy = new Busboy({ headers: req.headers });

  // We’ll hold a map of file names → upload promises
  const uploads = [];

  // Optional: emit progress via Server‑Sent Events
  const sendProgress = (fileName, data) => {
    // Example: simple SSE
    res.write(`data: ${JSON.stringify({ fileName, ...data })}\n\n`);
  };

  busboy.on("file", (fieldname, fileStream, filename, encoding, mimetype) => {
    // Build the S3 key – keep it unique
    const key = `uploads/${Date.now()}-${uuidv4()}${filename}`;

    // Capture the file size if the client sent it
    const contentLength = parseInt(req.headers["content-length"], 10) || undefined;

    const fileInfo = {
      stream: fileStream,
      key,
      mime: mimetype,
      onProgress: ({ loaded, total, percent }) => {
        // Here you can push the progress to the client
        sendProgress(filename, { loaded, total, percent });
      },
    };

    // Kick off the multipart upload
    const uploadPromise = createS3UploadStream(fileInfo)
      .then((data) => {
        // When finished, inform the client
        sendProgress(filename, { status: "finished", location: data.Location });
      })
      .catch((err) => {
        console.error("Upload error", err);
        sendProgress(filename, { status: "error", error: err.message });
      });

    uploads.push(uploadPromise);
  });

  busboy.on("finish", async () => {
    // All files were sent; await all uploads
    try {
      await Promise.all(uploads);
      // End SSE
      res.write(`event: done\ndata: {"status":"allDone"}\n\n`);
      res.end(); // Close connection
    } catch (err) {
      // If any upload failed
      res.status(500).send({ error: err.message });
    }
  });

  busboy.on("error", (err) => {
    console.error("Busboy error", err);
    res.status(400).send({ error: "Bad upload" });
  });

  req.pipe(busboy);
});

app.listen(PORT, () => {
  console.log(`Server listening on ${PORT}`);
});
```

### How the code works

| Step | What happens | Why it matters |
|------|--------------|----------------|
| `Busboy` parses the multipart request | We never read the whole file into memory | Keeps RAM usage low |
| `fileStream` is passed straight to `@aws-sdk/lib-storage` | The SDK uploads in **multipart** fashion | Handles huge files (GB+), retries individual parts |
| `Upload.on("httpUploadProgress")` | Emits bytes uploaded per part | We can calculate a percentage |
| `sendProgress` | Pushes a message back to the client via SSE | You can build a progress bar in the UI |
| `await Promise.all(uploads)` | Waits until all parts finish | Guarantees the request only ends when everything is done |

---

## 4.  Front‑end: Listening to progress (SSE example)

```html
<!DOCTYPE html>
<html>
<head>
  <title>Upload + Progress</title>
</head>
<body>
  <form id="uploadForm">
    <input type="file" name="file" required />
    <button type="submit">Upload</button>
  </form>

  <progress id="progressBar" max="100" value="0"></progress>
  <div id="status"></div>

  <script>
    const form = document.getElementById('uploadForm');
    const progressBar = document.getElementById('progressBar');
    const status = document.getElementById('status');

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      const fileInput = form.querySelector('input[type="file"]');
      const file = fileInput.files[0];
      const formData = new FormData();
      formData.append('file', file);

      // 1️⃣ Open SSE connection first
      const evtSource = new EventSource('/upload', { withCredentials: true });

      evtSource.onmessage = (event) => {
        const data = JSON.parse(event.data);
        if (data.percent) {
          progressBar.value = data.percent;
          status.textContent = `Uploading... ${data.percent}%`;
        }
        if (data.status === 'finished') {
          status.textContent = `✅ Uploaded to ${data.location}`;
          evtSource.close();
        }
        if (data.status === 'error') {
          status.textContent = `❌ ${data.error}`;
          evtSource.close();
        }
      };

      // 2️⃣ POST the file
      await fetch('/upload', {
        method: 'POST',
        body: formData,
      });
    });
  </script>
</body>
</html>
```

> *You can swap the SSE logic for a WebSocket or a chunked HTTP response if you prefer.*

---

## 5.  Things to consider

| Topic | Recommendation |
|-------|----------------|
| **Security** | Use IAM policy that only allows `s3:PutObject` on the bucket and maybe prefix `uploads/`. |
| **Large file size** | The SDK automatically handles up to 5 TB. Keep `partSize` ≥ 5 MiB. |
| **Memory** | No temp files, only the part buffer (default 5 MiB). |
| **Timeout** | S3 multipart upload requires the `CompleteMultipartUpload` to be called within 7 days. Our server keeps it alive while the client is connected. |
| **Retries** | The SDK retried each part up to 3 times by default. You can tweak `retryStrategy` on the client if needed. |
| **Progress** | `httpUploadProgress` gives you *bytes* uploaded for *this part*. The SDK aggregates them internally; you can simply divide `loaded / total`. |

---

## 6.  Quick “one‑liner” if you don’t need SSE

```js
app.post("/upload", async (req, res) => {
  const busboy = new Busboy({ headers: req.headers });

  busboy.on("file", (fieldname, fileStream, filename, encoding, mimetype) => {
    const upload = new Upload({
      client: s3Client,
      params: {
        Bucket: process.env.S3_BUCKET,
        Key: `uploads/${Date.now()}-${uuidv4()}-${filename}`,
        Body: fileStream,
        ContentType: mimetype,
      },
    });

    upload.on("httpUploadProgress", (progress) => {
      // You can log or send to client
      console.log(`${filename}: ${((progress.loaded / progress.total) * 100).toFixed(1)}%`);
    });

    upload.done()
      .then(() => res.status(200).json({ success: true }))
      .catch((err) => res.status(500).json({ error: err.message }));
  });

  req.pipe(busboy);
});
```

This snippet will stream the upload directly to S3, log progress to the console, and respond when the upload completes.

---

### TL;DR

1. **Parse** the multipart request with `busboy` (no buffering).  
2. **Create** a `new Upload` (AWS SDK v3).  
3. **Hook** into `httpUploadProgress` for real‑time bytes.  
4. **Stream** the file to S3 in **multipart** parts (5 MiB+ each).  
5. **Push** progress to the client (SSE, WebSocket, etc.).  

That’s it – a scalable, memory‑efficient, and progress‑aware upload flow! Happy coding. 🚀

