<div id="game"></div>

<script type="module">
/* ------------------------------------------------------------
   ASCIITD  –  A tiny tower‑defense in pure ascii
   ------------------------------------------------------------ */
class Grid {
  constructor(rows, cols, el) {
    this.rows = rows; this.cols = cols; this.el = el;
    this.cells = Array.from({length: rows*cols},
          (_,i)=> ({x:i%cols, y:Math.floor(i/cols), type:'empty'}));
    this.refresh();
  }
  refresh(){          // redraw grid
    this.el.innerHTML='';
    for (const c of this.cells){
      const div=document.createElement('div');
      div.className='cell'; div.dataset.type=c.type;
      div.textContent=this.char(c.type);
      this.el.appendChild(div);
    }
  }
  char(type){         // ascii symbol for each type
    switch(type){
      case 'player':return 'P';
      case 'stash' : return 'S';
      case 'zombie': return 'Z';
      default:     return '.';
    }
  }
  at(x,y){return this.cells[y*this.cols+x];}
  set(x,y,type){ this.at(x,y).type=type; this.refresh(); }
  clear(x,y){ this.at(x,y).type='empty'; this.refresh(); }
  neighbors(x,y){          // four orthogonal neighbours
    const dirs=[[-1,0],[1,0],[0,-1],[0,1]];
    return dirs.map(([dx,dy])=>{
      const nx=x+dx, ny=y+dy;
      if(nx>=0&&nx<this.cols&&ny>=0&&ny<this.rows) return this.at(nx,ny);
    }).filter(Boolean);
  }
}

class Entity{constructor(x,y){this.x=x; this.y=y;}}
class Player extends Entity{}
class Stash extends Entity{}
class Zombie extends Entity{
  moveTowards(target){
    const dx = target.x - this.x;
    const dy = target.y - this.y;
    if(Math.abs(dx)>Math.abs(dy)){
      this.x += Math.sign(dx);
    }else{
      this.y += Math.sign(dy);
    }
  }
}

class Game {
  constructor(){
    this.grid = new Grid(15,20,document.getElementById('game'));
    this.player=null; this.stashes=[]; this.zombies=[];
    this.day=true; this.interval=null;
    this.phaseEl=document.getElementById('phase');
    this.startBtn=document.getElementById('startBtn');
    this.startBtn.onclick=this.start.bind(this);
    this.grid.el.onclick=this.placeStash.bind(this);
  }

  start(){
    this.startBtn.disabled=true;
    this.grid.cells.forEach(c=>c.type='empty');
    const p=this.spawnPlayer();
    this.grid.set(p.x,p.y,'player');
    this.stashes=[];
    this.zombies=[];
    this.day=true; this.phaseEl.textContent='Day';
    clearInterval(this.interval);
    this.interval=setInterval(()=>this.tick(),250);
  }

  spawnPlayer(){
    const empty=this.grid.cells.filter(c=>c.type==='empty');
    const {x,y}=empty[Math.floor(Math.random()*empty.length)];
    return this.player=new Player(x,y);
  }

  placeStash(evt){
    const idx=Array.from(this.grid.el.children).indexOf(evt.target);
    if(idx===-1) return;
    const cell=this.grid.cells[idx];
    if(cell.type==='empty'){
      this.stashes.push(new Stash(cell.x,cell.y));
      this.grid.set(cell.x,cell.y,'stash');
    }
  }

  tick(){
    if(this.day){
      this.day=false; this.phaseEl.textContent='Night';
      // spawn zombie if any stash exists
      if(this.stashes.length){
        const border=this.grid.cells.filter(c=>{
          return c.type==='empty' && (c.x===0||c.x===this.grid.cols-1||c.y===0||c.y===this.grid.rows-1);
        });
        const {x,y}=border[Math.floor(Math.random()*border.length)];
        const z=new Zombie(x,y);
        this.zombies.push(z);
        this.grid.set(z.x,z.y,'zombie');
      }
    }else{
      this.day=true; this.phaseEl.textContent='Day';
    }

    // move zombies
    for(const z of [...this.zombies]){
      const target=this.stashes[0]; // only first stash
      if(!target){ this.zombies.splice(this.zombies.indexOf(z),1); continue;}
      this.grid.clear(z.x,z.y);
      z.moveTowards(target);
      if(z.x===target.x && z.y===target.y){
        // destroy stash
        this.grid.clear(target.x,target.y);
        this.stashes.shift();
        this.zombies.splice(this.zombies.indexOf(z),1);
      }else{
        this.grid.set(z.x,z.y,'zombie');
      }
    }
  }
}

new Game();  // kick‑off
</script>
</body>
</html>
