const fileUpload  = require('express-fileupload');
const path        = require('path');
const { User, Op } = require('./models');   // ваш sequelize
const ApiError    = require('./utils/ApiError'); // ваш класс ошибок

// 2. Создаём приложение и подключаем middleware
const app = express();

// body‑parser (если нужны JSON/URL‑encoded)
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// express‑fileupload – обязательно до роутов
app.use(fileUpload({ createParentPath: true })); // создаёт путь, если не существует

// 3. Роут (псевдо‑контроллер)
app.put('/api/user/:username', async (req, res) => {
  try {
    // 4. Ищем пользователя по имени
    const user = await User.findOne({
      where: {
        username: { [Op.iLike]: `%${req.params.username}` },
      },
    });

    if (!user) {
      return res.status(400).json({ error: 'Пользователь не найден.' });
    }

    // 5. Получаем файлы (если пришли)
    const { avatar, background } = req.files || {};

    // 6. Подготовка новых имён (с сохранением расширения)
    let newAvatar   = null;
    let newBackground = null;

    if (avatar) {
      const ext = path.extname(avatar.name); // .jpg, .png и т.д.
      newAvatar = `${req.user.username}_avatar${ext}`;
      await avatar.mv(path.resolve(__dirname, '..', 'uploads', newAvatar));
    }

    if (background) {
      const ext = path.extname(background.name);
      newBackground = `${req.user.username}_background${ext}`;
      await background.mv(path.resolve(__dirname, '..', 'uploads', newBackground));
    }

