            const background = ParserHelper.getHEXColor(value);
            newLine = { text, ...options, background };
            break;
          }

          case 'code': {
            const parser = new BBCodeParser();
            const parsedText = parser.getParsedText(text);

            newLine = {
              layout: codeLayout,
              table: {
                widths: ['*'],
                body: [[{ text: parsedText, color: '#f8f8f2' }]],
              },
              ...options,
