          }

          case 'img': {
            const link = text.startsWith('http') ? text : 'https:' + text;

            const imageName = ParserHelper.generateRandomValues(8) + '-image-' + text.slice(text.lastIndexOf('/') + 1);

            if (typeof addImageIntoDictionary === 'function') {
