### 4. `models/task.js`  (opcional: separación lógica)

```js
// models/task.js
const { v4: uuidv4 } = require('uuid');

class Task {
  constructor(title, description = '', completed = false) {
    this.id = uuidv4();            // ID único (UUID)
    this.title = title;
    this.description = description;
    this.completed = completed;
    this.createdAt = new Date();
    this.updatedAt = new Date();
  }

  update({ title, description, completed }) {
    if (title !== undefined) this.title = title;
    if (description !== undefined) this.description = description;
    if (completed !== undefined) this.completed = completed;
    this.updatedAt = new Date();
  }
}

module.exports = Task;
```

---

### 5. `routes/tasks.js`  (definición de endpoints)

```js
// routes/tasks.js
const express = require('express');
const Task = require('../models/task');

const router = express.Router();

// ------------------------------------------------------------------
// BD simulada en memoria
const tasks = [];   // Array que contendrá las tareas

// ------------------------------------------------------------------
// GET /api/tasks        -> Obtener todas las tareas
router.get('/', (req, res) => {
  res.json(tasks);
});

// GET /api/tasks/:id   -> Obtener tarea por ID
router.get('/:id', (req, res) => {
  const task = tasks.find(t => t.id === req.params.id);
  if (!task) return res.status(404).json({ error: 'Tarea no encontrada' });
  res.json(task);
});

// POST /api/tasks      -> Crear nueva tarea
router.post('/', (req, res) => {
  const { title, description, completed } = req.body;
  if (!title) return res.status(400).json({ error: 'El título es obligatorio' });

  const newTask = new Task(title, description, completed);
  tasks.push(newTask);
  res.status(201).json(newTask);
});

// PUT /api/tasks/:id   -> Actualizar tarea
router.put('/:id', (req, res) => {
  const task = tasks.find(t => t.id === req.params.id);
  if (!task) return res.status(404).json({ error: 'Tarea no encontrada' });

  const { title, description, completed } = req.body;
  task.update({ title, description, completed });

  res.json(task);
});

// DELETE /api/tasks/:id -> Eliminar tarea
router.delete('/:id', (req, res) => {
  const index = tasks.findIndex(t => t.id === req.params.id);
  if (index === -1) return res.status(404).json({ error: 'Tarea no encontrada' });

  const deleted = tasks.splice(index, 1); // devuelve array con el objeto eliminado
  res.json({ message: 'Tarea eliminada', task: deleted[0] });
});

module.exports = router;
```

---

### 6. Opcional: `dotenv` y `.env`

Si quieres cambiar el puerto u otras variables sin tocar el código, crea un archivo `.env`:

