### Полностью изменённый скрипт

```javascript
/* ────────  Инициализация кастомного select  ──────── */
$(".custom-select").each(function () {
  /* исходный select */
  var $select   = $(this),
      classes   = $select.attr("class")   || "",
      id        = $select.attr("id")     || "",
      name      = $select.attr("name")   || "",
      placeholder = $select.attr("placeholder") || "";

  /* ---------- 1️⃣ ПОДВАЛИМ placeholder → value (если есть) ---------- */
  var $defaultOption = $select.find('option[value="' + placeholder + '"]');
  if ($defaultOption.length) {
    // ставим атрибут selected в оригинальном select
    $defaultOption.prop('selected', true);
  }

  /* ---------- 2️⃣ Создаём шаблон кастомного списка ---------- */
  var triggerText = $defaultOption.length
        ? $defaultOption.text()          // если найдено, показываем текст выбранного пункта
        : placeholder;                   // иначе — placeholder (текст по умолчанию)

  var template = '<div class="' + classes + '">';
  template +=   '<span class="custom-select-trigger">' + triggerText + '</span>';
  template +=   '<div class="custom-options">';

  $select.find("option").each(function () {
    var $opt = $(this),
        cls  = $opt.attr("class") || "",
        val  = $opt.attr("value") || "",
        txt  = $opt.html()        || "",
        sel  = $opt.is(":selected") ? " selection" : "";

    template += '<span class="custom-option' + cls + sel +
                '" data-value="' + val + '">' + txt + '</span>';
  });

  template += '</div></div>';

  /* ---------- 3️⃣ Вставляем кастомный UI рядом с оригиналом ---------- */
  $select.wrap('<div class="custom-select-wrapper"></div>');
  $select.hide();
  $select.after(template);
});

/* ────────  Поведение при наведении  ──────── */
$(".custom-option:first-of-type").hover(
  function () {
    $(this).parents(".custom-options").addClass("option-hover");
  },
  function () {
    $(this).parents(".custom-options").removeClass("option-hover");
  }
);

/* ────────  Открытие/закрытие селекта  ──────── */
$(".custom-select-trigger").on("click", function (e) {
  $("html").one("click", function () {
    $(".custom-select").removeClass("opened");
  });
  $(this).parents(".custom-select").toggleClass("opened");
  e.stopPropagation();
});

/* ────────  Выбор пункта  ──────── */
$(".custom-option").on("click", function () {
  var $opt = $(this),
      $wrapper = $opt.parents(".custom-select-wrapper"),
      value = $opt.data("value");

  // ставим выбранный value в оригинальный <select>
  $wrapper.find("select").val(value).trigger("change");

  // обновляем класс selection
  $wrapper.find(".custom-option").removeClass("selection");
  $opt.addClass("selection");

  // обновляем текст триггера
  $wrapper.find(".custom-select-trigger").text($opt.text());

  // закрываем
  $wrapper.find(".custom-select").removeClass("opened");
});
```

---

### Краткие комментарии

| Что | Зачем |
|-----|-------|
| `prop('selected', true)` | Фактически ставим атрибут `selected` в оригинальный `<select>`, чтобы при отправке формы он посылался. |
| `sel = $opt.is(":selected") ? " selection" : ""` | Если пункт выбран изначально, сразу помечаем его классом `selection`, чтобы кастомный UI отразил это. |
| `triggerText` | Текст, который показывается в триггере: если найден `option` по `placeholder`, то его текст; иначе – сам placeholder. |
| `e.stopPropagation()` | Предотвращаем закрытие окна при клике на триггер. |

Теперь при загрузке страницы, если `placeholder` равен значению какого‑то `option`, то именно этот пункт будет выбран и будет отображён в кастомном селекте. Если ни один пункт не совпадает, будет использоваться просто placeholder‑текст.

