    "fetch": (() => {
      try { return typeof fetch === 'function'; } catch (_) { return false; }
    })(),

    // 11. Maps & Sets
    "mapSet": (() => {
      try { return typeof Map === 'function' && typeof Set === 'function'; } catch (_) { return false; }
    })(),

    // 12. WeakMap & WeakSet
    "weakMapSet": (() => {
      try { return typeof WeakMap === 'function' && typeof WeakSet === 'function'; } catch (_) { return false; }
    })(),

