    })(),

    // 19. Dynamic imports
    "dynamicImport": (() => {
      // cannot test in all environments; we only check for the keyword support
      try { return typeof import === 'function'; } catch (_) { return false; }
    })(),

    // 20. SharedArrayBuffer
    "sharedArrayBuffer": (() => {
      try { return typeof SharedArrayBuffer === 'function'; } catch (_) { return false; }
    })(),

    // 21. WebAssembly
    "webAssembly": (() => {
      try { return typeof WebAssembly === 'object'; } catch (_) { return false; }
    })(),

    // 22. Object.fromEntries
    "objectFromEntries": (() => {
      try { return typeof Object.fromEntries === 'function'; } catch (_) { return false; }
    })(),

    // 23. Array.prototype.flat
    "arrayFlat": (() => {
      try { return Array.isArray([1, [2, 3]].flat()); } catch (_) { return false; }
    })(),

    // 24. TypedArray.prototype.at
    "typedArrayAt": (() => {
      try { return typeof Uint8Array.prototype.at === 'function'; } catch (_) { return false; }
    })(),

    // 25. Intl.Segmenter (text segmentation)
    "intlSegmenter": (() => {
      try { return typeof Intl.Segmenter === 'function'; } catch (_) { return false; }
    })(),
  };

  return checks;
}
```

---

## How to use it

```js
const support = detectModernJsSupport();
console.log('Modern JS support:', support);

// Example: If you need at least async/await & fetch
if (!support.asyncAwait || !support.fetch) {
  console.warn('Your browser is missing some modern features – consider a polyfill or a fallback.');
}
```

### Why this helper is handy

* **No external dependencies** – just pure JS.
* **Extensible** – add any new feature test in the `checks` object.
* **Immediate feedback** – get a dictionary that maps each feature to `true / false`.
* **Can be used for graceful degradation** – show a warning or load polyfills only when needed.

---

## Adding more feature checks

If you want to support newer features that have appeared since this helper was written, add a new key/value pair:

```js
