      const d = parseInt(document.getElementById('day').value, 10);
      const m = parseInt(document.getElementById('month').value, 10);
      const y = parseInt(document.getElementById('year').value, 10);

      if(isNaN(d) || isNaN(m) || isNaN(y)){
        showMessage('الرجاء ملء جميع الحقول', true);
        return;
      }

      // تحقق من صحة التاريخ
      const birthDate = new Date(y, m-1, d);
      if(birthDate.getFullYear() !== y ||
         birthDate.getMonth() !== m-1 ||
         birthDate.getDate() !== d){
        showMessage('التاريخ غير صالح! تأكد من القيم', true);
        return;
      }

      const today = new Date();

      if(birthDate > today){
        showMessage('لا يمكن أن يكون تاريخ الميلاد في المستقبل', true);
        return;
      }

      let years = today.getFullYear() - birthDate.getFullYear();
      let months = today.getMonth() - birthDate.getMonth();
      let days   = today.getDate() - birthDate.getDate();

      if(days < 0){
        months -= 1;
        days += new Date(today.getFullYear(), today.getMonth(), 0).getDate(); // أيام الشهر السابق
