下面给出一个 **Node.js**（ES‑Module 语法）实现，核心思路是：

1. 读取 TSX 源码  
2. 用 **@babel/parser** 把代码解析成 AST（开启 `typescript`、`jsx` 等插件）  
3. 通过 **@babel/traverse** 遍历 AST，提取  
   * `import … from '...'` 语句  
   * `import('...')`  动态 import  
   * `require('...')`  CommonJS 语句  
4. 把所有引入的模块名（相对路径和外部依赖）统一收集到一个数组返回

> 你可以直接把下面的代码放到 `analyzeDependencies.js`（或 .ts）里，安装依赖后直接跑：

```bash
npm i @babel/parser @babel/traverse
```

> 如果你想在 TypeScript 项目里用，改名为 `*.ts` 并把 `import`/`export` 写成 `import { ... } from 'module'` 语法即可。

---

## 1️⃣ 代码

```js
// analyzeDependencies.js
import { readFile } from 'fs/promises';
import { parse } from '@babel/parser';
import traverse from '@babel/traverse';

/**
 * 分析给定 TSX 文件中所有的 import/require 语句，返回模块名列表。
 *
 * @param {string} filePath - TSX 文件路径
 * @returns {Promise<string[]>} 依赖模块名数组
 */
export async function analyzeDependencies(filePath) {
  // 1️⃣ 读取文件
  const source = await readFile(filePath, 'utf8');

  // 2️⃣ 解析成 AST
  const ast = parse(source, {
    sourceType: 'module',
    plugins: [
      'typescript',        // 支持 TS
      'jsx',               // 支持 TSX
      'dynamicImport',     // import('foo')
      'importMeta',        // import.meta
    ],
  });

  const deps = new Set(); // 用 Set 去重

  // 3️⃣ 遍历 AST，收集依赖
  traverse(ast, {
    // import Foo from 'bar';
    ImportDeclaration(path) {
      const source = path.node.source.value;
      if (source) deps.add(source);
    },

    // dynamic import('baz')
    Import(path) {
      const arg = path.parent?.arguments?.[0];
      if (arg && arg.type === 'StringLiteral') {
        deps.add(arg.value);
      }
    },

    // const X = require('qux');
    CallExpression(path) {
      const callee = path.node.callee;
      if (
        callee.type === 'Identifier' &&
        callee.name === 'require' &&
        path.node.arguments?.[0]?.type === 'StringLiteral'
      ) {
        const dep = path.node.arguments[0].value;
        deps.add(dep);
      }
    },
  });

  // 4️⃣ 转数组返回
  return Array.from(deps);
}

/* ----------------- Demo ----------------- */
if (import.meta.url === `file://${process.argv[1]}`) {
  const [,, file] = process.argv;
  if (!file) {
    console.error('Usage: node analyzeDependencies.js <tsx-file>');
    process.exit(1);
  }
  analyzeDependencies(file)
    .then(deps => {
      console.log('Dependencies in', file);
      deps.forEach(d => console.log(`- ${d}`));
    })
    .catch(err => {
      console.error('Error analyzing', file, err);
      process.exit(1);
    });
}
```

---

## 2️⃣ 说明

| 步骤 | 作用 | 关键点 |
|------|------|--------|
| 1️⃣ | 读取 TSX 文件 | 用 `fs/promises.readFile`，返回字符串 |
| 2️⃣ | 解析为 AST | `@babel/parser` + `typescript`、`jsx`、`dynamicImport`、`importMeta` 插件 |
| 3️⃣ | 遍历 & 收集 | ① `ImportDeclaration`（静态 import） ② `Import`（动态 import） ③ `CallExpression`（CommonJS require）<br>使用 `Set` 去重，支持相对路径与 npm 包名 |
| 4️⃣ | 返回 | `Array.from(set)`，可以自由排序或保持插入顺序 |

### 可选功能

* **区分内置模块与外部依赖**：  
  ```js
  import { builtinModules } from 'module';
  const isBuiltin = builtinModules.includes(dep);
  ```
* **过滤相对路径**（只想要 npm 包）：  
  ```js
