Below is a **complete, self‑contained “simple chat server”** that you can drop into any folder on a machine that has Node.js installed.  
The solution is split into three parts:

| File | What it does | Where it lives |
|------|--------------|----------------|
| `package.json` | Defines the Node.js package and pulls in the required dependency (`ws`). | Project root |
| `server.js` | The Node.js chat server that serves a minimal HTML client and handles WebSocket messages. | Project root |
| `run-server.ps1` | A PowerShell script that installs dependencies (if needed) and starts the server. | Project root |

---

## 1.  `package.json`

```json
{
  "name": "simple-node-chat",
  "version": "1.0.0",
  "description": "A minimal chat server built with Node.js + WebSocket",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "keywords": ["chat", "websocket", "node", "simple"],
  "author": "ChatGPT",
  "license": "MIT",
  "dependencies": {
    "ws": "^8.13.0"
  }
}
```

> **Why `ws`?**  
> The `ws` package is a lightweight, standards‑compliant WebSocket implementation that works on every Node.js runtime and is a single‑dependency solution for a chat server.

---

## 2.  `server.js`

```js
// server.js
const http = require('http');
const fs = require('fs');
const path = require('path');
const WebSocket = require('ws');

/*
 * 1️⃣  HTTP server – serves the client HTML file
 * 2️⃣  WebSocket server – broadcasts any received message to all connected clients
 */
const PORT = 3000;

// Create a very small HTTP server that only serves index.html
const httpServer = http.createServer((req, res) => {
  // Serve the HTML page at `/`
  if (req.url === '/' || req.url === '/index.html') {
    const filePath = path.join(__dirname, 'index.html');
    fs.readFile(filePath, 'utf8', (err, data) => {
      if (err) {
        res.writeHead(500);
        return res.end('Error loading index.html');
      }
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(data);
    });
  } else if (req.url === '/style.css') {
    // Serve optional CSS
    const filePath = path.join(__dirname, 'style.css');
    fs.readFile(filePath, 'utf8', (err, data) => {
      if (err) {
        res.writeHead(500);
        return res.end('Error loading style.css');
      }
      res.writeHead(200, { 'Content-Type': 'text/css' });
      res.end(data);
    });
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

/*
 * 3️⃣  WebSocket server – upgrade the HTTP connection to WS
 */
const wss = new WebSocket.Server({ server: httpServer });

wss.on('connection', (ws) => {
  console.log('👋 New client connected');

  ws.on('message', (message) => {
    // Echo the message to every connected client
    console.log(`💬 Message received: ${message}`);
    wss.clients.forEach((client) => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    });
  });

  ws.on('close', () => {
    console.log('🔚 Client disconnected');
  });
});

/*
 * 4️⃣  Start listening
 */
httpServer.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
  console.log(`⚙️  WebSocket endpoint: ws://localhost:${PORT}`);
});
```

**Explanation**

| Section | What happens |
|---------|--------------|
| **HTTP server** | Serves a static `index.html` (and optional `style.css`). This is the browser client that will connect via WebSocket. |
| **WebSocket server** | On every `connection`, it sets up listeners. When a message arrives, it broadcasts it to *all* connected clients (including the sender). |
| **Logging** | Simple console output lets you see when clients connect, disconnect, and send messages. |

---

## 3.  `index.html` (the client)

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Node Chat</title>
<style>
  body { font-family: Arial, sans-serif; margin: 0; padding: 0; background:#f0f0f0; }
  #chat { max-width: 600px; margin: 30px auto; padding: 10px; background:white; border-radius:5px; }
  #messages { height: 300px; overflow-y: auto; border: 1px solid #ccc; padding:10px; }
  #input { margin-top:10px; display:flex; }
  #input input { flex:1; padding:8px; }
  #input button { padding:8px 12px; margin-left:5px; }
  .message { margin-bottom:8px; }
  .timestamp { color:#888; font-size:0.85em; margin-right:5px; }
</style>
</head>
<body>
<div id="chat">
  <h2>Simple Chat</h2>
  <div id="messages"></div>
  <div id="input">
    <input id="msgInput" type="text" placeholder="Type a message…" autocomplete="off">
    <button id="sendBtn">Send</button>
  </div>
</div>

<script>
const ws = new WebSocket(`ws://${location.host}`);
const messagesDiv = document.getElementById('messages');
const input = document.getElementById('msgInput');
const btn = document.getElementById('sendBtn');

function addMessage(text) {
  const div = document.createElement('div');
  div.className = 'message';
  const ts = new Date().toLocaleTimeString();
  div.innerHTML = `<span class="timestamp">[${ts}]</span> ${text}`;
  messagesDiv.appendChild(div);
  messagesDiv.scrollTop = messagesDiv.scrollHeight;
}

ws.onopen = () => {
  addMessage('🔗 Connected to chat server');
};

ws.onmessage = (e) => {
  addMessage(e.data);
};

ws.onclose = () => {
  addMessage('❌ Disconnected');
};

btn.onclick = sendMessage;
input.addEventListener('keypress', (e) => {
  if (e.key === 'Enter') sendMessage();
});

function sendMessage() {
  const msg = input.value.trim();
  if (!msg) return;
  ws.send(msg);
  input.value = '';
}
</script>
</body>
</html>
```

> **Tip**: Open two browser tabs or windows to see the real‑time broadcast.

