### 3.5 `src/hooks/useAuth.ts`

```ts
import axios from 'axios';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useToast } from './useToast';

const API_URL = import.meta.env.VITE_API_URL;

export interface LoginPayload {
  email: string;
  password: string;
}

export interface SignUpPayload {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
}

export function useLogin() {
  const { addToast } = useToast();
  const queryClient = useQueryClient();

  return useMutation(
    async (payload: LoginPayload) => {
      const { data } = await axios.post(`${API_URL}/auth/login`, payload);
      // Store token in localStorage (or better: HttpOnly cookie)
      localStorage.setItem('token', data.token);
      return data;
    },
    {
      onSuccess: () => {
        queryClient.invalidateQueries(['currentUser']);
        addToast('Login successful', 'success');
      },
      onError: (err: any) => {
        const msg = err.response?.data?.message || 'Login failed';
        addToast(msg, 'error');
      },
    }
  );
}

export function useSignUp() {
  const { addToast } = useToast();

  return useMutation(
    async (payload: SignUpPayload) => {
      const { data } = await axios.post(`${API_URL}/auth/signup`, payload);
      return data;
    },
    {
      onSuccess: () => {
        addToast('Account created! Please log in.', 'success');
      },
      onError: (err: any) => {
        const msg = err.response?.data?.message || 'Sign‑up failed';
        addToast(msg, 'error');
      },
    }
  );
}
```

