// 2️⃣ Detail page – load item, populate fields
if (document.body.contains($('#item-title'))) {
  const query = new URLSearchParams(window.location.search);
  const id = Number(query.get('id'));
  const item = equipmentData.find(e => e.id === id);

  if (!item) {
    $('#item-title').textContent = "Item not found";
    return;
  }

  // Basic fields
  $('#item-title').textContent = item.name;
  $('#price').textContent = `Price: $${item.price.toLocaleString()}`;
  $('#details').textContent = item.details;
  $('#rating').innerHTML = renderStars(item.rating);
  $('#features').innerHTML = item.features.map(f => `<li>${f}</li>`).join("");

  // Images
  const imgGallery = $('#image-gallery');
  item.images.forEach(src => {
    const img = document.createElement('img');
    img.src = src;
    img.alt = item.name;
    imgGallery.appendChild(img);
  });

  // Videos
  const vidGallery = $('#video-gallery');
  item.videos.forEach(src => {
    const vid = document.createElement('video');
    vid.src = src;
    vid.controls = true;
    vidGallery.appendChild(vid);
  });

  // Helper to render star rating
  function renderStars(rating) {
    const full = Math.floor(rating);
    const half = rating % 1 >= 0.5;
    const stars = [];
    for (let i = 0; i < full; i++) stars.push('<i class="fas fa-star"></i>');
    if (half) stars.push('<i class="fas fa-star-half-alt"></i>');
    while (stars.length < 5) stars.push('<i class="far fa-star"></i>');
    return stars.join("");
  }
}
```

> **Key points**  
> - The same script is used on both pages; it checks for the presence of an element to decide which part to run.  
> - No backend: we simply read the `id` from the query string and find the item locally.  
> - **Icons**: The rating stars use FontAwesome icons. Add the CDN below the `<head>` of each page if you want them to show:

```html
