## Node.js – prosty szyfrowanie i odszyfrowywanie plików

Poniższy skrypt używa wbudowanego modułu **`crypto`** i pozwala:

1.  **Szyfrować** dowolny plik (np. `plik.js`) i zapisać go w postaci binarnej (rozszerzenie `.enc`).
2.  **Odszyfrowywać** plik z powrotem do pierwotnej postaci.

### Wymagania

- Node.js (≥ 12.x – w praktyce działa z dowolnym Node 14+)
- Nie ma dodatkowych zależności – wszystko wbudowane.

### Jak działa skrypt

| element | opis |
|---------|------|
| **PBKDF2** | Na podstawie hasła użytkownika tworzy klucz AES‑256 (32 B). |
| **IV (Initialisation Vector)** | Losowy 16‑Bajtowy wektor, zapisany na początku pliku z zaszyfrowanymi danymi. |
| **AES‑256‑CBC** | Standardowy tryb szyfrowania blokowego. |
| **Plik wyjściowy** | Struktura: `[IV(16B)] + [ciphertext]`. |
| **Obsługa dużych plików** | Operuje w trybie strumieniowym (`fs.createReadStream` / `fs.createWriteStream`) – nie ładuje całości pliku do pamięci. |

### Kod

```js
#!/usr/bin/env node
/**
 *  Szyfrowanie / odszyfrowywanie plików w Node.js
 *  ------------------------------------------------
 *  Użycie:
 *    node encrypt.js encrypt  password.txt  input.js   output.enc
 *    node encrypt.js decrypt  password.txt  output.enc decrypted.js
 *
 *  password.txt – plik zawierający hasło (jeden wiersz).
 *  input.js     – plik do zaszyfrowania (dowolny).
 *  output.enc   – wynikowy plik zaszyfrowany.
 *  decrypted.js – plik odszyfrowany (powinien być identyczny z input.js).
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// ----------- Ustawienia -----------
const ALGO = 'aes-256-cbc';
const KEY_LEN = 32;          // 256‑bit (32 B)
const IV_LEN = 16;           // 128‑bit (16 B)
const SALT_LEN = 16;         // do PBKDF2
const ITERATIONS = 100000;   // liczba iteracji PBKDF2
const DIGEST = 'sha256';     // funkcja skrótu w PBKDF2

// --------------------------------

// Pomocnicza: czytanie hasła z pliku
function readPassword(file) {
  const pwd = fs.readFileSync(file, 'utf8').trim();
  if (!pwd) throw new Error('Hasło nie może być puste');
  return pwd;
}

// Tworzenie klucza z hasła (PBKDF2)
function deriveKey(password, salt) {
  return crypto.pbkdf2Sync(password, salt, ITERATIONS, KEY_LEN, DIGEST);
}

// ---------- Szyfrowanie ----------
function encryptFile(src, dst, pwd) {
  const salt = crypto.randomBytes(SALT_LEN);
  const iv   = crypto.randomBytes(IV_LEN);
  const key  = deriveKey(pwd, salt);

  const cipher = crypto.createCipheriv(ALGO, key, iv);

  const inStream  = fs.createReadStream(src);
  const outStream = fs.createWriteStream(dst);

  // Struktura: [SALT][IV][ciphertext]
  outStream.write(salt);
  outStream.write(iv);

  inStream.pipe(cipher).pipe(outStream);

  outStream.on('finish', () => {
    console.log(`✅ Zaszyfrowano ${src} → ${dst}`);
  });
  outStream.on('error', err => {
    console.error('Błąd podczas szyfrowania:', err);
    process.exit(1);
  });
}

// ---------- Odszyfrowywanie ----------
function decryptFile(src, dst, pwd) {
  const inStream = fs.createReadStream(src);
  let salt, iv;
  let headerBytes = 0;

  // Odczytujemy najpierw SALT i IV z początku pliku
  const header = [];
  inStream.on('data', chunk => {
    if (headerBytes < SALT_LEN + IV_LEN) {
      header.push(chunk);
      headerBytes += chunk.length;
      if (headerBytes >= SALT_LEN + IV_LEN) {
        const combined = Buffer.concat(header);
        salt = combined.slice(0, SALT_LEN);
        iv   = combined.slice(SALT_LEN, SALT_LEN + IV_LEN);
        // Reszta danych to ciphertext
        const remaining = combined.slice(SALT_LEN + IV_LEN);
        // Przekazujemy stream dalej do decryption
        const key = deriveKey(pwd, salt);
        const decipher = crypto.createDecipheriv(ALGO, key, iv);
        const outStream = fs.createWriteStream(dst);
        // Najpierw zapisujemy już odczytane ciphertext
        outStream.write(remaining);
        // Kontynuuj z reszty strumienia
        inStream.pipe(decipher).pipe(outStream);
        outStream.on('finish', () => {
          console.log(`✅ Odszyfrowano ${src} → ${dst}`);
        });
        outStream.on('error', err => {
          console.error('Błąd podczas odszyfrowywania:', err);
          process.exit(1);
        });
        // Usuń handler aby nie odczytywać tego raz jeszcze
        inStream.removeAllListeners('data');
      }
    }
  });

  inStream.on('error', err => {
    console.error('Błąd czytania pliku wejściowego:', err);
    process.exit(1);
  });
}

// ------------------ Główna logika ------------------
function printUsage() {
  console.log(`
  Użycie:
    node encrypt.js encrypt  <hasło.txt> <plik_wejściowy> <plik_zaszyfrowany>
    node encrypt.js decrypt  <hasło.txt> <plik_zaszyfrowany> <plik_odszyfrowany>

  Przykład:
    node encrypt.js encrypt  password.txt  app.js  app.js.enc
    node encrypt.js decrypt  password.txt  app.js.enc  app.js
  `);
}

function main() {
  const [,, mode, pwdFile, src, dst] = process.argv;

  if (!mode || !pwdFile || !src || !dst) {
    printUsage();
    process.exit(1);
  }

  if (!fs.existsSync(pwdFile)) {
    console.error(`❌ Nie znaleziono pliku hasła: ${pwdFile}`);
    process.exit(1);
  }

  const pwd = readPassword(pwdFile);

  if (mode === 'encrypt') {
    encryptFile(src, dst, pwd);
  } else if (mode === 'decrypt') {
    decryptFile(src, dst, pwd);
  } else {
    console.error(`❌ Nieznany tryb: ${mode}`);
    printUsage();
    process.exit(1);
  }
}

main();
```

### Jak to testować

1. **Utwórz plik z hasłem**

   ```bash
   echo "mojeSuperHasło" > password.txt
   ```

2. **Szyfruj plik `plik.js`**

   ```bash
   node encrypt.js encrypt password.txt plik.js plik.js.enc
   ```

3. **Odszyfruj plik**

   ```bash
   node encrypt.js decrypt password.txt plik.js.enc plik_decrypted.js
   ```

4. **Sprawdź zgodność**

   ```bash
   diff plik.js plik_decrypted.js
   ```

   Jeśli nie ma różnic – wszystko działa!

### Bezpieczeństwo i najlepsze praktyki

| Rada | Dlaczego |
|------|----------|
| **Używaj silnych haseł** | Im silniejsze hasło, tym trudniejsze będzie złamanie klucza. |
| **Nie przechowuj kluczy w kodzie** | Klucz powinien być generowany z hasła lub przechowywany w bezpiecznym magazynie (np. KMS). |
| **Unikaj hard‑codowania** | Pamiętaj, aby `password.txt` nie było w repozytorium. |
| **Regularnie aktualizuj** | Upewnij się, że Node.js i biblioteki są aktualne. |
| **Weryfikuj integralność** | Po odszyfrowaniu możesz obliczyć HMAC lub SHA‑256, by potwierdzić, że plik nie został zmodyfikowany. |

### Rozszerzenia

- **Szyfrowanie folderów** – możesz rekurencyjnie iterować po plikach w folderze i szyfrować je pojedynczo.
- **Wykorzystanie HMAC** – dodaj kontrolę integralności po każdym pliku.
- **Zarządzanie kluczami** – zamiast hasła możesz wykorzystać key‑management system (AWS KMS, Azure Key Vault, HashiCorp Vault).
- **Kompresja** – przed szyfrowaniem możesz skompresować plik (np. `zlib`) dla lepszej wydajności przy dużych danych.

