### Example – `react‑table`

```tsx
import {
  useTable,
  useGlobalFilter,
  useFilters,
  useSortBy,
} from 'react-table';

function Table({ columns, data }) {
  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    rows,
    prepareRow,
    state,
    setGlobalFilter,
  } = useTable(
    { columns, data },
    useFilters,
    useGlobalFilter,
    useSortBy
  );

  return (
    <>
      {/* Global filter */}
      <input
        value={state.globalFilter || ''}
        onChange={e => setGlobalFilter(e.target.value)}
        placeholder="Search…"
        style={{ marginBottom: '1rem' }}
      />

      <table {...getTableProps()}>
        <thead>
          {headerGroups.map(hg => (
            <tr {...hg.getHeaderGroupProps()}>
              {hg.headers.map(column => (
                <th {...column.getHeaderProps()}>
                  {column.render('Header')}
                  {/* Column filter UI */}
                  <div>{column.canFilter ? column.render('Filter') : null}</div>
                </th>
              ))}
            </tr>
          ))}
        </thead>

        <tbody {...getTableBodyProps()}>
          {rows.map(row => {
            prepareRow(row);
            return (
              <tr {...row.getRowProps()}>
                {row.cells.map(cell => (
                  <td {...cell.getCellProps()}>{cell.render('Cell')}</td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </>
  );
}
```

*React‑table* comes with built‑in `useGlobalFilter` for global search and `useFilters` for per‑column filters. You only need to render the filter UI for each column.

