## 2. Custom plain‑JavaScript (no library)

If you’re not using a library, you can write a small utility that hides rows that don’t match the filter(s):

```html
<table id="myTable">
  <thead>
    <tr>
      <th>Name <input data-col="0" placeholder="Filter"/></th>
      <th>Age  <input data-col="1" placeholder="Filter"/></th>
      <!-- more headers -->
    </tr>
  </thead>
  <tbody>
    <!-- rows -->
  </tbody>
</table>

<input id="global-filter" placeholder="Global Search"/>
```

```js
const table = document.querySelector('#myTable');
const globalInput = document.getElementById('global-filter');
const colInputs = table.querySelectorAll('thead input');

function filterTable() {
  const rows = table.tBodies[0].rows;
  const globalVal = globalInput.value.trim().toLowerCase();
  const colVals = Array.from(colInputs).map(inp => inp.value.trim().toLowerCase());

  for (const row of rows) {
    let visible = true;

    // Column filters
    for (let c = 0; c < colVals.length; c++) {
      if (colVals[c] && !row.cells[c].textContent.toLowerCase().includes(colVals[c])) {
        visible = false;
        break;
      }
    }

    // Global filter – apply only if all column filters passed
    if (visible && globalVal) {
      const rowText = Array.from(row.cells).map(td => td.textContent).join(' ').toLowerCase();
      if (!rowText.includes(globalVal)) visible = false;
    }

    row.style.display = visible ? '' : 'none';
  }
}

globalInput.addEventListener('input', filterTable);
colInputs.forEach(inp => inp.addEventListener('input', filterTable));
```

This vanilla‑JS snippet demonstrates the logic: each column input filters its own column, and the global input checks every visible cell. Adjust for case‑sensitivity, regex, etc. as you need.

