## 1. The “raw” IndexedDB API (no helper libs)

> **Why use the raw API?**  
> It keeps you in the weeds – you see what the browser actually does.  
> If you’re comfortable with promises and async/await, the raw API is fine.  
> (Later in this answer we’ll show how to replace it with a tiny helper like *idb* or *Dexie.js*.)

```js
/**
 * A tiny wrapper that turns the event‑based IndexedDB API into promises.
 * It also centralises error handling.
 */
function openDB(name, version, upgradeCallback) {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(name, version);
    request.onerror = () => reject(request.error);
    request.onupgradeneeded = e => {
      upgradeCallback(e.target.result, e.oldVersion, e.newVersion);
    };
    request.onsuccess = e => resolve(e.target.result);
  });
}
```

### 1.1  Create/upgrade the database

```js
// 1. Open a database called “blog‑app” at version 1
//    If it does not exist, onupgradeneeded will fire.
async function initDB() {
  const db = await openDB('blog-app', 1, db => {
    // Create an object store for blog posts
    const postsStore = db.createObjectStore('posts', {
      keyPath: 'id',          // Auto‑generated or supplied
      autoIncrement: true    // If you want auto‑incrementing IDs
    });

    // Indexes:
    //  - By date (ascending)
    //  - By title (unique)
    //  - By tags (multiEntry so one tag can match many posts)
    postsStore.createIndex('date', 'date', { unique: false });
    postsStore.createIndex('title', 'title', { unique: true });
    postsStore.createIndex('tags', 'tags', { unique: false, multiEntry: true });

    // Object store for simple key/value settings
    db.createObjectStore('settings', { keyPath: 'key' });

    // Store for static asset meta‑data (URL, last‑modified, etc.)
    const assetsStore = db.createObjectStore('assets', { keyPath: 'url' });
    assetsStore.createIndex('lastModified', 'lastModified', { unique: false });
  });
  return db;
}
