});

// Delete article
router.post('/delete/:id', (req, res) => {
  const { id } = req.params;
  db.run('DELETE FROM articles WHERE id = ?', [id], function (err) {
    if (err) return res.sendStatus(500);
    res.redirect('/admin');
  });
});

// Settings page
router.get('/settings', async (req, res) => {
  const settings = await getSettings();
  res.render('author/settings', { settings, errors: null });
});

// Submit settings
router.post('/settings', (req, res) => {
  const { title, subtitle, author_name } = req.body;
  const errors = [];
  if (!title) errors.push('Title required');
  if (!subtitle) errors.push('Subtitle required');
  if (!author_name) errors.push('Author name required');

  if (errors.length) {
    return res.render('author/settings', {
      settings: { title, subtitle, author_name },
      errors
    });
  }

  db.run(
    `UPDATE settings SET title = ?, subtitle = ?, author_name = ? WHERE id = 1`,
    [title, subtitle, author_name],
    function (err) {
      if (err) return res.sendStatus(500);
      res.redirect('/admin');
    }
  );
});

module.exports = router;
```

