## 7. Reader Routes – `routes/reader.js`

```js
// routes/reader.js
const express = require('express');
const router = express.Router();
const db = require('../db');
const moment = require('moment');

// Helper: fetch settings
function getSettings() {
  return new Promise((resolve, reject) => {
    db.get('SELECT * FROM settings WHERE id = 1', (err, row) => {
      if (err) reject(err); else resolve(row);
    });
  });
}

// Home – list of published articles
router.get('/', async (req, res) => {
  const settings = await getSettings();

  const articles = await new Promise((resolve, reject) => {
    db.all(
      `SELECT * FROM articles WHERE is_published = 1
       ORDER BY published_at DESC`,
      (err, rows) => (err ? reject(err) : resolve(rows))
    );
  });

  res.render('reader/home', { settings, articles, moment });
});

// Article page
router.get('/article/:id', async (req, res) => {
  const { id } = req.params;
  const settings = await getSettings();

  const article = await new Promise((resolve, reject) => {
    db.get('SELECT * FROM articles WHERE id = ? AND is_published = 1', [id], (err, row) => {
      if (err) reject(err); else resolve(row);
    });
  });

  if (!article) return res.status(404).send('Article not found');

  const comments = await new Promise((resolve, reject) => {
    db.all(
      `SELECT * FROM comments WHERE article_id = ?
       ORDER BY created_at ASC`,
      [id],
      (err, rows) => (err ? reject(err) : resolve(rows))
    );
  });

  res.render('reader/article', { settings, article, comments, moment });
});

// Like
router.post('/article/:id/like', (req, res) => {
  const { id } = req.params;
  db.run(
    `UPDATE articles SET likes = likes + 1 WHERE id = ? AND is_published = 1`,
    [id],
    function (err) {
      if (err) return res.sendStatus(500);
      res.redirect(`/article/${id}`);
    }
  );
});

// Add comment
router.post('/article/:id/comment', (req, res) => {
  const { id } = req.params;
  const { text } = req.body;
  if (!text) return res.redirect(`/article/${id}`);

  const now = new Date().toISOString();
  db.run(
    `INSERT INTO comments (article_id, text, created_at)
     VALUES (?, ?, ?)`,
    [id, text, now],
    function (err) {
      if (err) return res.sendStatus(500);
      res.redirect(`/article/${id}`);
    }
  );
});

module.exports = router;
```

