где **`valueX` – массив строк**, и преобразует его в вложенный объект.  
Для того чтобы получить *точно* тот вид, который вы показали в примере,  
вам понадобится небольшая «правила‑переименования» и «правила‑распределения»  
(как именно каждый ключ «разворачивается» в путь в итоговом объекте).  
Функция `arrayToObject` принимает два коллбэка, которые позволяют задать эти правила.

```js
/**
 * Преобразует массив вида
 * [root, key1, val1, key2, val2, …]
 * в вложенный объект.
 *
 * @param {Array} arr          Исходный массив
 * @param {Object} opts        Опции
 * @param {Function} opts.keyMapper   (key)  → string | Array<string>
 *        Возвращает строку (или массив строк) – путь к ключу в объекте.
 *        Если возвращает массив – это цепочка вложенных ключей.
 * @param {Function} opts.valueMapper (key, value) → any
 *        Позволяет преобразовать значение (например, переставлять элементы)
 *        перед тем, как поместить его в объект.
 * @returns {Object}
 */
function arrayToObject(arr, opts = {}) {
  const { keyMapper = k => k, valueMapper = (k, v) => v } = opts;

  if (!Array.isArray(arr) || arr.length === 0) {
    return {};
  }

  const rootKey = arr[0];
  const result = {};

  // Установить значение по пути в объекте
  const setByPath = (obj, path, val) => {
    let cur = obj;
    for (let i = 0; i < path.length - 1; i++) {
      cur[path[i]] = cur[path[i]] || {};
      cur = cur[path[i]];
    }
    cur[path[path.length - 1]] = val;
  };

  // Проходим по массиву по парам ключ‑значение
  for (let i = 1; i + 1 < arr.length; i += 2) {
    const rawKey = arr[i];
    const rawVal = arr[i + 1];

    // Какой путь в объекте будет создан?
    const pathOrStr = keyMapper(rawKey);

    // Если ключ‑строка – просто оборачиваем в массив, чтобы можно было использовать setByPath
    const path = Array.isArray(pathOrStr) ? pathOrStr : [pathOrStr];

    // При желании можно изменить само значение
    const val = valueMapper(rawKey, rawVal);

    setByPath(result, path, val);
  }

  return { [rootKey]: result };
}
```

