  button:hover{background:#45a047;}
  pre{background:#2d2d2d;color:#f8f8f2;padding:1rem;border-radius:6px;overflow:auto;}
  .output{margin-top:1rem;}
</style>
</head>
<body>
<div class="container">
  <h2>Extended Euclidean Algorithm</h2>
  <div class="inputs">
    <input type="number" id="a" placeholder="Nhập số a (định tử)" min="1">
    <input type="number" id="b" placeholder="Nhập số b (mẫu)" min="1">
  </div>
  <button id="calcBtn">Tính</button>

  <div class="output">
    <pre id="result"></pre>
  </div>
</div>

<script>
document.getElementById('calcBtn').addEventListener('click', function(){
  const a = parseInt(document.getElementById('a').value,10);
  const b = parseInt(document.getElementById('b').value,10);
  const out = document.getElementById('result');
  out.textContent = '';

  if(isNaN(a) || isNaN(b) || a <= 0 || b <= 0){
    out.textContent = 'Vui lòng nhập hai số nguyên dương hợp lệ.';
    return;
  }

  /* 1. Euclidean Algorithm – các bước chia */
  const r = [a,b];
  const q = [];
  let i = 2;
  while(r[i-2] % r[i-1] !== 0){
    const q_i = Math.floor(r[i-2]/r[i-1]);
    const rem = r[i-2] % r[i-1];
    q.push(q_i);
    r.push(rem);
    i++;
  }
  q.push(Math.floor(r[i-2]/r[i-1])); // last quotient

  const steps = [];
  for(let j=0;j<q.length;j++){
    steps.push(`${r[j]} = ${q[j]} * ${r[j+1]} + ${r[j+2]}`);
  }
  steps.push(`${r[r.length-2]} = ${q[q.length-1]} * ${r[r.length-1]} + 0`);

  /* 2. Extended Euclidean – các bước phụ trục */
  // terms: array of {coeff, idx}
  let terms = [{coeff:1, idx:r.length-1}];
  const expLines = [];

  function formatTerms(ts){
    return ts.map(t=>`${t.coeff>=0?'': '-'}${Math.abs(t.coeff)} * ${r[t.idx]}`).join(' + ');
  }

  // print initial line (before any substitution)
  expLines.push(`=> ${formatTerms(terms)}`);

  while(true){
    // tìm thuật ngữ có idx lớn hơn 1 (để tiếp tục chia)
    const idxToReplace = terms.reduce((max,t)=> t.idx>max.idx?t:max, {idx:-1}).idx;
    if(idxToReplace<=1) break; // đã có chỉ số 0 hoặc 1 (số đầu và số mẫu)
    const term = terms.find(t=>t.idx===idxToReplace);
    terms = terms.filter(t=>t.idx!==idxToReplace); // bỏ term đó

    const q_val = q[idxToReplace-1]; // q[k] khi k = idx-1
    // Thêm hai thuật ngữ mới
    terms.push({coeff:term.coeff, idx:idxToReplace-2});
    terms.push({coeff:-term.coeff*q_val, idx:idxToReplace-1});

    // gộp giống nhau
    const merged = {};
    terms.forEach(t=>{
      if(Math.abs(t.coeff)<1e-9) return;
      if(merged[t.idx]) merged[t.idx] += t.coeff;
      else merged[t.idx] = t.coeff;
    });
    terms = Object.keys(merged).map(k=>({coeff:merged[k], idx:parseInt(k)}));

    expLines.push(`=> ${formatTerms(terms)}`);
  }

  // 3. Inverse modulo
  const coeffForA = terms.find(t=>t.idx===1)?.coeff || 0; // idx 1 là số a
  const coeffForB = terms.find(t=>t.idx===0)?.coeff || 0; // idx 0 là số b
  const gcd = r[r.length-1];
  let invText = '';
  if(gcd===1){
    const inv = ((-coeffForA)%b + b)%b; // vì a*inv + b*coeffForB = 1 => a*inv ≡ 1 (mod b)
    invText = `=> ${a}^-1(mod${b}) = ${coeffForA} (mod${b})\n   = ${inv} (mod${b})`;
  }else{
    invText = `Không có nghịch đảo modulo vì gcd(${a},${b}) = ${gcd}.`;
  }

  /* 4. Hiển thị kết quả */
  const result = [
    'Bước Euclidean:',
    ...steps,
    '',
    'Các bước phụ trục (Extended Euclidean):',
    ...expLines,
    '',
    invText
  ].join('\n');

  out.textContent = result;
});
</script>
</body>
</html>
```

### 📌 Hướng dẫn sử dụng

1. Nhập hai số nguyên dương vào ô *Nhập số a* và *Nhập số b*.
2. Nhấn nút **Tính**.
3. Kết quả sẽ hiển thị:
