## 8. Suggested refactor

Below is a cleaned‑up, “best‑practice” version of your startup file.  It keeps the same flow but fixes the issues above and adds a few niceties.

```js
/**
 *  server.js
 *
 *  Entry point for MedicsCommunicationServer
 */

require('dotenv').config();

const path = require('path');
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const { createLogger } = require('./services/Logger');
const MongoDBService = require('./services/MongodbService');
const LockManager = require('node-locksmith');

const logger = createLogger('MedicsCommunicationServer');
const lockManager = new LockManager({
  lockFileName: 'medics_communication_server.lock',
});

lockManager.initializeTerminationHandlers(); // release lock on SIGINT/SIGTERM

const app = express();

async function init() {
  // 1. Acquire a process lock (30 min timeout, 3 retries)
  await lockManager.createLock(30 * 60 * 1000, 3);

  // 2. Middlewares
  app.use(helmet()); // security headers
  app.use(cors({
    origin: ['https://example.com'], // <-- change as needed
    methods: 'GET,PUT,POST,DELETE,PATCH,OPTIONS',
    allowedHeaders: ['Origin', 'X-Requested-With', 'Content-Type', 'Accept', 'Authorization', 'noauth'],
  }));

  app.use(express.json({ limit: '10mb' }));          // modern body parser
  app.use(express.urlencoded({ extended: true, limit: '10mb', parameterLimit: 5000 }));

  // 3. Request logging
  app.use((req, res, next) => {
    logger.info(`HTTP ${req.method} ${req.originalUrl}`);
    next();
  });

  // 4. Static assets
  const staticRoot = path.resolve(__dirname, 'public');
  app.use('/files', express.static(staticRoot));

  // 5. Database
  try {
    await MongoDBService.connect(process.env.MONGODB_URI || require('./config.json').mongodbURL);
    logger.info('Connected to MongoDB');
  } catch (e) {
    logger.error('MongoDB connection failed', e);
    process.exit(1);
  }

  // 6. Models
  app.models = require('./models/index');

  // 7. Routes
  const routes = require('./routes');
  Object.entries(routes).forEach(([route, controller]) => {
    app.use(route, controller(app, route));
  });

  // 8. 404 handler
  app.use((req, res) => res.status(404).json({ error: 'Not Found' }));

  // 9. Error handler
  app.use((err, req, res, next) => {
    logger.error('Unhandled error', err);
    res.status(500).json({ error: 'Internal Server Error' });
  });

  // 10. Listen
  const PORT = process.env.SERVER_PORT || require('./config.json').serverPort || 3000;
  app.listen(PORT, () => {
    logger.info(`Listening on port ${PORT}`);
  });
}

init().catch(err => {
  logger.error('Failed to start server', err);
  process.exit(1);
});
```

### What changed?

1. **Lock timeout** – now a finite value; removes the risk of permanent lock.
2. **Single lock create** – no separate `checkLock`.
3. **Built‑in middleware** – `express.json/urlencoded` replace `body-parser`.
4. **CORS** – switched to the `cors` package for correctness.
5. **Static assets** – served only under `/files` (adjust as needed).
6. **Error handling** – 404 middleware, async route safety via `express-async-errors` can still be added if desired.
7. **Configuration** – reads from env first, falls back to config.json.
8. **Logging** – unified logger usage, request logging added.
9. **Port fallback** – ensures the server always has a port.

---

## 9. Final checklist

| ✅ | Item | Notes |
|---|------|-------|
|  | **Process locking** | Finite timeout, single create call. |
|  | **Middleware order** | Helmet → CORS → Body → Static → Routes → 404 → Error. |
|  | **Body parsing** | Use `express.json()` & `express.urlencoded()`. |
|  | **CORS** | Use `cors` package; restrict origins. |
|  | **Static** | Serve once, avoid duplicates. |
|  | **Error handling** | 404 + async safety + detailed logs. |
|  | **Logging** | Use logger everywhere; add request logger. |
|  | **Config** | Prefer env variables, validate presence. |
|  | **Graceful shutdown** | Lock released on SIGINT/SIGTERM. |
|  | **Dependencies** | Remove unused `body-parser`; add `cors` if not already. |
|  | **Port** | Expose via env, fallback to config, default 3000. |

