/**
 * A thin wrapper around the browser `WebSocket` API that:
 *   * opens a connection to the backend service,
 *   * parses incoming JSON messages,
 *   * emits high‑level events via a tiny pub/sub (`mitt`), and
 *   * exposes a `sendMessage` helper for sending JSON payloads.
 *
 * @example
 * import { websocketApi } from './WebSocketManager.js';
 *
 * // Subscribe to an event
 * websocketApi.emitter.on('update_station', ({ uuid }) => {
 *   console.log('Station updated:', uuid);
 * });
 *
 * // Send a message
 * websocketApi.sendMessage({ action: 'ping' });
 */
class WebSocketManager {
  /**
   * Creates a new `WebSocketManager`.  
   * The constructor does **not** open the connection – use {@link #open} instead.
   *
   * @constructor
   */
  constructor() {
    /**
     * An event emitter that follows the `mitt` API.  
     * Exposed so that callers can subscribe directly:
     *
     * ```js
     * websocketApi.emitter.on('update_station', ({ uuid }) => { … })
     * ```
     *
     * @type {import('mitt').Emitter}
     */
    this.emitter = mitt();
  }

  /**
   * Establishes a new WebSocket connection to the server.
   *
   * Once the socket is open, incoming messages are parsed as JSON and
   * translated into one of the following high‑level events:
   *
   * * **update_station** – emitted when a single station changes. Payload: `{ uuid }`.
   * * **update_station_list** – emitted when the list of stations changes. No payload.
   * * **update_inventory** – emitted when an inventory changes. Payload: `{ factory_uuid, inventory_name }`.
   *
   * @returns {void}
   */
  open() {
    this.socket = new WebSocket('ws://owbalancer.ddns.net:8765/site');

    // Preserve the `this` context inside the event listener.
    const self = this;

    this.socket.addEventListener('message', (msg) => {
      /** @type {any} */
      const json = JSON.parse(msg.data);

      const { action, uuid, factory, inventory } = json;

      switch (action) {
        case 'update_station':
          // @fires update_station
          self.emitter.emit('update_station', { uuid });
          break;

        case 'update_station_list':
          // @fires update_station_list
          self.emitter.emit('update_station_list');
          break;

        case 'update_inventory':
          // @fires update_inventory
          self.emitter.emit('update_inventory', {
            factory_uuid: factory,
            inventory_name: inventory,
          });
          break;

        default:
          /* eslint-disable-next-line no-console */
          console.warn(`WebSocketManager: unknown action "${action}"`);
      }
    });
  }

  /**
   * Sends a JSON‑encoded message to the server over the open WebSocket.
   *
   * @param {any} data - The payload to send. It will be converted to JSON with `JSON.stringify`.
   * @returns {void}
   * @throws {Error} If the socket is not open.
   */
  sendMessage(data) {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
      throw new Error('WebSocket is not connected');
    }
    this.socket.send(JSON.stringify(data));
  }
}

/**
 * A single, shared instance that can be imported wherever a WebSocket
 * connection is required.
 *
 * @type {WebSocketManager}
 */
export const websocketApi = new WebSocketManager();
```

