下面给出一套最小可运行的「3D 模型预览 Web 系统」代码。  
目录结构、后端（Node / Express）与前端（HTML + CSS + JS）全部包含在内，直接按步骤执行即可启动。

```
project/
│
├─ server.js                # 后端
├─ package.json             # npm 依赖
├─ models/                  # 存放模型与预览图
│   ├─ projectFiles/
│   │   ├─ modelA/
│   │   │   ├─ preview.png
│   │   │   └─ file.obj
│   │   └─ modelB/ …
│   ├─ documents/
│   │   └─ …                # 与 projectFiles 结构相同
│   └─ hdrpResources/
│       └─ …                # 与 projectFiles 结构相同
│
└─ public/                  # 前端文件
    ├─ index.html
    ├─ styles.css
    └─ script.js
```

---

## 1️⃣ `package.json`

```json
{
  "name": "model-preview",
  "version": "1.0.0",
  "description": "3D 模型预览 Web 系统",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  }
}
```

---

## 2️⃣ `server.js`

```js
const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;

// ---------- 静态资源 ----------
app.use(express.static('public'));              // 前端文件
app.use('/models', express.static('models'));   // 模型与预览图

// ---------- API ----------
app.get('/api/models', (req, res) => {
  const category = req.query.category || 'projectFiles';
  const page = parseInt(req.query.page, 10) || 1;
  const perPage = 20;

  const categoryPath = path.join(__dirname, 'models', category);

  fs.readdir(categoryPath, { withFileTypes: true }, (err, entries) => {
    if (err) {
      console.error(err);
      return res.status(500).json({ error: '读取目录失败' });
    }

    // 只取子目录（每个目录代表一个模型）
    const dirs = entries.filter(e => e.isDirectory()).map(e => e.name);

    const models = dirs.map(name => {
      const previewUrl = `/models/${category}/${name}/preview.png`;
      const fileUrl = `/models/${category}/${name}/file.obj`; // 可自行改扩展名
      return { id: name, name, previewUrl, fileUrl };
    });

    const total = models.length;
    const pageCount = Math.ceil(total / perPage);
    const start = (page - 1) * perPage;
    const pageModels = models.slice(start, start + perPage);

    res.json({ total, pageCount, page, models: pageModels });
  });
});

// ---------- 启动 ----------
app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

> **安装 & 启动**  
> ```bash
> npm install
> npm start
> ```

