## 5️⃣ `public/script.js`

```js
const API_URL = '/api/models';
const perPage = 20;

// 当前状态
let state = {
  category: 'projectFiles',
  page: 1,
  pageCount: 1
};

// 初始化
document.addEventListener('DOMContentLoaded', () => {
  // 绑定分类切换
  const radios = document.querySelectorAll('input[name="category"]');
  radios.forEach(r => r.addEventListener('change', onCategoryChange));

  // 第一次加载
  loadModels();
});

// ---------- 事件 ----------
function onCategoryChange(e) {
  state.category = e.target.value;
  state.page = 1;           // 切换分类后回到第一页
  loadModels();
}

// ---------- 加载模型 ----------
function loadModels() {
  fetch(`${API_URL}?category=${state.category}&page=${state.page}`)
    .then(r => r.json())
    .then(data => {
      state.pageCount = data.pageCount;
      renderGrid(data.models);
      renderPagination();
    })
    .catch(err => console.error(err));
}

// ---------- 渲染网格 ----------
function renderGrid(models) {
  const grid = document.getElementById('model-grid');
  grid.innerHTML = '';
  models.forEach(m => {
    const div = document.createElement('div');
    div.className = 'model-item';

    const a = document.createElement('a');
    a.href = m.fileUrl;          // 直接下载
    a.download = '';             // 浏览器下载

    const img = document.createElement('img');
    img.src = m.previewUrl;
    img.alt = m.name;

    a.appendChild(img);
    div.appendChild(a);

    const name = document.createElement('p');
    name.textContent = m.name;
    div.appendChild(name);

    grid.appendChild(div);
  });
}

// ---------- 渲染分页 ----------
function renderPagination() {
  const container = document.getElementById('pagination');
  container.innerHTML = '';

  const createBtn = (text, disabled, handler, active=false) => {
    const btn = document.createElement('span');
    btn.textContent = text;
    btn.className = 'page-btn';
    if (disabled) btn.classList.add('disabled');
    if (active) btn.classList.add('active');
    if (!disabled && handler) btn.addEventListener('click', handler);
    return btn;
  };

  // 上一页
  container.appendChild(createBtn('上一页', state.page === 1, () => {state.page--; loadModels();}));

  // 页码
  for (let i=1;i<=state.pageCount;i++){
    container.appendChild(createBtn(i, false, () => {state.page=i; loadModels();}, i===state.page));
  }

  // 下一页
  container.appendChild(createBtn('下一页', state.page===state.pageCount, () => {state.page++; loadModels();}));
}
```

---

### 说明

1. **目录分类**  
   - `models/projectFiles/`、`models/documents/`、`models/hdrpResources/` 每个子文件夹里再放置若干个模型子文件夹。  
   - 模型子文件夹命名随意，内部必须包含 `preview.png`（预览图）与 `file.obj`（可自行改扩展名）。

2. **自动更新**  
   - 服务器会实时读取 `models/` 目录下的内容，刷新页面后即可自动把新增/删除的模型纳入列表。

3. **分页**  
   - 每页 20 个模型，网格 4 列 × 5 行。  
   - 分页按钮会根据当前页数自动生成。

4. **下载**  
   - 预览图片是 `<a href=".../file.obj" download>`，点击即下载对应的模型文件。

5. **单选框分类**  
   - 通过 `<input type="radio">` 实现单选，切换后自动刷新列表，仅显示对应分类。

只需把上述文件放在对应位置，执行 `npm install` + `npm start` 即可在浏览器访问 `http://localhost:3000/`。祝开发愉快！

