| 7 | Write the generated files into a `generated/` folder (plus a `package.json` that contains all the required dependencies) | `fs` |
| 8 | (Optional) automatically run `npm install` and start the generated app | `child_process` |

> **Why this approach?**  
> *Using templates keeps the generator logic clear and makes it easy to tweak any part (e.g. change the auth strategy).*  
> *All files are created with **full comments** so you can read and modify them later.*

---

## 1. Project layout

```
generator/
├─ generator.js          ← the script you run to generate a new API
└─ templates/
   ├─ model.ejs
   ├─ controller.ejs
   ├─ router.ejs
   ├─ auth.ejs
   ├─ server.ejs
   └─ package.ejs
```

*The templates are EJS strings – you can also keep them as separate files if you prefer.*

---

## 2. Install the dependencies you’ll need for the generator itself

```bash
mkdir generator
cd generator
npm init -y
npm install node-sql-parser ejs readline-sync chalk
```

> *`readline-sync` gives a synchronous prompt (simpler in a single script).  
> `chalk` adds colourful console output.*

---

## 3. The generator script (`generator.js`)

```js
/**
 * generator.js
 * -------------
 * Prompt the user for a CREATE TABLE statement, parse it, and generate:
 *   - Sequelize model
 *   - CRUD controller
 *   - Express router (with auth, validation, security)
 *   - Minimal server bootstrap
 *
 * All files are written to ./generated/
 */

const fs   = require('fs');
const path = require('path');
const readline = require('readline-sync');
const chalk = require('chalk');
const { Parser } = require('node-sql-parser');
const ejs = require('ejs');

// -----------------------------------------------------------------------------
// 1. Ask for the SQL schema
// -----------------------------------------------------------------------------
// User can paste the statement or give a filename
const schemaInput = readline.question(
  chalk.bold('Enter CREATE TABLE SQL (or path to .sql file): ')
);

// -----------------------------------------------------------------------------
// 2. Load the SQL (either string or file)
// -----------------------------------------------------------------------------
let sql;
if (fs.existsSync(schemaInput)) {
  sql = fs.readFileSync(schemaInput, 'utf-8');
} else {
  sql = schemaInput;
}

// -----------------------------------------------------------------------------
// 3. Parse the SQL
// -----------------------------------------------------------------------------
let ast;
try {
  const parser = new Parser();
  ast = parser.astify(sql);
} catch (e) {
  console.error(chalk.red('❌  Failed to parse SQL:'), e.message);
  process.exit(1);
}

// We only support one CREATE TABLE statement
if (!Array.isArray(ast)) ast = [ast];
if (ast.length !== 1 || ast[0].type !== 'create') {
  console.error(chalk.red('❌  Only a single CREATE TABLE statement is supported.'));
  process.exit(1);
}
const createStmt = ast[0];

// -----------------------------------------------------------------------------
// 4. Convert the parsed AST into a plain JS description
// -----------------------------------------------------------------------------
const tableName = createStmt.table[0].table; // e.g. "users"

const columns = createStmt.create_definitions.map(col => {
  const colName = col.column.column;
  // Type mapping: keep the raw type but also convert to Sequelize type later
  const rawType = col.definition.dataType;

  // Constraints
  const constraints = {};
  if (col.definition.nullable === false) constraints.allowNull = false;
  if (col.definition.key === 'PRI') constraints.primaryKey = true;
  if (col.definition.unique) constraints.unique = true;
  if (col.definition.default !== undefined) {
    constraints.defaultValue = col.definition.default;
  }
  return { name: colName, rawType, constraints };
});

const parsed = { tableName, columns };
console.log(chalk.green('\n✅  Parsed table'), tableName);

// -----------------------------------------------------------------------------
// 5. Load the templates (you can replace these with files if you like)
// -----------------------------------------------------------------------------
const tmplDir = path.join(__dirname, 'templates');

const templates = {
  model: fs.readFileSync(path.join(tmplDir, 'model.ejs'), 'utf-8'),
