  package: fs.readFileSync(path.join(tmplDir, 'package.ejs'), 'utf-8'),
};

// -----------------------------------------------------------------------------
// 6. Render the templates
// -----------------------------------------------------------------------------
const context = {
  tableName,
  columns,
  // Utility helpers
  camelCase: str => str.replace(/_([a-z])/g, (_, l) => l.toUpperCase()),
  snakeCase: str => str.replace(/([A-Z])/g, '_$1').toLowerCase(),
  toSequelizeType: type => {
