    const t = type.toLowerCase();
    if (t.includes('int')) return 'Sequelize.INTEGER';
    if (t.includes('char') || t.includes('text')) return 'Sequelize.STRING';
    if (t.includes('bool')) return 'Sequelize.BOOLEAN';
    if (t.includes('date') || t.includes('time')) return 'Sequelize.DATE';
    // Default fallback
