### 4.2 `controller.ejs`

```ejs
/**
 * <%= camelCase(tableName) %>Controller.js
 * ---------------------------------------
 * CRUD controller for <%= tableName %>.
 * Uses Sequelize methods.  Add your own business logic here.
 */

const <%= camelCase(tableName) %> = require('../models/<%= camelCase(tableName) %>');

module.exports = {
  // GET /api/<%= snakeCase(tableName) %>
  async list(req, res, next) {
    try {
      const rows = await <%= camelCase(tableName) %>.findAll();
      res.json(rows);
    } catch (err) { next(err); }
  },

  // GET /api/<%= snakeCase(tableName) %>/:id
  async get(req, res, next) {
    try {
      const row = await <%= camelCase(tableName) %>.findByPk(req.params.id);
      if (!row) return res.status(404).json({ error: 'Not found' });
      res.json(row);
    } catch (err) { next(err); }
  },

  // POST /api/<%= snakeCase(tableName) %>
  async create(req, res, next) {
    try {
      const newRow = await <%= camelCase(tableName) %>.create(req.body);
      res.status(201).json(newRow);
    } catch (err) { next(err); }
  },

  // PUT /api/<%= snakeCase(tableName) %>/:id
  async update(req, res, next) {
    try {
      const [updated] = await <%= camelCase(tableName) %>.update(req.body, {
        where: { id: req.params.id }
      });
      if (!updated) return res.status(404).json({ error: 'Not found' });
      const updatedRow = await <%= camelCase(tableName) %>.findByPk(req.params.id);
      res.json(updatedRow);
    } catch (err) { next(err); }
  },

  // DELETE /api/<%= snakeCase(tableName) %>/:id
  async delete(req, res, next) {
    try {
      const deleted = await <%= camelCase(tableName) %>.destroy({
        where: { id: req.params.id }
      });
      if (!deleted) return res.status(404).json({ error: 'Not found' });
      res.status(204).end();
    } catch (err) { next(err); }
  }
};
