/**
 * auth.js
 * --------
 * Basic JWT authentication using Passport.
 * This example contains a static user for demo purposes.
 * Replace it with a proper user model in production!
 */

const passport = require('passport');
const { Strategy: JwtStrategy, ExtractJwt } = require('passport-jwt');
const jwt = require('jsonwebtoken');
const express = require('express');
const router = express.Router();

// Dummy user (replace with DB lookup)
const user = { id: 1, username: 'admin', password: 'admin' }; // Never store plaintext passwords!

// JWT strategy
passport.use(
  new JwtStrategy(
    {
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      secretOrKey: 'supersecret', // Put in .env in real apps
    },
    (payload, done) => {
      // Here you would normally fetch the user from a DB
      if (payload.sub === user.id) return done(null, user);
      return done(null, false);
    }
  )
);

// Login route
router.post('/login', (req, res) => {
  const { username, password } = req.body;
  if (username === user.username && password === user.password) {
    const token = jwt.sign({ sub: user.id }, 'supersecret', { expiresIn: '1h' });
    return res.json({ token });
  }
  res.status(401).json({ error: 'Invalid credentials' });
});

module.exports = router;
```

