// background.js

// Cache size limit – tweak if you hit Chrome storage quotas
const CACHE_LIMIT = 200;

// Helper: simple LRU cache in chrome.storage.local
async function getCache() {
  return new Promise(resolve => chrome.storage.local.get(['answers'], res => resolve(res.answers || {})));
}
async function setCache(cache) {
  await chrome.storage.local.set({ answers: cache });
}

async function fetchElonAnswer(query) {
  const payload = { query };
  const resp = await fetch('http://localhost:5000/ask', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  if (!resp.ok) {
    throw new Error(`API error: ${resp.status}`);
  }
  const data = await resp.json();
  return data.answer;  // expecting {answer: "..."}
}

chrome.runtime.onMessage.addListener(async (msg, sender, sendResponse) => {
  if (msg.type !== 'ask') return;

  const query = msg.query.trim().toLowerCase();

  // 1️⃣ Check local cache first
  const cache = await getCache();
  if (cache[query]) {
    sendResponse({ answer: cache[query] });
    return;
  }

  try {
    const answer = await fetchElonAnswer(query);

    // 2️⃣ Store in cache (maintain LRU size)
    cache[query] = answer;
    const keys = Object.keys(cache);
    if (keys.length > CACHE_LIMIT) {
      delete cache[keys[0]];  // naive LRU – remove oldest
    }
    await setCache(cache);

    sendResponse({ answer });
  } catch (err) {
    console.error(err);
    sendResponse({ answer: "Sorry, couldn't fetch a response." });
  }
});

/**
 * Context menu item – “Ask Elon Musk”
 */
chrome.contextMenus.create({
  id: 'askElon',
  title: 'Ask Elon Musk',
  contexts: ['selection']
});

chrome.contextMenus.onClicked.addListener((info, tab) => {
  if (info.menuItemId !== 'askElon') return;
  const query = info.selectionText.trim();
  if (!query) return;

  // Send a message to the content script so it can show the tooltip at the right spot
  chrome.tabs.sendMessage(tab.id, { type: 'contextAnswer', query }, async response => {
    // The content script will handle rendering
  });
});
```

