```python
# server/app.py
import os
import json
from flask import Flask, request, jsonify
import openai

app = Flask(__name__)

# Load your OpenAI key from env
openai.api_key = os.getenv("OPENAI_API_KEY")

def ask_musk(query):
    """
    Call OpenAI GPT-4 (or GPT-3.5) with a prompt that asks for Elon Musk’s
    remarks on the supplied topic. The response is trimmed to a short summary.
    """
    prompt = f"""
You are an assistant that only provides what Elon Musk actually said about
the following term or topic.  Respond in a single concise sentence or two.
If no known statement exists, reply with "I don't have a record of Elon Musk
speaking about that."  Do not add extra context or speculation.

Topic: "{query}"
"""

    # You can choose a smaller model if cost is a concern
    response = openai.ChatCompletion.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": prompt}],
        temperature=0.0,
        max_tokens=120,
    )

    answer = response.choices[0].message.content.strip()
    return answer

@app.route('/ask', methods=['POST'])
def ask():
    data = request.get_json()
    if not data or 'query' not in data:
        return jsonify({'error': 'Missing query'}), 400

    query = data['query'].strip()
    if not query:
        return jsonify({'error': 'Empty query'}), 400

    try:
        answer = ask_musk(query)
        return jsonify({'answer': answer})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == "__main__":
    # For local dev: `export OPENAI_API_KEY=sk-...` and run python app.py
    app.run(host="0.0.0.0", port=5000, debug=True)
