</head>
<body>

<header>
  <h1>Weather Forecast</h1>
  <form id="search-form">
    <input id="city-input" type="text" placeholder="Enter city name" required autocomplete="off">
    <button id="search-btn" type="submit">Search</button>
  </form>
</header>

<main>
  <div id="messages"></div>

  <section id="current-weather" style="display:none;">
