  </section>

  <section id="forecast" style="display:none;">
    <!-- cards inserted by JS -->
  </section>
</main>

<script>
/* ----------------------------------------------
   1.  Constants
---------------------------------------------- */
const API_KEY = 'YOUR_API_KEY_HERE';   // <-- put your key here
const CURRENT_URL = 'https://api.openweathermap.org/data/2.5/weather';
const FORECAST_URL = 'https://api.openweathermap.org/data/2.5/forecast';

/* ----------------------------------------------
   2.  DOM Elements
---------------------------------------------- */
const form = document.getElementById('search-form');
const cityInput = document.getElementById('city-input');
const messagesDiv = document.getElementById('messages');
const currentSection = document.getElementById('current-weather');
const forecastSection = document.getElementById('forecast');

const currentIcon = document.getElementById('current-icon');
const currentTemp = document.getElementById('current-temp');
const currentDesc = document.getElementById('current-desc');
const currentHumidity = document.getElementById('current-humidity');
const currentWind = document.getElementById('current-wind');

/* ----------------------------------------------
   3.  Helper Functions
---------------------------------------------- */
function showError(msg) {
  messagesDiv.innerHTML = `<p class="error">${msg}</p>`;
}

function showLoading(msg) {
  messagesDiv.innerHTML = `<p class="loading">${msg}</p>`;
}

function clearMessages() {
  messagesDiv.innerHTML = '';
}

function kelvinToCelsius(k) {
  return (k - 273.15).toFixed(1);
}

function getIconUrl(iconCode) {
  return `https://openweathermap.org/img/wn/${iconCode}@2x.png`;
}

/* ----------------------------------------------
   4.  Fetch Current Weather
---------------------------------------------- */
async function fetchCurrent(city) {
  const url = `${CURRENT_URL}?q=${encodeURIComponent(city)}&appid=${API_KEY}`;
  const resp = await fetch(url);
  if (!resp.ok) throw new Error('City not found');
  return await resp.json();
}

/* ----------------------------------------------
   5.  Fetch 5‑day Forecast
---------------------------------------------- */
async function fetchForecast(city) {
  const url = `${FORECAST_URL}?q=${encodeURIComponent(city)}&appid=${API_KEY}`;
  const resp = await fetch(url);
  if (!resp.ok) throw new Error('Forecast data not available');
  return await resp.json();
}

/* ----------------------------------------------
   6.  Render Current Weather
---------------------------------------------- */
function renderCurrent(data) {
  const { temp } = data.main;
  const { description, icon } = data.weather[0];
  const { humidity } = data.main;
  const { speed } = data.wind;

  currentIcon.src = getIconUrl(icon);
  currentIcon.alt = description;

  currentTemp.textContent = `${kelvinToCelsius(temp)} °C`;
  currentDesc.textContent = description.charAt(0).toUpperCase() + description.slice(1);
  currentHumidity.textContent = `Humidity: ${humidity}%`;
  currentWind.textContent = `Wind: ${speed} m/s`;

  currentSection.style.display = 'block';
}

/* ----------------------------------------------
   7.  Render Forecast
---------------------------------------------- */
function renderForecast(data) {
  forecastSection.innerHTML = ''; // clear previous

  // The API gives data every 3 hours. We pick one entry per day (e.g. the first entry of each day)
  const daily = [];
  const seenDates = new Set();

  for (const item of data.list) {
    const date = item.dt_txt.split(' ')[0];
    if (!seenDates.has(date)) {
      daily.push(item);
      seenDates.add(date);
    }
    if (daily.length === 5) break; // we only need 5 days
  }

  daily.forEach(entry => {
    const card = document.createElement('div');
    card.className = 'forecast-card';

    const dateObj = new Date(entry.dt * 1000);
    const day = dateObj.toLocaleDateString(undefined, { weekday: 'short' });
    const date = dateObj.toLocaleDateString();

    const icon = entry.weather[0].icon;
    const iconUrl = getIconUrl(icon);
    const desc = entry.weather[0].description;
    const tempMin = kelvinToCelsius(entry.main.temp_min);
    const tempMax = kelvinToCelsius(entry.main.temp_max);

    card.innerHTML = `
      <h3>${day} (${date})</h3>
      <img src="${iconUrl}" alt="${desc}">
      <p>${desc.charAt(0).toUpperCase() + desc.slice(1)}</p>
      <p>Min: ${tempMin}°C</p>
      <p>Max: ${tempMax}°C</p>
    `;
    forecastSection.appendChild(card);
  });

  forecastSection.style.display = 'grid';
}

/* ----------------------------------------------
   8.  Main handler
---------------------------------------------- */
async function handleSearch(event) {
  event.preventDefault();
  const city = cityInput.value.trim();
  if (!city) return;

  clearMessages();
  currentSection.style.display = 'none';
  forecastSection.style.display = 'none';

  try {
    showLoading('Fetching data…');
    const [curr, fore] = await Promise.all([
      fetchCurrent(city),
      fetchForecast(city)
    ]);

    clearMessages();
    renderCurrent(curr);
    renderForecast(fore);
  } catch (err) {
    showError(err.message);
  }
}

/* ----------------------------------------------
   9.  Event Listeners
---------------------------------------------- */
form.addEventListener('submit', handleSearch);

/* ----------------------------------------------
   10.  Optional: load default city on page load
---------------------------------------------- */
document.addEventListener('DOMContentLoaded', () => {
  cityInput.value = 'London';  // default city
  form.dispatchEvent(new Event('submit'));
});
</script>
</body>
</html>
```

---

## 3.  How it works

| Step | What happens | Key points |
|------|--------------|------------|
| 1. **User types a city** | The form `submit` event fires. | `preventDefault()` stops the page from reloading. |
| 2. **Show loading message** | `showLoading()` updates the UI. | Gives feedback while network calls are in flight. |
| 3. **Make two API requests** | `fetchCurrent()` & `fetchForecast()` run in parallel via `Promise.all`. | Faster than sequential requests. |
| 4. **Render current weather** | Data is inserted into the “Current” section. | Uses `kelvinToCelsius` for human‑friendly numbers. |
| 5. **Render 5‑day forecast** | Picks one entry per day (first 3‑hour block) and creates cards. | Keeps UI simple while still providing a 5‑day overview. |
| 6. **Show results** | Sections are made visible. | User sees both current weather & forecast. |
| 7. **Error handling** | Any problem (bad city name, network issue) triggers `showError()`. | Friendly message displayed. |

---

## 4.  Customisation & Extension Ideas

| Idea | How to implement |
|------|------------------|
| **Add unit selector (C/F)** | Store user preference in local storage, update `kelvinToCelsius` function accordingly. |
| **Geolocation** | Use `navigator.geolocation` to fetch latitude/longitude and call the “by coordinates” endpoints. |
| **More detailed forecast** | Use the full 3‑hour list and create a horizontal carousel or a table. |
| **Persist search history** | Store last N searches in `localStorage` and show them as buttons. |
| **Dark mode** | Add a toggle that swaps CSS variables. |
| **Map view** | Use Leaflet/OpenStreetMap to display the city’s location. |

---

## 5.  Troubleshooting

| Symptom | Cause & Fix |
|---------|-------------|
| API call fails with `401 Unauthorized` | You didn't put a valid API key or the key is disabled. Check the key in the OpenWeatherMap dashboard. |
| No results even for a known city | The key is blocked or you exceeded the free‑tier limit. Wait or request a higher quota. |
| Images not loading | Network blocked, or the icon URL is wrong. Ensure `https://openweathermap.org/img/wn/...` is reachable. |
| Page appears blank on mobile | CSS breakpoint at `400px` is too aggressive; adjust the media query or remove it. |

---

## 6.  Next steps

1. **Add a proper build process** – Separate CSS, JS, and use a bundler like Webpack/Vite for production.  
2. **Deploy** – Host the file on GitHub Pages, Netlify, Vercel, etc.  
3. **Add unit tests** – Use Jest or a browser‑based test runner to ensure fetch logic works.  

Enjoy building your own weather dashboard! 🚀

