### 1. `search` function (SQL‑based)

```js
// search.js (or the same file)
function search(query = '', role = '', city = '', genre = '', callback) {
  const conditions = [];
  const params = [];

  if (query) {
    conditions.push('(name LIKE ? OR genre LIKE ?)');
    params.push(`%${query}%`, `%${query}%`);
  }
  if (role)   { conditions.push('role = ?');   params.push(role); }
  if (city)   { conditions.push('city LIKE ?'); params.push(`%${city}%`); }
  if (genre)  { conditions.push('genre = ?');  params.push(genre); }

  const sql = `
    SELECT *
    FROM users
    ${conditions.length ? 'WHERE ' + conditions.join(' AND ') : ''}
  `;

  connection.query(sql, params, (err, rows) => callback(err, rows));
}
```

