      role: req.body.role,
      bio: req.body.bio
    };

    const sql = `
      UPDATE users SET
        name = ?, genre = ?, instrument = ?, soundcloud = ?, soundcloud1 = ?,
        soundcloud2 = ?, city = ?, role = ?, bio = ?
      WHERE id = ?
    `;
    const params = [
