```js
app.post("/register", (req, res) => {
  if (req.session.musicianId) {
    return res.redirect('/profile/' + req.session.musicianId);
  }

  const newUser = {
    name:      req.body.name,
    genre:     req.body.genre,
    instrument: req.body.instrument,
    soundcloud: req.body.soundcloud,
    password:  req.body.password,
    role:      req.body.role,
    city:      req.body.city,
    login:     req.body.login
  };

  const sql = `
    INSERT INTO users
      (name, genre, instrument, soundcloud, password, role, city, login)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `;
  const params = [
    newUser.name, newUser.genre, newUser.instrument,
    newUser.soundcloud, newUser.password,
    newUser.role, newUser.city, newUser.login
  ];

  connection.query(sql, params, (err, result) => {
    if (err) {
      res.status(500).send('Error during registration');
      return;
    }

    const id = result.insertId;

    // Thumbnail upload (if any)
    if (req.files && req.files.thumbnail) {
      const file = req.files.thumbnail;
      const filename = `musician_${id}_${file.name}`;
      file.mv('./public/img/' + filename, err => {
        if (!err) {
          connection.query('UPDATE users SET thumbnail = ? WHERE id = ?', [filename, id]);
        }
      });
    }

    req.session.musicianId = id;
    res.redirect('/profile/' + id);
  });
});
