Below is a **complete, copy‑paste‑ready** Node.js/Express API that satisfies the brief:

* **POST /api/newsletter** – accepts `email` (mandatory) and `name` (optional).
* Validates that the email is present and properly formatted.
* Persists the subscriber in MongoDB with Mongoose.
* Returns a JSON payload: `{ success: true }` on success, or `{ success: false, error: "…" }` on failure.

> **⚠️ Note:**  
> - You still need a running MongoDB instance (local or Atlas).  
> - The code uses environment variables for the DB URI (`MONGO_URI`) and the server port (`PORT`).

---

## 1. Project Layout

```
newsletter-api/
├── models/
│   └── Subscriber.js
├── routes/
│   └── newsletter.js
├── .env
├── package.json
└── server.js
```

---

## 2. `package.json`

```json
{
  "name": "newsletter-api",
  "version": "1.0.0",
  "description": "Simple newsletter signup API",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "keywords": [],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "express": "^4.18.2",
    "mongoose": "^8.0.0",
    "dotenv": "^16.0.3"
  },
  "devDependencies": {
    "nodemon": "^3.0.0"
  }
}
```

> Run `npm install` to fetch dependencies.

---

## 3. `.env`

```dotenv
# MongoDB connection string
MONGO_URI=mongodb://localhost:27017/newsletter

# Server listening port
PORT=3000
```

> Replace the `MONGO_URI` value if you’re using Atlas or another host.

---

## 4. Mongoose Model – `models/Subscriber.js`

```js
const mongoose = require('mongoose');

const subscriberSchema = new mongoose.Schema(
  {
    email: {
      type: String,
      required: [true, 'Email is required'],
      unique: true,
      lowercase: true,
      trim: true,
      validate: {
        validator: function (v) {
          // Simple RFC‑5322 compliant regex
          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
        },
        message: props => `${props.value} is not a valid e‑mail address`
      }
    },
    name: {
      type: String,
      trim: true,
      default: null
    }
  },
  { timestamps: true }
);

module.exports = mongoose.model('Subscriber', subscriberSchema);
```

*The `email` field is **unique** – duplicate addresses will result in a 409 Conflict.*

---

## 5. Route Handler – `routes/newsletter.js`

```js
const express = require('express');
const router = express.Router();
const Subscriber = require('../models/Subscriber');

// POST /api/newsletter
router.post('/', async (req, res) => {
  const { email, name } = req.body;

  // 1️⃣ Basic presence & format validation
  if (!email || typeof email !== 'string') {
    return res.status(400).json({
      success: false,
      error: 'Email is required and must be a string'
    });
  }

  // 2️⃣ Create document instance
  const newSubscriber = new Subscriber({ email, name });

  try {
    await newSubscriber.save();
    // 3️⃣ Success response
    return res.status(201).json({ success: true });
  } catch (err) {
    // 4️⃣ Handle duplicate key (email already exists)
    if (err.code === 11000) {
      return res.status(409).json({
        success: false,
        error: 'This email is already subscribed'
      });
    }
    // 5️⃣ Validation errors
    if (err.name === 'ValidationError') {
      const messages = Object.values(err.errors).map(e => e.message);
      return res.status(400).json({ success: false, error: messages.join('. ') });
    }
    // 6️⃣ Unexpected server error
    console.error(err);
    return res.status(500).json({ success: false, error: 'Internal server error' });
  }
});

module.exports = router;
```

---

## 6. Main Server – `server.js`

```js
require('dotenv').config();           // Load .env

const express = require('express');
const mongoose = require('mongoose');

const newsletterRouter = require('./routes/newsletter');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(express.json());              // Parse JSON bodies

// Routes
app.use('/api/newsletter', newsletterRouter);

// Health‑check endpoint
app.get('/', (_req, res) => res.send('Newsletter API is running.'));

// MongoDB connection + server start
mongoose
  .connect(process.env.MONGO_URI, {
    useNewUrlParser: true,
    useUnifiedTopology: true
  })
  .then(() => {
    console.log('✅ Connected to MongoDB');
    app.listen(PORT, () => {
      console.log(`🚀 Server listening on http://localhost:${PORT}`);
    });
  })
  .catch(err => {
    console.error('❌ MongoDB connection error:', err);
  });
```

