```js
/* ---------- Leaderboard helpers ---------- */
const LEADERBOARD_KEY = 'sobics_leaderboard';
const MAX_ENTRIES   = 10;            // Show only top 10

/**
 * Load the leaderboard from localStorage.
 * Returns an array of objects: [{name, score}, ...]
 */
function loadLeaderboard() {
  const raw = localStorage.getItem(LEADERBOARD_KEY);
  return raw ? JSON.parse(raw) : [];
}

/**
 * Save the whole leaderboard array to localStorage.
 */
function saveLeaderboard(list) {
  localStorage.setItem(LEADERBOARD_KEY, JSON.stringify(list));
}

/**
 * Insert a new score, keep top MAX_ENTRIES sorted descending.
 */
function addScoreToLeaderboard(name, score) {
  const list = loadLeaderboard();
  list.push({ name, score });
  list.sort((a,b) => b.score - a.score);
  if (list.length > MAX_ENTRIES) list.pop();
  saveLeaderboard(list);
  renderLeaderboard();
}

/**
 * Render the ordered list in the modal.
 */
function renderLeaderboard() {
  const ol = document.getElementById('leaderboard-list');
  const list = loadLeaderboard();
  ol.innerHTML = '';
  list.forEach((entry, idx) => {
    const li = document.createElement('li');
    li.textContent = `${idx+1}. ${entry.name} – ${entry.score}`;
    ol.appendChild(li);
  });
}

/**
 * Create a text file blob and trigger download.
 */
function downloadLeaderboard() {
  const list = loadLeaderboard();
  const lines = ['Leaderboard', '============'];
  list.forEach((e,i)=>lines.push(`${i+1}. ${e.name} – ${e.score}`));
  const blob = new Blob([lines.join('\n')], {type: 'text/plain'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'leaderboard.txt';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

/* ---------- Modal helpers ---------- */
function showModal(finalScore) {
  document.getElementById('final-score').textContent = finalScore;
  document.getElementById('score-modal').classList.remove('hidden');
  renderLeaderboard();
}

function hideModal() {
  document.getElementById('score-modal').classList.add('hidden');
}

/* ---------- Wire up the modal buttons ---------- */
document.getElementById('save-score-btn').addEventListener('click', () => {
  const nameInput = document.getElementById('player-name');
  const name = nameInput.value.trim();
  if (!name) { alert('Please enter a name'); return; }
  const score = parseInt(document.getElementById('final-score').textContent, 10);
  addScoreToLeaderboard(name, score);
  nameInput.value = '';      // reset for next game
});

document.getElementById('download-leaderboard-btn')
        .addEventListener('click', downloadLeaderboard);

document.getElementById('close-modal-btn')
        .addEventListener('click', hideModal);
```

