const db = require('../config/database');
const { hashPassword, comparePassword } = require('../utils/password');

class User {
  /** Создаёт нового пользователя (перед хешированием пароля) */
  static async create({ email, password }) {
    const hashed = await hashPassword(password);
    return new Promise((resolve, reject) => {
      const sql = 'INSERT INTO users (email, password) VALUES (?, ?)';
      const params = [email, hashed];
      db.run(sql, params, function (err) { // this refers to the statement
        if (err) return reject(err);
        resolve({ id: this.lastID, email }); // возвращаем id и email
      });
    });
  }

  /** Ищем пользователя по email */
  static async findByEmail(email) {
    return new Promise((resolve, reject) => {
      const sql = 'SELECT * FROM users WHERE email = ?';
      db.get(sql, [email], (err, row) => {
        if (err) return reject(err);
        resolve(row); // null, если не найден
      });
    });
  }

  /** Проверка пароля */
  static async validateCredentials(email, password) {
    const user = await User.findByEmail(email);
    if (!user) return null;
    const valid = await comparePassword(password, user.password);
    return valid ? user : null;
  }
}

module.exports = User;
