```js
const jwt = require('jsonwebtoken');
const JWT_SECRET = process.env.JWT_SECRET || 'very-secret-key';

module.exports = function (req, res, next) {
  const authHeader = req.headers['authorization']; // Bearer <token>
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Токен не предоставлен' });

  jwt.verify(token, JWT_SECRET, (err, payload) => {
    if (err) return res.status(403).json({ error: 'Токен недействителен' });

    // payload содержит sub, email, exp и т.д.
    req.user = payload; // можно добавить более подробную информацию, если нужно
    next();
  });
};
```

