Below is a **single‑file** example that shows how to build a simple *Markup Calculator* with HTML, CSS, and JavaScript.  
The results are displayed in a **bar chart** using the **Chart.js** library (loaded from a CDN).

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Markup Calculator</title>
  <!-- Chart.js CDN -->
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
  <style>
    body {font-family: Arial, sans-serif; margin: 20px; background:#f4f4f4;}
    .calculator {max-width: 500px; margin: auto; background:#fff; padding: 20px; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,.1);}
    .input-group {margin-bottom: 15px;}
    label {display: block; margin-bottom: 5px;}
    input[type="number"] {width: 100%; padding: 8px; box-sizing: border-box; border: 1px solid #ccc; border-radius: 4px;}
    #calculateBtn {padding: 10px 20px; cursor: pointer; background:#28a745; color:#fff; border:none; border-radius: 4px;}
    #calculateBtn:hover {background:#218838;}
    #results {margin-top: 20px;}
    #results table {width:100%; border-collapse: collapse;}
    #results td {padding: 8px 5px; border-bottom: 1px solid #eee;}
    #chartContainer {margin-top: 30px; width: 100%; max-width: 600px;}
  </style>
</head>
<body>

<div class="calculator">
  <h1>Markup Calculator</h1>

  <div class="input-group">
    <label for="costPrice">Cost Price ($)</label>
    <input type="number" id="costPrice" placeholder="e.g. 50.00" min="0" step="0.01">
  </div>

  <div class="input-group">
    <label for="markup">Markup (%)</label>
    <input type="number" id="markup" placeholder="e.g. 25" min="0" max="100" step="0.01">
  </div>

  <button id="calculateBtn">Calculate</button>

  <div id="results"></div>

  <div id="chartContainer">
    <canvas id="priceChart"></canvas>
  </div>
</div>

<script>
  /* Grab DOM elements */
  const costInput   = document.getElementById('costPrice');
  const markupInput = document.getElementById('markup');
  const calcBtn     = document.getElementById('calculateBtn');
  const resultsDiv  = document.getElementById('results');
  const ctx         = document.getElementById('priceChart').getContext('2d');

  let priceChart; // Chart instance

  /* ---------- Calculation logic ---------- */
  function calculateValues(cost, markupPercent) {
    const costVal   = parseFloat(cost);
    const markupVal = parseFloat(markupPercent);

    const sellingPrice        = costVal * (1 + markupVal / 100);
    const profit              = sellingPrice - costVal;
    const profitMarginPercent = (profit / sellingPrice) * 100;

    return {
      cost: costVal,
      markup: markupVal,
      sellingPrice,
      profit,
      profitMarginPercent
    };
  }

  /* ---------- UI rendering ---------- */
  function displayResults(vals) {
    resultsDiv.innerHTML = `
      <table>
        <tr><td>Cost Price</td><td>$${vals.cost.toFixed(2)}</td></tr>
        <tr><td>Markup</td><td>${vals.markup.toFixed(2)}%</td></tr>
        <tr><td>Selling Price</td><td>$${vals.sellingPrice.toFixed(2)}</td></tr>
        <tr><td>Profit</td><td>$${vals.profit.toFixed(2)}</td></tr>
        <tr><td>Profit Margin</td><td>${vals.profitMarginPercent.toFixed(2)}%</td></tr>
      </table>
    `;
  }

  function updateChart(vals) {
    const chartData = {
      labels: ['Cost', 'Selling', 'Profit'],
      datasets: [{
        label: 'Amount ($)',
        data: [vals.cost, vals.sellingPrice, vals.profit],
        backgroundColor: ['#36a2eb', '#ff6384', '#ffce56']
      }]
    };

    const options = {
      responsive: true,
      scales: { y: { beginAtZero: true } }
    };

    if (priceChart) {
      priceChart.data = chartData;
      priceChart.update();
    } else {
      priceChart = new Chart(ctx, {
        type: 'bar',
        data: chartData,
        options
      });
    }
  }

  /* ---------- Event listener ---------- */
  calcBtn.addEventListener('click', () => {
    const cost   = costInput.value.trim();
    const markup = markupInput.value.trim();

    if (cost === '' || markup === '') {
      alert('Please enter both cost and markup values.');
      return;
    }

    const vals = calculateValues(cost, markup);
    displayResults(vals);
    updateChart(vals);
  });
</script>

</body>
</html>
```

### How it works

1. **Inputs** – User enters *Cost Price* and *Markup %*.  
2. **Calculate** – Clicking **Calculate** triggers a JavaScript function that:
   * Computes the selling price (`cost * (1 + markup/100)`).
   * Calculates profit (`selling - cost`) and profit margin percent.  
3. **Results** – A small table shows the numeric outputs.  
4. **Chart** – A bar chart (Chart.js) visualizes Cost, Selling, and Profit.  
   * The chart updates each time you click “Calculate”.  

Feel free to expand the calculator (e.g., add quantity, tax, multiple items, or different chart types). All libraries used are lightweight and free. Happy coding!

