// -------------------------------------------------------
// 1. Firebase initialization
// -------------------------------------------------------
const firebaseConfig = {
  apiKey: "YOUR-API-KEY",
  authDomain: "YOUR-PROJECT.firebaseapp.com",
  projectId: "YOUR-PROJECT-ID",
  // Optional: add storageBucket, messagingSenderId, appId if you use them
};

firebase.initializeApp(firebaseConfig);
const auth = firebase.auth();
const db = firebase.firestore();

// -------------------------------------------------------
// 2. DOM elements
// -------------------------------------------------------
const signInBtn = document.getElementById('sign-in-btn');
const signOutBtn = document.getElementById('sign-out-btn');
const userInfoDiv = document.getElementById('user-info');
const signInBtnWrapper = document.getElementById('sign-in-btn-wrapper');
const orderSection = document.getElementById('order-section');
const orderForm = document.getElementById('order-form');
const orderStatus = document.getElementById('order-status');

// -------------------------------------------------------
// 3. Authentication helpers
// -------------------------------------------------------
const provider = new firebase.auth.GoogleAuthProvider();

signInBtn.addEventListener('click', () => {
  auth.signInWithPopup(provider).catch(err => {
    console.error('Sign‑in error', err);
    alert('Failed to sign in. Please try again.');
  });
});

signOutBtn.addEventListener('click', () => {
  auth.signOut();
});

auth.onAuthStateChanged(user => {
  if (user) {
    // User signed in
    signInBtnWrapper.classList.add('hidden');
    userInfoDiv.classList.remove('hidden');
    document.getElementById('user-name').textContent = user.displayName;
    document.getElementById('user-email').textContent = user.email;
    orderSection.classList.remove('hidden');
  } else {
    // User signed out
    signInBtnWrapper.classList.remove('hidden');
    userInfoDiv.classList.add('hidden');
    orderSection.classList.add('hidden');
  }
  orderStatus.textContent = ''; // clear any old status
});

// -------------------------------------------------------
// 4. Order form handling
// -------------------------------------------------------
orderForm.addEventListener('submit', async (e) => {
  e.preventDefault();

  const dish = document.getElementById('dish').value;
  const quantity = parseInt(document.getElementById('quantity').value, 10);
  const comments = document.getElementById('comments').value.trim();

  const user = auth.currentUser;
  if (!user) {
    alert('You must be signed in to place an order.');
    return;
  }

  // Simple client‑side validation
  if (!dish || quantity < 1) {
    alert('Please fill out the form correctly.');
    return;
  }

  // Disable button to prevent double‑click
  const submitBtn = orderForm.querySelector('button[type="submit"]');
  submitBtn.disabled = true;
  submitBtn.textContent = 'Placing…';

  try {
    await db.collection('orders').add({
      userId: user.uid,
      userName: user.displayName,
      userEmail: user.email,
      dish,
      quantity,
      comments,
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    });

    orderStatus.textContent = '✅ Order placed successfully!';
    orderForm.reset(); // clear form
  } catch (err) {
    console.error('Order error', err);
    orderStatus.textContent = '❌ Failed to place order. Try again.';
  } finally {
    submitBtn.disabled = false;
    submitBtn.textContent = 'Place Order';
  }
});
