Below is a **single‑file** implementation of a classic Snake game that runs directly in any modern browser.  
Just copy the code into a file named `snake.html` and open it – no libraries, no build steps.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake – vanilla JS</title>
<style>
  body { margin:0; display:flex; justify-content:center; align-items:center; height:100vh; background:#222; font-family:Arial,Helvetica,sans-serif; color:#eee;}
  canvas { background:#111; display:block; }
  #info { text-align:center; margin-top:10px; }
  #score { font-size:1.2em; }
</style>
</head>
<body>
<canvas id="gameCanvas" width="400" height="400"></canvas>
<div id="info">
  <div id="score">Score: 0</div>
  <div>Use arrow keys to move. Press Space to restart after game over.</div>
</div>

<script>
/*======================================================================
  Snake – minimal vanilla‑JS implementation
  ======================================================*/

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');

const canvasSize = 400;          // canvas width / height
const cellSize = 20;             // pixel size of one cell
const rows = canvasSize / cellSize;
const cols = canvasSize / cellSize;

let snake = [{x: 9, y: 9}];      // start in center (9,9)
let dir = {x: 0, y: -1};         // initial direction: up
let food = null;
let interval = null;
let gameOver = false;
let score = 0;

// ------------------------------------------------------------
// Helper functions
// ------------------------------------------------------------
function randomCell() {
    return {
        x: Math.floor(Math.random() * cols),
        y: Math.floor(Math.random() * rows)
    };
}

function placeFood() {
    do { food = randomCell(); }
    while (snake.some(s => s.x === food.x && s.y === food.y));
}

function drawCell(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
}

function draw() {
    ctx.clearRect(0, 0, canvasSize, canvasSize);

    // draw food
    drawCell(food.x, food.y, '#ff0');

    // draw snake
    snake.forEach((segment, index) => {
        drawCell(segment.x, segment.y, index === 0 ? '#0f0' : '#0c0');
    });
}

function moveSnake() {
    // compute new head
    const newHead = {
        x: (snake[0].x + dir.x + cols) % cols,
        y: (snake[0].y + dir.y + rows) % rows
    };

    // collision with self?
    if (snake.some(seg => seg.x === newHead.x && seg.y === newHead.y)) {
        endGame();
        return;
    }

    snake.unshift(newHead);

    // eating food?
    if (newHead.x === food.x && newHead.y === food.y) {
        score += 1;
        scoreEl.textContent = `Score: ${score}`;
        placeFood();
    } else {
        snake.pop(); // remove tail
    }
}

function endGame() {
    clearInterval(interval);
    gameOver = true;
    alert(`Game over! Your score: ${score}\nPress Space to restart.`);
}

function restartGame() {
    snake = [{x: 9, y: 9}];
    dir = {x: 0, y: -1};
    score = 0;
    scoreEl.textContent = `Score: ${score}`;
    gameOver = false;
    placeFood();
    interval = setInterval(() => { moveSnake(); draw(); }, 150);
}

// ------------------------------------------------------------
// Event handling
// ------------------------------------------------------------
document.addEventListener('keydown', e => {
    if (gameOver && e.key === ' ') { restartGame(); return; }

    switch (e.key) {
        case 'ArrowUp':
        case 'w':
            if (dir.y !== 1) dir = {x:0, y:-1};
            break;
        case 'ArrowDown':
        case 's':
            if (dir.y !== -1) dir = {x:0, y:1};
            break;
        case 'ArrowLeft':
        case 'a':
            if (dir.x !== 1) dir = {x:-1, y:0};
            break;
        case 'ArrowRight':
        case 'd':
            if (dir.x !== -1) dir = {x:1, y:0};
            break;
    }
});

// ------------------------------------------------------------
// Start the game
// ------------------------------------------------------------
restartGame();
</script>
</body>
</html>
```

### How it works

1. **Grid** – The canvas is 400×400px, divided into 20×20 pixel cells (`cellSize = 20`).  
   Snake and food positions are stored as `{x, y}` coordinates on this grid.

2. **Snake movement** – Every 150 ms (`setInterval`) the snake:
   - Computes a new head based on the current direction.
   - Wraps around the edges (the classic “infinite” board).
   - Checks for self‑collision.
   - Adds the new head, and removes the tail unless a food cell was eaten.

3. **Food** – Placed randomly in an empty cell. When eaten the score increases and new food appears.

4. **Input** – Arrow keys (or WASD) change the snake’s direction, but the snake can’t reverse onto itself.

5. **Game over** – When the snake collides with itself a `clearInterval` stops the loop and a prompt shows the final score.  
   Press the space bar to restart.

Feel free to tweak the speed (`setInterval` delay), grid size, or colors to your liking. Enjoy!

