## 4. script.js

```js
/* ===== المتغيرات ===== */
const gameArea  = document.getElementById('gameArea');
const paddle    = document.getElementById('paddle');
const ball      = document.getElementById('ball');
const scoreEl   = document.getElementById('score');
const missesEl  = document.getElementById('misses');
const messageEl = document.getElementById('message');

let score   = 0;
let misses  = 0;
const maxMisses = 5;

// أبعاد اللعبة
const areaWidth  = gameArea.clientWidth;
const areaHeight = gameArea.clientHeight;

// سرعة سقوط الكرة
const fallSpeed = 2000; // 2 ثانية للوصول من الأعلى إلى الأسفل

// سرعة تحريك المقابض
const paddleSpeed = 7; // pixels per key press

/* ===== تحريك المقابض ===== */
document.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') {
        movePaddle(-paddleSpeed);
    } else if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') {
        movePaddle(paddleSpeed);
    }
});

function movePaddle(dx) {
    const currentLeft = paddle.offsetLeft;
    let newLeft = currentLeft + dx;
    // منع خروج المقابض عن حدود اللعبة
    if (newLeft < 0) newLeft = 0;
    if (newLeft + paddle.offsetWidth > areaWidth)
        newLeft = areaWidth - paddle.offsetWidth;
    paddle.style.left = newLeft + 'px';
}

/* ===== إطلاق الكرة ===== */
function launchBall() {
    // إخفاء أي كرة سابقة
    ball.style.display = 'none';
    ball.style.left = (Math.random() * (areaWidth - 20)) + 'px';
    ball.style.top = '-20px';
    ball.style.display = 'block';

    // بدء الحركة باستخدام requestAnimationFrame
    const startTime = performance.now();
    function animate(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / fallSpeed, 1);
        const y = progress * areaHeight;
        ball.style.top = y + 'px';

        // إذا وصلت الكرة إلى القاع
        if (progress === 1) {
            // هل صادفت المقابض؟
            if (isCaught()) {
                score++;
                scoreEl.textContent = score;
                messageEl.textContent = '✓ قبضت!';
            } else {
                misses++;
                missesEl.textContent = misses;
                messageEl.textContent = '✘ ضاعت!';
                if (misses >= maxMisses) {
                    endGame();
                    return;
                }
            }
            // إطلاق كرة جديدة بعد ثانية قصيرة
            setTimeout(launchBall, 1000);
        } else {
            requestAnimationFrame(animate);
        }
    }
    requestAnimationFrame(animate);
}

/* ===== فحص التصادم ===== */
function isCaught() {
    const ballRect = ball.getBoundingClientRect();
    const paddleRect = paddle.getBoundingClientRect();

    // مقارنة المواقع
    return (
        ballRect.bottom >= paddleRect.top &&
        ballRect.right >= paddleRect.left &&
        ballRect.left <= paddleRect.right
    );
}

/* ===== إنهاء اللعبة ===== */
function endGame() {
    messageEl.textContent = `انتهى! النقاط: ${score}`;
    // إيقاف الكرة
    ball.style.display = 'none';
    // تعطيل تحريك المقابض
    document.removeEventListener('keydown', keyHandler);
}

/* ===== بدء اللعبة ===== */
launchBall();
