## 4. `src/index.js` (ES‑module / UMD)

```js
/* eslint-disable no-console */
const { fromEvent, BehaviorSubject } = rxjs;
const { ajax } = rxjs.ajax;
const { tap, switchMap } = rxjs.operators;

// Элементы DOM
const btnShow   = document.getElementById('btnShow');
const btnDelete = document.getElementById('btnDelete');
const container = document.getElementById('dataContainer');

// Хранилище данных (Observable)
const data$ = new BehaviorSubject([]);   // начальное значение – пустой массив

/* ---------------------- 1. Показать данные ---------------------- */
fromEvent(btnShow, 'click')
  .pipe(
    // 1) Запрос к серверу
    switchMap(() => ajax.getJSON('src/data.json')),
    // 2) Обновляем BehaviorSubject
    tap(json => data$.next(json))
  )
  .subscribe();

/* ---------------------- 2. Удалить последнюю строку ---------------------- */
fromEvent(btnDelete, 'click')
  .pipe(
    tap(() => {
      const current = data$.value;          // текущее значение
      if (current.length > 0) {
        data$.next(current.slice(0, -1));   // отбрасываем последний элемент
      }
    })
  )
  .subscribe();

/* ---------------------- 3. Рендер таблицы ---------------------- */
data$.subscribe(data => {
  renderTable(data);
});

/* ---------------------- 4. Функция рендера ---------------------- */
function renderTable(data) {
  container.innerHTML = '';   // очищаем контейнер

  if (data.length === 0) {
    container.textContent = 'Нет данных';
    return;
  }

  const table  = document.createElement('table');
  const thead  = document.createElement('thead');
  const tbody  = document.createElement('tbody');

  /* Заголовки – ключи первого объекта */
  const headerRow = document.createElement('tr');
  Object.keys(data[0]).forEach(key => {
    const th = document.createElement('th');
    th.textContent = key;
    headerRow.appendChild(th);
  });
  thead.appendChild(headerRow);

  /* Строки таблицы */
  data.forEach(item => {
    const row = document.createElement('tr');
    Object.values(item).forEach(value => {
      const td = document.createElement('td');
      td.textContent = value;
      row.appendChild(td);
    });
    tbody.appendChild(row);
  });

  table.appendChild(thead);
  table.appendChild(tbody);
  container.appendChild(table);
}
```

### Что делает код

| Шаг | Что происходит |
|-----|----------------|
| **1.** | `fromEvent(btnShow, 'click')` создаёт поток кликов. |
| **2.** | `switchMap` → `ajax.getJSON('src/data.json')` → поток JSON. |
| **3.** | `tap(json => data$.next(json))` – сохраняем массив в `BehaviorSubject`. |
| **4.** | `fromEvent(btnDelete, 'click')` → `tap` → берём `data$.value`, отбрасываем последний элемент и вызываем `data$.next(newArray)`. |
| **5.** | `data$.subscribe(renderTable)` – любая смена данных приводит к перерисовке. |
| **6.** | `renderTable` формирует `<table>` из массива объектов. |

> Если хотите **не использовать** таблицу, просто замените `renderTable` на любой другой способ вывода – список, карточки и т.д.

## 5. Как запустить

1. **Скопируйте** приведённые файлы в ваш проект.  
2. **Добавьте** файл `data.json` в `src/`. Например:

```json
[
  { "id": 1, "name": "Alice", "age": 28 },
  { "id": 2, "name": "Bob",   "age": 34 },
  { "id": 3, "name": "Carol", "age": 22 }
