// ---------------------------------------------------------------------------
// Next button logic ---------------------------------------------------------
const nextButton = document.createElement("button");
nextButton.id = "nextButton";
nextButton.textContent = "Next";
nextButton.className = "nextbutton";

nextButton.addEventListener('click', () => {
  imageIndex++;          // move to the next picture

