    parentDiv.innerHTML = chosenColor
        ? `You bet on ${chosenColor} $${purse}`
        : "Please choose a color to bet on.";

    /* Add Start Race button */
    const startRaceButton = document.createElement('button');
    startRaceButton.textContent = "Start Race";
    startRaceButton.onclick = handleButtonClick;   // no inline `onclick` string
    parentDiv.appendChild(startRaceButton);
