/* --------------  ANIMATION -------------- */
function animate(marker, coords, index, markerName) {
    /* ... animation logic ... */

    if (progress >= 1) {
        index++;
        if (index < coords.length - 1) {
            setTimeout(() => animate(marker, coords, index, markerName), 500);
        } else if (!winnerDeclared) {
