### Um‑Schreiben als **Vue 3 Composition‑API‑Modul**

```js
// src/composables/useQueue.js
import { reactive, toRefs, inject } from 'vue';

/**
 * useQueue
 * ----------
 * Ein re‑usable „Queue“‑Composable, der die gleichen
 * Funktionalitäten wie deine Klasse hat, aber in der
 * Composition‑API auspackt.
 *
 *  * `eventBus`   → wird über `inject('eventbus')` geladen
 *  * `config`     → (optional) kann über `inject('config')` geladen werden
 *
 *  Die Instanz ist **singleton‑artig**: jedes
 *  Aufrufen von `useQueue()` liefert die gleiche reaktive
 *  Instanz – genau wie `new Queue()` in deinem Original‑Code.
 */
export default function useQueue() {
  // ------------------------------------------------------------------
  // 1. Abhängigkeiten holen
  // ------------------------------------------------------------------
  const eventBus = inject('eventbus'); // muss im Parent‑Provider definiert sein
  const config   = inject('config');   // optional – falls du `$config` brauchst

  // ------------------------------------------------------------------
  // 2. Reaktive State‑Definition
  // ------------------------------------------------------------------
  const state = reactive({
    items: [],
    queueRunning: false,
  });

  // ------------------------------------------------------------------
  // 3. Methoden – identisch zu deiner Klassen‑Implementation
  // ------------------------------------------------------------------
  const isEmpty = () => state.items.length === 0;

  const addToQueue = (item) => {
    item.fromQueue = true;
    item.step      = 3;
    state.items.push(item);

    console.log(
      'Queue: adding item to queue:',
      state.items.length,
      'queueRunning:',
      state.queueRunning,
      state.items
    );

    if (!state.queueRunning) {
      console.log(
        'Queue: added To Queue, start play cause queue is running',
        'queueRunning:',
        state.queueRunning
      );
      playQueued();
    }
  };

  const playQueued = () => {
    state.queueRunning = true;

    console.log('Queue: playQueued, queue length is:', state.items.length);

    const item = state.items.shift(); // FIFO
    item.step = 4;

    console.log('Queue: playQueued trigger eventBus', item.type, item);
    eventBus.emit(item.type, item);
  };

  const playQueuedEnded = (event) => {
    event.target.removeEventListener('ended', playQueuedEnded, true);

    if (isEmpty()) {
      state.queueRunning = false;
      console.log(
        'Queue: playQueuedEnded no more entries in queue:',
        state.items.length,
        state.queueRunning
      );
    } else {
      console.log(
        'Queue: playQueuedEnded item ended, remaining items:',
        state.items.length,
        state.queueRunning
      );

      // Zeit‑Verzögerung zwischen den Queue‑Items
      console.log(
        'Queue: setting timer for next run:',
        config?.settings?.alerts?.queueTimeDistance
      );
      window.setTimeout(
        playQueued,
        config?.settings?.alerts?.queueTimeDistance ?? 2000
      ); // default 2 s falls keine Config vorhanden
    }
  };

  // ------------------------------------------------------------------
  // 4. Expose – reaktive Properties + Methoden
  // ------------------------------------------------------------------
  return {
    // reactive refs for direct use in templates
    ...toRefs(state),

    // Methods
    isEmpty,
    addToQueue,
    playQueued,
    playQueuedEnded,
  };
}
```

---

## Wie benutzt du das?

```vue
<script setup>
import useQueue from '@/composables/useQueue.js';

const { items, queueRunning, addToQueue } = useQueue();

/* Beispiel‑Aufruf – z. B. nach einem Button‑Click */
function enqueue() {
  const newItem = {
    type: 'play',
    data: { /* … */ },
  };
  addToQueue(newItem);
}
