```js
// ───────────────────────────────────────────────────────────────────────────────
//  ws-client.js – A tiny ES‑module that handles the WebSocket chat
// ───────────────────────────────────────────────────────────────────────────────

import { getPublicIP } from './utils.js';   // optional – see below

// ---------- DOM ----------
const loginDiv = document.getElementById('login');
const chatDiv  = document.getElementById('chat');
const nameInp  = document.getElementById('name');
const connectBtn = document.getElementById('connectBtn');
const disconnectBtn = document.getElementById('disconnectBtn');
const userInfoSpan  = document.getElementById('userInfo');
const chatLog  = document.getElementById('chatLog');
const msgInput = document.getElementById('msgInput');
const sendBtn  = document.getElementById('sendBtn');
const fileInput  = document.getElementById('fileInput');
const sendFileBtn = document.getElementById('sendFileBtn');

// ---------- State ----------
let ws;
let localName = '';
let publicIP = null;

// ---------- Helpers ----------
function log(text) {
  chatLog.value += text + '\n';
  chatLog.scrollTop = chatLog.scrollHeight;
}

// ---------- Public IP lookup ----------
async function fetchIP() {
  try {
    const res = await fetch('https://api.ipify.org?format=json');
    const data = await res.json();
    return data.ip;
  } catch (e) {
    console.warn('IP lookup failed', e);
    return 'unknown';
  }
}

// ---------- WebSocket ----------
function initSocket() {
  const url = new URL(window.location);
  // switch ws:// or wss:// depending on page protocol
  url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
  url.port = '3000';
  ws = new WebSocket(url.toString());
  ws.binaryType = 'arraybuffer';   // we’ll receive blobs

  ws.onopen = () => {
    log('🟢 Connected');
  };

  ws.onmessage = (ev) => {
    // Binary → Blob
    if (ev.data instanceof ArrayBuffer) {
      const headerStr = readHeader(ev.data);
      const header = JSON.parse(headerStr);
      const fileBuffer = ev.data.slice(headerStr.length); // skip header
      const blob = new Blob([fileBuffer]);

      if (header.type === 'file') {
        displayFile(blob, header.fileName);
      }
    } else {
      // Text (JSON)
      const msg = JSON.parse(ev.data);
      if (msg.type === 'text') {
        const ts = new Date(msg.ts).toLocaleTimeString();
        log(`[${ts}] ${msg.user}@${msg.fromIP}: ${msg.text}`);
      }
    }
  };

  ws.onclose = () => {
    log('🔴 Disconnected');
    toggleUI(false);
  };

  ws.onerror = (err) => {
    console.error(err);
    log('❌ Error occurred – see console');
  };
}

function readHeader(buffer) {
  // Header is JSON + null terminator '\0'
  const decoder = new TextDecoder();
  const view = new Uint8Array(buffer);
  let i = 0;
  while (view[i] !== 0) i++;
  return decoder.decode(buffer.slice(0, i));
}

function displayFile(blob, fileName) {
  // For images we embed them, for others we offer download
  const url = URL.createObjectURL(blob);
  if (blob.type.startsWith('image/')) {
    const img = new Image();
    img.src = url;
    img.style.maxWidth = '200px';
    img.style.display = 'block';
    chatLog.value += '\n[Image] ' + fileName + '\n';
    document.body.appendChild(img);
  } else {
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName || 'download';
    a.textContent = `[Download] ${fileName}`;
    chatLog.value += '\n' + a.outerHTML + '\n';
    document.body.appendChild(a);
  }
  // Revoke after a bit
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

// ---------- UI ----------
function toggleUI(isConnected) {
  loginDiv.style.display = isConnected ? 'none' : 'block';
  chatDiv.style.display  = isConnected ? 'block' : 'none';
  if (isConnected) userInfoSpan.textContent = `🧑 ${localName}`;
}

connectBtn.addEventListener('click', async () => {
  localName = nameInp.value.trim();
  if (!localName) { alert('Name required'); return; }

  publicIP = await fetchIP();
  initSocket();
  toggleUI(true);
});

disconnectBtn.addEventListener('click', () => {
  if (ws) ws.close();
});

sendBtn.addEventListener('click', () => {
  const txt = msgInput.value.trim();
  if (!txt) return;
  if (ws && ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify({
      type: 'text',
      user: localName,
      text: txt
    }));
    msgInput.value = '';
  } else {
    alert('Not connected');
  }
});

sendFileBtn.addEventListener('click', () => {
  const file = fileInput.files[0];
  if (!file) { alert('Select a file'); return; }
  if (!ws || ws.readyState !== WebSocket.OPEN) { alert('Not connected'); return; }

  // Send a header first, then the binary data
  const header = {
    type: 'file',
    fileName: file.name
  };
  const headerBuf = new TextEncoder().encode(JSON.stringify(header) + '\0');
  const reader = new FileReader();
  reader.onload = () => {
    const dataBuf = new Uint8Array(reader.result);
    // Concatenate header + data
    const packet = new Uint8Array(headerBuf.length + dataBuf.length);
    packet.set(headerBuf, 0);
    packet.set(dataBuf, headerBuf.length);
    ws.send(packet);
  };
  reader.readAsArrayBuffer(file);
});
```

