  return `
You are a radiology education AI. Generate a quiz for residents.

- **Board**: ${board}
- **Question type**: ${type}
- **Difficulty**: ${difficulty}
- **Number of questions**: ${num}
- **Additional context**: ${context}

Output format:
1. Question 1 (include stem, 4 options [A‑D], correct answer letter)
2. Question 2 …
3. ...
Provide the full list without markdown.`;
};

// ---------- Route ----------
app.post('/api/generate', async (req, res) => {
  const { board, type, difficulty, num, context } = req.body;

  // Basic validation
  if (!board || !type || !difficulty || !num) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const prompt = buildPrompt({ board, type, difficulty, num, context });

  try {
    const openaiResponse = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: 'gpt-3.5-turbo',
        temperature: 0.7,
        max_tokens: 1500,
        messages: [{ role: 'user', content: prompt }]
      })
    });

    const data = await openaiResponse.json();

    if (!openaiResponse.ok) {
      console.error('OpenAI error', data);
      return res.status(502).json({ error: 'Failed to generate quiz' });
    }

    const quizText = data.choices[0].message.content.trim();
    res.json({ quiz: quizText });

  } catch (err) {
    console.error('Server error', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ---------- Start ----------
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
