$(function () {
    /* ──────────────────────────────────────────────────────────────────────
       1.  Utils
       ────────────────────────────────────────────────────────────────────── */
    const API_ROOT = "http://localhost:5000/quiz/api/v1.0";

    function getJson(url) {
        return fetch(url).then(r => {
            if (!r.ok) throw new Error(`HTTP ${r.status}`);
            return r.json();
        });
    }

    /* ──────────────────────────────────────────────────────────────────────
       2.  API Calls
       ────────────────────────────────────────────────────────────────────── */
    async function fetchQuestionnaires() {
        return (await getJson(`${API_ROOT}/quiz`)).questionnaires;
    }

    async function fetchQuestionsFor(qId) {
        return (await getJson(`${API_ROOT}/quiz/${qId}/questions`)).questions;
    }

    async function fetchQuestion(id) {
        return (await getJson(`${API_ROOT}/questions/${id}`)).question;
    }

    async function createQuestion(data) {
        return fetch(`${API_ROOT}/questions`, {
            method: "POST",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify(data)
        }).then(r => r.json());
    }

    async function updateQuestion(id, data) {
        return fetch(`${API_ROOT}/questions/${id}`, {
            method: "PUT",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify(data)
        }).then(r => r.json());
    }

    async function deleteQuestion(id) {
        return fetch(`${API_ROOT}/questions/${id}`, {method: "DELETE"})
            .then(r => r.json());
    }

    /* ──────────────────────────────────────────────────────────────────────
       3.  UI Helpers
       ────────────────────────────────────────────────────────────────────── */
    function showError(msg) {
        $("#questionnaires").html(`<b>Impossible : ${msg}</b>`);
    }

    function buildQuestionList(questions) {
        const $ul = $("<ul>");
        for (const q of questions) {
            const $li = $("<li>")
                .text(q.title)
                .data("q-id", q.id)
                .on("click", () => loadQuestionDetails(q.id));
            $ul.append($li);
        }
        $("#questions").html($ul);
    }

    function buildQuestionnaireList(questionnaires) {
        const $ul = $("<ul>");
        for (const q of questionnaires) {
            const $li = $("<li>")
                .text(q.name)
                .data("q-id", q.id)
                .on("click", () => loadQuestions(q.id));
            $ul.append($li);
        }
        $("#questionnaires").html($ul);
    }

    /* Formulaire de création/modification (un seul, on le réutilise) */
    function openQuestionForm(mode, data = {}) {
        /* mode : "create" | "edit" | "delete" */
        const $form = $("#currenttask");
        $form.empty();

        const isMultiple = data.questionType === "multiple";

        $form.append(`
            <label>Titre : <input type="text" id="title" value="${data.title || ''}"></label><br>
            <label>Type :
                <input type="radio" name="type" id="isMultiple" value="multiple" ${isMultiple ? "checked" : ""}> Multiple
                <input type="radio" name="type" id="isSimple" value="simple" ${!isMultiple ? "checked" : ""}> Simple
            </label><br>
        `);

        if (isMultiple) {
            $form.append(`
                <label>Proposition 1 : <input type="text" id="prop1" value="${data.proposition1 || ''}"></label><br>
                <label>Proposition 2 : <input type="text" id="prop2" value="${data.proposition2 || ''}"></label><br>
                <label>Réponse (1 ou 2) : <input type="number" id="reponse" min="1" max="2" value="${data.reponse || ''}"></label><br>
            `);
        } else {
            $form.append(`
                <label>Réponse : <input type="text" id="reponse" value="${data.reponse || ''}"></label><br>
            `);
        }

        $form.append(`<button id="submitBtn">${mode === "create" ? "Ajouter" : mode === "edit" ? "Modifier" : "Supprimer"}</button>`);

        const $btn = $("#submitBtn");
        if (mode === "delete") $btn.on("click", () => deleteQuestion(data.id).then(refreshQuestionnaireList));
        else if (mode === "edit") $btn.on("click", () => updateCurrentQuestion());
        else $btn.on("click", () => createCurrentQuestion());
    }

    /* Méthodes de sauvegarde */
    async function createCurrentQuestion() {
        const q = buildQuestionFromForm();
        await createQuestion(q);
        $("#currenttask").empty();
        refreshQuestionnaireList();
    }

    async function updateCurrentQuestion() {
        const q = buildQuestionFromForm();
        await updateQuestion(q.id, q);
        $("#currenttask").empty();
        refreshQuestionnaireList();
    }

    function buildQuestionFromForm() {
        const id = $("#currenttask").data("id") || null;
        const title = $("#currenttask #title").val();
        const type = $("#currenttask input[name='type']:checked").val();
        const reponse = type === "multiple" ?
            parseInt($("#currenttask #reponse").val()) : $("#currenttask #reponse").val();

        if (type === "multiple") {
            return {
                id,
                title,
                questionType: type,
                questionnaire_id: $("#questionnaire-id").val(),
                proposition1: $("#currenttask #prop1").val(),
                proposition2: $("#currenttask #prop2").val(),
                reponse
            };
        } else {
            return {id, title, questionType: type, questionnaire_id: $("#questionnaire-id").val(), reponse};
        }
    }

    /* ──────────────────────────────────────────────────────────────────────
       4.  Event Bindings
       ────────────────────────────────────────────────────────────────────── */
    $("#button").on("click", refreshQuestionnaireList);

    // Refresh la liste des questionnaires
    async function refreshQuestionnaireList() {
        try {
            const qs = await fetchQuestionnaires();
            buildQuestionnaireList(qs);
        } catch (e) {
            showError(e.message);
        }
    }

    // Chargement des questions d’un questionnaire
    async function loadQuestions(qId) {
        try {
            const qs = await fetchQuestionsFor(qId);
            buildQuestionList(qs);
            $("#questionnaire-id").val(qId); // stocke l’ID pour création de q
        } catch (e) { showError(e.message); }
    }

    // Chargement d’une question détaillée (edit / delete)
    async function loadQuestionDetails(qId) {
        try {
            const q = await fetchQuestion(qId);
            $("#currenttask").data("id", qId);
            openQuestionForm(q.questionType === "simple" ? "edit" : "edit", q);
        } catch (e) { showError(e.message); }
    }

    /* Initialisation */
    refreshQuestionnaireList();
});
```

