## 10. Создание новой темы (`new_topic.php`)

```php
<?php
require_once 'inc/db.php';
require_once 'inc/functions.php';

if (!is_logged_in()) redirect('login.php');

$errors = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $title   = trim($_POST['title'] ?? '');
    $content = trim($_POST['content'] ?? '');

    if (!$title || !$content) {
        $errors[] = 'Заголовок и содержание не могут быть пустыми';
    } else {
        $pdo->beginTransaction();
        try {
            // Добавляем тему
            $stmt = $pdo->prepare('INSERT INTO topics (user_id, title) VALUES (?,?)');
            $stmt->execute([$_SESSION['user_id'], $title]);

            $topic_id = $pdo->lastInsertId();

            // Добавляем первый пост
            $stmt = $pdo->prepare('INSERT INTO posts (topic_id, user_id, content) VALUES (?,?,?)');
            $stmt->execute([$topic_id, $_SESSION['user_id'], $content]);

            $pdo->commit();
            redirect('topic.php?id=' . $topic_id);
        } catch (Exception $e) {
            $pdo->rollBack();
            $errors[] = 'Ошибка: ' . $e->getMessage();
        }
    }
}
?>
