```php
// Path: Classes/autoloader.php
<?php

/**
 * Class Autoloader
 */
class Autoloader
{
    /**
     * Enregistre notre autoloader
     */
    public static function register(): void
    {
        spl_autoload_register([__CLASS__, 'autoload']);
    }

    /**
     * Inclue le fichier correspondant à notre classe
     * @param string $fqcn Le nom de la classe à charger
     */
    public static function autoload(string $fqcn): void
    {
        // On considère que les fichiers sont directement dans le dossier "Classes/"
        // (pas de namespaces, donc on ne transforme rien)
        $path = str_replace('\\', '/', $fqcn);
        $file = __DIR__ . '/' . $path . '.php';

        if (is_file($file)) {
            require_once $file;
        } else {
            // Vous pouvez lancer une exception ou afficher un message d’erreur
            trigger_error("Le fichier $file n’existe pas.", E_USER_WARNING);
        }
    }
}
```

