## 5.  `Classes/Quiz.php`

```php
<?php
/**
 * Classe gérant l’ensemble du quizz
 */
class Quiz
{
    /**
     * @var Question[]
     */
    private array $questions = [];

    /**
     * Ajoute une question au quiz
     */
    public function addQuestion(Question $q): void
    {
        $this->questions[] = $q;
    }

    /**
     * Affiche le quizz entier sous forme de formulaire
     */
    public function afficheQuiz(): void
    {
        echo '<form action="Action/submit.php" method="post">';
        foreach ($this->questions as $q) {
            $q->afficheQuestion();
            echo '<br>';
        }
        // champ caché pour savoir que le formulaire a été soumis
        echo '<input type="hidden" name="submit" value="1">';
        echo '<button type="submit">Valider</button>';
        echo '</form>';
    }

    /**
     * Calcule le score à partir des données POST
     */
    public function checkReponse(array $postData): int
    {
        $score = 0;
        foreach ($this->questions as $q) {
            $uuid = $q->getUuid();
            $answer = $postData[$uuid] ?? null;
            if ($q->checkReponse($answer)) {
                $score++;
            }
        }
        return $score;
    }
}
```

