 * 1️⃣ Lecture du JSON
 * 2️⃣ Création d’un objet Quiz
 * 3️⃣ Instanciation des questions en fonction de leur type
 * -------------------------------------------------------------------- */
$json = file_get_contents('./Data/model.json');
$data = json_decode($json, true);

$quiz = new Quiz();

foreach ($data as $questionData) {
    // on décide du type de question à instancier
    switch ($questionData['type']) {
        case 'radio':
            $quiz->addQuestion(new \Classes\Form\Type\RadioQuestion($questionData));
            break;

        case 'text':
            $quiz->addQuestion(new \Classes\Form\Type\TextQuestion($questionData));
            break;

        // ajoutez d’autres cas ici si vous créez d’autres types
        default:
            throw new Exception("Type de question inconnu : {$questionData['type']}");
    }
}

/* --------------------------------------------------------------------
 * 4️⃣ Affichage du quiz
