## 6. `config.php` – загрузка конфига и вспомогательные функции

```php
<?php
$CONFIG_PATH = __DIR__.'/config.json';
$config_path = $CONFIG_PATH;
if (!file_exists($CONFIG_PATH)) {
    die('Конфигурационный файл не найден. Создайте config.json.');
}
$config = json_decode(file_get_contents($CONFIG_PATH), true);

// Создаём каталог для загрузок, если его нет
function init_upload_dir() {
    global $config;
    if (!is_dir($config['upload_dir'])) {
        mkdir($config['upload_dir'], 0755, true);
    }
}

// Форматируем размер в человекочитаемом виде
function format_bytes($bytes, $precision=2) {
    $units = ['байт', 'КБ', 'МБ', 'ГБ', 'ТБ'];
    $i = 0;
    while ($bytes >= 1024 && $i < count($units)-1) {
        $bytes /= 1024;
        $i++;
    }
    return round($bytes, $precision).' '.$units[$i];
}

// Путь для ссылок (работает даже в поддиректории)
function url_path($path) {
    return rtrim($_SERVER['PHP_SELF'], 'index.php').$path;
}

/* ===================== Работа с метаданными файлов ===================== */
function load_files() {
    global $config;
    if (!file_exists($config['files_db'])) return [];
    return json_decode(file_get_contents($config['files_db']), true) ?: [];
}

function save_files($data) {
    global $config;
    file_put_contents($config['files_db'], json_encode($data, JSON_PRETTY_PRINT));
}

function add_file_record($stored, $original, $retention) {
    $files = load_files();
    $id = uniqid();
    $files[$id] = [
        'stored'      => $stored,
        'original'    => $original,
        'upload_time' => time(),
        'retention'   => $retention
    ];
    save_files($files);
}

function delete_file($id) {
    global $config;
    $files = load_files();
    if (!isset($files[$id])) return;
    $filePath = $config['upload_dir'].'/'.$files[$id]['stored'];
    if (file_exists($filePath)) unlink($filePath);
    unset($files[$id]);
    save_files($files);
}

function clean_old_files() {
    global $config;
    $files = load_files();
    $now = time();
    foreach ($files as $id => $f) {
        $expiry = $f['upload_time'] + $f['retention']*86400;
        if ($now > $expiry) {
            delete_file($id);
        }
    }
}
```

