   1️⃣  Initialise variables
   --------------------------------------- */
$first   = '';
$second  = '';
$op      = '+';
$result  = null;
$errors  = [];

/* ---------------------------------------
   2️⃣  Process the form on POST
   --------------------------------------- */
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    /* Sanitize numeric input – allows decimals */
    $first  = filter_input(INPUT_POST, 'first',  FILTER_SANITIZE_NUMBER_FLOAT,
                           FILTER_FLAG_ALLOW_FRACTION);
    $second = filter_input(INPUT_POST, 'second', FILTER_SANITIZE_NUMBER_FLOAT,
