        'link_daftar' => 'https://remote.example.com/daftar2',
        'mainbanner'  => 'https://remote.example.com/banners/mainbanner2.jpg',
    ],
    // Tambah brand sesuai kebutuhan
];

/**
 * 3. Set header & output
 */
