 */

require_once __DIR__ . '/config.php';

/**
 * Effettua una chiamata GET all’API di Matomo
 *
 * @param string $endpoint   Nome dell’azione API (es. "SitesManager.getSitesId")
 * @param array  $params     Parametri aggiuntivi
 *
 * @return array|bool        Array decodificato (JSON/CSV) oppure false su errore
 */
function matomo_api_get(string $endpoint, array $params = []): array|bool
{
    // Parametri di base
    $params = array_merge([
        'token_auth' => MATOMO_TOKEN,
        'format'     => 'json',      // default JSON (può essere sovrascritto)
        'module'     => 'API',
        'method'     => $endpoint,
        'idSite'     => DEFAULT_SITE_ID,
    ], $params);

    // Costruzione URL
    $query = http_build_query($params);
    $url   = MATOMO_URL . '/' . $query;

    // cURL
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        'Accept: */*',
    ]);
    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($httpCode !== 200) {
        return false;
    }

    // Se è JSON lo decodifichiamo
    if (strpos($params['format'], 'json') !== false) {
        return json_decode($response, true);
    }

    // Altri formati (es. CSV) restituiremo la stringa grezza
    return $response;
}

/**
 * Recupera la lista dei siti disponibili
 *
 * @return array  Array di array con chiavi 'idSite' e 'name'
 */
function get_sites(): array
{
    $data = matomo_api_get('SitesManager.getSitesId');
    if ($data === false) {
        return [];
    }
    return $data; // già in forma desiderata
}
```

